local isFriend: (plr: Player, recolor: boolean?) -> boolean? = function(plr: Player, recolor: boolean?): boolean?
	local friends: table = vape.Categories.Friends;
	if not friends.Options['Use friends']["Enabled"] then
		return nil;
	end;
	local friend: boolean = table.find(friends.ListEnabled, plr.Name) ~= nil;
	return friend and (not recolor or friends.Options['Recolor visuals']["Enabled"]);
end;

local isTarget: (plr: Player) -> boolean = function(plr: Player): boolean
	return table.find(vape.Categories.Targets.ListEnabled, plr.Name) ~= nil;
end;

local addBlur: (parent: GuiObject) -> ImageLabel = function(parent: GuiObject): ImageLabel
	local blur: ImageLabel = Instance.new('ImageLabel');
	blur.Name = 'Blur';
	blur.Size = UDim2.new(1, 89, 1, 52);
	blur.Position = UDim2.fromOffset(-48, -31);
	blur.BackgroundTransparency = 1;
	blur.Image = getcustomasset('velo/assets/new/blur.png');
	blur.ScaleType = Enum.ScaleType.Slice;
	blur.SliceCenter = Rect.new(52, 31, 261, 502);
	blur.Parent = parent;
	return blur;
end;

local removeTags: (text: string) -> string = function(text: string): string
	return (text:gsub('<br%s*/>', '\n'):gsub('<[^<>]->', ''));
end;

local roundPos: (vec: Vector3) -> Vector3 = function(vec: Vector3): Vector3
	return Vector3.new(math.round(vec.X / 3) * 3, math.round(vec.Y / 3) * 3, math.round(vec.Z / 3) * 3);
end;

local collection: (tags: {string} | string, owner: table, customAdd: ((list: table, object: Instance, tag: string) -> ())?, customRemove: ((list: table, object: Instance, tag: string) -> ())?) -> table = function(tags: {string} | string, owner: table, customAdd: ((list: table, object: Instance, tag: string) -> ())?, customRemove: ((list: table, object: Instance, tag: string) -> ())?): table
	local list: table = {};
	local add: (object: Instance, tag: string) -> () = function(object: Instance, tag: string): ()
		if customAdd then
			customAdd(list, object, tag);
		else
			table.insert(list, object);
		end;
	end;
	for _: number, tag: string in (type(tags) == 'table' and tags or {tags}) do
		owner:Clean(collectionService:GetInstanceAddedSignal(tag):Connect(function(object: Instance): ()
			add(object, tag);
		end));
		owner:Clean(collectionService:GetInstanceRemovedSignal(tag):Connect(function(object: Instance): ()
			if customRemove then
				customRemove(list, object, tag);
				return;
			end;
			local index: number? = table.find(list, object);
			if index then
				table.remove(list, index);
			end;
		end));
		for _: number, object: Instance in collectionService:GetTagged(tag) do
			add(object, tag);
		end;
	end;
	owner:Clean(function(): ()
		table.clear(list);
	end);
	return list;
end;

local getItem: (itemType: string, items: table?, partial: boolean?) -> (table?, number?) = function(itemType: string, items: table?, partial: boolean?): (table?, number?)
	for slot: number, item: table in (items or store.inventory.inventory.items) do
		if item.itemType == itemType or (partial and item.itemType:find(itemType, 1, true)) then
			return item, slot;
		end;
	end;
	return nil, nil;
end;

local getSword: () -> (table?, number?) = function(): (table?, number?)
	local best: table?, bestSlot: number?, bestDamage: number, bestRange: number = nil, nil, -1, -1;
	for slot: number, item: table in store.inventory.inventory.items do
		local meta: table? = bedwars.ItemMeta[item.itemType];
		local sword: table? = meta and meta.sword;
		if sword then
			local damage: number, range: number = sword.damage or 0, sword.attackRange or store.swordDistance or 0;
			if damage > bestDamage or (damage == bestDamage and range > bestRange) then
				best, bestSlot, bestDamage, bestRange = item, slot, damage, range;
			end;
		end;
	end;
	return best, bestSlot;
end;

local getTool: (breakType: string) -> (table?, number?) = function(breakType: string): (table?, number?)
	local best: table?, bestSlot: number?, bestPower: number = nil, nil, 0;
	for slot: number, item: table in store.inventory.inventory.items do
		local breaker: table? = bedwars.ItemMeta[item.itemType].breakBlock;
		local power: number = breaker and breaker[breakType] or 0;
		if power > bestPower then
			best, bestSlot, bestPower = item, slot, power;
		end;
	end;
	return best, bestSlot;
end;

local getWool: () -> (string?, number?) = function(): (string?, number?)
	for _: number, item: table in store.inventory.inventory.items do
		if item.itemType:find('wool') then
			return item.itemType, item.amount;
		end;
	end;
	return nil, nil;
end;

local getBow: () -> (table?, number?) = function(): (table?, number?)
	local best: table?, bestSlot: number?, bestDamage: number = nil, nil, 0;
	for slot: number, item: table in store.inventory.inventory.items do
		local source: table? = bedwars.ItemMeta[item.itemType].projectileSource;
		if source and table.find(source.ammoItemTypes, 'arrow') then
			local damage: number = bedwars.ProjectileMeta[source.projectileType('arrow')].combat.damage or 0;
			if damage > bestDamage then
				best, bestSlot, bestDamage = item, slot, damage;
			end;
		end;
	end;
	return best, bestSlot;
end;

local getBestArmor: (slot: number) -> table? = function(slot: number): table?
	local best: table?, bestReduction: number = nil, 0;
	for _: number, item: table in store.inventory.inventory.items do
		local armor: table? = bedwars.ItemMeta[item.itemType].armor;
		if armor and armor.slot == slot and (armor.damageReductionMultiplier or 0) > bestReduction then
			best, bestReduction = item, armor.damageReductionMultiplier;
		end;
	end;
	return best;
end;

local getStrength: (ent: table) -> number = function(ent: table): number
	local strength: number = 0;
	for _: number, item: table in (ent.Player and store.inventories[ent.Player] or {["items"] = {}}).items do
		local sword: table? = bedwars.ItemMeta[item.itemType] and bedwars.ItemMeta[item.itemType].sword;
		if sword and sword.damage > strength then
			strength = sword.damage;
		end;
	end;
	return strength;
end;

local isCasting: () -> boolean = function(): boolean
	local casting: any = lplr:GetAttribute('IsCasting');
	return casting ~= nil and casting ~= 0 and casting ~= '' and casting ~= false;
end;

local canSwing: () -> boolean = function(): boolean
	if bedwars.SwordController:getSwordSwingDisabled() or isCasting() then
		return false;
	end;
	local meta: table? = store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name];
	return meta ~= nil and meta.sword ~= nil and meta.sword.chargedAttack == nil;
end;

local canPlace: () -> boolean = function(): boolean
	return not bedwars.BlockPlacementController.disabled and not isCasting();
end;

local isAfk: () -> boolean = function(): boolean
	return tick() - store.lastInput >= config.AfkTime;
end;

local getReach: (tool: Instance?) -> number = function(tool: Instance?): number
	local meta: table? = tool and bedwars.ItemMeta[tool.Name];
	return meta and meta.sword and meta.sword.attackRange or store.swordDistance;
end;

local getSpeed: () -> number = function(): number
	local multiplier: number, stacking: boolean = 0, true;
	local modifiers: table = bedwars.SprintController:getMovementStatusModifier():getModifiers();
	for modifier: table in modifiers do
		local constant: number = modifier.constantSpeedMultiplier or 0;
		if constant > math.max(multiplier, 1) then
			stacking = false;
			multiplier = constant - 0.06 * math.round(constant);
		end;
	end;
	for modifier: table in modifiers do
		multiplier += math.max((modifier.moveSpeedMultiplier or 0) - 1, 0);
	end;
	if multiplier > 0 and stacking then
		multiplier += 0.16 + 0.02 * math.round(multiplier);
	end;
	local boost: number = store.speedBoost.Expires > tick() and store.speedBoost.Amount or 0;
	return (config.BaseSpeed + boost) * (multiplier + 1);
end;

local hotbarSlotOf: (tool: Instance?) -> number? = function(tool: Instance?): number?
	for index: number, slot: table in store.inventory.hotbar or {} do
		if slot.item and slot.item.tool == tool then
			return index - 1;
		end;
	end;
	return nil;
end;

local switchItem: (tool: Instance, delayTime: number?) -> boolean = function(tool: Instance, delayTime: number?): boolean
	local hand: ObjectValue? = lplr.Character and lplr.Character:FindFirstChild('HandInvItem');
	if not hand or hand.Value == tool or tool.Parent == nil then
		return false;
	end;
	fire('SetInvItem', 'CallServerAsync', {["hand"] = tool});
	hand.Value = tool;
	local waitTime: number = delayTime or config.SwitchDelay;
	if waitTime > 0 then
		task.wait(waitTime);
	end;
	return true;
end;

local hotbarSwitch: (slot: number?) -> boolean = function(slot: number?): boolean
	if not slot or store.inventory.hotbarSlot == slot then
		return false;
	end;
	bedwars.Store:dispatch({["type"] = 'InventorySelectHotbarSlot', ["slot"] = slot});
	vapeEvents.InventoryChanged.Event:Wait();
	return true;
end;

local inventorySlots: () -> table = function(): table
	local snapshot: table? = bedwars.Store:getState().Inventory.slotSnapshot;
	return snapshot and snapshot.player and snapshot.player.slots or {};
end;

local moveSlot: (operation: table) -> boolean = function(operation: table): boolean
	local success: boolean, result: any = bedwars.InventoryDraggingController:sendTransaction(operation, nil):await();
	return success and result == true;
end;

local functionRange: (callback: any, fallback: number?) -> number? = function(callback: any, fallback: number?): number?
	if type(callback) ~= 'function' then
		return fallback;
	end;
	local constants: {any} = debug.getconstants(callback);
	for index: number, constant: any in constants do
		if constant == 'maxActivationDistance' then
			return type(constants[index + 1]) == 'number' and constants[index + 1] or fallback;
		end;
	end;
	return fallback;
end;

local getPlacedBlock: (position: Vector3?) -> (Instance?, Vector3?) = function(position: Vector3?): (Instance?, Vector3?)
	if not position then
		return nil, nil;
	end;
	local cell: Vector3 = bedwars.BlockController:getBlockPosition(position);
	return bedwars.BlockController:getStore():getBlockAt(cell), cell;
end;

local getBlocksInPoints: (from: Vector3, to: Vector3) -> {Vector3} = function(from: Vector3, to: Vector3): {Vector3}
	local blockStore: table, list: {Vector3} = bedwars.BlockController:getStore(), {};
	for x: number = from.X, to.X do
		for y: number = from.Y, to.Y do
			for z: number = from.Z, to.Z do
				local cell: Vector3 = Vector3.new(x, y, z);
				if blockStore:getBlockAt(cell) then
					table.insert(list, cell * 3);
				end;
			end;
		end;
	end;
	return list;
end;

local getNearGround: (range: number?) -> Vector3? = function(range: number?): Vector3?
	local reach: Vector3 = Vector3.new(3, 3, 3) * (range or 10);
	local origin: Vector3 = entitylib.character.RootPart.Position;
	local closest: Vector3?, distance: number = nil, 60;
	for _: number, block: Vector3 in getBlocksInPoints(bedwars.BlockController:getBlockPosition(origin - reach), bedwars.BlockController:getBlockPosition(origin + reach)) do
		local top: Vector3 = block + Vector3.new(0, 3, 0);
		if not getPlacedBlock(top) and (origin - block).Magnitude < distance then
			closest, distance = top, (origin - block).Magnitude;
		end;
	end;
	return closest;
end;

local targetParts: {string} = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random'};
local limbParts: {[string]: {string}} = {
	["Torso"] = {'UpperTorso', 'LowerTorso', 'Torso'},
	["Left arm"] = {'LeftUpperArm', 'LeftLowerArm', 'LeftHand', 'Left Arm'},
	["Right arm"] = {'RightUpperArm', 'RightLowerArm', 'RightHand', 'Right Arm'},
	["Left leg"] = {'LeftUpperLeg', 'LeftLowerLeg', 'LeftFoot', 'Left Leg'},
	["Right leg"] = {'RightUpperLeg', 'RightLowerLeg', 'RightFoot', 'Right Leg'}
};
local randomLimb: {[Instance]: table} = {};

local getTargetPart: (ent: table, mode: string) -> BasePart = function(ent: table, mode: string): BasePart
	if mode == 'Random' and ent.Character then
		local pick: table? = randomLimb[ent.Character];
		if not pick or tick() > pick.Expires then
			pick = {["Part"] = targetParts[math.random(2, #targetParts - 1)], ["Expires"] = tick() + 1};
			randomLimb[ent.Character] = pick;
		end;
		mode = pick.Part;
	end;
	if mode == 'Head' then
		return ent.Character and ent.Character:FindFirstChild('Head') or ent.Head or ent.RootPart;
	end;
	for _: number, name: string in (ent.Character and limbParts[mode] or {}) do
		local part: BasePart? = ent.Character:FindFirstChild(name);
		if part then
			return part;
		end;
	end;
	return ent.RootPart;
end;

local kitPriority: {[string]: number} = {["hannah"] = 5, ["spirit_assassin"] = 4, ["dasher"] = 3, ["jade"] = 2, ["regent"] = 1};
local flatAngle: (ent: table) -> number = function(ent: table): number
	local root: BasePart = entitylib.character.RootPart;
	local facing: Vector3 = root.CFrame.LookVector * Vector3.new(1, 0, 1);
	local delta: Vector3 = (ent.RootPart.Position - root.Position) * Vector3.new(1, 0, 1);
	return delta.Magnitude > 0 and facing.Magnitude > 0 and math.acos(math.clamp(facing.Unit:Dot(delta.Unit), -1, 1)) or 0;
end;
local mouseDistance: (ent: table) -> number = function(ent: table): number
	local point: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(ent.RootPart.Position);
	return visible and (inputService:GetMouseLocation() - Vector2.new(point.X, point.Y)).Magnitude or math.huge;
end;

local sortMethods: {[string]: (a: table, b: table) -> boolean} = {
	["Distance"] = function(a: table, b: table): boolean
		return a.Magnitude < b.Magnitude;
	end,
	["Damage"] = function(a: table, b: table): boolean
		return (a.Entity.Character:GetAttribute('LastDamageTakenTime') or 0) < (b.Entity.Character:GetAttribute('LastDamageTakenTime') or 0);
	end,
	["Threat"] = function(a: table, b: table): boolean
		return getStrength(a.Entity) > getStrength(b.Entity);
	end,
	["Kit"] = function(a: table, b: table): boolean
		return (a.Entity.Player and kitPriority[a.Entity.Player:GetAttribute('PlayingAsKits')] or 0) > (b.Entity.Player and kitPriority[b.Entity.Player:GetAttribute('PlayingAsKits')] or 0);
	end,
	["Health"] = function(a: table, b: table): boolean
		return a.Entity.Health < b.Entity.Health;
	end,
	["Angle"] = function(a: table, b: table): boolean
		return flatAngle(a.Entity) < flatAngle(b.Entity);
	end,
	["Mouse"] = function(a: table, b: table): boolean
		return mouseDistance(a.Entity) < mouseDistance(b.Entity);
	end
};
local sortNames: {string} = {'Distance', 'Damage', 'Threat', 'Kit', 'Health', 'Angle', 'Mouse'};

local getFacingEntity: (query: table, cone: number?) -> table? = function(query: table, cone: number?): table?
	if not entitylib.isAlive then
		return nil;
	end;
	local root: BasePart = entitylib.character.RootPart;
	local origin: Vector3 = query.Origin or root.Position;
	local facing: Vector3 = root.CFrame.LookVector * Vector3.new(1, 0, 1);
	local limit: number = math.rad((cone or 120) / 2);
	query.Origin = origin;
	for _: number, ent: table in entitylib.AllPosition(query) do
		local delta: Vector3 = (ent.RootPart.Position - origin) * Vector3.new(1, 0, 1);
		if facing.Magnitude == 0 or delta.Magnitude == 0 or math.acos(math.clamp(facing.Unit:Dot(delta.Unit), -1, 1)) <= limit then
			return ent;
		end;
	end;
	return nil;
end;

local frictionUsers: {[string]: boolean} = {};
local savedFriction: {[BasePart]: any} = {};
local frictionConnection: RBXScriptConnection?;
local frictionPart: (part: Instance) -> () = function(part: Instance): ()
	if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' and savedFriction[part] == nil then
		savedFriction[part] = part.CustomPhysicalProperties or false;
		part.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0.2, 0.5, 1, 1);
	end;
end;
local updateFriction: () -> () = function(): ()
	if frictionConnection then
		frictionConnection:Disconnect();
		frictionConnection = nil;
	end;
	if next(frictionUsers) and entitylib.isAlive then
		for part: BasePart in savedFriction do
			if not part.Parent then
				savedFriction[part] = nil;
			end;
		end;
		for _: number, part: Instance in entitylib.character.Character:GetDescendants() do
			frictionPart(part);
		end;
		frictionConnection = entitylib.character.Character.DescendantAdded:Connect(frictionPart);
		return;
	end;
	for part: BasePart, saved: any in savedFriction do
		part.CustomPhysicalProperties = saved or nil;
	end;
	table.clear(savedFriction);
end;

local createProgressBar: () -> table = function(): table
	local frame: Frame = Instance.new('Frame');
	frame.AnchorPoint = Vector2.new(0.5, 0);
	frame.Position = UDim2.new(0.5, 0, 1, -200);
	frame.Size = UDim2.new(0.2, 0, 0, 20);
	frame.BackgroundTransparency = 0.5;
	frame.BorderSizePixel = 0;
	frame.BackgroundColor3 = Color3.new();
	frame.Visible = false;
	frame.Parent = vape.gui;
	local fill: Frame = Instance.new('Frame');
	fill.Size = UDim2.fromScale(1, 1);
	fill.BorderSizePixel = 0;
	fill.Parent = frame;
	local label: TextLabel = Instance.new('TextLabel');
	label.Font = Enum.Font.Gotham;
	label.TextStrokeTransparency = 0;
	label.TextColor3 = Color3.new(0.9, 0.9, 0.9);
	label.TextSize = 20;
	label.Size = UDim2.fromScale(1, 1);
	label.Position = UDim2.fromScale(0, -1);
	label.BackgroundTransparency = 1;
	label.Parent = frame;
	return {
		["Frame"] = frame,
		["Set"] = function(remaining: number, total: number): ()
			fill.BackgroundColor3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value);
			fill.Size = UDim2.fromScale(math.clamp(remaining / total, 0, 1), 1);
			label.Text = string.format('%.1fs', math.max(remaining, 0));
		end
	};
end;

local propertyLock: () -> table = function(): table
	local locked: {[Instance]: table} = {};
	local lock: table = {};
	lock.Apply = function(object: Instance, properties: {[string]: any}): ()
		local entry: table? = locked[object];
		if not entry then
			entry = {["Values"] = {}, ["Connections"] = {object.Destroying:Connect(function(): ()
				locked[object] = nil;
			end)}};
			locked[object] = entry;
		end;
		for property: string, value: any in properties do
			local saved: table? = entry.Values[property];
			if not saved then
				saved = {["Original"] = object[property]};
				entry.Values[property] = saved;
				table.insert(entry.Connections, object:GetPropertyChangedSignal(property):Connect(function(): ()
					if object[property] ~= saved.Applied then
						saved.Original = object[property];
						object[property] = saved.Applied;
					end;
				end));
			end;
			saved.Applied = value;
			object[property] = value;
		end;
	end;
	lock.Restore = function(): ()
		for object: Instance, entry: table in locked do
			for _: number, connection: RBXScriptConnection in entry.Connections do
				connection:Disconnect();
			end;
			if object.Parent then
				for property: string, saved: table in entry.Values do
					object[property] = saved.Original;
				end;
			end;
		end;
		table.clear(locked);
	end;
	return lock;
end;

velo.run(function(): ()
	local customEntity: (character: Model) -> () = function(character: Model): ()
		if character:HasTag('inventory-entity') and not character:HasTag('Monster') and not character:HasTag('trainingRoomDummy') then
			return;
		end;
		entitylib.addEntity(character, nil, character:HasTag('Drone') and function(self: table): boolean
			local owner: Player? = playersService:GetPlayerByUserId(self.Character:GetAttribute('PlayerUserId'));
			return not owner or lplr:GetAttribute('Team') ~= owner:GetAttribute('Team');
		end or function(self: table): boolean
			return lplr:GetAttribute('Team') ~= self.Character:GetAttribute('Team');
		end);
	end;

	local shieldOf: (character: Model) -> number = function(character: Model): number
		return math.max(character:GetAttribute('TotalShield') or 0, 0);
	end;

	local refreshInventory: (plr: Player, ent: table?) -> () = function(plr: Player, ent: table?): ()
		task.delay(0.1, function(): ()
			if bedwars.getInventory then
				store.inventories[plr] = bedwars.getInventory(plr);
				if ent then
					entitylib.Events.EntityUpdated:Fire(ent);
				end;
			end;
		end);
	end;

	local oldStart: () -> () = entitylib.start;
	entitylib.start = function(): ()
		oldStart();
		if entitylib.Running then
			for _: number, character: Model in collectionService:GetTagged('entity') do
				customEntity(character);
			end;
			table.insert(entitylib.Connections, collectionService:GetInstanceAddedSignal('entity'):Connect(customEntity));
			table.insert(entitylib.Connections, collectionService:GetInstanceRemovedSignal('entity'):Connect(function(character: Model): ()
				entitylib.removeEntity(character);
			end));
		end;
	end;

	entitylib.addPlayer = function(plr: Player): ()
		if plr.Character then
			entitylib.refreshEntity(plr.Character, plr);
		end;
		entitylib.PlayerConnections[plr] = {
			plr.CharacterAdded:Connect(function(character: Model): ()
				entitylib.refreshEntity(character, plr);
			end),
			plr.CharacterRemoving:Connect(function(character: Model): ()
				entitylib.removeEntity(character, plr == lplr);
			end),
			plr:GetAttributeChangedSignal('Team'):Connect(function(): ()
				for _: number, ent: table in entitylib.List do
					if ent.Targetable ~= entitylib.targetCheck(ent) then
						entitylib.refreshEntity(ent.Character, ent.Player);
					end;
				end;
				if plr == lplr then
					entitylib.start();
				else
					entitylib.refreshEntity(plr.Character, plr);
				end;
			end)
		};
	end;

	entitylib.addEntity = function(character: Model?, plr: Player?, teamCheck: ((self: table) -> boolean)?): ()
		if not character then
			return;
		end;
		entitylib.EntityThreads[character] = task.spawn(function(): ()
			local humanoid: any, root: BasePart?, head: BasePart?;
			if plr then
				humanoid = character:WaitForChild('Humanoid', 10);
				root = humanoid and (humanoid.RootPart or character:WaitForChild('HumanoidRootPart', workspace.StreamingEnabled and math.huge or 10));
				head = character:WaitForChild('Head', 10) or root;
			else
				humanoid = {["HipHeight"] = 0.5};
				if not character.PrimaryPart then
					character:GetPropertyChangedSignal('PrimaryPart'):Wait();
				end;
				root = character.PrimaryPart;
				head = root;
			end;
			entitylib.EntityThreads[character] = nil;
			if not humanoid or not root then
				return;
			end;
			local ent: table = {
				["Connections"] = {},
				["Character"] = character,
				["Health"] = (character:GetAttribute('Health') or 100) + shieldOf(character),
				["Head"] = head,
				["Humanoid"] = humanoid,
				["HumanoidRootPart"] = root,
				["HipHeight"] = humanoid.HipHeight + (root.Size.Y / 2) + (humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or 0),
				["Jumps"] = 0,
				["JumpTick"] = tick(),
				["Jumping"] = false,
				["LandTick"] = tick(),
				["MaxHealth"] = character:GetAttribute('MaxHealth') or 100,
				["NPC"] = plr == nil,
				["Player"] = plr,
				["RootPart"] = root,
				["TeamCheck"] = teamCheck
			};
			for _: number, signal: any in entitylib.getUpdateConnections(ent) do
				table.insert(ent.Connections, signal:Connect(function(): ()
					ent.Health = (character:GetAttribute('Health') or 100) + shieldOf(character);
					ent.MaxHealth = character:GetAttribute('MaxHealth') or 100;
					entitylib.Events.EntityUpdated:Fire(ent);
				end));
			end;
			if plr == lplr then
				ent.AirTime = tick();
				entitylib.character = ent;
				entitylib.isAlive = true;
				entitylib.Events.LocalAdded:Fire(ent);
				table.insert(ent.Connections, character.AttributeChanged:Connect(function(attribute: string): ()
					vapeEvents.AttributeChanged:Fire(attribute);
				end));
			else
				ent.Targetable = entitylib.targetCheck(ent);
				if plr then
					for _: number, name: string in {'ArmorInvItem_0', 'ArmorInvItem_1', 'ArmorInvItem_2', 'HandInvItem'} do
						local value: Instance? = character:WaitForChild(name, 5);
						if value then
							table.insert(ent.Connections, value:GetPropertyChangedSignal('Value'):Connect(function(): ()
								refreshInventory(plr, ent);
							end));
						end;
					end;
					local animate: Instance? = character:FindFirstChild('Animate');
					local jump: Instance? = animate and animate:FindFirstChild('jump');
					local jumpAnimation: Animation? = jump and jump:FindFirstChildWhichIsA('Animation');
					local animator: Animator? = humanoid:FindFirstChildWhichIsA('Animator');
					if jumpAnimation and animator then
						table.insert(ent.Connections, animator.AnimationPlayed:Connect(function(track: AnimationTrack): ()
							if track.Animation.AnimationId == jumpAnimation.AnimationId then
								ent.JumpTick = tick();
								ent.Jumps += 1;
								ent.LandTick = tick() + 1;
								ent.Jumping = ent.Jumps > 1;
							end;
						end));
					end;
					refreshInventory(plr, nil);
				end;
				table.insert(entitylib.List, ent);
				entitylib.Events.EntityAdded:Fire(ent);
			end;
			table.insert(ent.Connections, character.ChildRemoved:Connect(function(part: Instance): ()
				if part == root or part == humanoid or part == head then
					if part == root and humanoid.RootPart then
						root = humanoid.RootPart;
						ent.RootPart = root;
						ent.HumanoidRootPart = root;
						return;
					end;
					entitylib.removeEntity(character, plr == lplr);
				end;
			end));
		end);
	end;

	entitylib.getUpdateConnections = function(ent: table): table
		local character: Model = ent.Character;
		local signals: table = {
			character:GetAttributeChangedSignal('Health'),
			character:GetAttributeChangedSignal('MaxHealth'),
			character:GetAttributeChangedSignal('TotalShield'),
			{
				["Connect"] = function(): table
					ent.Friend = ent.Player and isFriend(ent.Player) or nil;
					ent.Target = ent.Player and isTarget(ent.Player) or nil;
					return {["Disconnect"] = function(): () end};
				end
			}
		};
		return signals;
	end;

	entitylib.targetCheck = function(ent: table): boolean
		if ent.TeamCheck then
			return ent:TeamCheck();
		end;
		if ent.NPC then
			return true;
		end;
		if isFriend(ent.Player) or not select(2, whitelist:get(ent.Player)) then
			return false;
		end;
		return lplr:GetAttribute('Team') ~= ent.Player:GetAttribute('Team');
	end;

	local baseWallcheck: (origin: Vector3, position: Vector3, ignore: any) -> RaycastResult? = entitylib.Wallcheck;
	local wallParams: RaycastParams = RaycastParams.new();
	wallParams.FilterType = Enum.RaycastFilterType.Exclude;
	entitylib.Wallcheck = function(origin: Vector3, position: Vector3, ignore: any, ent: table?): RaycastResult?
		local selfRoot: BasePart? = entitylib.isAlive and entitylib.character.RootPart;
		if not ent or not ent.Character or not selfRoot then
			return baseWallcheck(origin, position, ignore);
		end;
		local filter: {Instance} = {lplr.Character, ent.Character};
		for _: number, object: Instance in collectionService:GetTagged('DontBlockSwordRaycast') do
			table.insert(filter, object);
		end;
		for _: number, object: Instance in (type(ignore) == 'table' and ignore or {}) do
			table.insert(filter, object);
		end;
		wallParams.FilterDescendantsInstances = filter;
		local selfFeet: Vector3 = selfRoot.Position - Vector3.new(0, entitylib.character.HipHeight, 0);
		local targetFeet: Vector3 = ent.RootPart.Position - Vector3.new(0, ent.HipHeight, 0);
		for _: number, height: number in {0, 2.5, 5} do
			local from: Vector3, to: Vector3 = selfFeet + Vector3.new(0, height, 0), targetFeet + Vector3.new(0, height, 0);
			if not bedwars.QueryUtil:raycast(from, to - from, wallParams) or not bedwars.QueryUtil:raycast(to, from - to, wallParams) then
				return nil;
			end;
		end;
		return bedwars.QueryUtil:raycast(selfFeet, targetFeet - selfFeet, wallParams);
	end;

	vape:Clean(entitylib.Events.LocalAdded:Connect(updateFriction));
	vape:Clean(entitylib.Events.EntityRemoved:Connect(function(ent: table): ()
		randomLimb[ent.Character] = nil;
	end));
	vape:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
		store.inventories[plr] = nil;
	end));
end);
entitylib.start();

