		["NoBuildUtil"] = require(ts['no-build']['no-build-util']).NoBuildUtil,
		["NotificationController"] = flamework.resolveDependency('@easy-games/game-core:client/controllers/notification-controller@NotificationController'),
		["PartyController"] = flamework.resolveDependency('@easy-games/lobby:client/controllers/party-controller@PartyController'),
		["ProjectileMeta"] = require(ts.projectile['projectile-meta']).ProjectileMeta,
		["PyroUpgradeMeta"] = require(ts.games.bedwars.kit.kits.pyro['flamethrower-upgrade']).FlamethrowerUpgradeMeta,
		["QueryUtil"] = gameCore.GameQueryUtil,
		["QueueCard"] = require(playerTs.controllers.global.queue.ui['queue-card']).QueueCard,
		["QueueMeta"] = require(ts.game['queue-meta']).QueueMeta,
		["RankMeta"] = require(ts.rank['rank-meta']).RankMeta,
		["Roact"] = require(rbxts['@rbxts'].roact.src),
		["RuntimeLib"] = require(replicatedStorage.rbxts_include.RuntimeLib),
		["scaleTool"] = require(rbxts['@rbxts']['scale-model'].out).scaleTool,
		["SettingsMeta"] = require(ts.settings['settings-meta']).SettingMeta,
		["SharedConstants"] = require(ts['shared-constants']).CpsConstants,
		["SorcererBalance"] = require(ts.balance['sorcerer-balance']).SorcererBalance,
		["SorcererTierMeta"] = require(ts.balance['sorcerer-balance']).SorcererTierMeta,
		["SoulBrokerConstants"] = require(ts.games.bedwars.kit.kits['soul-broker']['soul-broker-constants']).SoulBrokerConstants,
		["SoundList"] = require(ts.sound['game-sound']).GameSound,
		["SoundManager"] = gameCore.SoundManager,
		["StatusEffectMeta"] = require(ts['status-effect']['status-effect-type']).StatusEffectType,
		["StatusEffectUtil"] = require(ts['status-effect']['status-effect-util']).StatusEffectUtil,
		["Store"] = require(playerTs.ui.store).ClientStore,
		["SummonerKitBalance"] = require(ts.games.bedwars.kit.kits.summoner['summoner-kit-balance']).SummonerKitBalance,
		["SummonerUtil"] = require(ts.games.bedwars.kit.kits.summoner['summoner-kit-util']),
		["SyncEvents"] = require(playerTs['client-sync-events']).ClientSyncEvents,
		["TaliyahUtil"] = require(ts.games.bedwars.kit.kits.taliyah['taliyah-util']).TaliyahUtil,
		["TeamUpgradeMeta"] = debug.getupvalue(require(ts.games.bedwars['team-upgrade']['team-upgrade-meta']).getTeamUpgradeMetaForQueue, 2),
		["UILayers"] = gameCore.UILayers,
		["VisualizerUtils"] = require(playerTs.lib.visualizer['visualizer-utils']).VisualizerUtils,
		["VoidHunterBalance"] = require(ts.games.bedwars.kit.kits['void-hunter']['void-hunter-kit-balance']).VoidHunterKitBalance,
		["VoidRegentBalance"] = require(ts.balance['void-regent-balance']).VoidRegentBalance,
		["VoidWalkerDamageBuff"] = statusEffectMeta and statusEffectMeta.void_walker_damage_buff,
		["VoidWalkerKitBalance"] = require(ts.games.bedwars.kit.kits['void-walker']['void-walker-kit-balance']).VoidWalkerKitBalance,
		["WarlockBalance"] = require(ts.balance['balance-file']).WarlockBalance,
		["WeldTable"] = require(ts.util['weld-util']).WeldUtil,
		["WinEffectMeta"] = require(ts.locker['win-effect']['win-effect-meta']).WinEffectMeta,
		["WizardUtil"] = require(ts.games.bedwars.kit.kits.wizard['wizard-util']).WizardUtil,
		["ZapNetworking"] = require(playerTs.lib.network)
	} do
		rawset(bedwars, name, value);
	end;

	bedwars.getInventory = function(plr: Player): table
		return inventoryUtil.getInventory(plr) or {["items"] = {}, ["armor"] = {}};
	end;
	bedwars.getIcon = function(item: table, show: boolean?): string
		local meta: table? = bedwars.ItemMeta[item.itemType];
		return meta and show and meta.image or '';
	end;
	store.swordDistance = bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE;
	store.blockPlacer = bedwars.BlockPlacer.new(bedwars.BlockEngine, 'wool_white');

	local remoteLimits: {[string]: number} = store.remoteLimits;
	local serverGet: any = rawget(getrawmetatable(remotesModule.Server), 'Get');
	local registry: any = type(serverGet) == 'function' and debug.getupvalue(serverGet, 1);
	local construct: table?, definitions: table? = nil, nil;
	if type(registry) == 'table' then
		construct, definitions = next(registry);
	end;
	local globalLimits: any = construct and construct.globalMiddleware and debug.getupvalue(construct.globalMiddleware[2], 1);
	for name: string, limit: any in (type(globalLimits) == 'table' and globalLimits or {}) do
		if type(limit) == 'number' then
			remoteLimits[name] = limit;
		end;
	end;
	for name: string, definition: any in (type(definitions) == 'table' and definitions or {}) do
		for _: number, middleware: any in (remoteLimits[name] == nil and type(definition) == 'table' and type(definition.ServerMiddleware) == 'table' and definition.ServerMiddleware or {}) do
			local upvalues: table = type(middleware) == 'function' and debug.getupvalues(middleware) or {};
			if #upvalues >= 6 and tostring(upvalues[6]):find('Request limit') and type(upvalues[3]) == 'number' then
				remoteLimits[name] = upvalues[3];
				break;
			end;
		end;
	end;
	if not construct then
		notif('Velocity', 'Remote rate limits unavailable, using '..config.RemoteLimit..'/min', 10, 'warning');
	end;

	local remoteBudget: {[string]: table} = {};
	fire = function(name: string, method: string?, ...: any): any
		local budget: table? = remoteBudget[name];
		local now: number = os.clock();
		if not budget or now - budget.Reset >= config.RemoteWindow then
			budget = {["Used"] = 0, ["Reset"] = now};
			remoteBudget[name] = budget;
		end;
		local remote: any = client:Get(name);
		local call: string = method or (remote.CallServer and 'CallServer' or remote.CallServerAsync and 'CallServerAsync' or 'SendToServer');
		if budget.Used >= (remoteLimits[name] or config.RemoteLimit) then
			return call == 'CallServerAsync' and idlePromise or false;
		end;
		budget.Used += 1;
		return remote[call](remote, ...);
	end;

	local oldGet: (self: table, name: string) -> any = client.Get;
	client.Get = function(self: table, name: string): any
		local remote: any = oldGet(self, name);
		local hook: ((remote: any, ...any) -> ...any)? = remoteHooks[name];
		if not hook then
			return remote;
		end;
		return setmetatable({
			["SendToServer"] = function(_: any, ...: any): ...any
				return hook(remote, ...);
			end
		}, {__index = remote});
	end;

	remoteHooks.SwordHit = function(remote: any, attack: table, ...: any): ...any
		local selfPosition: Vector3 = attack.validate.selfPosition.value;
		local delta: Vector3 = attack.validate.targetPosition.value - selfPosition;
		store.attackReach = math.floor(delta.Magnitude * 100) / 100;
		store.attackReachUpdate = tick() + 1;
		local extend: boolean = (vape.Modules.Reach and vape.Modules.Reach["Enabled"]) or (vape.Modules.HitBoxes and vape.Modules.HitBoxes["Enabled"]);
		if extend and delta.Magnitude > 0.001 then
			attack.validate.selfPosition.value += delta.Unit * math.max(delta.Magnitude - (getReach(attack.weapon) - 0.001), 0);
		end;
		local victim: Player? = attack.entityInstance and playersService:GetPlayerFromCharacter(attack.entityInstance);
		if victim and not select(2, whitelist:get(victim)) then
			return nil;
		end;
		return remote:SendToServer(attack, ...);
	end;

	local oldBreakable: (...any) -> boolean = bedwars.BlockController.isBlockBreakable;
	bedwars.BlockController.isBlockBreakable = function(self: table, breakData: table, plr: Player): boolean
		local block: Instance? = bedwars.BlockController:getStore():getBlockAt(breakData.blockPosition);
		if block and block.Name == 'bed' then
			for _: number, other: Player in playersService:GetPlayers() do
				if block:GetAttribute('Team'..(other:GetAttribute('Team') or 0)..'NoBreak') and not select(2, whitelist:get(other)) then
					return false;
				end;
			end;
		end;
		return oldBreakable(self, breakData, plr);
	end;

	local oldHitBlock: (...any) -> ...any = bedwars.BlockBreaker.hitBlock;
	local hitBlock: (...any) -> ...any = function(self: table, ...: any): ...any
		store.lastHit = tick();
		for _: string, hook: (...any) -> () in blockHitHooks do
			hook(self, ...);
		end;
		return oldHitBlock(self, ...);
	end;
	bedwars.BlockBreaker.hitBlock = hitBlock;

	local refreshKits: () -> () = function(): ()
		local primary: string = string.split(bedwars.Store:getState().Bedwars.kit or '', ',')[1];
		store.equippedKit = primary ~= 'none' and primary or '';
		local attribute: any = lplr:GetAttribute('PlayingAsKits');
		local kits: {string} = {};
		for _: number, kit: string in string.split(store.equippedKit..','..(type(attribute) == 'string' and attribute or ''), ',') do
			if kit ~= '' and kit ~= 'none' and not table.find(kits, kit) then
				table.insert(kits, kit);
			end;
		end;
		if table.concat(kits, ',') ~= table.concat(store.equippedKits, ',') then
			store.equippedKits = kits;
			vapeEvents.KitChanged:Fire(kits);
		end;
	end;

	local updateStore: (new: table, old: table) -> () = function(new: table, old: table): ()
		if new.Bedwars ~= old.Bedwars then
			refreshKits();
		end;
		if new.Game ~= old.Game then
			store.matchState = new.Game.matchState;
			store.queueType = new.Game.queueType or 'bedwars_test';
		end;
		if new.Inventory == old.Inventory then
			return;
		end;
		local newInventory: table = new.Inventory and new.Inventory.observedInventory or {["inventory"] = {}};
		local oldInventory: table = old.Inventory and old.Inventory.observedInventory or {["inventory"] = {}};
		store.inventory = newInventory;
		if not newInventory.hotbar then
			newInventory.hotbar = {};
			for index: number, item: table in newInventory.inventory.items or {} do
				table.insert(newInventory.hotbar, {["item"] = item});
				if newInventory.inventory.hand and item.tool == newInventory.inventory.hand.tool then
					newInventory.hotbarSlot = index - 1;
				end;
			end;
		end;
		if newInventory ~= oldInventory then
			vapeEvents.InventoryChanged:Fire();
		end;
		if newInventory.inventory.items ~= oldInventory.inventory.items then
			store.tools.sword = getSword();
			for _: number, breakType: string in {'stone', 'wood', 'wool'} do
				store.tools[breakType] = getTool(breakType);
			end;
			vapeEvents.InventoryAmountChanged:Fire();
		end;
		if newInventory.inventory.hand ~= oldInventory.inventory.hand then
			local hand: table? = newInventory.inventory.hand;
			local meta: table = hand and bedwars.ItemMeta[hand.itemType] or {};
			store.hand = {
				["tool"] = hand and hand.tool,
				["amount"] = hand and hand.amount or 0,
				["toolType"] = hand and (meta.sword and 'sword' or meta.block and 'block' or hand.itemType:find('bow') and 'bow') or ''
			};
		end;
	end;
	local storeChanged: table = bedwars.Store.changed:connect(updateStore);
	updateStore(bedwars.Store:getState(), {});
	vape:Clean(lplr:GetAttributeChangedSignal('PlayingAsKits'):Connect(refreshKits));

	local lastAttacker: {[Instance]: Instance} = {};
	local dead: {[Instance]: boolean} = {};
	local forgetCharacter: (ent: table) -> () = function(ent: table): ()
		if ent.Character then
			lastAttacker[ent.Character] = nil;
			dead[ent.Character] = nil;
		end;
	end;
	local deathsFromHealth: () -> () = function(): ()
		vape:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
			if damage.entityInstance and damage.fromEntity then
				lastAttacker[damage.entityInstance] = damage.fromEntity;
			end;
		end));
		vape:Clean(entitylib.Events.EntityUpdated:Connect(function(ent: table): ()
			local character: Model? = ent.Character;
			if not character or dead[character] or (character:GetAttribute('Health') or 1) > 0 then
				return;
			end;
			dead[character] = true;
			local team: string = tostring(ent.Player and ent.Player:GetAttribute('Team'));
			local bedStanding: boolean = false;
			for _: number, bed: Instance in collectionService:GetTagged('bed') do
				bedStanding = bedStanding or tostring(bed:GetAttribute('TeamId')) == team;
			end;
			vapeEvents.EntityDeathEvent:Fire({["entityInstance"] = character, ["fromEntity"] = lastAttacker[character], ["finalKill"] = ent.Player ~= nil and not bedStanding});
		end));
		vape:Clean(entitylib.Events.EntityRemoved:Connect(forgetCharacter));
		vape:Clean(entitylib.Events.LocalRemoved:Connect(forgetCharacter));
	end;
	for _: number, event: string in {'MatchEndEvent', 'EntityDeathEvent', 'BedwarsBedBreak', 'BalloonPopped', 'AngelProgress', 'GrapplingHookFunctions'} do
		client:WaitFor(event):andThen(function(connection: any): ()
			vape:Clean(connection:Connect(function(...: any): ()
				vapeEvents[event]:Fire(...);
			end));
		end):catch(function(): ()
			if event == 'EntityDeathEvent' then
				deathsFromHealth();
			else
				warn('Velocity: BedWars no longer defines the '..event..' remote');
			end;
		end);
	end;

	vape:Clean(bedwars.ZapNetworking.EntityDamageEventZap.On(function(...: any): ()
		local arguments: table = table.pack(...);
		vapeEvents.EntityDamageEvent:Fire({
			["entityInstance"] = arguments[1],
			["damage"] = arguments[2],
			["damageType"] = arguments[3],
			["fromPosition"] = arguments[4],
			["fromEntity"] = arguments[5],
			["knockbackMultiplier"] = arguments[6],
			["knockbackId"] = arguments[7],
			["disableDamageHighlight"] = arguments[13]
		});
	end));

	local swordSwing: table = bedwars.SyncEvents.SwordSwing:setPriority(500):connect(function(event: table): ()
		if event.swordType and type(event.attackSpeed) == 'number' then
			store.swordSpeeds[event.swordType] = event.attackSpeed;
		end;
	end);
	vape:Clean(function(): ()
		swordSwing:Destroy();
	end);

	vape:Clean(bedwars.ZapNetworking.BreakBlockEventZap.On(function(...: any): ()
		local arguments: table = table.pack(...);
		vapeEvents.BreakBlockEvent:Fire({["blockRef"] = {["blockPosition"] = arguments[1]}, ["player"] = arguments[5]});
	end));

	vape:Clean(inputService.InputBegan:Connect(function(input: InputObject): ()
		store.lastInput = tick();
	end));
	vape:Clean(inputService.InputChanged:Connect(function(input: InputObject): ()
		if input.UserInputType ~= Enum.UserInputType.MouseMovement or input.Delta.Magnitude > 0 then
			store.lastInput = tick();
		end;
	end));

	vape:Clean(workspace.ChildAdded:Connect(function(projectile: Instance): ()
		task.defer(function(): ()
			if projectile.Parent and projectile:GetAttribute('ProjectileShooter') == lplr.UserId then
				table.insert(store.selfProjectiles, projectile);
				projectile.Destroying:Once(function(): ()
					local index: number? = table.find(store.selfProjectiles, projectile);
					if index then
						table.remove(store.selfProjectiles, index);
					end;
				end);
			end;
		end);
	end));

	store.blocks = collection('block', vape);
	store.shop = collection({'BedwarsItemShop', 'TeamUpgradeShopkeeper'}, vape, function(list: table, object: Instance, tag: string): ()
		table.insert(list, {["Id"] = object.Name, ["RootPart"] = object, ["Shop"] = object:HasTag('BedwarsItemShop'), ["Upgrades"] = object:HasTag('TeamUpgradeShopkeeper')});
	end, function(list: table, object: Instance, tag: string): ()
		for index: number, entry: table in list do
			if entry.RootPart == object then
				table.remove(list, index);
				break;
			end;
		end;
	end);
	store.enchant = collection({'enchant-table', 'broken-enchant-table'}, vape, nil, function(list: table, object: Instance, tag: string): ()
		if object:HasTag('enchant-table') and tag == 'broken-enchant-table' then
			return;
		end;
		local index: number? = table.find(list, object);
		if index then
			table.remove(list, index);
		end;
	end);

	local loadShop: () -> boolean = function(): boolean
		local identity: number? = getthreadidentity and getthreadidentity();
		if identity then
			setthreadidentity(2);
		end;
		local shopModule: Instance? = ts.games.bedwars.shop:FindFirstChild('bedwars-shop');
		if shopModule then
			bedwars.Shop = require(shopModule).BedwarsShop;
			local itemGetter: any = debug.getupvalue(bedwars.Shop.getShopItem, 1);
			bedwars.ShopItems = type(itemGetter) == 'function' and debug.getupvalue(itemGetter, 2) or nil;
			store.shopLoaded = true;
		end;
		if identity then
			setthreadidentity(identity);
		end;
		return store.shopLoaded;
	end;
	task.defer(loadShop);

	local kills: table = sessioninfo:AddItem('Kills');
	local beds: table = sessioninfo:AddItem('Beds');
	local wins: table = sessioninfo:AddItem('Wins');
	local games: table = sessioninfo:AddItem('Games');
	local mapName: string = 'Unknown';
	sessioninfo:AddItem('Map', 0, function(): string
		return mapName;
	end, false);
	task.delay(1, function(): ()
		games:Increment();
	end);

	vape:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(bedTable: table): ()
		if bedTable.player and bedTable.player.UserId == lplr.UserId then
			beds:Increment();
		end;
	end));
	vape:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(winTable: table): ()
		if (bedwars.Store:getState().Game.myTeam or {}).id == winTable.winningTeamId or lplr.Neutral then
			wins:Increment();
		end;
	end));
	vape:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable: table): ()
		local killer: Player? = playersService:GetPlayerFromCharacter(deathTable.fromEntity);
		local killed: Player? = playersService:GetPlayerFromCharacter(deathTable.entityInstance);
		if killer == lplr and killed and killed ~= lplr then
			kills:Increment();
		end;
	end));

	vape:Clean(task.spawn(function(): ()
		local world: Instance = workspace:WaitForChild('Map', math.huge):WaitForChild('Worlds', math.huge):GetChildren()[1] or workspace.Map.Worlds.ChildAdded:Wait();
		mapName = string.gsub(string.split(world.Name, '_')[2] or world.Name, '-', '');
		store.map = world;
		local airRay: RaycastParams = RaycastParams.new();
		airRay.FilterType = Enum.RaycastFilterType.Include;
		airRay.FilterDescendantsInstances = {world.Parent or world};
		store.airRay = airRay;
		local blockFolder: Instance? = world:FindFirstChild('Blocks');
		if blockFolder then
			vape:Clean(blockFolder.ChildRemoved:Connect(function(): ()
				vapeEvents.BlocksChanged:Fire();
			end));
			vape:Clean(blockFolder.ChildAdded:Connect(function(block: Instance): ()
				vapeEvents.BlocksChanged:Fire();
				task.defer(function(): ()
					local placer: number = block:GetAttribute('PlacedByUserId') or 0;
					if block:IsA('BasePart') and block:GetAttribute('Block') and placer ~= 0 then
						local cell: Vector3 = block.Position / 3;
						vapeEvents.PlaceBlockEvent:Fire({
							["blockRef"] = {["blockPosition"] = Vector3.new(math.floor(cell.X), math.floor(cell.Y), math.floor(cell.Z))},
							["player"] = playersService:GetPlayerByUserId(placer)
						});
					end;
				end);
			end));
		end;
	end));

	local nextPing: number = 0;
	vape:Clean(runService.Heartbeat:Connect(function(): ()
		local now: number = tick();
		if entitylib.isAlive then
			entitylib.character.AirTime = entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air and now or entitylib.character.AirTime;
		end;
		for _: number, ent: table in entitylib.List do
			ent.LandTick = math.abs(ent.RootPart.AssemblyLinearVelocity.Y) < 0.1 and ent.LandTick or now;
			if now - ent.LandTick > 0.2 and ent.Jumps ~= 0 then
				ent.Jumps = 0;
				ent.Jumping = false;
			end;
		end;
		if now >= nextPing then
			nextPing = now + config.PingRefresh;
			store.ping.total = statsService.Network.ServerStatsItem['Data Ping']:GetValue() / 1000;
		end;
	end));

	vape:Clean(function(): ()
		table.clear(blockHitHooks);
		table.clear(remoteHooks);
		if bedwars.BlockBreaker.hitBlock == hitBlock then
			bedwars.BlockBreaker.hitBlock = oldHitBlock;
		end;
		client.Get = oldGet;
		bedwars.BlockController.isBlockBreakable = oldBreakable;
		store.blockPlacer:disable();
		storeChanged:disconnect();
		for _: string, event: BindableEvent in vapeEvents do
			event:Destroy();
		end;
		table.clear(vapeEvents);
		table.clear(bedwars);
		table.clear(store);
	end);
end, true);

local placeBlock: (position: Vector3, itemType: string) -> any = function(position: Vector3, itemType: string): any
	if not canPlace() or not getItem(itemType) then
		return nil;
	end;
	store.blockPlacer.blockType = itemType;
	return store.blockPlacer:placeBlock(bedwars.BlockController:getBlockPosition(position));
end;

local projectileSourceOf: (itemType: string, kitWeapons: boolean?) -> table? = function(itemType: string, kitWeapons: boolean?): table?
	local meta: table? = bedwars.ItemMeta[itemType];
	if not meta then
		return nil;
	end;
	if itemType == 'wizard_stick' or itemType == 'mage_spellbook' then
		local elements: table = bedwars.MageKitUtil.MageElementMeta;
		local unlocked: table = bedwars.MageKitUtil.getUnlockedMageElements(lplr) or {};
		local chosen: string = 'BASE';
		if itemType == 'mage_spellbook' then
			local cycled: string? = bedwars.BalanceFile.MAGE_ELEMENT_CYCLE[(lplr:GetAttribute('MageElementIndex') or 0) + 1];
			chosen = cycled and table.find(unlocked, cycled) and cycled or 'BASE';
		else
			for _: number, element: string in unlocked do
				chosen = elements[element] and elements[element].projectileSource and element or chosen;
			end;
		end;
		return elements[chosen] and elements[chosen].projectileSource;
	end;
	if not kitWeapons then
		return meta.projectileSource;
	end;
	if itemType:find('frost_staff_') then
		local frosty: table? = bedwars.FrostyGunController;
		if frosty and frosty.projectileMode ~= bedwars.FrostyGunMode.PROJECTILE then
			if bedwars.AbilityController:canUseAbility('frosty_gun_swap', {["disableBlockedAbilityAlert"] = true}) then
				bedwars.AbilityController:useAbility('frosty_gun_swap');
			end;
			return nil;
		end;
	elseif itemType:match('^ninja_chakram_%d+$') and bedwars.ChakramController and bedwars.ChakramController.chakramIsLaunched then
		return nil;
	end;
	return meta.projectileSource;
end;

local getProjectiles: (filter: {string}?, kitWeapons: boolean?) -> {table} = function(filter: {string}?, kitWeapons: boolean?): {table}
	local list: {table} = {};
	local normalize: (text: string) -> string = function(text: string): string
		return ' '..tostring(text):lower():gsub('[_%s]+', ' ');
	end;
	for _: number, item: table in store.inventory.inventory.items do
		local source: table? = projectileSourceOf(item.itemType, kitWeapons);
		if not source then
			continue;
		end;
		local ammo: string? = item.itemType;
		if source.ammoItemTypes and #source.ammoItemTypes > 0 then
			ammo = nil;
			for _: number, other: table in store.inventory.inventory.items do
				if table.find(source.ammoItemTypes, other.itemType) then
					ammo = other.itemType;
					break;
				end;
			end;
		end;
		local kitWeapon: boolean = kitWeapons == true and (item.itemType == 'mage_spellbook' or item.itemType:find('frost_staff_', 1, true) ~= nil or item.itemType:find('life_', 1, true) == 1 or item.itemType:match('^ninja_chakram_%d+$') ~= nil);
		local allowed: boolean = filter == nil or #filter == 0 or kitWeapon;
		for _: number, entry: string in (ammo and filter or {}) do
			local needle: string = normalize(entry);
			for _: number, name: string in {ammo, item.itemType, bedwars.ItemMeta[item.itemType].displayName or ''} do
				allowed = allowed or normalize(name):find(needle, 1, true) ~= nil;
			end;
		end;
		if ammo and allowed then
			table.insert(list, {["Item"] = item, ["Ammo"] = ammo, ["Projectile"] = source.projectileType(ammo), ["Source"] = source});
		end;
	end;
	return list;
end;

local ballistics: table = {};
ballistics.fallGravity = function(ent: table): number
	local gravity: number = workspace.Gravity;
	local balloons: number? = ent.Character:GetAttribute('InflatedBalloons');
	if balloons and balloons > 0 then
		gravity *= 1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975);
	end;
	if ent.Character.PrimaryPart and ent.Character.PrimaryPart:FindFirstChild(config.SlowFallSound) then
		gravity = 6;
	end;
	if ent.Player and ent.Player:GetAttribute('IsOwlTarget') then
		for _: number, owl: Instance in collectionService:GetTagged('Owl') do
			if owl:GetAttribute('Target') == ent.Player.UserId and owl:GetAttribute('Status') == 2 then
				gravity = 0;
			end;
		end;
	end;
	return gravity;
end;
ballistics.solve = function(origin: Vector3, speed: number, gravity: number, ent: table, target: Vector3?, velocity: Vector3?, horizontal: number?, vertical: number?): (Vector3?, number?)
	local goal: Vector3 = target or ent.RootPart.Position;
	local motion: Vector3 = velocity or ent.RootPart.AssemblyLinearVelocity;
	local leadX: number, leadY: number = horizontal or 1, vertical or 1;
	local fall: number = ballistics.fallGravity(ent);
	local aim: Vector3?, flight: number? = nil, nil;
	for pass: number = 1, 2 do
		aim = prediction.SolveTrajectory(origin, speed, gravity, goal, motion, fall, ent.HipHeight, ent.Jumping and config.JumpPower or nil, store.airRay);
		if not aim then
			return nil, nil;
		end;
		-- SolveTrajectory returns origin + launch velocity; the intercept time comes from the horizontal closing speed.
		local closing: Vector3 = (aim - origin - motion) * Vector3.new(1, 0, 1);
		local offset: Vector3 = (goal - origin) * Vector3.new(1, 0, 1);
		flight = closing:Dot(closing) > 1e-6 and offset:Dot(closing) / closing:Dot(closing) or (goal - origin).Magnitude / speed;
		if pass == 2 or (leadX == 1 and leadY == 1) then
			break;
		end;
		local rise: number = motion.Y * flight - fall * flight * flight * 0.5;
		goal += Vector3.new(motion.X * flight * (leadX - 1), rise * (leadY - 1), motion.Z * flight * (leadX - 1));
	end;
	return aim, flight;
end;
ballistics.arcClear = function(origin: Vector3, velocity: Vector3, gravity: number, flight: number, ignore: {Instance}): boolean
	local params: RaycastParams = RaycastParams.new();
	params.FilterType = Enum.RaycastFilterType.Exclude;
	params.FilterDescendantsInstances = ignore;
	local last: Vector3 = origin;
	for step: number = 1, config.ArcSamples do
		local t: number = flight * step / config.ArcSamples;
		local point: Vector3 = origin + velocity * t + Vector3.new(0, -0.5 * gravity * t * t, 0);
		if workspace:Raycast(last, point - last, params) then
			return false;
		end;
		last = point;
	end;
	return true;
end;
ballistics.motion = {};
vape:Clean(entitylib.Events.EntityRemoved:Connect(function(ent: table): ()
	ballistics.motion[ent.RootPart] = nil;
end));
ballistics.hitChance = function(ent: table, flight: number?): number
	if not flight or flight ~= flight or flight <= 0 then
		return 0;
	end;
	local velocity: Vector3 = ent.RootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1);
	local sample: table? = ballistics.motion[ent.RootPart];
	if not sample then
		sample = {["Velocity"] = velocity, ["Clock"] = os.clock(), ["Accel"] = 0, ["Speed"] = velocity.Magnitude};
		ballistics.motion[ent.RootPart] = sample;
	end;
	local elapsed: number = os.clock() - sample.Clock;
	if elapsed >= 0.05 then
		local blend: number = math.min(elapsed * 5, 1);
		sample.Accel += ((velocity - sample.Velocity).Magnitude / elapsed - sample.Accel) * blend;
		sample.Speed += (velocity.Magnitude - sample.Speed) * blend;
		sample.Velocity, sample.Clock = velocity, os.clock();
	end;
	local drift: number = math.max(sample.Speed, velocity.Magnitude) * math.min(flight, 0.4) * math.clamp(sample.Accel / 120, 0, 1);
	return 1 / (1 + (drift / 3) ^ 2);
end;
ballistics.watch = function(shotId: string, origin: Vector3, velocity: Vector3, gravity: number, ent: table, lifetime: number?): ()
	local character: Model? = ent.Character;
	if not character or velocity.Magnitude <= 0 then
		return;
	end;
	local overlap: OverlapParams = OverlapParams.new();
	overlap.FilterType = Enum.RaycastFilterType.Include;
	overlap.FilterDescendantsInstances = {character};
	local box: Vector3 = Vector3.new(3, 1, 3);
	local substeps: number = math.clamp(math.ceil(velocity.Magnitude / 170), 1, 16);
	local started: number, last: Vector3 = os.clock(), origin;
	local watcher: RBXScriptConnection;
	watcher = runService.Heartbeat:Connect(function(): ()
		local t: number = os.clock() - started;
		if t > (lifetime or config.ProjectileLifetime) or not character.Parent then
			watcher:Disconnect();
			return;
		end;
		local point: Vector3 = origin + velocity * t + Vector3.new(0, -0.5 * gravity * t * t, 0);
		for step: number = 1, substeps do
			if #workspace:GetPartBoundsInBox(CFrame.new(last:Lerp(point, step / substeps)), box, overlap) > 0 then
				watcher:Disconnect();
				fire('ProjectileHit', 'SendToServer', shotId, character);
				return;
			end;
		end;
		if store.airRay and workspace:Raycast(last, point - last, store.airRay) then
			watcher:Disconnect();
			return;
		end;
		last = point;
	end);
end;
ballistics.shotData = function(itemType: string): table
	local source: table? = bedwars.ItemMeta[itemType] and bedwars.ItemMeta[itemType].projectileSource;
	return {["shotId"] = bedwars.IdUtil.generateId(8), ["drawDurationSec"] = math.max(1, source and source.maxStrengthChargeSec or 0)};
end;
ballistics.skinnedSource = function(item: table, source: table?): table?
	local meta: table? = bedwars.ItemMeta[item.itemType];
	source = source or meta and meta.projectileSource;
	local skin: table? = item.itemSkin and bedwars.getItemSkinMeta(item.itemSkin);
	if not source or not skin or type(skin.projectileSourceOverrides) ~= 'table' then
		return source;
	end;
	local merged: table = table.clone(source);
	for key: string, value: any in skin.projectileSourceOverrides do
		merged[key] = value;
	end;
	return merged;
end;
ballistics.launchSound = function(item: table, source: table?): ()
	source = ballistics.skinnedSource(item, source);
	if not source then
		return;
	end;
	local soundConfig: table = source.launchSoundConfig or {};
	local randomPitch: (range: table?) -> number? = function(range: table?): number?
		return range and range.Min + math.random() * (range.Max - range.Min) or nil;
	end;
	if source.launchSound and #source.launchSound > 0 then
		bedwars.AudioManager:playAudio(source.launchSound[math.random(1, #source.launchSound)], {["playbackSpeedMultiplier"] = randomPitch(soundConfig.pitch), ["volumeMultiplier"] = soundConfig.volumeMultiplier or 1});
	end;
	if source.launchOverlaySound and source.launchOverlaySound ~= '' then
		bedwars.AudioManager:playAudio(source.launchOverlaySound, {["playbackSpeedMultiplier"] = randomPitch(soundConfig.launchOverlayPitch)});
	end;
end;
ballistics.fire = function(item: table, ammo: string, projectile: string, ent: table): boolean
	local meta: table? = bedwars.ProjectileMeta[projectile];
	if not meta or not entitylib.isAlive then
		return false;
	end;
	local origin: Vector3 = entitylib.character.RootPart.Position;
	local speed: number, gravity: number = meta.launchVelocity, meta.gravitationalAcceleration or config.Gravity;
	local rough: Vector3? = ballistics.solve(origin, speed, gravity, ent);
	if not rough then
		return false;
	end;
	local offset: table = bedwars.BowConstantsTable;
	local shootPosition: Vector3 = (CFrame.new(origin, rough) * CFrame.new(-offset.RelX, -offset.RelY, -offset.RelZ)).Position;
	local aim: Vector3?, flight: number? = ballistics.solve(shootPosition, speed, gravity, ent);
	aim = aim or rough;
	local velocity: Vector3 = CFrame.lookAt(shootPosition, aim).LookVector * speed;
	if flight and not ballistics.arcClear(shootPosition, velocity, gravity, flight, {lplr.Character, gameCamera, ent.Character}) then
		return false;
	end;
	local shotId: string = bedwars.IdUtil.generateId(8);
	fire('ProjectileFire', 'CallServerAsync', item.tool, ammo, projectile, shootPosition, origin, velocity, shotId, ballistics.shotData(item.itemType), workspace:GetServerTimeNow() - config.ShotLatency):andThen(function(result: any): ()
		if type(result) == 'table' and result.accepted and result.model then
			result.model.Parent = replicatedStorage;
		end;
	end);
	ballistics.watch(shotId, shootPosition, velocity, gravity, ent, meta.lifetimeSec);
	return true;
end;

local mining: table = {["Cache"] = {}, ["Pending"] = {}, ["Health"] = {["Value"] = -1, ["Cell"] = Vector3.zero}};
vape:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(): ()
	table.clear(mining.Cache);
end));
vape:Clean(vapeEvents.BlocksChanged.Event:Connect(function(): ()
	table.clear(mining.Cache);
end));

mining.health = function(block: Instance, cell: Vector3): number
	local data: Instance? = bedwars.BlockController:getStore():getBlockData(cell);
	return data and (data:GetAttribute('1') or data:GetAttribute('Health')) or block:GetAttribute('Health') or 0;
end;

mining.hits = function(block: Instance, position: Vector3): number?
	if block:GetAttribute('NoBreak') or (position - entitylib.character.RootPart.Position).Magnitude > config.BreakRange then
		return nil;
	end;
	local cell: Vector3 = bedwars.BlockController:getBlockPosition(position);
	if not bedwars.BlockController:isBlockBreakable({["blockPosition"] = cell}, lplr) then
		return nil;
	end;
	local breakType: string = bedwars.ItemMeta[block.Name].block.breakType;
	local tool: table? = store.tools[breakType];
	local power: number = tool and bedwars.ItemMeta[tool.itemType].breakBlock[breakType] or 2;
	return math.max(math.ceil(mining.health(block, cell) / power), 1);
end;

mining.trace = function(from: Vector3, to: Vector3, visit: (position: Vector3) -> boolean?): ()
	local direction: Vector3 = to - from;
	local cell: Vector3 = bedwars.BlockController:getBlockPosition(from);
	local axes: table = {};
	for _: number, axis: string in {'X', 'Y', 'Z'} do
		local delta: number = direction[axis];
		local step: number = delta > 0 and 1 or delta < 0 and -1 or 0;
		axes[axis] = {
			["Cell"] = cell[axis],
			["Step"] = step,
			["Next"] = step == 0 and math.huge or (((cell[axis] + step * 0.5) * 3) - from[axis]) / delta,
			["Delta"] = step == 0 and math.huge or 3 / math.abs(delta)
		};
	end;
	for _: number = 1, 100 do
		if visit(Vector3.new(axes.X.Cell, axes.Y.Cell, axes.Z.Cell) * 3) then
			return;
		end;
		local nearest: table = axes.X;
		for _: number, axis: table in {axes.Y, axes.Z} do
			nearest = axis.Next < nearest.Next and axis or nearest;
		end;
		if nearest.Next > 1 then
			return;
		end;
		nearest.Cell += nearest.Step;
		nearest.Next += nearest.Delta;
	end;
end;

mining.reachable = function(position: Vector3): boolean
	local eyes: {Vector3} = {entitylib.character.Head.Position, gameCamera.CFrame.Position};
	for _: number, eye: Vector3 in eyes do
		for x: number = -1, 1 do
			for y: number = -1, 1 do
				for z: number = -1, 1 do
					local reached: boolean = false;
					mining.trace(eye, position + Vector3.new(x, y, z) * 1.35, function(cell: Vector3): boolean?
						reached = cell == position;
						return reached or getPlacedBlock(cell) ~= nil;
					end);
					if reached then
						return true;
					end;
				end;
			end;
		end;
	end;
	return false;
end;

mining.route = function(target: Instance, goal: Vector3, sightline: boolean, nearest: boolean): (Vector3?, number?, {[Vector3]: Vector3})
	local origin: Vector3 = entitylib.character.RootPart.Position;
	local key: string = tostring(goal)..(sightline and 'S' or 'P')..(nearest and 'N' or 'C');
	local cached: table? = mining.Cache[key];
	if cached and cached.Origin == bedwars.BlockController:getBlockPosition(origin) and os.clock() - cached.Clock < config.PathLifetime then
		return cached.Position, cached.Cost, cached.Path;
	end;
	local known: {[Vector3]: any} = {};
	local blockAt: (cell: Vector3) -> Instance? = function(cell: Vector3): Instance?
		if known[cell] == nil then
			known[cell] = getPlacedBlock(cell) or false;
		end;
		return known[cell] or nil;
	end;
	local score: (position: Vector3, cost: number) -> number = function(position: Vector3, cost: number): number
		return nearest and cost + (position - origin).Magnitude / 6 - (position == store.breakTarget and 1.5 or 0) or cost;
	end;
	local best: Vector3?, bestCost: number?, bestScore: number = nil, nil, math.huge;
	local path: {[Vector3]: Vector3} = {};

	if sightline then
		for _: number, eye: Vector3 in {entitylib.character.Head.Position, gameCamera.CFrame.Position} do
			for x: number = -1, 1 do
				for y: number = -1, 1 do
					for z: number = -1, 1 do
						local crossed: {Vector3}, cost: number, valid: boolean = {}, 0, false;
						mining.trace(eye, goal + Vector3.new(x, y, z) * 1.35, function(cell: Vector3): boolean?
							local block: Instance? = blockAt(cell);
							if cell == goal or block == target then
								valid = (cell - origin).Magnitude <= config.BreakRange;
								if cell ~= goal then
									table.insert(crossed, cell);
								end;
								return true;
							end;
							if block then
								local hits: number? = mining.hits(block, cell);
								if not hits then
									return true;
								end;
								cost += hits;
								table.insert(crossed, cell);
							end;
							return nil;
						end);
						local first: Vector3 = crossed[1] or goal;
						if valid and score(first, cost) < bestScore then
							best, bestCost, bestScore = first, cost, score(first, cost);
							table.clear(path);
							for index: number, cell: Vector3 in crossed do
								path[cell] = crossed[index + 1] or goal;
							end;
						end;
					end;
				end;
			end;
		end;
	else
		local openCache: {[Vector3]: boolean} = {};
		local isOpen: (cell: Vector3) -> boolean = function(cell: Vector3): boolean
			if openCache[cell] == nil then
				local frontier: {Vector3}, seen: {[Vector3]: boolean}, escaped: boolean = {cell}, {[cell] = true}, false;
				for _: number = 1, 400 do
					local current: Vector3? = table.remove(frontier);
					if not current or (current - goal).Magnitude > config.PathRadius then
						escaped = current ~= nil;
						break;
					end;
					for _: number, side: Vector3 in sides do
						local neighbour: Vector3 = current + side;
						if not seen[neighbour] and not blockAt(neighbour) then
							seen[neighbour] = true;
							table.insert(frontier, neighbour);
						end;
					end;
				end;
				for visited: Vector3 in seen do
					openCache[visited] = escaped;
				end;
			end;
			return openCache[cell];
		end;
		local heap: {table} = {{0, goal}};
		local push: (node: table) -> () = function(node: table): ()
			table.insert(heap, node);
			local index: number = #heap;
			while index > 1 and heap[index // 2][1] > node[1] do
				heap[index], heap[index // 2] = heap[index // 2], node;
				index //= 2;
			end;
		end;
		local pop: () -> table? = function(): table?
			local top: table? = heap[1];
			local last: table? = table.remove(heap);
			if #heap > 0 then
				heap[1] = last;
				local index: number = 1;
				while index * 2 <= #heap do
					local child: number = index * 2;
					if child < #heap and heap[child + 1][1] < heap[child][1] then
						child += 1;
					end;
					if heap[index][1] <= heap[child][1] then
						break;
					end;
					heap[index], heap[child] = heap[child], heap[index];
					index = child;
				end;
			end;
			return top;
		end;
		local distance: {[Vector3]: number}, done: {[Vector3]: boolean} = {[goal] = 0}, {};
		for _: number = 1, config.PathBudget do
			local node: table? = pop();
			if not node then
				break;
			end;
			local cell: Vector3 = node[2];
			if done[cell] then
				continue;
			end;
			done[cell] = true;
			for _: number, side: Vector3 in sides do
				local neighbour: Vector3 = cell + side;
				local block: Instance? = blockAt(neighbour);
				local hits: number? = 0;
				if not block and isOpen(neighbour) then
					if blockAt(cell) and (cell - origin).Magnitude <= config.BreakRange and score(cell, node[1]) < bestScore then
						best, bestCost, bestScore = cell, node[1], score(cell, node[1]);
					end;
					continue;
				elseif block and block ~= target then
					hits = mining.hits(block, neighbour);
				end;
				if hits and not done[neighbour] and node[1] + hits < (distance[neighbour] or math.huge) then
					distance[neighbour] = node[1] + hits;
					path[neighbour] = cell;
					push({node[1] + hits, neighbour});
				end;
			end;
		end;
	end;

	mining.Cache[key] = {["Origin"] = bedwars.BlockController:getBlockPosition(origin), ["Clock"] = os.clock(), ["Position"] = best, ["Cost"] = bestCost, ["Path"] = path};
	return best, bestCost, path;
end;

local breakBlock: (block: Instance, options: table?) -> (Vector3?, {[Vector3]: Vector3}?, Vector3?, boolean) = function(block: Instance, options: table?): (Vector3?, {[Vector3]: Vector3}?, Vector3?, boolean)
	options = options or {};
	if lplr:GetAttribute('DenyBlockBreak') or not entitylib.isAlive or store.infinitefly then
		return nil, nil, nil, false;
	end;
	local timeout: number = math.max(1, lplr:GetNetworkPing() * 4 + 0.5);
	for index: number = #mining.Pending, 1, -1 do
		local request: table = mining.Pending[index];
		if tick() - request.Sent >= timeout or getPlacedBlock(request.Position) ~= request.Block then
			table.remove(mining.Pending, index);
		end;
	end;
	local active: table? = mining.Pending[#mining.Pending];
	if active and (not options.Sequential or #mining.Pending >= 4) then
		return active.Position, active.Path, active.Target, false;
	end;

	local origin: Vector3 = entitylib.character.RootPart.Position;
	local handler: table? = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name);
	local cells: {Vector3} = handler and handler:getContainedPositions(block) or {bedwars.BlockController:getBlockPosition(block.Position)};
	local position: Vector3?, path: {[Vector3]: Vector3}?, target: Vector3?, cost: number, direct: boolean = nil, nil, nil, math.huge, false;
	for _: number, cell: Vector3 in cells do
		local hit: Vector3?, hitCost: number?, hitPath: {[Vector3]: Vector3} = mining.route(block, cell * 3, options.Wallcheck == true, options.Nearest == true);
		local isDirect: boolean = hit ~= nil and getPlacedBlock(hit) == block;
		if hit and ((isDirect and not direct) or (isDirect == direct and hitCost < cost)) then
			position, path, target, cost, direct = hit, hitPath, cell * 3, hitCost, isDirect;
		end;
	end;
	store.breakTarget = position;
	if not position or (options.DirectOnly and not direct) or (position - origin).Magnitude > config.BreakRange then
		return nil, nil, nil, false;
	end;
	local hitBlock: Instance?, hitCell: Vector3? = getPlacedBlock(position);
	if not hitBlock then
		return nil, nil, nil, false;
	end;
	if options.OnTarget then
		options.OnTarget(position, path, target);
	end;

	if workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack > config.SwingLockout then
		local tool: table? = store.tools[bedwars.ItemMeta[hitBlock.Name].block.breakType] or store.tools.stone;
		local hand: ObjectValue? = lplr.Character and lplr.Character:FindFirstChild('HandInvItem');
		if tool and hand and hand.Value ~= tool.tool then
			if options.SwitchDelay and options.SwitchDelay > 0 then
				task.wait(options.SwitchDelay);
				if not entitylib.isAlive or getPlacedBlock(position) ~= hitBlock then
					return position, path, target, false;
				end;
			end;
			store.breakTool = {["tool"] = tool.tool, ["expires"] = tick() + 0.5};
			if options.AutoTool then
				hotbarSwitch(hotbarSlotOf(tool.tool));
			end;
			local equipped: boolean, result: any = fire('SetInvItem', 'CallServerAsync', {["hand"] = tool.tool}):await();
			if not equipped or result == false or not hand.Parent then
				return position, path, target, false;
			end;
			hand.Value = tool.tool;
		end;
	end;

	if mining.Health.Value == -1 or mining.Health.Cell ~= hitCell then
		mining.Health.Value = mining.health(hitBlock, hitCell);
		mining.Health.Cell = hitCell;
	end;
	local before: number = mining.health(hitBlock, hitCell);
	local request: table = {["Position"] = position, ["Target"] = target, ["Path"] = path, ["Block"] = hitBlock, ["Sent"] = tick()};
	table.insert(mining.Pending, request);
	bedwars.ClientDamageBlock:Get('DamageBlock'):CallServerAsync({
		["blockRef"] = {["blockPosition"] = hitCell},
		["hitPosition"] = position,
		["hitNormal"] = Vector3.FromNormalId(Enum.NormalId.Top)
	}):andThen(function(result: any): ()
		local index: number? = table.find(mining.Pending, request);
		if index then
			table.remove(mining.Pending, index);
		end;
		if result == 'cancelled' then
			table.clear(mining.Cache);
			store.damageBlockFail = tick() + 0.1;
			return;
		end;
		if result and options.Effects and store.breakTarget == position then
			local after: number = result == 'destroyed' and 0 or mining.health(hitBlock, hitCell);
			local damage: number = math.max(before - after, 0);
			(options.Healthbar or bedwars.BlockBreaker.updateHealthbar)(bedwars.BlockBreaker, {["blockPosition"] = hitCell}, before, hitBlock:GetAttribute('MaxHealth'), damage, hitBlock);
			mining.Health.Value = math.max(before - damage, 0);
			if mining.Health.Value <= 0 then
				bedwars.BlockBreaker.breakEffect:playBreak(hitBlock.Name, hitCell, lplr);
				bedwars.BlockBreaker.blockHealthbar:destroy();
				mining.Health.Cell = Vector3.zero;
			else
				bedwars.BlockBreaker.breakEffect:playHit(hitBlock.Name, hitCell, lplr);
			end;
		end;
		if result and options.Animation then
			local minimal: boolean = options.Animation == 'Minimal';
			local track: AnimationTrack? = (not minimal or math.random(0, 1) == 1) and bedwars.AnimationUtil:playAnimation(lplr, bedwars.BlockController:getAnimationController():getAssetId(1)) or nil;
			bedwars.ViewmodelController:playAnimation(15);
			if track then
				task.delay(minimal and 0.01 or 0.3, function(): ()
					track:Stop();
					track:Destroy();
				end);
			end;
		end;
		if result == 'destroyed' then
			table.clear(mining.Cache);
		end;
	end):catch(function(): ()
		local index: number? = table.find(mining.Pending, request);
		if index then
			table.remove(mining.Pending, index);
		end;
		table.clear(mining.Cache);
	end);
	return position, path, target, true;
end;

if vape.ThreadFix then
	setthreadidentity(8);
end;

for _: number, name: string in {'AntiRagdoll', 'TriggerBot', 'SilentAim', 'Jesus', 'Invisible', 'AutoRejoin', 'Rejoin', 'Disabler', 'Timer', 'ServerHop', 'Wallhop', 'Xray', 'MouseTP', 'MurderMystery', 'SpinBot', 'Anti-AFK'} do
	vape:Remove(name);
end;


velo.run(function(): ()
