	local AnimationTween: table;
	local Limit: table;
	local SwingOnly: table;
	local HitSound: table;
	local HitSoundType: table;
	local HitSoundVolume: table;

	local hitBudget: number = 60 / config.RemoteLimit;
	local soundFolder: string = 'velo/sounds';
	local hitSounds: {[string]: any} = {
		["skeet.cc"] = 'rbxassetid://5447626464',
		["baimware"] = 'rbxassetid://6607339542',
		["neverlose"] = 'rbxassetid://6607204501',
		["rust"] = 'rbxassetid://5043539486',
