		["sit"] = {'sit.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/sit.mp3'},
		["osu"] = {'osu.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/osu.mp3'},
