		["zing"] = {'zing.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/animezing.mp3'},
		["crowbar"] = {'crowbar.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/crowbar.mp3'},
		["laugh"] = {'laugh.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/laugh.mp3'},
		["burp"] = {'burp.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/burp.mp3'},
		["mario"] = {'mario.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/mariowoahh.mp3'},
		["huh"] = {'huh.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/huhh.mp3'},
		["ara ara"] = {'ara.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/ara.mp3'},
		["aimhook"] = {'nv.mp3', 'https://raw.githubusercontent.com/Storm99999/whitelistkeys/main/aimhook/sounds/Track.mp3'}
	};
	local hitSoundIds: {[string]: string} = {};
	local scanInterval: number = 1 / 75;
	local flat: Vector3 = Vector3.new(1, 0, 1);
	local parked: Vector3 = Vector3.new(9e9, 9e9, 9e9);
	local fixedSpeeds: {[string]: number} = {["frosty_hammer"] = 0.3};
	local furyScale: number = 1 - (bedwars.BlackMarketeerBalance.FURY_POTION_ATTACK_SPEED_MULTIPLIER - 1);
	local lag: table = {["Target"] = 0.12, ["Self"] = 0.09, ["SelfLow"] = 0.07, ["SelfHigh"] = 0.11, ["Claim"] = 0.05, ["Cap"] = 8, ["Trail"] = 0.3};
	local slack: table = {["Server"] = 3.6, ["Range"] = 0.4, ["Claim"] = 1};
	local tuning: table = {
		["Window"] = 8,
		["FloorWindow"] = 32,
		["ExcessCap"] = 0.25,
		["FloorSlack"] = 0.01,
		["HoldCap"] = 0.18,
		["OutlierSamples"] = 4,
		["OutlierGap"] = 0.1,
		["GuardPing"] = 0.12,
		["LockTick"] = 1 / 60,
		["LockDrift"] = 0.004,
		["LockNudge"] = 0.0005,
		["LockPhase"] = 0.0085,
		["LockEdge"] = 0.0035,
		["LockFloor"] = 0.25,
		["LockGhost"] = 0.3,
		["LockPing"] = 0.2
	};
	local kitAmmo: {table} = {
		{["Option"] = 'Use sophia', ["Names"] = {'frost staff'}},
		{["Option"] = 'Use whim', ["Names"] = {'mage spellbook'}},
		{["Option"] = 'Use nazar', ["Names"] = {'life bow', 'life crossbow', 'life headhunter'}},
		{["Option"] = 'Use umeko', ["Names"] = {'ninja chakram'}},
		{["Option"] = 'Use Lasso', ["Names"] = {'lasso'}}
	};

	local auraanims: table = vape.Libraries.auraanims;
	local swordEffect: (...any) -> ...any = rawget(rawget(getmetatable(bedwars.SwordController), '__index'), 'playSwordEffect');
	local rng: Random = Random.new();
	local boxes: {BoxHandleAdornment} = {};
	local boxShown: {[BoxHandleAdornment]: boolean} = {};
	local particles: {Part} = {};
	local attacked: {table} = {};
	local swingOnlyTargets: {table} = {};
	local targetPool: {table} = {};
	local trail: table = {["Times"] = {}, ["Points"] = {}};
	local characterParts: {[Model]: {Instance}} = {};
	local circle: MeshPart?;
	local state: table = {};
	local frame: table = {};
	local aim: table = {["Since"] = 0, ["Found"] = 0, ["Rotating"] = false};
	local arm: table = {["Index"] = 0, ["Running"] = false};
	local hitreg: table = {
		["Ghosts"] = {},
		["Pending"] = {},
		["Transit"] = {},
		["Recent"] = {},
		["Stamps"] = {},
		["Lock"] = {["Sends"] = {}, ["Frame"] = 0}
	};
	local serverTick: number = 1 / 60;
	local follow: table = {["Watch"] = {}, ["Stats"] = {}};
	local boxAnchors: {[BoxHandleAdornment]: Part} = {};

	local resetHitreg: () -> () = function(): ()
		hitreg.GhostDelay, hitreg.GhostHold, hitreg.GhostStep, hitreg.GhostCount, hitreg.GhostWindow = 0, 0, 0, 0, 0;
		hitreg.Deadline, hitreg.TransitMin, hitreg.ConfirmMin, hitreg.Spread, hitreg.Outliers = 0, nil, nil, 0, 0;
		for _: number, list: table in {hitreg.Ghosts, hitreg.Pending, hitreg.Transit, hitreg.Recent, hitreg.Stamps, hitreg.Lock.Sends} do
			table.clear(list);
		end;
		local lock: table = hitreg.Lock;
		lock.Target, lock.Sent, lock.Stamp, lock.Searching, lock.Offset = 0, 0, 0, true, nil;
		lock.Space = tuning.LockTick * 17 + tuning.LockDrift;
	end;
	resetHitreg();

	local hitLifetime: () -> number = function(): number
		return math.max(2, lplr:GetNetworkPing() * 2 + 0.3, (hitreg.ConfirmMin or 0) + hitreg.Spread + 0.5);
	end;

	local setMobileSwing: (visible: boolean) -> () = function(visible: boolean): ()
		local mobile: Instance? = inputService.TouchEnabled and lplr.PlayerGui:FindFirstChild('MobileUI');
		local button: Instance? = mobile and mobile:FindFirstChild('2');
		if button then
			button.Visible = visible;
		end;
	end;

	local trailAt: (moment: number, fallback: Vector3) -> Vector3 = function(moment: number, fallback: Vector3): Vector3
		local times: {number}, points: {Vector3} = trail.Times, trail.Points;
		if #times == 0 then
			return fallback;
		end;
		if moment <= times[1] then
			return points[1];
		end;
		for index: number = #times, 2, -1 do
			if times[index - 1] <= moment then
				local span: number = times[index] - times[index - 1];
				return points[index - 1]:Lerp(points[index], span > 0 and math.clamp((moment - times[index - 1]) / span, 0, 1) or 1);
			end;
		end;
		return points[#points];
	end;

	local serverView: (seen: Vector3, velocity: Vector3, fallback: Vector3) -> (Vector3, number, Vector3) = function(seen: Vector3, velocity: Vector3, fallback: Vector3): (Vector3, number, Vector3)
		local now: number = os.clock();
		local low: Vector3, high: Vector3 = trailAt(now - lag.SelfLow, fallback), trailAt(now - lag.SelfHigh, fallback);
		local lagged: (seconds: number) -> Vector3 = function(seconds: number): Vector3
			local offset: Vector3 = velocity * seconds;
			return offset.Magnitude > lag.Cap and offset.Unit * lag.Cap or offset;
		end;
		local reference: Vector3 = seen - lagged(lag.Target);
		local distance: number = math.max((seen - low).Magnitude, (seen - high).Magnitude, (reference - low).Magnitude, (reference - high).Magnitude);
		return seen - lagged(lag.Claim), distance, trailAt(now - lag.Self, fallback);
	end;

	local validTarget: (ent: table) -> boolean = function(ent: table): boolean
		local character: Model? = ent.Character;
		local drops: Instance? = workspace:FindFirstChild('ItemDrops');
		return character ~= nil and character:IsA('Model') and character.Parent ~= nil and ent.RootPart ~= nil and ent.RootPart:IsDescendantOf(character)
			and ent.Health > 0 and ent.Targetable == true and entitylib.isVulnerable(ent)
			and not character:HasTag('ItemDrop') and not ent.RootPart:HasTag('ItemDrop') and not (drops and character:IsDescendantOf(drops));
	end;

	local withinAngle: (delta: Vector3, facing: Vector3) -> boolean = function(delta: Vector3, facing: Vector3): boolean
		local planar: Vector3 = delta * flat;
		return planar.Magnitude <= 0.001 or facing.Magnitude <= 0.001 or math.acos(math.clamp(facing.Unit:Dot(planar.Unit), -1, 1)) <= math.rad(AngleSlider["Value"]) / 2;
	end;

	local playSwing: (sword: table, meta: table) -> () = function(sword: table, meta: table): ()
		local delay: number = PerfectSwing["Enabled"] and math.max(meta.sword and meta.sword.attackSpeed or 0.11, 0.11) or math.max(SwingTime:GetRandomValue(), 0.11);
		state.AnimDelay = tick() + delay;
		state.SwingGap = delay;
		local tinker: table? = bedwars.TinkerKitController;
		local mount: any = tinker and tinker.userMap and tinker.userMap[lplr];
		if typeof(mount) ~= 'Instance' or not mount.Parent then
			mount = nil;
			for _: number, child: Instance in (lplr.Character and lplr.Character:GetChildren() or {}) do
				if child:IsA('Model') and child.Name:match('tinker$') then
					mount = child;
					break;
				end;
			end;
		end;
		if mount then
			state.AnimDelay = tick() + math.max(delay, 0.35);
			bedwars.AudioManager:playAudio(bedwars.SoundList.DRILL_ATTACK_1);
			bedwars.MountAnimationController:playAnimationInMount(mount, bedwars.AnimationType.TINKER_ATTACK, 1.85);
			return;
		end;
		bedwars.SwordController:playSwordEffect(meta, false, {["itemSkin"] = sword.itemSkin});
		if (meta.displayName or ''):find(' Scythe') then
			bedwars.ScytheController:playLocalAnimation();
		end;
	end;

	local selectSword: () -> (table?, table?) = function(): (table?, table?)
		if not entitylib.isAlive then
			return nil, nil;
		end;
		local sinceSwing: number = tick() - bedwars.SwordController.lastSwing;
		if Mouse["Enabled"] and not inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and sinceSwing > 0.3 then
			return nil, nil;
		end;
		if (AfkCheck["Enabled"] and isAfk()) or (GuiCheck["Enabled"] and bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)) then
			return nil, nil;
		end;
		local character: Model = lplr.Character;
		if Attackable["Enabled"] and ((character:GetAttribute('StunnedUntilTime') or 0) > workspace:GetServerTimeNow() or character:FindFirstChild('elk') or bedwars.StatusEffectUtil:isActive(character, 'frozen')) then
			return nil, nil;
		end;
		local sword: table? = Limit["Enabled"] and store.hand or store.tools.sword;
		if not sword or not sword.tool then
			return nil, nil;
		end;
		if Limit["Enabled"] and (store.hand.toolType ~= 'sword' or bedwars.DaoController.chargingMaid) then
			return nil, nil;
		end;
		if SwingOnly["Enabled"] and sinceSwing > 0.2 then
			return nil, nil;
		end;
		return sword, bedwars.ItemMeta[sword.tool.Name];
	end;

	local onDamage: (damage: table) -> () = function(damage: table): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		if damage.fromEntity ~= lplr.Character or damage.damageType ~= 0 then
			return;
		end;
		state.StatLanded += 1;
		local watched: Instance? = damage.entityInstance;
		local watch: table? = watched and follow.Watch[watched];
		if watch then
			local hitStamp: any = watched:GetAttribute('LastDamageTakenTime');
			if os.clock() > watch.Expire then
				follow.Watch[watched] = nil;
			elseif type(hitStamp) == 'number' and hitStamp >= watch.Server - 0.01 then
				watch.Seen += 1;
				if watch.Seen >= 2 and watch.Sent then
					follow.Watch[watched] = nil;
					local stats: table = follow.Stats[watch.Key];
					stats.Landed += 1;
					if stats.Landed == 1 then
						notif('DoubleHit', 'Follow-up hits are landing'..(watch.Swap and ' with weapon swap.' or '.'), 4);
					end;
					return;
				end;
			end;
		end;
		table.remove(hitreg.Ghosts, 1);
		local victim: Instance? = damage.entityInstance;
		local stamp: any = victim and victim:GetAttribute('LastDamageTakenTime');
		if type(stamp) ~= 'number' or stamp ~= stamp then
			return;
		end;

		local lock: table = hitreg.Lock;
		for index: number, send: table in (stamp > lock.Stamp and lock.Sends or {}) do
			if not send.Done and stamp >= send.Server - 0.05 and stamp <= send.Server + 0.24 then
				send.Done = true;
				local previous: table? = lock.Sends[index - 1];
				local extra: number = previous and previous.Done and lock.Stamp > 0 and math.round((stamp - lock.Stamp) / tuning.LockTick) - math.round((send.Server - previous.Server) / tuning.LockTick) or 0;
				local offset: number = stamp - send.Server;
				local spike: boolean = lock.Searching and extra == 1 and lock.Offset ~= nil and (lock.Offset - tuning.LockDrift + tuning.LockTick - offset) > tuning.LockEdge;
				lock.Offset = offset - (lock.Searching and extra > 0 and extra * tuning.LockTick or 0);
				if extra == 1 and lock.Searching and not spike then
					lock.Searching = false;
					lock.Space = tuning.LockTick * 17;
					lock.Target += tuning.LockTick - tuning.LockDrift * 0.5 - tuning.LockPhase;
				elseif extra >= 1 and extra <= 45 then
					lock.Target += extra * tuning.LockTick - (lock.Searching and 0 or tuning.LockNudge);
				end;
				lock.Stamp = stamp;
				break;
			end;
		end;

		local received: number = os.clock();
		local lifetime: number = hitLifetime();
		local center: number = hitreg.TransitMin and hitreg.TransitMin + hitreg.Spread * 0.5 or 0;
		local lowest: number = hitreg.TransitMin and hitreg.TransitMin - tuning.FloorSlack or -math.huge;
		local selected: number?, best: number = nil, math.huge;
		for pass: number = 1, 2 do
			for index: number, entry: table in hitreg.Pending do
				local implied: number = stamp - entry.Timer;
				local elapsed: number = received - entry.Timer;
				if entry.Target == victim and elapsed >= 0 and elapsed < lifetime and (pass == 2 or implied >= lowest) then
					local difference: number = hitreg.TransitMin and math.abs(implied - center) or index - 1;
					if difference < best then
						selected, best = index, difference;
					end;
				end;
			end;
			if selected then
				break;
			end;
		end;
		local previousStamp: number? = hitreg.Stamps[victim];
		hitreg.Stamps[victim] = stamp;
		if not selected then
			return;
		end;

		local entry: table = hitreg.Pending[selected];
		local transit: number = stamp - entry.Timer;
		local usable: boolean = not (previousStamp and stamp <= previousStamp);
		if usable and #hitreg.Recent >= tuning.OutlierSamples then
			local sorted: {number} = table.clone(hitreg.Recent);
			table.sort(sorted);
			if transit < sorted[(#sorted + 1) // 2] - tuning.OutlierGap then
				hitreg.Outliers += 1;
				if hitreg.Outliers > 2 then
					hitreg.Outliers = 0;
					table.clear(hitreg.Recent);
					table.clear(hitreg.Transit);
					hitreg.TransitMin = nil;
				else
					usable = false;
				end;
			else
				hitreg.Outliers = 0;
			end;
		end;
		for _: number = 1, selected do
			table.remove(hitreg.Pending, 1);
		end;
		if not usable then
			return;
		end;

		table.insert(hitreg.Transit, transit);
		if #hitreg.Transit > tuning.Window then
			table.remove(hitreg.Transit, 1);
		end;
		table.insert(hitreg.Recent, transit);
		if #hitreg.Recent > tuning.FloorWindow then
			table.remove(hitreg.Recent, 1);
		end;
		local floor: number = math.min(transit, table.unpack(hitreg.Recent));
		local minimum: number, maximum: number = math.min(transit, table.unpack(hitreg.Transit)), math.max(transit, table.unpack(hitreg.Transit));
		local confirmation: number = received - entry.Timer;
		hitreg.Spread = maximum - minimum;
		hitreg.TransitMin = math.min(hitreg.TransitMin and hitreg.TransitMin + 0.001 or transit, transit);
		hitreg.ConfirmMin = math.min(hitreg.ConfirmMin and hitreg.ConfirmMin + 0.001 or confirmation, confirmation);
		hitreg.Deadline = math.max(hitreg.Deadline, entry.Sent + entry.Gap + math.clamp(transit - floor, 0, tuning.ExcessCap));
	end;

	local fastHit: (ent: table) -> () = function(ent: table): ()
		local filter: {string} = table.clone(Projectiles.ListEnabled);
		for _: number, kit: table in kitAmmo do
			for _: number, name: string in (Killaura.Options[kit.Option]["Enabled"] and kit.Names or {}) do
				table.insert(filter, name);
			end;
		end;
		local shots: {table} = getProjectiles(filter, UseSophia["Enabled"] or UseUmeko["Enabled"]);
		if #shots == 0 then
			return;
		end;
		state.ShotIndex = shots[state.ShotIndex + 1] and state.ShotIndex + 1 or 1;
		local shot: table = shots[state.ShotIndex];
		local meta: table? = bedwars.ProjectileMeta[shot.Projectile];
		if tick() <= (state.FireRates[shot.Item.itemType] or 0) or not meta or type(meta.launchVelocity) ~= 'number' then
			return;
		end;
		local slot: number? = hotbarSlotOf(shot.Item.tool);
		local oldSlot: number?, oldTool: Instance? = store.inventory.hotbarSlot, store.hand.tool;
		state.Shooting = true;
		if slot then
			switchItem(shot.Item.tool, 0);
		end;
		task.delay(0.1, function(): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			if LegitSwitch["Enabled"] and slot then
				hotbarSwitch(slot);
			end;
			if Killaura["Enabled"] and validTarget(ent) and ballistics.fire(shot.Item, shot.Ammo, shot.Projectile, ent) then
				ballistics.launchSound(shot.Item, shot.Source);
				state.FireRates[shot.Item.itemType] = tick() + (shot.Source.fireDelaySec or 0.1);
				state.LastShot = tick() + FireRate["Value"];
			end;
			if oldTool then
				switchItem(oldTool, 0);
			end;
			if LegitSwitch["Enabled"] then
				hotbarSwitch(oldSlot);
			end;
			state.Shooting = false;
		end);
	end;

	local hitSoundId: (name: string) -> string? = function(name: string): string?
		local entry: any = hitSounds[name];
		if type(entry) ~= 'table' then
			return entry;
		end;
		if not hitSoundIds[name] then
			local path: string = soundFolder..'/'..entry[1];
			if not isfile(path) then
				if not isfolder(soundFolder) then
					makefolder(soundFolder);
				end;
				writefile(path, game:HttpGet(entry[2], true));
			end;
			hitSoundIds[name] = getcustomasset(path);
		end;
		return hitSoundIds[name];
	end;

	local aimAt: (ent: table) -> (Vector3?, Vector3?, Vector3?) = function(ent: table): (Vector3?, Vector3?, Vector3?)
		local root: BasePart? = lplr.Character and lplr.Character.PrimaryPart;
		local actual: BasePart? = ent.Character and ent.Character.PrimaryPart;
		if not entitylib.isAlive or root ~= frame.Root or not actual or not validTarget(ent) then
			return nil, nil, nil;
		end;
		local claim: Vector3, serverDistance: number, selfClaim: Vector3 = serverView(actual.Position, ent.RootPart.AssemblyLinearVelocity, store.rootpart and store.rootpart.Position or root.Position);
		if serverDistance > frame.RangeLimit or not withinAngle(ent.RootPart.Position - root.Position, root.CFrame.LookVector * flat) then
			return nil, nil, nil;
		end;
		local reachDelta: Vector3 = claim - selfClaim;
		local direction: Vector3 = reachDelta.Magnitude > 0.001 and reachDelta.Unit or Vector3.new(0, -1, 0);
		return claim, claim - direction * math.min(reachDelta.Magnitude, frame.Reach - slack.Claim), direction;
	end;

	local sendHit: (ent: table, claim: Vector3, hitPosition: Vector3, direction: Vector3, weapon: Instance?) -> () = function(ent: table, claim: Vector3, hitPosition: Vector3, direction: Vector3, weapon: Instance?): ()
		fire('SwordHit', 'SendToServer', {
			["weapon"] = weapon or frame.Sword.tool,
			["chargedAttack"] = {["chargeRatio"] = 0},
			["entityInstance"] = ent.Character,
			["validate"] = {
				["raycast"] = {
					["cameraPosition"] = {["value"] = hitPosition},
					["cursorDirection"] = {["value"] = direction}
				},
				["targetPosition"] = {["value"] = claim},
				["selfPosition"] = {["value"] = hitPosition}
			}
		});
	end;

	local altSword: (current: table) -> table? = function(current: table): table?
		local best: table?, bestDamage: number = nil, -1;
		for _: number, item: table in store.inventory.inventory.items do
			local meta: table? = bedwars.ItemMeta[item.itemType];
			local damage: number = meta and meta.sword and meta.sword.damage or -1;
			if item.tool and item.tool ~= current.tool and damage > bestDamage then
				best, bestDamage = item, damage;
			end;
		end;
		return best;
	end;

	local followUp: (ent: table, sentAt: number, hitDelay: number) -> () = function(ent: table, sentAt: number, hitDelay: number): ()
		local main: table = frame.Sword;
		local weapon: table? = DoubleSwap["Enabled"] and altSword(main) or main;
		if not weapon or (DoubleSwap["Enabled"] and weapon == main) then
			return;
		end;
		local swapped: boolean = weapon ~= main;
		local key: string = (swapped and 'swap:' or 'same:')..main.itemType;
		local stats: table = follow.Stats[key] or {["Sent"] = 0, ["Landed"] = 0, ["Warned"] = false};
		follow.Stats[key] = stats;
		if (stats.Landed == 0 and stats.Sent >= 12) or rng:NextNumber(0, 100) > DoubleChance["Value"] then
			return;
		end;
		local meta: table? = bedwars.ItemMeta[main.itemType];
		local window: number = meta and meta.sword and meta.sword.multiHitCheckDurationSec or 0;
		local delay: number = DoubleDelay["Value"] / 1000;
		if delay <= 0 then
			delay = (swapped or window <= serverTick * 2) and serverTick or window * 0.5;
		end;
		delay = math.clamp(delay, serverTick, math.max(hitDelay - serverTick * 2, serverTick));
		local victim: Model = ent.Character;
		local tracked: boolean = type(victim:GetAttribute('LastDamageTakenTime')) == 'number';
		local watch: table = {["Seen"] = 0, ["Sent"] = false, ["Key"] = key, ["Swap"] = swapped, ["Server"] = bedwars.SwordController.lastAttack, ["Expire"] = os.clock() + delay + lplr:GetNetworkPing() * 2 + 0.4};
		if tracked then
			follow.Watch[victim] = watch;
		end;
		task.delay(delay, function(): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			if not (Killaura["Enabled"] and DoubleHit["Enabled"]) or state.Shooting or state.LastHit ~= sentAt or not (weapon.tool and weapon.tool.Parent) then
				return;
			end;
			local followClaim: Vector3?, followHit: Vector3?, followDirection: Vector3? = aimAt(ent);
			if not followClaim then
				return;
			end;
			watch.Sent = true;
			sendHit(ent, followClaim, followHit, followDirection, weapon.tool);
			if not tracked then
				return;
			end;
			stats.Sent += 1;
			if stats.Sent >= 12 and stats.Landed == 0 and not stats.Warned then
				stats.Warned = true;
				notif('DoubleHit', 'Server rejected 12 follow-ups'..(swapped and ' with weapon swap' or '')..' on '..main.itemType..', paused for that sword.', 6, 'warning');
			end;
		end);
	end;

	local strike: (target: table) -> () = function(target: table): ()
		local ent: table = target.Entity;
		local high: boolean = HighHitreg["Enabled"];
		local ping: number = lplr:GetNetworkPing();
		local gameCooldown: number = math.max(bedwars.SwordController.lastAttack + frame.Cooldown - workspace:GetServerTimeNow(), 0);
		local hitDelay: number = math.max(hitBudget, frame.Spacing + hitreg.GhostDelay, ChargeTime["Value"], gameCooldown);
		if DynamicHits["Enabled"] then
			hitDelay = math.max(math.min(hitDelay * math.min(target.Delta.Magnitude, frame.Reach) / math.max(frame.Reach, 0.001), hitDelay), frame.GapMin);
		end;
		local deadline: number = math.max(state.SwingCooldown + hitDelay, state.LastHit + frame.GapMin, tick() + gameCooldown);
		local tracked: boolean = type(ent.Character:GetAttribute('LastDamageTakenTime')) == 'number';
		if tracked then
			deadline = math.max(deadline, math.min(hitreg.Deadline, state.LastHit + hitDelay + tuning.HoldCap));
		end;
		local lock: table = hitreg.Lock;
		local locked: boolean = frame.Stock and high and ping < tuning.LockPing;
		if locked then
			local latest: table? = lock.Sends[#lock.Sends];
			if latest and not latest.Done and os.clock() - lock.Sent > 0.25 + lock.Frame * 2 then
				latest.Done = true;
				lock.Stamp, lock.Offset, lock.Searching = 0, nil, true;
				lock.Space = tuning.LockTick * 17 + tuning.LockDrift;
				lock.Target = lock.Sent + tuning.LockGhost;
			end;
			local behind: number = os.clock() - lock.Target;
			if lock.Target > 0 and behind > 0.05 then
				if behind < 10 then
					lock.Target += math.ceil(behind / tuning.LockTick) * tuning.LockTick;
				else
					lock.Target, lock.Stamp, lock.Searching, lock.Offset = 0, 0, true, nil;
					lock.Space = tuning.LockTick * 17 + tuning.LockDrift;
				end;
			end;
			deadline = math.max(state.LastHit + tuning.LockFloor, tick() + lock.Target - os.clock());
		end;
		local pending: table? = hitreg.Pending[#hitreg.Pending];
		local waiting: boolean = tracked and frame.Stock and high and ping >= tuning.GuardPing and pending ~= nil and #hitreg.Pending < 3 and hitreg.ConfirmMin ~= nil and hitreg.ConfirmMin + state.FrameTime < hitDelay and pending.Sent == state.LastHit;
		if waiting then
			deadline = math.max(deadline, state.LastHit + hitDelay + 0.04);
		end;
		local remaining: number = deadline - tick();
		local frameSpan: number = locked and math.max(state.FrameTime, lock.Frame) or math.min(state.FrameTime, lock.Frame);
		if frame.Stock and high and not waiting and remaining > 0 and remaining < math.min(frameSpan, 0.25) then
			local finish: number = os.clock() + remaining;
			repeat until os.clock() >= finish;
		end;
		if tick() < deadline then
			return;
		end;

		local claim: Vector3?, hitPosition: Vector3?, direction: Vector3? = aimAt(ent);
		if not claim then
			return;
		end;
		local delta: Vector3 = ent.RootPart.Position - frame.Root.Position;
		local airborne: boolean = ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(ent.RootPart.AssemblyLinearVelocity.Y) > 0.01;

		bedwars.SwordController.lastAttack = workspace:GetServerTimeNow();
		state.LastAttack = tick();
		store.attackReach = math.floor(delta.Magnitude * 100) / 100;
		store.attackReachUpdate = tick() + 1;
		state.SwingCooldown = math.max(state.SwingCooldown + hitDelay, tick() - (frame.Stock and high and math.min(state.FrameTime, hitDelay - swordtiming.HitFloor * frame.Scale) or 0));
		state.LastHit = tick();

		if airborne and rng:NextNumber(0, 100) > AirHits:GetRandomValue() then
			fire('SwordSwingMiss', nil, {["weapon"] = frame.Sword.tool, ["chargeRatio"] = 0});
			return;
		end;
		if tracked then
			local lifetime: number = hitLifetime();
			local cap: number = math.max(8, math.ceil(lifetime / frame.Spacing) + 2);
			for _: number = 1, #hitreg.Pending do
				if os.clock() - hitreg.Pending[1].Timer <= lifetime and #hitreg.Pending < cap then
					break;
				end;
				table.remove(hitreg.Pending, 1);
			end;
			table.insert(hitreg.Pending, {["Target"] = ent.Character, ["Sent"] = state.LastHit, ["Timer"] = os.clock(), ["Gap"] = swordtiming.ArrivalFloor * frame.Scale});
			local timeout: number = math.max(0.3 + store.ping.total, ping * 2 + 0.3);
			table.insert(hitreg.Ghosts, tick() + (hitreg.ConfirmMin and timeout or math.max(timeout, lifetime)));
		end;
		if locked then
			local now: number = os.clock();
			if lock.Target == 0 or math.abs(now - lock.Target) > 0.05 then
				lock.Target = now;
			end;
			lock.Target += lock.Space;
			lock.Sent = now;
			table.insert(lock.Sends, {["Server"] = workspace:GetServerTimeNow(), ["Done"] = false});
			if #lock.Sends > 6 then
				table.remove(lock.Sends, 1);
			end;
		end;
		sendHit(ent, claim, hitPosition, direction);
		state.StatSent += 1;
		if DoubleHit["Enabled"] then
			followUp(ent, state.LastHit, hitDelay);
		end;
		if FastHits["Enabled"] and not state.Shooting and tick() > state.LastShot then
			fastHit(ent);
		end;
	end;

	local animateArm: () -> ();
	animateArm = function(): ()
		local wrist: Motor6D? = arm.Wrist;
		if not (Killaura["Enabled"] and Animation["Enabled"] and store.attacking and wrist and wrist.Parent) then
			if arm.Running and wrist and wrist.Parent then
				tweenService:Create(wrist, TweenInfo.new(AnimationTween["Enabled"] and 0.001 or 0.3, Enum.EasingStyle.Exponential), {["C0"] = arm.C0}):Play();
			end;
			arm.Running = false;
			return;
		end;
		if AnimationMode["Value"] == 'Random' then
			auraanims.Random = {{["CFrame"] = CFrame.Angles(math.rad(math.random(1, 360)), math.rad(math.random(1, 360)), math.rad(math.random(1, 360))), ["Time"] = 0.12}};
		end;
		local keyframes: {table} = auraanims[AnimationMode["Value"]];
		local first: boolean = not arm.Running;
		arm.Running = true;
		arm.Index = first and 1 or arm.Index % #keyframes + 1;
		local keyframe: table = keyframes[arm.Index] or keyframes[1];
		local duration: number = first and (AnimationTween["Enabled"] and 0.001 or 0.1) or keyframe.Time / math.max(AnimationSpeed["Value"], 0.1);
		local motion: Tween = tweenService:Create(wrist, TweenInfo.new(duration, Enum.EasingStyle.Linear), {["C0"] = arm.C0 * keyframe.CFrame});
		motion.Completed:Once(function(playback: Enum.PlaybackState): ()
			if playback == Enum.PlaybackState.Completed then
				animateArm();
			end;
		end);
		motion:Play();
	end;

	local updateVisuals: () -> () = function(): ()
		for index: number, box: BoxHandleAdornment in boxes do
			local target: table? = attacked[index];
			if target and not boxShown[box] then
				box.Size = Vector3.zero;
				tweenService:Create(box, TweenInfo.new(BoxStartSpeed["Value"], Enum.EasingStyle[BoxTween["Value"]]), {["Size"] = Vector3.new(4, 6, 4)}):Play();
			elseif not target and boxShown[box] then
				tweenService:Create(box, TweenInfo.new(BoxEndSpeed["Value"], Enum.EasingStyle[BoxTween["Value"]]), {["Size"] = Vector3.zero}):Play();
			end;
			boxShown[box] = target ~= nil;
			if target then
				local anchor: Part = boxAnchors[box];
				anchor.CFrame = target.Entity.RootPart.CFrame;
				anchor.Parent = gameCamera;
				box.Color3 = Color3.fromHSV(target.Check["Hue"], target.Check["Sat"], target.Check["Value"]);
				box.Transparency = 1 - target.Check["Opacity"];
			end;
		end;
		for index: number, part: Part in particles do
			local target: table? = attacked[index];
			part.Position = target and target.Entity.RootPart.Position or parked;
			part.Parent = target and gameCamera or nil;
		end;
		if circle and entitylib.isAlive then
			circle.Size = Vector3.new(AttackRange["Value"] * 0.7, 0.01, AttackRange["Value"] * 0.7);
			circle.Position = entitylib.character.RootPart.Position - Vector3.new(0, entitylib.character.Humanoid.HipHeight, 0);
		end;
	end;

	local refreshCircle: () -> () = function(): ()
		if circle and not (Killaura["Enabled"] and RangeVisualizer["Enabled"]) then
			circle:Destroy();
			circle = nil;
		elseif not circle and Killaura["Enabled"] and RangeVisualizer["Enabled"] then
			local ring: MeshPart = Instance.new('MeshPart');
			ring.MeshId = 'rbxassetid://3726303797';
			ring.Color = Color3.fromHSV(RangeColor["Hue"], RangeColor["Sat"], RangeColor["Value"]);
			ring.Transparency = 1 - RangeColor["Opacity"];
			ring.CanCollide = false;
			ring.CanQuery = false;
			ring.Anchored = true;
			ring.Material = Enum.Material.Neon;
			ring.Parent = gameCamera;
			bedwars.QueryUtil:setQueryIgnored(ring, true);
			circle = ring;
		end;
	end;

	local step: (delta: number) -> () = function(delta: number): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local now: number = tick();
		hitreg.Lock.Frame = delta;
		if state.FrameTime == 0 then
			state.FrameTime = HighHitreg["Enabled"] and delta or 1 / 240;
			state.FrameWindow = now;
		end;
		state.FrameCount += 1;
		if now - state.FrameWindow >= 0.25 then
			state.FrameTime += ((now - state.FrameWindow) / state.FrameCount - state.FrameTime) * 0.1;
			state.FrameCount, state.FrameWindow = 0, now;
		end;
		if state.Shooting then
			return;
		end;

		table.clear(attacked);
		store.attacking = false;
		store.KillauraTarget = nil;
		local sword: table?, meta: table? = selectSword();
		local high: boolean = HighHitreg["Enabled"];
		if sword and meta then
			local root: BasePart = lplr.Character.PrimaryPart or entitylib.character.RootPart;
			local clock: number = os.clock();
			local times: {number}, points: {Vector3} = trail.Times, trail.Points;
			if #times > 0 and clock - times[#times] > 0.25 then
				table.clear(times);
				table.clear(points);
			end;
			table.insert(times, clock);
			table.insert(points, (store.rootpart or root).Position);
			for _: number = 1, #times do
				if #times <= 2 or clock - times[2] < lag.Trail then
					break;
				end;
				table.remove(times, 1);
				table.remove(points, 1);
			end;
			if clock - state.ScanClock >= scanInterval then
				state.Entities = entitylib.AllPosition({
					["Origin"] = root.Position,
					["Range"] = SwingRange["Value"],
					["Wallcheck"] = Targets.Walls["Enabled"] or nil,
					["Part"] = 'RootPart',
					["Players"] = Targets.Players["Enabled"],
					["NPCs"] = Targets.NPCs["Enabled"],
					["Sort"] = sortMethods[Sort["Value"]]
				});
				state.ScanClock = clock;
			end;

			if #state.Entities > 0 then
				if store.hand.tool ~= sword.tool then
					local slot: number? = LegitSwitch["Enabled"] and hotbarSlotOf(sword.tool);
					if slot then
						bedwars.Store:dispatch({["type"] = 'InventorySelectHotbarSlot', ["slot"] = slot});
						return;
					end;
				end;
				switchItem(sword.tool, 0);
				local fury: number = bedwars.StatusEffectUtil:isActive(lplr.Character, 'fury_potion') and furyScale or 1;
				local spacing: number, scale: number, gapMin: number, cooldown: number, stock: boolean = swordtiming.Calculate(fixedSpeeds[sword.tool.Name] or meta.sword and meta.sword.attackSpeed or 0.3, fury, high, hitBudget);
				if stock and high then
					gapMin = math.max(gapMin + hitreg.GhostDelay, ChargeTime["Value"]);
				end;
				local band: number = (high and 10 / 34 or 10 / 33) * scale;
				local bandFrames: number = math.floor(band / state.FrameTime);
				if stock and math.ceil(spacing / state.FrameTime) * state.FrameTime > band and bandFrames * state.FrameTime >= math.max(high and 10 / 35 or 10 / 34, swordtiming.HighSpacing) * scale then
					spacing = math.max(bandFrames * state.FrameTime - state.FrameTime * 0.5, swordtiming.GapFloor * scale);
				end;
				frame.Sword, frame.Root, frame.Spacing, frame.Scale, frame.GapMin, frame.Cooldown, frame.Stock = sword, root, spacing, scale, gapMin, cooldown, stock;
				frame.Reach = getReach(sword.tool);
				frame.RangeLimit = math.min(AttackRange["Value"], frame.Reach + slack.Server - slack.Range);

				local sendPosition: Vector3 = store.rootpart and store.rootpart.Position or root.Position;
				local facing: Vector3 = root.CFrame.LookVector * flat;
				table.clear(swingOnlyTargets);
				for _: number, ent: table in state.Entities do
					if #attacked >= MaxTargets["Value"] then
						break;
					end;
					if not validTarget(ent) then
						continue;
					end;
					local offset: Vector3 = ent.RootPart.Position - root.Position;
					if not withinAngle(offset, facing) then
						continue;
					end;
					local actual: BasePart? = ent.Character.PrimaryPart;
					local _: Vector3, distance: number = serverView(actual and actual.Position or ent.RootPart.Position, ent.RootPart.AssemblyLinearVelocity, sendPosition);
					local hittable: boolean = actual ~= nil and distance <= frame.RangeLimit;
					local slot: number = #attacked + #swingOnlyTargets + 1;
					local target: table = targetPool[slot] or {};
					targetPool[slot] = target;
					target.Entity, target.Delta, target.Hittable = ent, offset, hittable;
					target.Check = hittable and BoxAttackColor or BoxSwingColor;
					table.insert(hittable and attacked or swingOnlyTargets, target);
				end;
				for _: number, target: table in swingOnlyTargets do
					if #attacked >= MaxTargets["Value"] then
						break;
					end;
					table.insert(attacked, target);
				end;
				if Focus["Enabled"] then
					local damage: number = meta.sword and meta.sword.damage or 0;
					local lead: number? = nil;
					for index: number, target: table in attacked do
						if target.Hittable and target.Entity.Health <= damage then
							lead = index;
							break;
						end;
						if not lead and target.Hittable and target.Entity == state.Focus then
							lead = index;
						end;
					end;
					if lead and lead > 1 then
						table.insert(attacked, 1, table.remove(attacked, lead));
					end;
					if attacked[1] and attacked[1].Hittable then
						state.Focus = attacked[1].Entity;
					end;
				end;

				for index: number, target: table in attacked do
					local ent: table = target.Entity;
					targetinfo.Targets[ent] = tick() + 1;
					local swung: boolean = false;
					if index == 1 then
						store.attacking = true;
						store.KillauraTarget = ent;
						local planar: Vector3 = target.Delta * flat;
						if aim.Target ~= ent or (planar.Magnitude > 0 and facing.Magnitude > 0 and facing.Unit:Dot(planar.Unit) < -0.5) then
							aim.Target, aim.Since = ent, tick();
						end;
						aim.Found = tick();
						if not NoSwing["Enabled"] and state.AnimDelay < tick() and not SwingOnly["Enabled"] then
							playSwing(sword, meta);
							swung = true;
						end;
					end;
					if target.Hittable then
						strike(target);
					elseif swung then
						fire('SwordSwingMiss', nil, {["weapon"] = sword.tool, ["chargeRatio"] = 0});
					end;
				end;
			end;
		else
			state.ScanClock = 0;
		end;

		if #attacked == 0 then
			table.clear(hitreg.Ghosts);
		end;
		local ghosted: boolean = false;
		for _: number = 1, #hitreg.Ghosts do
			if tick() <= hitreg.Ghosts[1] then
				break;
			end;
			table.remove(hitreg.Ghosts, 1);
			ghosted = true;
		end;
		if ghosted then
			hitreg.GhostCount = (tick() < hitreg.GhostWindow and hitreg.GhostCount or 0) + 1;
			hitreg.GhostWindow = tick() + 5;
			if hitreg.GhostCount > 1 and tick() > hitreg.GhostStep then
				hitreg.GhostStep = tick() + 1;
				hitreg.GhostHold = tick() + (high and 2 or 10);
				hitreg.GhostDelay = math.min(hitreg.GhostDelay + (high and 0.001 or 0.003), high and 10 / 34 - swordtiming.HighSpacing or 0.1);
			end;
		elseif hitreg.GhostDelay > 0 and tick() > hitreg.GhostHold then
			hitreg.GhostHold = tick() + (high and 2 or 10);
			hitreg.GhostDelay = math.max(hitreg.GhostDelay - (high and 0.001 or 0.003), 0);
		end;

		if tick() - state.StatClock >= 10 then
			local span: number = tick() - state.StatClock;
			if HitStats["Enabled"] and state.StatSent > 0 then
				notif('Killaura', string.format('%d sent, %d landed (%d%%), %.2f landed/s, ghost +%dms, ping %dms', state.StatSent, state.StatLanded, math.floor(math.min(state.StatLanded / state.StatSent, 1) * 100), state.StatLanded / span, math.floor(hitreg.GhostDelay * 1000), math.floor(lplr:GetNetworkPing() * 1000)), 8);
			end;
			state.StatSent, state.StatLanded, state.StatClock = 0, 0, tick();
		end;
		if #attacked > 0 then
			state.ContinueUntil = tick() + ContinueSwing:GetRandomValue() / 1000;
		elseif sword and meta and tick() < state.ContinueUntil and state.AnimDelay < tick() and not NoSwing["Enabled"] and not SwingOnly["Enabled"] then
			playSwing(sword, meta);
			fire('SwordSwingMiss', nil, {["weapon"] = sword.tool, ["chargeRatio"] = 0});
		end;

		updateVisuals();
		if Face["Enabled"] and attacked[1] and entitylib.isAlive then
			local body: BasePart = lplr.Character.PrimaryPart or entitylib.character.RootPart;
			local look: Vector3 = attacked[1].Entity.RootPart.Position;
			body.CFrame = CFrame.lookAt(body.Position, Vector3.new(look.X, body.Position.Y + 0.001, look.Z));
		end;

		local viewmodel: Instance? = gameCamera:FindFirstChild('Viewmodel');
		local hand: Instance? = viewmodel and viewmodel:FindFirstChild('RightHand');
		local wrist: Instance? = hand and hand:FindFirstChild('RightWrist');
		if wrist ~= arm.Wrist then
			arm.Wrist, arm.C0, arm.Running = wrist, wrist and wrist.C0, false;
		end;
		if Animation["Enabled"] and store.attacking and wrist and not arm.Running then
			animateArm();
		end;
	end;

	local aimStep: (delta: number) -> () = function(delta: number): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local target: table? = aim.Target;
		local active: boolean = AimMode["Value"] ~= 'Off' and entitylib.isAlive and target ~= nil and target.RootPart ~= nil and target.RootPart.Parent ~= nil and tick() - aim.Found < 0.5;
		local silent: boolean = active and AimMode["Value"] == 'Silent';
		if silent ~= aim.Rotating and entitylib.isAlive then
			entitylib.character.Humanoid.AutoRotate = not silent;
			aim.Rotating = silent;
		end;
		if not active then
			return;
		end;
		local progress: number = math.min((tick() - aim.Since) * AimSpeed["Value"] * 0.5, 1);
		local speed: number = AimSpeed["Value"] * (progress < 0.5 and 4 * progress ^ 3 or 1 - (-2 * progress + 2) ^ 3 / 2);
		if silent then
			local root: BasePart = entitylib.character.RootPart;
			local direction: Vector3 = (target.RootPart.Position - root.Position) * flat;
			if direction.Magnitude > 0 then
				root.CFrame = root.CFrame:Lerp(CFrame.lookAlong(root.Position, direction), math.clamp((speed + 2) * delta, 0, 1));
			end;
			return;
		end;
		local point: Vector3 = target.RootPart.Position;
		if AimArea["Value"] == 'Closest' then
			local parts: {Instance} = characterParts[target.Character] or target.Character:GetChildren();
			characterParts[target.Character] = parts;
			local mouse: Vector2, closest: number = inputService:GetMouseLocation(), math.huge;
			for _: number, part: Instance in parts do
				if part.Parent and part:IsA('BasePart') then
					local screen: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(part.Position);
					local distance: number = (mouse - Vector2.new(screen.X, screen.Y)).Magnitude;
					if visible and distance < closest then
						closest, point = distance, part.Position;
					end;
				end;
			end;
		end;
		local jitter: Vector3 = Vector3.new(rng:NextNumber() - 0.5, rng:NextNumber() - 0.5, rng:NextNumber() - 0.5) * 15 * delta;
		gameCamera.CFrame = gameCamera.CFrame:Lerp(CFrame.lookAt(gameCamera.CFrame.Position, point + jitter), math.clamp(speed * delta, 0, 1));
	end;

	Killaura = vape.Categories.Blatant:CreateModule({
		["Name"] = 'Killaura',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			state = {
				["LastEffect"] = 0, ["LastAttack"] = 0, ["EffectSwing"] = 0, ["SwingGap"] = 0.11, ["AnimDelay"] = 0, ["ContinueUntil"] = 0,
				["SwingCooldown"] = 0, ["LastHit"] = 0, ["LastShot"] = 0, ["Shooting"] = false, ["ShotIndex"] = 1, ["FireRates"] = {},
				["FrameTime"] = 0, ["FrameCount"] = 0, ["FrameWindow"] = 0, ["ScanClock"] = 0, ["Entities"] = {},
				["StatSent"] = 0, ["StatLanded"] = 0, ["StatClock"] = tick()
			};
			resetHitreg();
			hitBudget = 60 / (store.remoteLimits.SwordHit or config.RemoteLimit);
			table.clear(trail.Times);
			table.clear(trail.Points);
			setMobileSwing(Limit["Enabled"]);

			local previousEffect: (...any) -> ...any = bedwars.SwordController.playSwordEffect;
			local effectHook: (self: table, swordMeta: table, charged: boolean, settings: table?) -> ...any;
			effectHook = function(self: table, swordMeta: table, charged: boolean, chargeSettings: table?): ...any
				if not Killaura["Enabled"] or bedwars.SwordController.playSwordEffect ~= effectHook or (chargeSettings and chargeSettings.playAnimation == false) then
					return previousEffect(self, swordMeta, charged, chargeSettings);
				end;
				if SwingOnly["Enabled"] then
					local clicked: number = bedwars.SwordController.lastSwing;
					if tick() - state.LastAttack < 0.4 and clicked == state.EffectSwing then
						return nil;
					end;
					state.EffectSwing = clicked;
					return previousEffect(self, swordMeta, charged, chargeSettings);
				end;
				if (tick() - state.LastAttack < 0.4 or tick() - state.AnimDelay < 0.4) and tick() - state.LastEffect < state.SwingGap then
					return nil;
				end;
				state.LastEffect = tick();
				state.SwingGap = math.max(SwingTime:GetRandomValue(), 0.11);
				return previousEffect(self, swordMeta, charged, chargeSettings);
			end;
			bedwars.SwordController.playSwordEffect = effectHook;

			if Animation["Enabled"] then
				local viewmodelGate: table = {
					["Controllers"] = {
						["ViewmodelController"] = {
							["isVisible"] = function(): boolean
								return bedwars.ViewmodelController:isVisible();
							end,
							["playAnimation"] = function(_: table, ...: any): ()
								if SwingOnly["Enabled"] or not store.attacking or not (arm.Wrist and arm.Wrist.Parent) then
									bedwars.ViewmodelController:playAnimation(...);
								end;
							end
						}
					}
				};
				debug.setupvalue(swordEffect, 7, viewmodelGate);
				debug.setupvalue(bedwars.ScytheController.playLocalAnimation, 3, viewmodelGate);
			end;

			refreshCircle();
			Killaura:Clean(vapeEvents.EntityDamageEvent.Event:Connect(onDamage));
			local hitSound: Sound = Instance.new('Sound');
			hitSound.Parent = workspace;
			Killaura:Clean(hitSound);
			Killaura:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				if not HitSound["Enabled"] or damage.fromEntity ~= lplr.Character or damage.entityInstance == lplr.Character then
					return;
				end;
				local id: string? = hitSoundId(HitSoundType["Value"]);
				if id then
					hitSound.SoundId = id;
					hitSound.Volume = HitSoundVolume["Value"];
					hitSound.TimePosition = 0;
					hitSound:Play();
				end;
			end));
			Killaura:Clean(entitylib.Events.EntityAdded:Connect(function(): ()
				state.ScanClock = 0;
			end));
			Killaura:Clean(entitylib.Events.EntityRemoved:Connect(function(ent: table): ()
				state.ScanClock = 0;
				if ent.Character then
					hitreg.Stamps[ent.Character] = nil;
					characterParts[ent.Character] = nil;
					follow.Watch[ent.Character] = nil;
				end;
				if aim.Target == ent then
					aim.Target = nil;
				end;
			end));
			Killaura:Clean(runService.Heartbeat:Connect(step));
			Killaura:Clean(runService.PostSimulation:Connect(aimStep));
			Killaura:Clean(function(): ()
				store.KillauraTarget = nil;
				store.attacking = false;
				resetHitreg();
				table.clear(attacked);
				table.clear(characterParts);
				table.clear(targetPool);
				for _: number, box: BoxHandleAdornment in boxes do
					box.Size = Vector3.zero;
					boxShown[box] = false;
					boxAnchors[box].Parent = nil;
				end;
				table.clear(follow.Watch);
				for _: number, part: Part in particles do
					part.Parent = nil;
				end;
				debug.setupvalue(swordEffect, 7, bedwars.Knit);
				debug.setupvalue(bedwars.ScytheController.playLocalAnimation, 3, bedwars.Knit);
				if bedwars.SwordController.playSwordEffect == effectHook then
					bedwars.SwordController.playSwordEffect = previousEffect;
				end;
				if arm.Wrist and arm.Wrist.Parent and arm.C0 then
					tweenService:Create(arm.Wrist, TweenInfo.new(AnimationTween["Enabled"] and 0.001 or 0.3, Enum.EasingStyle.Exponential), {["C0"] = arm.C0}):Play();
				end;
				arm.Running = false;
				if aim.Rotating and entitylib.isAlive then
					entitylib.character.Humanoid.AutoRotate = true;
				end;
				aim.Rotating, aim.Target = false, nil;
				refreshCircle();
				setMobileSwing(true);
			end);
		end,
		["ExtraText"] = function(): string
			return 'Public';
		end,
		["Tooltip"] = 'Attack players around you\nwithout aiming at them.'
	});

