		["Name"] = 'Color End',
		["Function"] = paintParticles,
		["Darker"] = true,
		["Visible"] = false
	});
	ParticleSize = Killaura:CreateSlider({
		["Name"] = 'Size',
		["Min"] = 0,
		["Max"] = 1,
		["Default"] = 0.2,
		["Decimal"] = 100,
		["Function"] = paintParticles,
		["Darker"] = true,
		["Visible"] = false
	});
	RangeVisualizer = Killaura:CreateToggle({
		["Name"] = 'Range Visualizer',
		["Function"] = function(callback: boolean): ()
			RangeColor.Object.Visible = callback;
			refreshCircle();
		end
	});
	RangeColor = Killaura:CreateColorSlider({
		["Name"] = 'colour',
		["DefaultHue"] = 0.6,
		["DefaultOpacity"] = 0.5,
		["Function"] = function(hue: number, sat: number, value: number, opacity: number): ()
			if circle then
				circle.Color = Color3.fromHSV(hue, sat, value);
				circle.Transparency = 1 - opacity;
			end;
		end,
		["Darker"] = true,
		["Visible"] = false
	});
	Face = Killaura:CreateToggle({["Name"] = 'Face target'});
	Animation = Killaura:CreateToggle({
		["Name"] = 'Custom Animation',
		["Function"] = function(callback: boolean): ()
			for _: number, option: table in {AnimationMode, AnimationSpeed, AnimationTween} do
				option.Object.Visible = callback;
			end;
			if Killaura["Enabled"] then
				Killaura:Toggle();
				Killaura:Toggle();
			end;
		end
	});
	local animationNames: {string} = {};
	for name: string in auraanims do
		if name ~= 'Normal' then
			table.insert(animationNames, name);
		end;
	end;
	table.sort(animationNames);
	table.insert(animationNames, 1, 'Normal');
	AnimationMode = Killaura:CreateDropdown({
		["Name"] = 'Animation Mode',
		["List"] = animationNames,
		["Darker"] = true,
		["Visible"] = false
	});
	AnimationSpeed = Killaura:CreateSlider({
		["Name"] = 'Animation Speed',
		["Min"] = 0,
		["Max"] = 2,
		["Default"] = 1,
		["Decimal"] = 10,
		["Darker"] = true,
		["Visible"] = false
	});
	AnimationTween = Killaura:CreateToggle({
		["Name"] = 'No Tween',
		["Darker"] = true,
		["Visible"] = false
	});
	Limit = Killaura:CreateToggle({
		["Name"] = 'Limit to items',
		["Function"] = function(callback: boolean): ()
			if Killaura["Enabled"] then
				setMobileSwing(callback);
			end;
		end,
		["Tooltip"] = 'Only attacks while a sword is held.'
	});
	SwingOnly = Killaura:CreateToggle({
		["Name"] = 'Swing only',
		["Tooltip"] = 'Only attacks while you swing manually.'
	});
	HitSound = Killaura:CreateToggle({
		["Name"] = 'Hit Sound',
		["Function"] = function(callback: boolean): ()
			HitSoundType.Object.Visible = callback;
			HitSoundVolume.Object.Visible = callback;
		end,
		["Tooltip"] = 'Plays a sound every time something you attack takes damage.'
	});
	local soundNames: {string} = {};
	for name: string in hitSounds do
		table.insert(soundNames, name);
	end;
	table.sort(soundNames, function(a: string, b: string): boolean
		return a == 'skeet.cc' or (b ~= 'skeet.cc' and a < b);
	end);
	HitSoundType = Killaura:CreateDropdown({
		["Name"] = 'Hit Sound Type',
		["List"] = soundNames,
		["Darker"] = true,
		["Visible"] = false
	});
	HitSoundVolume = Killaura:CreateSlider({
		["Name"] = 'Hit Sound Volume',
		["Min"] = 1,
		["Max"] = 10,
		["Default"] = 5,
		["Darker"] = true,
		["Visible"] = false
	});
end);


velo.run(function(): ()
	local AntiDeath: table = {["Enabled"] = false};
	local Mode: table;
	local Threshold: table;
	local StopThreshold: table;
	local Cooldown: table;
	local Notify: table;
	local revealPause: number = 5;
	local airborneLimit: number = 1.7;
	local sinkDepth: Vector3 = Vector3.new(0, 200, 0);
	local hidden: table? = nil;
	local pausedUntil: number, lastTrigger: number, floatUntil: number = 0, 0, 0;

	local reveal: (announce: boolean) -> () = function(announce: boolean): ()
		local state: table? = hidden;
		if not state then
			return;
		end;
		hidden = nil;
		store.rootpart = nil;
		pausedUntil = tick() + revealPause;
		if not state.Root.Parent or not state.Character.Parent then
			state.Clone:Destroy();
			return;
		end;
		local resume: CFrame = state.Clone.CFrame;
		state.Character.Parent = replicatedStorage;
		state.Root.Parent = state.Character;
		state.Clone:Destroy();
		state.Character.PrimaryPart = state.Root;
		state.Character.Parent = workspace;
		state.Root.CanCollide = true;
		state.Root.CFrame = resume;
		local humanoid: Humanoid? = state.Character:FindFirstChildOfClass('Humanoid');
		if humanoid then
			humanoid.HipHeight = state.HipHeight;
		end;
		if announce and Notify["Enabled"] then
			notif('AntiDeath', 'You are visible again', 12, 'info');
		end;
	end;

	AntiDeath = vape.Categories.Blatant:CreateModule({
		["Name"] = 'AntiDeath',
		["Function"] = function(callback: boolean): ()
			if not callback then
				reveal(false);
				return;
			end;
			AntiDeath:Clean(entitylib.Events.LocalRemoved:Connect(function(): ()
				reveal(true);
			end));
			AntiDeath:Clean(runService.PreSimulation:Connect(function(): ()
				if not entitylib.isAlive then
					return;
				end;
				local character: Model = lplr.Character;
				local percent: number = entitylib.character.Health / entitylib.character.MaxHealth * 100;
				if hidden then
					if percent >= StopThreshold["Value"] then
						reveal(true);
						return;
					end;
					if tick() - entitylib.character.AirTime > airborneLimit then
						floatUntil = tick() + 0.2;
					end;
					hidden.Root.AssemblyLinearVelocity = Vector3.new(0, 1, 0);
					hidden.Root.CFrame = hidden.Clone.CFrame - (tick() > floatUntil and sinkDepth or Vector3.zero);
					return;
				end;
				if tick() <= pausedUntil or tick() - lastTrigger < Cooldown["Value"] or percent > Threshold["Value"] then
					return;
				end;
				lastTrigger = tick();
				if Notify["Enabled"] then
					notif('AntiDeath', 'Health below '..Threshold["Value"]..'%', 12, 'warning');
				end;
				if Mode["Value"] == 'Teleport' then
					entitylib.character.RootPart.CFrame += Vector3.new(0, 100, 0);
					pausedUntil = tick() + revealPause;
					return;
				end;
				if store.rootpart or not character.Parent or entitylib.character.Humanoid.Health <= 0 then
					return;
				end;
				local root: BasePart = entitylib.character.HumanoidRootPart;
				local state: table = {["Character"] = character, ["Root"] = root, ["HipHeight"] = entitylib.character.Humanoid.HipHeight};
				character.Parent = replicatedStorage;
				state.Clone = root:Clone();
				state.Clone.Parent = character;
				root.Transparency = 1;
				root.Parent = workspace;
				character.PrimaryPart = state.Clone;
				character.Parent = workspace;
				bedwars.QueryUtil:setQueryIgnored(state.Clone, true);
				bedwars.QueryUtil:setQueryIgnored(root, true);
				store.rootpart = root;
				hidden = state;
				pausedUntil = tick() + revealPause;
			end));
		end,
		["Tooltip"] = 'Uses selected mode when on a threshold'
	});
	Mode = AntiDeath:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Invincibility', 'Teleport'},
		["Tooltip"] = 'Teleport - Teleports you high up\nInvincibility - Makes you unhittable'
	});
	StopThreshold = AntiDeath:CreateSlider({
		["Name"] = 'Stop Threshold',
		["Min"] = 1,
		["Max"] = 100,
		["Default"] = 30,
		["Suffix"] = '%',
		["Tooltip"] = 'Health percentage to untrigger at'
	});
	Threshold = AntiDeath:CreateSlider({
		["Name"] = 'Threshold',
		["Min"] = 1,
		["Max"] = 100,
		["Default"] = 30,
		["Suffix"] = '%',
		["Tooltip"] = 'Health percentage to trigger at'
	});
	Cooldown = AntiDeath:CreateSlider({
		["Name"] = 'Delay',
		["Min"] = 1,
		["Max"] = 20,
		["Default"] = 5,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'sec' or 'secs';
		end,
		["Tooltip"] = 'Delay between triggers'
	});
	Notify = AntiDeath:CreateToggle({
		["Name"] = 'Notify on trigger',
		["Default"] = true
	});
end);

velo.run(function(): ()
	local AntiFall: table = {["Enabled"] = false};
	local Platform: table;
	local MoveMode: table;
	local Material: table;
	local PartColor: table;
	local Balloon: table;
	local VoidDrop: table;
	local OwlCheck: table;
	local ResetAfterDrop: table;
	local AutoReset: table;
	local ResetDelay: table;
	local PearlCheck: table;
	local WhisperCheck: table;
	local LassoCheck: table;
	local voidMargin: number = 50;
	local voidRate: number = 0.05;
	local resources: {string} = {'iron', 'diamond', 'emerald', 'gold'};
	local groundAxes: {Vector3} = {Vector3.xAxis, Vector3.zAxis, -Vector3.xAxis, -Vector3.zAxis};
	local wallRay: RaycastParams = RaycastParams.new();
	wallRay.RespectCanCollide = true;

	local refresh: () -> () = function(): ()
		if not LassoCheck then
			return;
		end;
		for _: number, option: table in {MoveMode, Material, PartColor} do
			option.Object.Visible = Platform["Enabled"];
		end;
		OwlCheck.Object.Visible = VoidDrop["Enabled"];
		ResetAfterDrop.Object.Visible = VoidDrop["Enabled"];
		for _: number, option: table in {ResetDelay, PearlCheck, WhisperCheck, LassoCheck} do
			option.Object.Visible = AutoReset["Enabled"];
		end;
		if AntiFall["Enabled"] then
			AntiFall:Toggle();
			AntiFall:Toggle();
		end;
	end;

	local canBeSaved: () -> boolean = function(): boolean
		if PearlCheck["Enabled"] and getItem('telepearl') then
			return true;
		end;
		if WhisperCheck["Enabled"] and lplr:GetAttribute('IsOwlTarget') then
			return true;
		end;
		for _: number, child: Instance in (LassoCheck["Enabled"] and lplr.Character and lplr.Character:GetChildren() or {}) do
			if child:IsA('Accessory') and child:FindFirstChild('Rope') then
				return true;
			end;
		end;
		return false;
	end;

	AntiFall = vape.Categories.Blatant:CreateModule({
		["Name"] = 'AntiFall',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local voidLine: number? = nil;
			local platformBuilt: boolean = false;
			local nextVoid: number, nextBalloon: number, nextReset: number, touchDebounce: number = 0, 0, 0, 0;
			local dropping: boolean = false;
			local resetting: table? = nil;
			local walker: RBXScriptConnection? = nil;

			local stopWalking: () -> () = function(): ()
				if walker then
					walker:Disconnect();
					walker = nil;
				end;
				store.antiFallDirection = nil;
			end;
			AntiFall:Clean(function(): ()
				stopWalking();
				store.antiFallPart = nil;
			end);

			local buildPlatform: () -> () = function(): ()
				platformBuilt = true;
				local lowest: number = math.huge;
				for _: number, cell: Vector3 in bedwars.BlockController:getStore():getAllBlockPositions() do
					local position: Vector3 = cell * 3;
					if position.Y < lowest and not getPlacedBlock(position + Vector3.new(0, 3, 0)) then
						lowest = position.Y;
					end;
				end;
				if lowest == math.huge then
					return;
				end;
				local part: Part = Instance.new('Part');
				part.Size = Vector3.new(10000, 1, 10000);
				part.Transparency = 1 - PartColor.Opacity;
				part.Material = Enum.Material[Material["Value"]];
				part.Color = Color3.fromHSV(PartColor.Hue, PartColor.Sat, PartColor.Value);
				part.Position = Vector3.new(0, lowest - 2, 0);
				part.CanCollide = MoveMode["Value"] == 'Collide';
				part.Anchored = true;
				part.CanQuery = false;
				part.Parent = workspace;
				store.antiFallPart = part;
				AntiFall:Clean(part);
				AntiFall:Clean(part.Touched:Connect(function(touched: BasePart): ()
					if touched.Parent ~= lplr.Character or not entitylib.isAlive or store.infinitefly or touchDebounce >= tick() then
						return;
					end;
					touchDebounce = tick() + 0.1;
					local root: BasePart = entitylib.character.RootPart;
					if MoveMode["Value"] == 'Velocity' then
						root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 100, root.AssemblyLinearVelocity.Z);
						return;
					end;
					local top: Vector3? = MoveMode["Value"] == 'Normal' and getNearGround() or nil;
					if not top then
						return;
					end;
					local lastTeleport: any = lplr:GetAttribute('LastTeleported');
					wallRay.FilterDescendantsInstances = {gameCamera, lplr.Character};
					wallRay.CollisionGroup = root.CollisionGroup;
					stopWalking();
					walker = runService.PreSimulation:Connect(function(): ()
						if vape.Modules.Fly["Enabled"] or vape.Modules.LongJump["Enabled"] or store.infinitefly or not entitylib.isAlive or lplr:GetAttribute('LastTeleported') ~= lastTeleport then
							stopWalking();
							return;
						end;
						local body: BasePart = entitylib.character.RootPart;
						local delta: Vector3 = (top - body.Position) * Vector3.new(1, 0, 1);
						local direction: Vector3 = delta.Magnitude > 0 and delta.Unit or Vector3.zero;
						store.antiFallDirection = direction;
						body.AssemblyLinearVelocity *= Vector3.new(1, 0, 1);
						local wall: RaycastResult? = workspace:Raycast(body.Position, direction, wallRay);
						if wall then
							local step: Vector3 = roundPos(wall.Position + wall.Normal * 1.5) + Vector3.new(0, 3, 0);
							for _: number = 1, 10 do
								if not getPlacedBlock(step) then
									top = Vector3.new(top.X, step.Y, top.Z);
									break;
								end;
								step += Vector3.new(0, 3, 0);
							end;
						end;
						body.CFrame += Vector3.new(0, top.Y - body.Position.Y, 0);
						if not frictionUsers.Speed then
							body.AssemblyLinearVelocity = direction * getSpeed() + Vector3.new(0, body.AssemblyLinearVelocity.Y, 0);
						end;
						if delta.Magnitude < 1 then
							stopWalking();
						end;
					end);
				end));
			end;

			AntiFall:Clean(runService.Heartbeat:Connect(function(): ()
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				if store.matchState == 0 then
					return;
				end;
				if Platform["Enabled"] and not platformBuilt then
					buildPlatform();
				end;
				if tick() < nextVoid or not entitylib.isAlive or store.infinitefly then
					return;
				end;
				nextVoid = tick() + voidRate;
				if not voidLine then
					local lowest: number = math.huge;
					for _: number, block: BasePart in store.blocks do
						lowest = math.min(lowest, block.Position.Y - block.Size.Y / 2 - voidMargin);
					end;
					if lowest == math.huge then
						return;
					end;
					voidLine = lowest;
				end;
				local character: table = entitylib.character;
				local root: BasePart = character.RootPart;
				if root.Position.Y >= voidLine then
					resetting = nil;
					return;
				end;
				local balloons: number = lplr.Character:GetAttribute('InflatedBalloons') or 0;
				if Balloon["Enabled"] and balloons < 3 and tick() >= nextBalloon and getItem('balloon') then
					nextBalloon = tick() + 0.2;
					for _: number = 1, 3 do
						bedwars.BalloonController:inflateBalloon();
					end;
					return;
				end;
				if VoidDrop["Enabled"] and not dropping and balloons <= 0 and not getItem('balloon') and not (OwlCheck["Enabled"] and root:FindFirstChild('OwlLiftForce')) then
					dropping = true;
					for _: number, resource: string in resources do
						local item: table? = getItem(resource);
						local dropped: any = item and fire('DropItem', 'CallServer', {["item"] = item.tool, ["amount"] = item.amount});
						if typeof(dropped) == 'Instance' then
							dropped:SetAttribute('ClientDropTime', tick() + 100);
							if ResetAfterDrop["Enabled"] and tick() >= nextReset then
								nextReset = tick() + 1;
								fire('ResetCharacter', 'SendToServer');
							end;
						end;
					end;
					dropping = false;
				end;
				if not AutoReset["Enabled"] or store.matchState ~= 1 or resetting == character then
					return;
				end;
				if root.AssemblyLinearVelocity.Y < 0 and not canBeSaved() and not workspace:Raycast(root.Position, Vector3.new(0, -2000, 0), store.airRay) then
					resetting = character;
					task.delay(ResetDelay["Value"], function(): ()
						if AntiFall["Enabled"] and entitylib.isAlive and entitylib.character == character and root.Parent and root.AssemblyLinearVelocity.Y < 0 and not canBeSaved() and not workspace:Raycast(root.Position, Vector3.new(0, -2000, 0), store.airRay) then
							fire('ResetCharacter', 'SendToServer');
						elseif resetting == character then
							resetting = nil;
						end;
					end);
				end;
			end));
		end,
		["Tooltip"] = 'Help\'s you with your Parkinson\'s\nPrevents you from falling into the void.'
	});
	Platform = AntiFall:CreateToggle({
		["Name"] = 'Platform',
		["Default"] = true,
		["Function"] = refresh,
		["Tooltip"] = 'Places an invisible floor under the lowest block'
	});
	MoveMode = AntiFall:CreateDropdown({
		["Name"] = 'Move Mode',
		["List"] = {'Normal', 'Collide', 'Velocity'},
		["Darker"] = true,
		["Function"] = function(value: string): ()
			if store.antiFallPart then
				store.antiFallPart.CanCollide = value == 'Collide';
			end;
		end,
		["Tooltip"] = 'Normal - Smoothly moves you towards the nearest safe point\nVelocity - Launches you upward after touching\nCollide - Allows you to walk on the part'
	});
	local materials: {string} = {'ForceField'};
	for _: number, material: EnumItem in Enum.Material:GetEnumItems() do
		if material.Name ~= 'ForceField' then
			table.insert(materials, material.Name);
		end;
	end;
	Material = AntiFall:CreateDropdown({
		["Name"] = 'Material',
		["List"] = materials,
		["Darker"] = true,
		["Function"] = function(value: string): ()
			if store.antiFallPart then
				store.antiFallPart.Material = Enum.Material[value];
			end;
		end
	});
	PartColor = AntiFall:CreateColorSlider({
		["Name"] = 'Color',
		["DefaultOpacity"] = 0.5,
		["Darker"] = true,
		["Function"] = function(hue: number, sat: number, value: number, opacity: number): ()
			if store.antiFallPart then
				store.antiFallPart.Color = Color3.fromHSV(hue, sat, value);
				store.antiFallPart.Transparency = 1 - opacity;
			end;
		end
	});
	Balloon = AntiFall:CreateToggle({
		["Name"] = 'Auto Balloon',
		["Tooltip"] = 'Inflates balloons once you fall below the map'
	});
	VoidDrop = AntiFall:CreateToggle({
		["Name"] = 'Void Drop',
		["Function"] = refresh,
		["Tooltip"] = 'Drops your resources once you fall below the map'
	});
	OwlCheck = AntiFall:CreateToggle({
		["Name"] = 'Owl check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Refuses to drop items if being picked up by an owl'
	});
	ResetAfterDrop = AntiFall:CreateToggle({
		["Name"] = 'Reset after drop',
		["Darker"] = true,
		["Tooltip"] = 'Resets as soon as your resources are dropped'
	});
	AutoReset = AntiFall:CreateToggle({
		["Name"] = 'Auto Reset',
		["Function"] = refresh,
		["Tooltip"] = 'Resets once you fall past the void line so you can respawn sooner'
	});
	ResetDelay = AntiFall:CreateSlider({
		["Name"] = 'Reset Delay',
		["Min"] = 0,
		["Max"] = 2,
		["Default"] = 0,
		["Decimal"] = 10,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value == 1 and 'second' or 'seconds';
		end,
		["Tooltip"] = 'How long to wait before resetting. 0 resets instantly'
	});
	PearlCheck = AntiFall:CreateToggle({
		["Name"] = 'Pearl check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Never resets while you are carrying a telepearl'
	});
	WhisperCheck = AntiFall:CreateToggle({
		["Name"] = 'Whisper check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Never resets while an owl is assigned to you'
	});
	LassoCheck = AntiFall:CreateToggle({
		["Name"] = 'Lasso check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Never resets while a lasso is attached to you'
	});
	refresh();
end);

velo.run(function(): ()
	local AntiVoidFlag: table = {["Enabled"] = false};
	local groundAxes: {Vector3} = {Vector3.xAxis, Vector3.zAxis, -Vector3.xAxis, -Vector3.zAxis};

	local nearGround: (origin: Vector3) -> Vector3? = function(origin: Vector3): Vector3?
		local ground: Vector3?, groundDistance: number = nil, math.huge;
		for _: number, axis: Vector3 in groundAxes do
			for step: number = 1, 18 do
				local hit: RaycastResult? = workspace:Raycast(origin + Vector3.new(0, 500, 0) + axis * step, Vector3.new(0, -1000, 0), store.airRay);
				local distance: number = hit and (Vector3.new(origin.X, hit.Position.Y, origin.Z) - hit.Position).Magnitude or math.huge;
				if distance < groundDistance then
					ground, groundDistance = hit.Position, distance;
				end;
			end;
		end;
		return ground;
	end;

	AntiVoidFlag = vape.Categories.Blatant:CreateModule({
		["Name"] = 'AntiVoidFlag',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			if not replicatesignal then
				notif('AntiVoidFlag', "This executor can't replicate the seat signal it needs", 5, 'warning');
				task.defer(function(): ()
					if AntiVoidFlag["Enabled"] then
						AntiVoidFlag:Toggle();
					end;
				end);
				return;
			end;
			local seat: Instance = replicatedStorage.Assets.Effects.snowball_rider.Handle.Seat;
			local welded: boolean = false;
			AntiVoidFlag:Clean(function(): ()
				if welded then
					replicatesignal(seat.RemoteDestroySeatWeld);
					welded = false;
				end;
			end);
			AntiVoidFlag:Clean(runService.Heartbeat:Connect(function(): ()
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				if not entitylib.isAlive then
					if welded then
						replicatesignal(seat.RemoteDestroySeatWeld);
						welded = false;
					end;
					return;
				end;
				local root: BasePart? = lplr.Character:FindFirstChild('HumanoidRootPart');
				local humanoid: Humanoid? = lplr.Character:FindFirstChildOfClass('Humanoid');
				if root and humanoid and not isnetworkowner(root) and not workspace:Raycast(root.Position, Vector3.new(0, -1000, 0), store.airRay) then
					root.AssemblyLinearVelocity = Vector3.zero;
					welded = true;
					humanoid:ChangeState(Enum.HumanoidStateType.Jumping);
					replicatesignal(seat.RemoteCreateSeatWeld, humanoid);
				elseif welded and (not root or isnetworkowner(root)) then
					local ground: Vector3? = root and nearGround(root.Position);
					if root and ground then
						notif('AntiVoidFlag', 'Teleported.', 8, 'info');
						root.AssemblyLinearVelocity = Vector3.new(0, 2.5, 0);
						root.CFrame = CFrame.lookAlong(ground + Vector3.new(0, 2.5, 0), root.CFrame.LookVector);
					end;
					replicatesignal(seat.RemoteDestroySeatWeld);
					welded = false;
				end;
			end));
		end,
		["Tooltip"] = 'When the server takes your character over the void, welds you to a seat until control returns, then puts you on the nearest ground'
	});
end);

velo.run(function(): ()
	local NoFall: table = {["Enabled"] = false};
	local Damage: table;
	local safeFall: number = 45;
	local silenced: {[Humanoid]: {any}} = {};

	local silence: (humanoid: Humanoid) -> () = function(humanoid: Humanoid): ()
		if not getconnections or silenced[humanoid] then
			return;
		end;
		silenced[humanoid] = {};
		humanoid.Destroying:Once(function(): ()
			silenced[humanoid] = nil;
		end);
		for _: number, connection: any in getconnections(humanoid.StateChanged) do
			connection:Disable();
			table.insert(silenced[humanoid], connection);
		end;
	end;

	NoFall = vape.Categories.Blatant:CreateModule({
		["Name"] = 'NoFall',
		["Function"] = function(callback: boolean): ()
			if not callback then
				for _: Humanoid, connections: {any} in silenced do
					for _: number, connection: any in connections do
						connection:Enable();
					end;
				end;
				table.clear(silenced);
				return;
			end;
			if entitylib.isAlive then
				silence(entitylib.character.Humanoid);
			end;
			local tracked: number, lastHit: number = 0, 0;
			NoFall:Clean(runService.PostSimulation:Connect(function(): ()
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				if not entitylib.isAlive or store.matchState ~= 1 or store.cannonFlight or store.infinitefly then
					tracked = 0;
					return;
				end;
				local root: BasePart = entitylib.character.RootPart;
				local velocity: Vector3 = root.AssemblyLinearVelocity;
				if tracked < -(safeFall + Damage["Value"] * 0.75) then
					local cushion: Vector3 = Vector3.new(0, 2.5, 0);
					root.AssemblyLinearVelocity = cushion;
					entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Landed);
					runService.PreRender:Wait();
					if root.AssemblyLinearVelocity == cushion then
						root.AssemblyLinearVelocity = velocity;
					end;
					if os.clock() - lastHit >= 0.1 then
						fire('GroundHit', 'SendToServer', nil, Vector3.new(0, tracked, 0), workspace:GetServerTimeNow());
						lastHit = os.clock();
					end;
				end;
				tracked = velocity.Y;
			end));
			NoFall:Clean(entitylib.Events.LocalAdded:Connect(function(ent: table): ()
				if ent.Humanoid:WaitForChild('Animator', 5) then
					task.delay(0.5, function(): ()
						if NoFall["Enabled"] then
							silence(ent.Humanoid);
						end;
					end);
				end;
			end));
		end,
		["Tooltip"] = 'Prevents taking fall damage.'
	});
	Damage = NoFall:CreateSlider({
		["Name"] = 'Damage',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 0,
		["Suffix"] = '%',
		["Tooltip"] = 'How much of each fall lands on you, it only starts saving you once you are dropping faster than this lets through'
	});
end);

velo.run(function(): ()
	local DamageBoost: table = {["Enabled"] = false};
	local Strength: table;
	local Duration: table;
	local Push: table;
	local wallRay: RaycastParams = RaycastParams.new();
	wallRay.RespectCanCollide = true;

	DamageBoost = vape.Categories.Blatant:CreateModule({
		["Name"] = 'DamageBoost',
		["Function"] = function(callback: boolean): ()
			store.speedBoost = {["Amount"] = 0, ["Expires"] = 0};
			if not callback then
				return;
			end;
			local stacked: number = 0;
			DamageBoost:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
				if not entitylib.isAlive or tick() <= stacked or damage.entityInstance ~= lplr.Character or vape.Modules.LongJump["Enabled"] then
					return;
				end;
				local horizontal: number = damage.knockbackMultiplier and damage.knockbackMultiplier.horizontal or 0;
				local knockback: number = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {["vertical"] = 0, ["horizontal"] = horizontal}).Magnitude * (0.9 + store.ping.total);
				stacked = tick() + knockback / 45;
				store.speedBoost = {["Amount"] = knockback * Strength["Value"] / 100, ["Expires"] = tick() + horizontal / 3.5 * Duration["Value"] / 100};
			end));
			DamageBoost:Clean(function(): ()
				store.speedBoost = {["Amount"] = 0, ["Expires"] = 0};
			end);
			DamageBoost:Clean(runService.PreSimulation:Connect(function(delta: number): ()
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				if not Push["Enabled"] or store.speedBoost.Expires <= tick() or not entitylib.isAlive or frictionUsers.Speed or frictionUsers.Fly or vape.Modules.LongJump["Enabled"] or store.infinitefly or store.antiFallDirection then
					return;
				end;
				local root: BasePart = entitylib.character.RootPart;
				if not isnetworkowner(root) or entitylib.character.Humanoid:GetState() == Enum.HumanoidStateType.Climbing then
					return;
				end;
				local step: Vector3 = entitylib.character.Humanoid.MoveDirection * store.speedBoost.Amount * delta;
				wallRay.FilterDescendantsInstances = {lplr.Character, gameCamera};
				wallRay.CollisionGroup = root.CollisionGroup;
				local wall: RaycastResult? = workspace:Raycast(root.Position, step, wallRay);
				if wall then
					step = wall.Position + wall.Normal - root.Position;
				end;
				root.CFrame += step;
			end));
		end,
		["Tooltip"] = 'Makes you go faster when damaged. Works with Speed, Fly and LongJump, and on its own.'
	});
	Strength = DamageBoost:CreateSlider({
		["Name"] = 'Strength',
		["Min"] = 0,
		["Max"] = 300,
		["Default"] = 100,
		["Suffix"] = '%',
		["Tooltip"] = 'Extra speed from each hit, 100% is the knockback the hit would have given you'
	});
	Duration = DamageBoost:CreateSlider({
		["Name"] = 'Duration',
		["Min"] = 0,
		["Max"] = 500,
		["Default"] = 100,
		["Suffix"] = '%',
		["Tooltip"] = 'How long the boost lasts, 100% matches catsix (stronger knockback lasts longer)'
	});
	Push = DamageBoost:CreateToggle({
		["Name"] = 'Boost without Speed',
		["Default"] = true,
		["Tooltip"] = 'Pushes you forward yourself while Blatant Speed and Fly are off, so the boost works in Legit Speed or with Speed disabled'
	});
end);

velo.run(function(): ()
	local Speed: table = {["Enabled"] = false};
	local Mode: table;
	local Value: table;
	local WallCheck: table;
	local AutoJump: table;
	local AlwaysJump: table;
	local modifier: table = {};
	local wallRay: RaycastParams = RaycastParams.new();
	wallRay.RespectCanCollide = true;

	Speed = vape.Categories.Blatant:CreateModule({
		["Name"] = 'Speed',
		["Function"] = function(callback: boolean): ()
			local blatant: boolean = callback and Mode["Value"] == 'Blatant';
			frictionUsers.Speed = blatant or nil;
			updateFriction();
			debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, blatant and 'constantSpeedMultiplier' or 'moveSpeedMultiplier');
			bedwars.StatefulEntityKnockbackController.lastImpulseTime = blatant and math.huge or time();
			if not callback then
				return;
			end;
			if not blatant then
				modifier.moveSpeedMultiplier = Value["Value"] / 20;
				local handle: any = bedwars.SprintController:getMovementStatusModifier():addModifier(modifier);
				Speed:Clean(function(): ()
					handle:Destroy();
				end);
			end;
			Speed:Clean(runService.PreSimulation:Connect(function(delta: number): ()
				if blatant then
					bedwars.StatefulEntityKnockbackController.lastImpulseTime = math.huge;
				end;
				if not entitylib.isAlive or vape.Modules.Fly["Enabled"] or vape.Modules.LongJump["Enabled"] or not isnetworkowner(entitylib.character.RootPart) then
					return;
				end;
				local root: BasePart = entitylib.character.RootPart;
				if store.cannonFlight and store.cannonFlight.Root == root then
					return;
				end;
				local humanoid: Humanoid = entitylib.character.Humanoid;
				local state: Enum.HumanoidStateType = humanoid:GetState();
				if state == Enum.HumanoidStateType.Climbing then
					return;
				end;
				local direction: Vector3 = store.antiFallDirection or humanoid.MoveDirection;
				if blatant then
					local current: number = getSpeed();
					local step: Vector3 = direction * math.max(Value["Value"] - current, 0) * delta;
					if WallCheck["Enabled"] then
						wallRay.FilterDescendantsInstances = {lplr.Character, gameCamera};
						wallRay.CollisionGroup = root.CollisionGroup;
						local wall: RaycastResult? = workspace:Raycast(root.Position, step, wallRay);
						if wall then
							step = wall.Position + wall.Normal - root.Position;
						end;
					end;
					root.CFrame += step;
					root.AssemblyLinearVelocity = direction * current + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0);
				end;
				if AutoJump["Enabled"] and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.Landed) and direction ~= Vector3.zero and (store.attacking or AlwaysJump["Enabled"]) then
					humanoid:ChangeState(Enum.HumanoidStateType.Jumping);
				end;
			end));
		end,
		["ExtraText"] = function(): string
			return Mode["Value"];
		end,
		["Tooltip"] = 'Increases your movement with various methods.'
	});
	Mode = Speed:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Blatant', 'Legit'},
		["Function"] = function(value: string): ()
			if WallCheck then
				WallCheck.Object.Visible = value == 'Blatant';
			end;
			if Speed["Enabled"] then
				Speed:Toggle();
				Speed:Toggle();
			end;
		end,
		["Tooltip"] = 'Blatant - Heatseeker, moves your root forward every frame\nLegit - Raises your walkspeed through the games own speed system'
	});
	Value = Speed:CreateSlider({
		["Name"] = 'Speed',
		["Min"] = 1,
		["Max"] = 23,
		["Default"] = 23,
		["Function"] = function(value: number): ()
			if Speed["Enabled"] and Mode["Value"] == 'Legit' then
				modifier.moveSpeedMultiplier = value / 20;
				bedwars.SprintController:getMovementStatusModifier():updateModifiers();
			end;
		end,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	WallCheck = Speed:CreateToggle({
		["Name"] = 'Wall Check',
		["Default"] = true
	});
	AutoJump = Speed:CreateToggle({
		["Name"] = 'AutoJump',
		["Function"] = function(callback: boolean): ()
			AlwaysJump.Object.Visible = callback;
		end
	});
	AlwaysJump = Speed:CreateToggle({
		["Name"] = 'Always Jump',
		["Visible"] = false,
		["Darker"] = true
	});
end);

velo.run(function(): ()
	local original: ((self: table, modifier: table) -> any)? = nil;
	vape.Categories.Blatant:CreateModule({
		["Name"] = 'NoSlowdown',
		["Function"] = function(callback: boolean): ()
			local statusModifier: table = bedwars.SprintController:getMovementStatusModifier();
			if not callback then
				if original then
					statusModifier.addModifier = original;
					original = nil;
				end;
				return;
			end;
			local addModifier: (self: table, modifier: table) -> any = statusModifier.addModifier;
			original = addModifier;
			statusModifier.addModifier = function(self: table, modifier: table): any
				if modifier.moveSpeedMultiplier then
					modifier.moveSpeedMultiplier = math.max(modifier.moveSpeedMultiplier, 1);
				end;
				return addModifier(self, modifier);
			end;
			for active: table in statusModifier.modifiers do
				if (active.moveSpeedMultiplier or 1) < 1 then
					statusModifier:removeModifier(active);
				end;
			end;
		end,
		["Tooltip"] = 'Prevents slowing down when using items.'
	});
end);

velo.run(function(): ()
	local HitBoxes: table = {["Enabled"] = false};
	local Mode: table;
	local Expand: table;
	local BoxColor: table;
	local Projectiles: table;
	local ProjectileExpand: table;
	local swordRegionDefault: number = 3.8;
	local baseSize: Vector3 = Vector3.new(3, 6, 3);
	local bodies: {[table]: Part} = {};
	local shots: {[table]: Part} = {};
	local shotCount: number = 0;
	local swordPatched: boolean = false;

	local attach: (list: {[table]: Part}, ent: table, size: Vector3, transparency: number) -> () = function(list: {[table]: Part}, ent: table, size: Vector3, transparency: number): ()
		local part: Part = Instance.new('Part');
		part.Size = size;
		part.Position = ent.RootPart.Position;
		part.CanCollide = false;
		part.Massless = true;
		part.Color = Color3.fromHSV(BoxColor.Hue, BoxColor.Sat, BoxColor.Value);
		part.Transparency = transparency;
		part.Parent = ent.Character;
		local weld: Motor6D = Instance.new('Motor6D');
		weld.Part0 = part;
		weld.Part1 = ent.RootPart;
		weld.Parent = part;
		list[ent] = part;
		part.Destroying:Once(function(): ()
			if list[ent] == part then
				list[ent] = nil;
			end;
		end);
	end;

	local clear: (list: {[table]: Part}) -> () = function(list: {[table]: Part}): ()
		for _: table, part: Part in list do
			part:Destroy();
		end;
		table.clear(list);
	end;

	local addBody: (ent: table) -> () = function(ent: table): ()
		if ent.Targetable and ent.Player and not bodies[ent] then
			attach(bodies, ent, baseSize + Vector3.one * (Expand["Value"] / 5), 1 - BoxColor.Opacity);
		end;
	end;

	HitBoxes = vape.Categories.Blatant:CreateModule({
		["Name"] = 'HitBoxes',
		["Function"] = function(callback: boolean): ()
			if not callback then
				if swordPatched then
					debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, swordRegionDefault);
					swordPatched = false;
				end;
				clear(bodies);
				clear(shots);
				return;
			end;
			HitBoxes:Clean(entitylib.Events.EntityRemoved:Connect(function(ent: table): ()
				for _: number, list: {[table]: Part} in {bodies, shots} do
					if list[ent] then
						list[ent]:Destroy();
						list[ent] = nil;
					end;
				end;
			end));
			if Mode["Value"] == 'Sword' then
				debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, Expand["Value"] / 3);
				swordPatched = true;
			else
				HitBoxes:Clean(entitylib.Events.EntityAdded:Connect(addBody));
				for _: number, ent: table in entitylib.List do
					addBody(ent);
				end;
			end;
			if not Projectiles["Enabled"] then
				return;
			end;
			local launched: table = bedwars.SyncEvents.ProjectileLaunched:connect(function(event: table): ()
				if event.shooter ~= lplr.Character then
					return;
				end;
				for _: number, ent: table in entitylib.List do
					if ent.Targetable and ent.Player and not shots[ent] then
						attach(shots, ent, baseSize + Vector3.one * ProjectileExpand["Value"], 1);
					end;
				end;
				shotCount += 1;
				local current: number = shotCount;
				local meta: table? = bedwars.ProjectileMeta[event.projectileType];
				task.delay(meta and meta.lifetimeSec or 3, function(): ()
					if shotCount == current then
						clear(shots);
					end;
				end);
			end);
			HitBoxes:Clean(function(): ()
				launched:Destroy();
			end);
		end,
		["Tooltip"] = 'Expands attack hitbox'
	});
	Mode = HitBoxes:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Sword', 'Player'},
		["Function"] = function(value: string): ()
			if BoxColor then
				BoxColor.Object.Visible = value == 'Player';
			end;
			if HitBoxes["Enabled"] then
				HitBoxes:Toggle();
				HitBoxes:Toggle();
			end;
		end,
		["Tooltip"] = 'Sword - Increases the range around you to hit entities\nPlayer - Increases the players hitbox'
	});
	Expand = HitBoxes:CreateSlider({
		["Name"] = 'Expand amount',
		["Min"] = 0,
		["Max"] = 14.4,
		["Default"] = 14.4,
		["Decimal"] = 10,
		["Function"] = function(value: number): ()
			if not HitBoxes["Enabled"] then
				return;
			end;
			if swordPatched then
				debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, value / 3);
			end;
			for _: table, part: Part in bodies do
				part.Size = baseSize + Vector3.one * (value / 5);
			end;
		end,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	BoxColor = HitBoxes:CreateColorSlider({
		["Name"] = 'Hitbox Color',
		["DefaultOpacity"] = 0,
		["Visible"] = false,
		["Darker"] = true,
		["Function"] = function(hue: number, sat: number, value: number, opacity: number): ()
			for _: table, part: Part in bodies do
				part.Color = Color3.fromHSV(hue, sat, value);
				part.Transparency = 1 - opacity;
			end;
		end,
		["Tooltip"] = 'Color and opacity of the player hitbox parts'
	});
	Projectiles = HitBoxes:CreateToggle({
		["Name"] = 'Projectiles',
		["Function"] = function(callback: boolean): ()
			ProjectileExpand.Object.Visible = callback;
			if HitBoxes["Enabled"] then
				HitBoxes:Toggle();
				HitBoxes:Toggle();
			end;
		end,
		["Tooltip"] = 'Expands the hitbox your projectiles check against, only while one of your projectiles is in the air'
	});
	ProjectileExpand = HitBoxes:CreateSlider({
		["Name"] = 'Projectile Expand',
		["Min"] = 0,
		["Max"] = 20,
		["Default"] = 8,
		["Decimal"] = 10,
		["Visible"] = false,
		["Darker"] = true,
		["Function"] = function(value: number): ()
			for _: table, part: Part in shots do
				part.Size = baseSize + Vector3.one * value;
			end;
		end,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	HitBoxes:CreateButton({
		["Name"] = 'Sync to legit hitbox',
		["Function"] = function(): ()
			ProjectileExpand:SetValue(0);
		end
	});
end);

velo.run(function(): ()
	local SpinBot: table = {["Enabled"] = false};
	local Mode: table;
	local Value: table;
	local SpinX: table;
	local SpinY: table;
	local SpinZ: table;

	SpinBot = vape.Categories.Blatant:CreateModule({
		["Name"] = 'SpinBot',
		["Function"] = function(callback: boolean): ()
			if not callback then
				if entitylib.isAlive and Mode["Value"] == 'RotVelocity' then
					entitylib.character.Humanoid.AutoRotate = true;
				end;
				return;
			end;
			local mover: BodyAngularVelocity? = nil;
			if Mode["Value"] == 'BodyMover' then
				mover = Instance.new('BodyAngularVelocity');
				SpinBot:Clean(mover);
			end;
			SpinBot:Clean(runService.PreSimulation:Connect(function(): ()
				if not entitylib.isAlive or vape.Modules.LongJump["Enabled"] then
					return;
				end;
				local root: BasePart = entitylib.character.RootPart;
				local speed: number = Value["Value"];
				if Mode["Value"] == 'RotVelocity' then
					local spin: Vector3 = root.AssemblyAngularVelocity;
					entitylib.character.Humanoid.AutoRotate = false;
					root.AssemblyAngularVelocity = Vector3.new(SpinX["Enabled"] and speed or spin.X, SpinY["Enabled"] and speed or spin.Y, SpinZ["Enabled"] and speed or spin.Z);
				elseif Mode["Value"] == 'CFrame' then
					local angle: number = math.rad((tick() * 20 * speed) % 360);
					local x: number, y: number, z: number = root.CFrame:ToOrientation();
					root.CFrame = CFrame.new(root.Position) * CFrame.Angles(SpinX["Enabled"] and angle or x, SpinY["Enabled"] and angle or y, SpinZ["Enabled"] and angle or z);
				elseif mover then
					mover.Parent = root;
					mover.MaxTorque = Vector3.new(SpinX["Enabled"] and math.huge or 0, SpinY["Enabled"] and math.huge or 0, SpinZ["Enabled"] and math.huge or 0);
					mover.AngularVelocity = Vector3.one * speed;
				end;
			end));
		end,
		["Tooltip"] = 'Makes your character spin around in circles (does not work in first person)'
	});
	Mode = SpinBot:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'CFrame', 'RotVelocity', 'BodyMover'},
		["Function"] = function(): ()
			if SpinBot["Enabled"] then
				SpinBot:Toggle();
				SpinBot:Toggle();
			end;
		end
	});
	Value = SpinBot:CreateSlider({
		["Name"] = 'Speed',
		["Min"] = 1,
		["Max"] = 100,
		["Default"] = 40
	});
	SpinX = SpinBot:CreateToggle({["Name"] = 'Spin X'});
	SpinY = SpinBot:CreateToggle({
		["Name"] = 'Spin Y',
		["Default"] = true
	});
	SpinZ = SpinBot:CreateToggle({["Name"] = 'Spin Z'});
