	local Mode: table = {["Value"] = 'Heatseeker'};
	local Speed: table;
	local VerticalSpeed: table;
	local WallCheck: table;
	local PopBalloons: table;
	local TeleportDown: table;
	local AirTime: table;
	local Touchdown: table;
	local Return: table;
	local ShowProgress: table;
	local AirOnly: table;
	local ShowDistance: table;
	local pullRetry: number = 0.2;
	local hoverHeight: number = 195;
	local groundScan: number = 175;
	local landingPace: number = 2.55;
	local climbKeys: {[Enum.KeyCode]: number} = {[Enum.KeyCode.Space] = 1, [Enum.KeyCode.ButtonA] = 1, [Enum.KeyCode.LeftShift] = -1, [Enum.KeyCode.ButtonL2] = -1};
	local climb: {[number]: number} = {[1] = 0, [-1] = 0};
	local pull: table = {["ReturnY"] = nil, ["Until"] = 0, ["Next"] = 0};
	local wallParams: RaycastParams = RaycastParams.new();
	wallParams.RespectCanCollide = true;
	local filtered: Model?;
	local filteredFloor: BasePart?;
	local bar: table?;
	local session: table?;
	local visibleIn: {[table]: {string}} = {};

	local setBar: (wanted: boolean) -> () = function(wanted: boolean): ()
		if bar then
			bar.Frame:Destroy();
			bar = nil;
		end;
		if wanted then
			bar = createProgressBar();
		end;
	end;

	local trackClimb: (module: table) -> () = function(module: table): ()
		climb[1], climb[-1] = 0, 0;
		module:Clean(inputService.InputBegan:Connect(function(input: InputObject): ()
			local direction: number? = climbKeys[input.KeyCode];
			if direction and not inputService:GetFocusedTextBox() then
				climb[direction] = direction;
			end;
