			end;
		end));
		local touchGui: Instance? = inputService.TouchEnabled and lplr.PlayerGui:FindFirstChild('TouchGui');
		local jumpButton: Instance? = touchGui and touchGui:FindFirstChild('JumpButton', true);
		if jumpButton then
			module:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function(): ()
				climb[1] = jumpButton.ImageRectOffset.X == 146 and 1 or 0;
			end));
		end;
	end;

	local pullDown: (root: BasePart, airborne: boolean) -> boolean = function(root: BasePart, airborne: boolean): boolean
		local now: number = tick();
		if pull.Until > now then
			return true;
		end;
		if pull.ReturnY then
			root.CFrame = CFrame.lookAlong(Vector3.new(root.Position.X, pull.ReturnY, root.Position.Z), root.CFrame.LookVector);
			entitylib.character.AirTime = now;
			pull.ReturnY = nil;
			return false;
		end;
		if airborne and now - entitylib.character.AirTime > AirTime["Value"] and pull.Next < now then
			local ground: RaycastResult? = workspace:Raycast(root.Position, Vector3.new(0, -1000, 0), store.airRay or wallParams);
			if ground then
				pull.ReturnY = Return["Enabled"] and root.Position.Y or nil;
				pull.Until = now + Touchdown["Value"];
				pull.Next = pull.Until + pullRetry;
				root.CFrame = CFrame.lookAlong(Vector3.new(root.Position.X, ground.Position.Y + entitylib.character.HipHeight, root.Position.Z), root.CFrame.LookVector);
				return true;
			end;
		end;
		return false;
	end;

	local finishInfinite: () -> () = function(): ()
		if not session then
			return;
		end;
		for object: Instance, saved: any in session.Hidden do
			if type(saved) == 'boolean' then
				object.Enabled = saved;
			else
				object.LocalTransparencyModifier = saved;
			end;
		end;
		if session.Fake then
			session.Fake:Destroy();
		end;
		local humanoid: Humanoid? = lplr.Character and lplr.Character:FindFirstChildOfClass('Humanoid');
		if gameCamera.CameraSubject == session.Part and humanoid then
			gameCamera.CameraSubject = humanoid;
		end;
		session.Part:Destroy();
		session = nil;
	end;
	vape:Clean(finishInfinite);

	local landInfinite: () -> () = function(): ()
		store.infinitefly = false;
		local noFall: table? = vape.Modules.NoFall;
		if noFall and not noFall["Enabled"] then
			noFall:Toggle();
		end;
		local fallTime: number, ground: RaycastResult? = 0, nil;
		if entitylib.isAlive and isnetworkowner(entitylib.character.RootPart) and store.airRay then
			local root: BasePart = entitylib.character.RootPart;
			fallTime = 1;
			ground = workspace:Raycast(root.Position, Vector3.new(0, -1000, 0), store.airRay);
			if ground then
				local height: number = math.max(root.Position.Y - ground.Position.Y - entitylib.character.Humanoid.HipHeight - root.Size.Y / 2, 0);
				local falling: number = math.max(-root.AssemblyLinearVelocity.Y, 0);
				fallTime = (-falling + math.sqrt(falling * falling + 2 * workspace.Gravity * height)) / workspace.Gravity;
			end;
		end;
		task.delay(fallTime / landingPace, function(): ()
			if ground and entitylib.isAlive then
				local cell: Vector3 = bedwars.BlockController:getBlockPosition(ground.Position) * 3;
				local center: RaycastResult? = workspace:Raycast(Vector3.new(cell.X, ground.Position.Y + 1, cell.Z), Vector3.new(0, -2, 0), store.airRay);
				local flat: boolean = center ~= nil and center.Normal.Y > 0.99 and math.abs(center.Position.Y - ground.Position.Y) < 0.1 and not workspace:Raycast(center.Position + Vector3.new(0, 0.1, 0), Vector3.new(0, 6, 0), store.airRay);
				entitylib.character.RootPart.CFrame = CFrame.new((flat and center.Position or ground.Position) + Vector3.new(0, 2.5, 0));
			end;
			finishInfinite();
			notif('InfiniteFly', 'Landed', 2.5, 'info');
		end);
	end;

	local startInfinite: () -> () = function(): ()
		if not entitylib.isAlive or session or not store.airRay or workspace:Raycast(entitylib.character.RootPart.Position, Vector3.new(0, -1000, 0), store.airRay) then
			notif('InfiniteFly', 'Only starts over the void.', 8, 'warning');
			task.defer(function(): ()
				if InfiniteFly["Enabled"] then
					InfiniteFly:Toggle();
				end;
			end);
			return;
		end;
		local character: Model = entitylib.character.Character;
		local root: BasePart = entitylib.character.RootPart;
		local start: Vector3 = root.Position;
		local part: Part = Instance.new('Part');
		part.Transparency = 1;
		part.CanQuery = false;
		part.CanTouch = false;
		part.CanCollide = false;
		part.Anchored = true;
		part.CFrame = entitylib.character.Head.CFrame;
		part.Parent = workspace;
		session = {["Part"] = part, ["Hidden"] = {}, ["Twins"] = {}};
		local active: table = session;

		local archivable: boolean = character.Archivable;
		character.Archivable = true;
		local fake: Model = character:Clone();
		character.Archivable = archivable;
		local pairTwins: (real: Instance, copy: Instance) -> ();
		pairTwins = function(real: Instance, copy: Instance): ()
			local copies: {Instance} = copy:GetChildren();
			local index: number = 1;
			for _: number, child: Instance in real:GetChildren() do
				local twin: Instance? = copies[index];
				if twin and twin.Name == child.Name and twin.ClassName == child.ClassName then
					index += 1;
					if child:IsA('BasePart') then
						active.Twins[child] = twin;
					end;
					pairTwins(child, twin);
				end;
			end;
		end;
		pairTwins(character, fake);
		local stripped: {Instance} = fake:GetDescendants();
		table.insert(stripped, fake);
		for _: number, object: Instance in stripped do
			for _: number, tag: string in object:GetTags() do
				object:RemoveTag(tag);
			end;
			if object:IsA('LuaSourceContainer') or object:IsA('JointInstance') or object:IsA('Constraint') or object:IsA('WeldConstraint') or object:IsA('ParticleEmitter') or object:IsA('Trail') or object:IsA('Beam') or object:IsA('Highlight') or object:IsA('ForceField') or object:IsA('Sound') or object:IsA('ObjectValue') then
				object:Destroy();
			elseif object:IsA('BasePart') then
				object.CanCollide = false;
				object.CanQuery = false;
				object.CanTouch = false;
				object.Anchored = true;
			end;
		end;
		local fakeHumanoid: Humanoid? = fake:FindFirstChildOfClass('Humanoid');
		if fakeHumanoid then
			fakeHumanoid.RequiresNeck = false;
			fakeHumanoid.BreakJointsOnDeath = false;
			fakeHumanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None;
			fakeHumanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff;
			fakeHumanoid.EvaluateStateMachine = false;
		end;
		fake.Name = 'InfiniteFlyFake';
		fake.Parent = workspace;
		active.Fake = fake;

		local hide: (object: Instance) -> () = function(object: Instance): ()
			if active.Hidden[object] ~= nil then
				return;
			end;
			if object:IsA('BasePart') or object:IsA('Decal') then
				active.Hidden[object] = object.LocalTransparencyModifier;
				object.LocalTransparencyModifier = 1;
			elseif object:IsA('BillboardGui') then
				active.Hidden[object] = object.Enabled;
				object.Enabled = false;
			end;
		end;
		for _: number, object: Instance in character:GetDescendants() do
			hide(object);
		end;
		InfiniteFly:Clean(character.DescendantAdded:Connect(hide));
		InfiniteFly:Clean(character.DescendantRemoving:Connect(function(object: Instance): ()
			local twin: Instance? = active.Twins[object];
			if twin then
				active.Twins[object] = nil;
				twin:Destroy();
			end;
			local saved: any = active.Hidden[object];
			if saved ~= nil then
				active.Hidden[object] = nil;
				if type(saved) == 'boolean' then
					object.Enabled = saved;
				else
					object.LocalTransparencyModifier = saved;
				end;
			end;
		end));
		gameCamera.CameraSubject = part;
		store.infinitefly = true;

		local label: TextLabel?, shadow: TextLabel?;
		if ShowDistance["Enabled"] then
			label = Instance.new('TextLabel');
			label.Size = UDim2.fromOffset(100, 20);
			label.Position = UDim2.new(0.5, 6, 0.5, 60);
			label.AnchorPoint = Vector2.new(0.5, 0);
			label.BackgroundTransparency = 1;
			label.Text = '0 blocks';
			label.ZIndex = 6;
			label.TextColor3 = Color3.new(1, 1, 1);
			label.TextSize = 18;
			label.FontFace = uipallet.Font;
			shadow = label:Clone();
			shadow.ZIndex = 5;
			shadow.Position += UDim2.fromOffset(1, 1);
			shadow.TextColor3 = Color3.new();
			label.Parent = vape.gui;
			shadow.Parent = vape.gui;
			InfiniteFly:Clean(label);
			InfiniteFly:Clean(shadow);
		end;

		local simTime: number, lagAverage: number?, lastView: number?, lastRoot: Vector3?, rootVelocity: Vector3 = 0, nil, nil, nil, Vector3.zero;
		local fakeVisible: boolean = true;
		InfiniteFly:Clean(runService.PostSimulation:Connect(function(delta: number): ()
			if not entitylib.isAlive then
				return;
			end;
			local position: Vector3 = entitylib.character.RootPart.Position;
			simTime += delta;
			if lastRoot and delta > 0 then
				rootVelocity = Vector3.new(position.X - lastRoot.X, 0, position.Z - lastRoot.Z) / delta;
			end;
			lastRoot = position;
		end));
		runService:BindToRenderStep('VelocityInfiniteFly', Enum.RenderPriority.Camera.Value - 1, function(delta: number): ()
			for object: Instance, saved: any in active.Hidden do
				if type(saved) == 'boolean' then
					object.Enabled = false;
				elseif object.LocalTransparencyModifier ~= 1 then
					object.LocalTransparencyModifier = 1;
				end;
			end;
			if not entitylib.isAlive then
				return;
			end;
			local now: number = os.clock();
			local step: number = math.min(lastView and now - lastView or delta, 0.1);
			lastView = now;
			local lag: number = now - simTime;
			lagAverage = lagAverage and lagAverage + (lag - lagAverage) * math.min(step / 0.25, 1) or lag;
			local lead: Vector3 = rootVelocity * (lag - lagAverage);
			if lead.Magnitude > 2 then
				lead = lead.Unit * 2;
			end;
			local rootPosition: Vector3 = entitylib.character.RootPart.Position;
			part.CFrame = CFrame.new(rootPosition.X + lead.X, part.Position.Y + step * (climb[1] + climb[-1]) * InfiniteVertical["Value"], rootPosition.Z + lead.Z);
			local shift: Vector3 = Vector3.new(part.Position.X - rootPosition.X, part.Position.Y - entitylib.character.Head.Position.Y, part.Position.Z - rootPosition.Z);
			for real: Instance, twin: BasePart in active.Twins do
				twin.CFrame = real.CFrame + shift;
			end;
			local visible: boolean = (gameCamera.CFrame.Position - gameCamera.Focus.Position).Magnitude > 1;
			if visible ~= fakeVisible then
				fakeVisible = visible;
				for _: number, object: Instance in fake:GetDescendants() do
					if object:IsA('BillboardGui') then
						object.Enabled = visible;
					elseif object:IsA('BasePart') or object:IsA('Decal') then
						object.LocalTransparencyModifier = visible and 0 or 1;
					end;
				end;
			end;
		end);
		InfiniteFly:Clean(function(): ()
			runService:UnbindFromRenderStep('VelocityInfiniteFly');
		end);

		local scanDirections: {Vector3} = {Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1)};
		InfiniteFly:Clean(runService.PreSimulation:Connect(function(): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			if not entitylib.isAlive or entitylib.character.RootPart ~= root or not isnetworkowner(root) then
				notif('InfiniteFly', 'Network ownership disowned', 10, 'alert');
				InfiniteFly:Toggle();
				return;
			end;
			if workspace:Raycast(root.Position, Vector3.new(0, -1000, 0), store.airRay) then
				notif('InfiniteFly', 'Force landing', 3.5, 'alert');
				InfiniteFly:Toggle();
				return;
			end;
			if label and shadow then
				label.Text = math.round((start - Vector3.new(root.Position.X, part.Position.Y, root.Position.Z)).Magnitude / 3)..' blocks';
				shadow.Text = label.Text;
			end;
			local nearGround: boolean = root.Position.Y <= part.Position.Y + 4;
			for _: number, direction: Vector3 in {entitylib.character.Humanoid.MoveDirection, table.unpack(scanDirections)} do
				for distance: number = 1, (nearGround and 0 or 4) do
					nearGround = nearGround or workspace:Blockcast(root.CFrame + direction * distance, Vector3.new(3, 3, 3), Vector3.new(0, -groundScan, 0), store.airRay) ~= nil;
				end;
			end;
			if nearGround then
				root.CFrame = CFrame.lookAlong(Vector3.new(root.Position.X, hoverHeight, root.Position.Z), root.CFrame.LookVector);
			end;
		end));
	end;

	local startHeatseeker: () -> () = function(): ()
		local heatseeker: boolean = Mode["Value"] == 'Heatseeker';
		pull.ReturnY, pull.Until, pull.Next = nil, 0, 0;
		setBar(ShowProgress["Enabled"]);
		if heatseeker then
			local oldDeflate: (...any) -> ...any = bedwars.BalloonController.deflateBalloon;
			bedwars.BalloonController.deflateBalloon = function(): () end;
			Fly:Clean(function(): ()
				bedwars.BalloonController.deflateBalloon = oldDeflate;
				if PopBalloons["Enabled"] and entitylib.isAlive and (lplr.Character:GetAttribute('InflatedBalloons') or 0) > 0 then
					for _: number = 1, 3 do
						bedwars.BalloonController:deflateBalloon();
					end;
				end;
			end);
			if lplr.Character and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
				bedwars.BalloonController:inflateBalloon();
			end;
			Fly:Clean(vapeEvents.AttributeChanged.Event:Connect(function(attribute: string): ()
				if attribute == 'InflatedBalloons' and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
					bedwars.BalloonController:inflateBalloon();
				end;
			end));
		end;
		Fly:Clean(runService.PreSimulation:Connect(function(delta: number): ()
			if not entitylib.isAlive or store.infinitefly or not isnetworkowner(entitylib.character.RootPart) then
				if bar then
					bar.Frame.Visible = false;
				end;
				return;
			end;
			local root: BasePart = entitylib.character.RootPart;
			local humanoid: Humanoid = entitylib.character.Humanoid;
			if filtered ~= lplr.Character or filteredFloor ~= store.antiFallPart then
				filtered, filteredFloor = lplr.Character, store.antiFallPart;
				wallParams.FilterDescendantsInstances = {filtered, gameCamera, filteredFloor};
			end;
			wallParams.CollisionGroup = root.CollisionGroup;
			local airborne: boolean = humanoid.FloorMaterial == Enum.Material.Air;
			local balloons: boolean = heatseeker and ((lplr.Character:GetAttribute('InflatedBalloons') or 0) > 0 or store.matchState == 2);
			local pulling: boolean = not heatseeker or (TeleportDown["Enabled"] and not balloons);
			if bar then
				bar.Frame.Visible = pulling and (airborne or not AirOnly["Enabled"]);
				bar.Set(AirTime["Value"] - (airborne and tick() - entitylib.character.AirTime or 0), AirTime["Value"]);
			end;
			local holding: boolean = pulling and pullDown(root, airborne);
			if not heatseeker then
				if holding then
					root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z);
				end;
				return;
			end;
			local lift: number = holding and 0 or (-0.02 + (balloons and 6 or 0) * (tick() % 0.4 < 0.2 and -1 or 1)) + (climb[1] + climb[-1]) * VerticalSpeed["Value"];
			local moveDirection: Vector3 = humanoid.MoveDirection;
			local walkSpeed: number = getSpeed();
			local destination: Vector3 = moveDirection * math.max(Speed["Value"] - walkSpeed, 0) * delta;
			if WallCheck["Enabled"] then
				local wall: RaycastResult? = workspace:Raycast(root.Position, destination, wallParams);
				if wall then
					destination = (wall.Position + wall.Normal) - root.Position;
				end;
			end;
			root.CFrame += destination;
			root.AssemblyLinearVelocity = moveDirection * walkSpeed + Vector3.new(0, lift, 0);
		end));
	end;

	Fly = vape.Categories.Blatant:CreateModule({
		["Name"] = 'Fly',
		["Function"] = function(callback: boolean): ()
			frictionUsers.Fly = callback and Mode["Value"] == 'Heatseeker' or nil;
			updateFriction();
			if not callback then
				return;
			end;
			Fly:Clean(function(): ()
				setBar(false);
			end);
			trackClimb(Fly);
			startHeatseeker();
		end,
		["ExtraText"] = function(): string
			return Mode["Value"];
		end,
		["Tooltip"] = 'Makes you go zoom.\nHeatseeker: balloon fly with TP Down once the balloons run out.\nTP Down: only pulls you to the ground after too long in the air.'
	});

	local refreshOptions: () -> () = function(): ()
		for option: table, modes: {string} in visibleIn do
			option.Object.Visible = table.find(modes, Mode["Value"]) ~= nil and (option ~= AirOnly or ShowProgress["Enabled"]);
		end;
	end;

	Mode = Fly:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Heatseeker', 'TP Down'},
		["Function"] = function(value: string): ()
			refreshOptions();
			if Fly["Enabled"] then
				Fly:Toggle();
				Fly:Toggle();
			end;
		end
	});
	Speed = Fly:CreateSlider({
		["Name"] = 'Speed',
		["Min"] = 1,
		["Max"] = 23,
		["Default"] = 23,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	VerticalSpeed = Fly:CreateSlider({
		["Name"] = 'Vertical Speed',
		["Min"] = 1,
		["Max"] = 150,
		["Default"] = 50,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	WallCheck = Fly:CreateToggle({
		["Name"] = 'Wall Check',
		["Default"] = true
	});
	PopBalloons = Fly:CreateToggle({
		["Name"] = 'Pop Balloons',
		["Default"] = true
	});
	TeleportDown = Fly:CreateToggle({
		["Name"] = 'TP Down',
		["Default"] = true,
		["Tooltip"] = 'Without balloons, briefly teleports you to the ground before the air timer runs out.'
	});
	AirTime = Fly:CreateSlider({
		["Name"] = 'Air Time',
		["Min"] = 0.5,
		["Max"] = 3,
		["Default"] = 1.7,
		["Decimal"] = 10,
		["Suffix"] = function(value: number): string
			return value == 1 and 'second' or 'seconds';
		end,
		["Tooltip"] = 'How long you can stay in the air before you get pulled down.'
	});
	Touchdown = Fly:CreateSlider({
		["Name"] = 'Touchdown',
		["Min"] = 0.05,
		["Max"] = 0.5,
		["Default"] = 0.11,
		["Decimal"] = 100,
		["Suffix"] = function(value: number): string
			return value == 1 and 'second' or 'seconds';
		end,
		["Tooltip"] = 'How long you stay on the ground before going back up.'
	});
	Return = Fly:CreateToggle({
		["Name"] = 'Return',
		["Default"] = true,
		["Tooltip"] = 'Teleports you back up to the height you were pulled down from.'
	});
	ShowProgress = Fly:CreateToggle({
		["Name"] = 'Show Progressbar',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			refreshOptions();
			setBar(callback and Fly["Enabled"]);
		end,
		["Tooltip"] = 'Shows a bar counting down to the next pull down.'
	});
	AirOnly = Fly:CreateToggle({
		["Name"] = 'Air Only',
		["Darker"] = true,
		["Tooltip"] = 'Only shows the bar while you are in the air.'
	});
	visibleIn[Speed] = {'Heatseeker'};
	visibleIn[VerticalSpeed] = {'Heatseeker'};
	visibleIn[WallCheck] = {'Heatseeker'};
	visibleIn[PopBalloons] = {'Heatseeker'};
	visibleIn[TeleportDown] = {'Heatseeker'};
	visibleIn[AirTime] = {'Heatseeker', 'TP Down'};
	visibleIn[Touchdown] = {'Heatseeker', 'TP Down'};
	visibleIn[Return] = {'Heatseeker', 'TP Down'};
	visibleIn[ShowProgress] = {'Heatseeker', 'TP Down'};
	visibleIn[AirOnly] = {'Heatseeker', 'TP Down'};
	refreshOptions();

	InfiniteFly = vape.Categories.Blatant:CreateModule({
		["Name"] = 'InfiniteFly',
		["Function"] = function(callback: boolean): ()
			if not callback then
				if session and store.infinitefly then
					landInfinite();
				end;
				return;
			end;
			trackClimb(InfiniteFly);
			startInfinite();
		end,
		["Tooltip"] = 'Hover over the void with your body parked out of reach.'
	});
	InfiniteVertical = InfiniteFly:CreateSlider({
		["Name"] = 'Vertical Speed',
		["Min"] = 1,
		["Max"] = 150,
		["Default"] = 50,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	ShowDistance = InfiniteFly:CreateToggle({
		["Name"] = 'Show distance',
		["Default"] = true,
		["Tooltip"] = 'Shows how many blocks you travelled.'
	});
end);

velo.run(function(): ()
	local LongJump: table = {["Enabled"] = false};
	local Speed: table;
	local CameraDirection: table;
	local StoreDamage: table;
	local CannonMode: table = {["Value"] = 'Boost'};
	local AimMode: table;
	local PositionMode: table;
	local SearchRange: table;
	local PlaceCannon: table;
	local AutoSwitch: table;
	local LaunchCannon: table;
	local ShowTarget: table;
	local OldCorrection: table;
	local DaveyOnly: table;
	local CannonSpeed: table = {["Enabled"] = false};
	local CannonLaunchSpeed: table = {["Value"] = 200};
	local coast: number = 1.1;
	local lift: number = 15;
	local storedLift: number = 10;
	local legitCannonSpeed: number = 200;
	local softSteps: number = 14;
	local safeFallSpeed: number = 99;
	local fallDamageScale: number = 0.884;
	local abilityOptions: table = {["disableBlockedAbilityAlert"] = true};
	local boosts: {[string]: table} = {
		["cannon"] = {["Multiplier"] = 5.25, ["Duration"] = 2.3},
		["cat"] = {["Multiplier"] = 4, ["Duration"] = 2.5},
		["grapple"] = {["Multiplier"] = 2.5, ["Duration"] = 2.5},
		["hammer"] = {["Multiplier"] = 1.4, ["Duration"] = 2.5},
		["dao"] = {["Multiplier"] = 4.5, ["Duration"] = 2.4}
	};
	local methodOf: {[string]: string} = {
		["cannon"] = 'cannon', ["cat"] = 'cat', ["fireball"] = 'fireball', ["grappling_hook"] = 'grapple',
		["jade_hammer"] = 'hammer', ["void_axe"] = 'hammer', ["tnt"] = 'tnt', ["siege_tnt"] = 'tnt', ["pirate_gunpowder_barrel"] = 'tnt',
		["wood_dao"] = 'dao', ["stone_dao"] = 'dao', ["iron_dao"] = 'dao', ["diamond_dao"] = 'dao', ["emerald_dao"] = 'dao'
	};
	local methodOrder: {string} = {'cannon', 'cat', 'fireball', 'grappling_hook', 'jade_hammer', 'void_axe', 'tnt', 'siege_tnt', 'pirate_gunpowder_barrel', 'wood_dao', 'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'};
	local jump: table = {["Tick"] = tick(), ["Speed"] = 0, ["Lift"] = lift, ["Direction"] = Vector3.zero, ["Start"] = nil, ["Waiting"] = nil};
	local arcParams: RaycastParams = RaycastParams.new();
	arcParams.RespectCanCollide = true;
	local cannonConstant: table?;
	local aimSession: table?;
	local visibleIn: {[table]: () -> boolean} = {};

	local propel: (look: Vector3, speed: number, duration: number) -> () = function(look: Vector3, speed: number, duration: number): ()
		jump.Speed = speed;
		jump.Lift = lift;
		jump.Tick = tick() + duration;
		jump.Direction = Vector3.new(look.X, 0, look.Z).Unit;
	end;

	local boost: (method: string, look: Vector3) -> () = function(method: string, look: Vector3): ()
		propel(look, boosts[method].Multiplier * Speed["Value"], boosts[method].Duration);
	end;

	local findCannonConstant: () -> table? = function(): table?
		if cannonConstant then
			return cannonConstant;
		end;
		local controller: table = bedwars.CannonHandController;
		local meta: any = getmetatable(controller);
		local launchSelf: any = type(meta) == 'table' and type(rawget(meta, '__index')) == 'table' and rawget(meta.__index, 'launchSelf') or controller.launchSelf;
		if type(launchSelf) ~= 'function' then
			return nil;
		end;
		local search: (func: (...any) -> ...any, depth: number) -> table?;
		search = function(func: (...any) -> ...any, depth: number): table?
			local constants: {any} = debug.getconstants(func);
			if table.find(constants, 'LaunchSelfFromCannon') then
				for index: number, value: any in constants do
					if type(value) == 'number' and value > 0 then
						return {["Func"] = func, ["Index"] = index, ["Original"] = value};
					end;
				end;
			end;
			for _: number, upvalue: any in (depth < 3 and debug.getupvalues(func) or {}) do
				local found: table? = type(upvalue) == 'function' and debug.info(upvalue, 's') ~= '[C]' and search(upvalue, depth + 1) or nil;
				if found then
					return found;
				end;
			end;
			return nil;
		end;
		cannonConstant = search(launchSelf, 0);
		for index: number, value: any in (cannonConstant == nil and debug.getconstants(launchSelf) or {}) do
			if type(value) == 'number' then
				cannonConstant = {["Func"] = launchSelf, ["Index"] = index, ["Original"] = value};
				break;
			end;
		end;
		return cannonConstant;
	end;

	local applyCannonSpeed: () -> () = function(): ()
		local constant: table? = findCannonConstant();
		if constant then
			debug.setconstant(constant.Func, constant.Index, CannonSpeed["Enabled"] and CannonLaunchSpeed["Value"] or constant.Original);
		end;
	end;
	vape:Clean(function(): ()
		if cannonConstant then
			debug.setconstant(cannonConstant.Func, cannonConstant.Index, cannonConstant.Original);
		end;
	end);

	local solveArc: (origin: Vector3, delta: Vector3, velocity: Vector3, speed: number) -> number? = function(origin: Vector3, delta: Vector3, velocity: Vector3, speed: number): number?
		local gravity: number = workspace.Gravity;
		local launchFor: (t: number) -> Vector3 = function(t: number): Vector3
			return (delta + Vector3.new(0, gravity * t * t * 0.5, 0)) / t;
		end;
		local excess: (t: number) -> number = function(t: number): number
			return (launchFor(t) - velocity).Magnitude;
		end;
		local low: number, high: number = 0.0001, 20;
		for _: number = 1, 50 do
			local first: number, second: number = low + (high - low) / 3, high - (high - low) / 3;
			if excess(first) < excess(second) then
				high = second;
			else
				low = first;
			end;
		end;
		local easiest: number = (low + high) / 2;
		if excess(easiest) > speed then
			return nil;
		end;
		local edge: (outside: number, inside: number) -> number = function(outside: number, inside: number): number
			for _: number = 1, 60 do
				local middle: number = (outside + inside) / 2;
				if excess(middle) > speed then
					outside = middle;
				else
					inside = middle;
				end;
			end;
			return (outside + inside) / 2;
		end;
		local quick: number, lazy: number = edge(0.0001, easiest), edge(20, easiest);
		local candidates: {number} = {quick, lazy};
		for step: number = 1, softSteps do
			table.insert(candidates, quick + (lazy - quick) * step / (softSteps + 1));
		end;
		if OldCorrection["Enabled"] then
			for step: number = -24, 24 do
				local t: number = easiest * (1 + step * 0.05);
				if t > 0.05 and excess(t) <= speed then
					table.insert(candidates, t);
				end;
			end;
		end;
		local apex: (t: number) -> number = function(t: number): number
			local rise: number = launchFor(t).Y;
			return rise > 0 and rise * rise / (2 * gravity) or 0;
		end;
		table.sort(candidates, function(a: number, b: number): boolean
			if apex(a) ~= apex(b) then
				return apex(a) < apex(b);
			end;
			return a < b;
		end);
		local grounded: boolean = entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air;
		local lower: Vector3 = Vector3.yAxis * math.max(entitylib.character.HipHeight - 2, 0);
		for _: number, t: number in candidates do
			local arc: Vector3 = launchFor(t);
			if grounded and arc.Y <= 0 then
				continue;
			end;
			local previous: Vector3, clear: boolean = origin, true;
			local steps: number = math.clamp(math.ceil(math.max(t * 60, (arc.Magnitude * t + gravity * t * t * 0.5) / 6)), 12, 240);
			for step: number = 1, steps do
				local elapsed: number = t * step / steps;
				local point: Vector3 = origin + arc * elapsed - Vector3.new(0, gravity * elapsed * elapsed * 0.5, 0);
				local hit: RaycastResult? = workspace:Spherecast(previous, 2, point - previous, arcParams) or workspace:Spherecast(previous - lower, 2, point - previous, arcParams);
				local landing: boolean = hit ~= nil and step == steps and hit.Normal.Y > 0.7 and ((hit.Position - origin - delta) * Vector3.new(1, 0, 1)).Magnitude <= 2.5;
				if hit and not landing then
					clear = false;
					break;
				end;
				previous = point;
			end;
			if clear then
				return t;
			end;
		end;
		return nil;
	end;

	local startAim: () -> () = function(): ()
		local root: BasePart = entitylib.character.RootPart;
		local humanoid: Humanoid = entitylib.character.Humanoid;
		local active: table = {["Phase"] = 'plan', ["Until"] = 0};
		aimSession = active;
		local cannon: BasePart?, spot: Vector3?;
		local closest: number = SearchRange["Value"];
		for _: number, block: Instance in store.blocks do
			if block.Name == 'cannon' and (root.Position - block.Position).Magnitude <= closest then
				cannon, closest = block, (root.Position - block.Position).Magnitude;
			end;
		end;

		local finish: (message: string?) -> () = function(message: string?): ()
			if active.Done then
				return;
			end;
			active.Done = true;
			if message then
				notif('LongJump', message, 5, 'warning');
			end;
			local controller: table = bedwars.CannonHandController;
			if active.Hook and controller.launchSelf == active.Hook then
				controller.launchSelf = active.OldLaunch;
			end;
			if store.cannonFlight == active then
				store.cannonFlight = nil;
			end;
			if active.Launched and humanoid.Parent and not humanoid.AutoRotate then
				humanoid.AutoRotate = active.AutoRotate;
			end;
			if OldCorrection["Enabled"] and active.Launched and entitylib.isAlive and entitylib.character.RootPart == root then
				root.AssemblyLinearVelocity = Vector3.new(0, math.min(root.AssemblyLinearVelocity.Y, 0), 0);
			end;
			if active.Visual then
				active.Visual:Destroy();
			end;
			task.defer(function(): ()
				if aimSession == active and LongJump["Enabled"] then
					LongJump:Toggle();
				end;
			end);
		end;
		LongJump:Clean(function(): ()
			finish(nil);
		end);

		if not cannon then
			local item: table? = getItem('cannon');
			if not PlaceCannon["Enabled"] or not item then
				finish(PlaceCannon["Enabled"] and 'No cannon in your inventory.' or 'No cannon in range.');
				return;
			end;
			local feet: Vector3 = roundPos(root.Position - Vector3.new(0, entitylib.character.HipHeight + 1.5, 0));
			for drop: number = 0, 3 do
				if getPlacedBlock(feet - Vector3.yAxis * (3 * drop)) then
					feet -= Vector3.yAxis * (3 * drop);
					break;
				end;
			end;
			local nearest: number = math.huge;
			for x: number = -3, 3 do
				for z: number = -3, 3 do
					for y: number = 0, 1 do
						local cell: Vector3 = feet + Vector3.new(x * 3, y * 3, z * 3);
						local distance: number = (root.Position - cell).Magnitude;
						local free: boolean = not getPlacedBlock(cell) and not getPlacedBlock(cell + Vector3.yAxis * 3) and getPlacedBlock(cell - Vector3.yAxis * 3) ~= nil;
						if free and distance <= SearchRange["Value"] and distance < nearest and cell ~= feet and cell ~= feet + Vector3.yAxis * 3 then
							spot, nearest = cell, distance;
						end;
					end;
				end;
			end;
			if not spot then
				finish('Nowhere to put a cannon.');
				return;
			end;
			if AutoSwitch["Enabled"] then
				switchItem(item.tool);
				hotbarSwitch(hotbarSlotOf(item.tool));
			end;
			if not LongJump["Enabled"] or active.Done then
				return;
			end;
			placeBlock(spot, 'cannon');
			active.Phase, active.Until = 'place', tick() + 1 + store.ping.total;
		end;

		local direction: Vector3, targetPosition: Vector3, flightTime: number, launchSpeed: number;
		local turnFrom: Vector3, turnTime: number, turned: number = Vector3.zero, 0, 0;
		local nextAim: number = 0;
		local plan: () -> () = function(): ()
			local aimRay: Ray = (PositionMode["Value"] == 'Camera' or inputService.TouchEnabled) and Ray.new(gameCamera.CFrame.Position, gameCamera.CFrame.LookVector) or cloneref(lplr:GetMouse()).UnitRay;
			local ignored: {Instance} = {lplr.Character, gameCamera, cannon};
			local hit: RaycastResult?, firstHit: RaycastResult?;
			for _: number = 1, 8 do
				arcParams.FilterDescendantsInstances = ignored;
				local result: RaycastResult? = workspace:Raycast(aimRay.Origin, aimRay.Direction * 10000, arcParams);
				if not result then
					break;
				end;
				firstHit = firstHit or result;
				if collectionService:HasTag(result.Instance, 'block') then
					hit = result;
					break;
				end;
				table.insert(ignored, result.Instance);
			end;
			arcParams.FilterDescendantsInstances = {lplr.Character, gameCamera, cannon};
			hit = hit or firstHit;
			if not hit then
				finish('No block found where you are aiming.');
				return;
			end;
			local origin: Vector3 = root.Position;
			local velocity: Vector3 = root.AssemblyLinearVelocity;
			local constant: table? = findCannonConstant();
			launchSpeed = CannonSpeed["Enabled"] and CannonLaunchSpeed["Value"] or constant and constant.Original or legitCannonSpeed;
			targetPosition = hit.Position + Vector3.new(0, entitylib.character.HipHeight, 0);
			local maxRange: number = launchSpeed * launchSpeed / workspace.Gravity;
			if (targetPosition - origin).Magnitude > maxRange then
				finish('Too far away ('..math.floor((targetPosition - origin).Magnitude)..' studs away, '..math.floor(maxRange)..' max).');
				return;
			end;
			local solved: number? = solveArc(origin, targetPosition - origin, velocity, launchSpeed);
			if not solved then
				finish('No clear cannon arc to that position.');
				return;
			end;
			flightTime = solved;
			local arc: Vector3 = (targetPosition - origin + Vector3.new(0, workspace.Gravity * flightTime * flightTime * 0.5, 0)) / flightTime;
			local landingSpeed: number = math.max(workspace.Gravity * flightTime - arc.Y, 0);
			local fallDamage: number = math.max(landingSpeed - safeFallSpeed, 0) * fallDamageScale;
			local noFall: table? = vape.Modules.NoFall;
			if fallDamage >= humanoid.Health - 3 and not (noFall and noFall["Enabled"]) then
				finish('That landing would deal about '..math.floor(fallDamage)..' damage ('..math.floor(landingSpeed)..' studs/s down), pick a lower or closer spot.');
				return;
			end;
			direction = (arc - velocity).Unit;
			if ShowTarget["Enabled"] then
				local cell: Vector3 = roundPos(hit.Position - hit.Normal * 1.5);
				local visual: Part = Instance.new('Part');
				visual.Size = Vector3.new(3, 3, 3);
				visual.CFrame = CFrame.new(cell);
				visual.Anchored = true;
				visual.CanCollide = false;
				visual.CanQuery = false;
				visual.CanTouch = false;
				visual.CastShadow = false;
				visual.Transparency = 1;
				local selection: SelectionBox = Instance.new('SelectionBox');
				selection.Adornee = visual;
				selection.LineThickness = 0.04;
				selection.Color3 = Color3.new(1, 1, 1);
				selection.SurfaceColor3 = Color3.new(1, 1, 1);
				selection.SurfaceTransparency = 0.75;
				selection.Parent = visual;
				local bounds: Vector2 = getfontsize('Landing (000 studs)', 14, uipallet.Font);
				local billboard: BillboardGui = Instance.new('BillboardGui');
				billboard.Size = UDim2.fromOffset(bounds.X + 8, bounds.Y + 7);
				billboard.StudsOffsetWorldSpace = (targetPosition - cell) + Vector3.new(0, 2, 0);
				billboard.AlwaysOnTop = true;
				billboard.Parent = visual;
				local tag: TextLabel = Instance.new('TextLabel');
				tag.Size = billboard.Size;
				tag.BackgroundColor3 = Color3.new();
				tag.BackgroundTransparency = 0.5;
				tag.BorderSizePixel = 0;
				tag.FontFace = uipallet.Font;
				tag.TextSize = 14;
				tag.TextColor3 = Color3.new(1, 1, 1);
				tag.Text = 'Landing ('..math.floor((targetPosition - origin).Magnitude)..' studs)';
				tag.Parent = billboard;
				bedwars.QueryUtil:setQueryIgnored(visual, true);
				visual.Parent = gameCamera;
				active.Visual, active.Tag = visual, tag;
			end;
			if AimMode["Value"] == 'Legit' then
				turnFrom = gameCamera.CFrame.LookVector;
				turnTime = math.clamp(math.deg(math.acos(math.clamp(turnFrom:Dot(direction), -1, 1))) / 300, 0.15, 0.8);
				active.Phase = 'turn';
			else
				active.Phase, active.Until = 'settle', tick() + cannon.StopAimingPrompt.HoldDuration + 0.2 + store.ping.total;
			end;
		end;

		local launch: () -> () = function(): ()
			local controller: table = bedwars.CannonHandController;
			active.OldLaunch = controller.launchSelf;
			active.AutoRotate = humanoid.AutoRotate;
			active.Until = tick() + (LaunchCannon["Enabled"] and 2 or 30) + store.ping.total;
			active.Hook = function(self: table, block: Instance, ...: any): ...any
				if block ~= cannon or active.Done then
					return active.OldLaunch(self, block, ...);
				end;
				active.Fired = true;
				active.Before = root.AssemblyLinearVelocity;
				active.Origin = root.Position;
				active.Velocity = (targetPosition - root.Position + Vector3.yAxis * workspace.Gravity * flightTime * flightTime * 0.5) / flightTime;
				active.Until = tick() + 2 + store.ping.total;
				store.cannonFlight = active;
				local results: table = table.pack(active.OldLaunch(self, block, ...));
				active.LaunchedAt = tick();
				if controller.launchSelf == active.Hook then
					controller.launchSelf = active.OldLaunch;
				end;
				return table.unpack(results, 1, results.n);
			end;
			controller.launchSelf = active.Hook;
			active.Phase = 'flight';
			active.Elapsed = 0;
			if LaunchCannon["Enabled"] then
				controller:launchSelf(cannon);
			end;
		end;

		LongJump:Clean(runService.PreSimulation:Connect(function(delta: number): ()
			if active.Done then
				return;
			end;
			local now: number = tick();
			if not entitylib.isAlive or entitylib.character.RootPart ~= root or (cannon and not cannon.Parent and active.Phase ~= 'flight') then
				finish(nil);
				return;
			end;
			if active.Phase == 'place' then
				for _: number, placed: Instance in collectionService:GetTagged('cannon') do
					if placed:IsA('BasePart') and (placed.Position - spot).Magnitude < 1.5 then
						cannon = placed;
						active.Phase = 'plan';
						break;
					end;
				end;
				if active.Phase == 'place' and now > active.Until then
					finish(nil);
				end;
			elseif active.Phase == 'plan' then
				plan();
			elseif active.Phase == 'turn' then
				turned += delta;
				local alpha: number = math.clamp(turned / turnTime, 0, 1);
				local eased: number = alpha < 0.5 and 2 * alpha * alpha or 1 - ((-2 * alpha + 2) ^ 2) / 2;
				local look: Vector3 = turnFrom:Lerp(direction, eased);
				if look.Magnitude > 0.001 then
					gameCamera.CFrame = CFrame.lookAt(gameCamera.CFrame.Position, gameCamera.CFrame.Position + look.Unit);
				end;
				if alpha >= 1 then
					bedwars.CannonController:startAiming(cannon);
					active.Phase, active.Until = 'hold', now + cannon.AimPrompt.HoldDuration;
				end;
			elseif active.Phase == 'hold' then
				if now >= active.Until then
					active.Phase, active.Until = 'ready', now + 1;
				end;
			elseif active.Phase == 'ready' then
				if cannon.StopAimingPrompt.Enabled or now > active.Until then
					bedwars.CannonController:stopAiming();
					active.Phase, active.Until = 'settle', now + cannon.StopAimingPrompt.HoldDuration + 0.2 + store.ping.total;
				end;
			elseif active.Phase == 'settle' then
				if now >= active.Until then
					if AimMode["Value"] == 'Legit' and bedwars.CannonController:isAiming() then
						bedwars.CannonController:stopAiming();
					end;
					active.Phase, active.Until = 'aim', now + 1;
				end;
			elseif active.Phase == 'aim' then
				local look: any = cannon:GetAttribute('LookVector');
				if typeof(look) == 'Vector3' and (look - direction).Magnitude < 0.0001 then
					launch();
				elseif now > active.Until then
					finish('Cannon refused the aim.');
				elseif now >= nextAim then
					nextAim = now + 0.15;
					fire('AimCannon', 'SendToServer', {["cannonBlockPos"] = bedwars.BlockController:getBlockPosition(cannon.Position), ["lookVector"] = direction});
				end;
			elseif active.Phase == 'flight' then
				if active.Fired and store.cannonFlight ~= active then
					finish(nil);
					return;
				end;
				if not active.Fired then
					local look: any = cannon.Parent and cannon:GetAttribute('LookVector');
					if typeof(look) == 'Vector3' and (look - direction).Magnitude >= 0.0001 then
						finish('Cannon was re-aimed before you launched.');
					elseif now > active.Until then
						finish(nil);
					end;
					return;
				end;
				local gravity: number = workspace.Gravity;
				if not active.Launched and (root.AssemblyLinearVelocity - active.Before):Dot(direction) > launchSpeed * 0.5 then
					active.Launched = true;
					active.Until = (active.LaunchedAt or now) + flightTime + 3;
					humanoid.AutoRotate = false;
					humanoid:ChangeState(Enum.HumanoidStateType.Freefall);
					root.AssemblyAngularVelocity = Vector3.zero;
					if not OldCorrection["Enabled"] then
						local needed: Vector3 = (targetPosition - root.Position + Vector3.yAxis * gravity * flightTime * flightTime * 0.5) / flightTime;
						local current: Vector3 = root.AssemblyLinearVelocity;
						if (needed - current).Magnitude > 2 and needed.Magnitude <= math.max(current.Magnitude, launchSpeed) + 1 then
							root.AssemblyLinearVelocity = needed;
						end;
					end;
				end;
				if active.Launched then
					local grounded: boolean = humanoid.FloorMaterial ~= Enum.Material.Air or (root.AssemblyLinearVelocity.Y <= 0 and workspace:Raycast(root.Position, Vector3.yAxis * -(entitylib.character.HipHeight + 0.05), arcParams) ~= nil);
					if not grounded then
						active.Airborne = true;
					elseif active.Airborne or now - (active.LaunchedAt or now) > 0.2 then
						finish(nil);
						return;
					end;
					active.Elapsed += delta;
					if OldCorrection["Enabled"] then
						if active.Elapsed < flightTime then
							local elapsed: number = active.Elapsed;
							local ideal: Vector3 = active.Origin + active.Velocity * elapsed - Vector3.yAxis * gravity * elapsed * elapsed * 0.5;
							local corrected: Vector3 = active.Velocity - Vector3.yAxis * gravity * elapsed + (ideal - root.Position) * 6;
							local ceiling: number = math.sqrt(launchSpeed * launchSpeed + 2 * gravity * math.max(active.Origin.Y - root.Position.Y, 0));
							local stepVelocity: Vector3 = corrected.Magnitude > ceiling and corrected.Unit * ceiling or corrected;
							if workspace:Spherecast(root.Position, 2, stepVelocity * delta, arcParams) then
								finish(nil);
								return;
							end;
							root.AssemblyLinearVelocity = stepVelocity;
						else
							root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0);
							if active.Elapsed >= flightTime + 0.5 then
								finish(nil);
								return;
							end;
						end;
					elseif active.Elapsed >= flightTime then
						finish(nil);
						return;
					end;
				end;
				if active.Tag then
					active.Tag.Text = 'Landing ('..math.floor((targetPosition - root.Position).Magnitude)..' studs)';
				end;
				if now > active.Until then
					finish(nil);
				end;
			end;
		end));
	end;

	local launches: {[string]: (item: table?, look: Vector3) -> ()} = {};
	launches.cannon = function(item: table?, look: Vector3): ()
		local feet: Vector3 = jump.Start - Vector3.new(0, entitylib.character.HipHeight - 3, 0);
		local cell: Vector3 = roundPos(feet);
		placeBlock(cell, 'cannon');
		task.defer(function(): ()
			local block: Instance?, blockCell: Vector3? = getPlacedBlock(cell);
			if not block or block.Name ~= 'cannon' or (entitylib.character.RootPart.Position - block.Position).Magnitude >= 20 then
				return;
			end;
			local tool: table? = store.tools[bedwars.ItemMeta[block.Name].block.breakType];
			if tool then
				switchItem(tool.tool);
			end;
			fire('AimCannon', 'SendToServer', {["cannonBlockPos"] = blockCell, ["lookVector"] = look});
			local breakDelay: number = 0.1;
			if bedwars.BlockController:calculateBlockDamage(lplr, {["blockPosition"] = blockCell}) < block:GetAttribute('Health') then
				breakDelay = 0.4;
				breakBlock(block, {["Effects"] = true, ["Animation"] = 'Normal'});
			end;
			local attempt: (tries: number) -> ();
			attempt = function(tries: number): ()
				if not LongJump["Enabled"] then
					return;
				end;
				if fire('LaunchSelfFromCannon', 'CallServer', {["cannonBlockPos"] = blockCell}) then
					breakBlock(block, {["Effects"] = true, ["Animation"] = 'Normal'});
					boost('cannon', look);
				elseif tries < 3 then
					task.delay(0.1, attempt, tries + 1);
				end;
			end;
			task.delay(breakDelay, attempt, 1);
		end);
	end;
	launches.cat = function(item: table?, look: Vector3): ()
		local oldLeap: (...any) -> ...any = bedwars.CatController.leap;
		local leap: (...any) -> ...any;
		leap = function(...: any): ...any
			boost('cat', look);
			entitylib.character.RootPart.AssemblyLinearVelocity = Vector3.zero;
			return oldLeap(...);
		end;
		bedwars.CatController.leap = leap;
		LongJump:Clean(function(): ()
			if bedwars.CatController.leap == leap then
				bedwars.CatController.leap = oldLeap;
			end;
		end);
		jump.Waiting = {
			["Ready"] = function(): boolean
				return bedwars.AbilityController:canUseAbility('CAT_POUNCE', abilityOptions);
			end,
			["Go"] = function(): ()
				bedwars.AbilityController:useAbility('CAT_POUNCE');
			end
		};
	end;
	launches.fireball = function(item: table?, look: Vector3): ()
		local projectile: string = item.itemType == 'fireball' and 'fireball' or 'grappling_hook_projectile';
		local launchSpeed: number = projectile == 'fireball' and 60 or 140;
		local origin: Vector3 = jump.Start - look * 0.1;
		local offset: table = bedwars.BowConstantsTable;
		local shot: CFrame = CFrame.lookAlong(origin, Vector3.new(0, -launchSpeed, 0)) * CFrame.new(-offset.RelX, -offset.RelY, -offset.RelZ);
		switchItem(item.tool, 0);
		task.delay(0.1, function(): ()
			local result: any = fire('ProjectileFire', 'CallServer', item.tool, projectile == 'fireball' and 'fireball' or nil, projectile, shot.Position, origin, shot.LookVector * launchSpeed, bedwars.IdUtil.generateId(8), ballistics.shotData(item.itemType), workspace:GetServerTimeNow() - config.ShotLatency);
			if type(result) == 'table' and result.accepted then
				ballistics.launchSound(item);
			end;
		end);
	end;
	launches.grapple = launches.fireball;
	launches.hammer = function(item: table?, look: Vector3): ()
		local ability: string = (item.itemType:find('jade_hammer') and 'jade_hammer' or item.itemType)..'_jump';
		jump.Waiting = {
			["Ready"] = function(): boolean
				return bedwars.AbilityController:canUseAbility(ability, abilityOptions);
			end,
			["Go"] = function(): ()
				switchItem(item.tool, 0);
				entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping);
				jump.Start = entitylib.character.RootPart.Position + Vector3.new(0, 3.1, 0);
				task.delay(0.1, function(): ()
					if LongJump["Enabled"] then
						bedwars.AbilityController:useAbility(ability);
						boost('hammer', look);
					end;
				end);
			end
		};
	end;
	launches.tnt = function(item: table?, look: Vector3): ()
		local cell: Vector3 = roundPos(jump.Start - Vector3.new(0, entitylib.character.HipHeight - 3, 0));
		jump.Start = Vector3.new(cell.X, jump.Start.Y, cell.Z) + look * (item.itemType == 'pirate_gunpowder_barrel' and 2.6 or 0.2);
		placeBlock(cell, item.itemType);
	end;
	launches.dao = function(item: table?, look: Vector3): ()
		local origin: Vector3 = jump.Start;
		jump.Waiting = {
			["Ready"] = function(): boolean
				return (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash', abilityOptions);
			end,
			["Go"] = function(): ()
				bedwars.SwordController.lastAttack = workspace:GetServerTimeNow();
				switchItem(item.tool, 0.1);
				if not LongJump["Enabled"] then
					return;
				end;
				replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
					["direction"] = look,
					["origin"] = origin,
					["weapon"] = item.itemType
				});
				boost('dao', look);
			end
		};
	end;

	LongJump = vape.Categories.Blatant:CreateModule({
		["Name"] = 'LongJump',
		["Function"] = function(callback: boolean): ()
			if callback and store.infinitefly then
				notif('LongJump', 'Unavailable until Fly has landed', 3, 'warning');
				LongJump:Toggle();
				return;
			end;
			frictionUsers.LongJump = callback or nil;
			updateFriction();
			if not callback then
				jump.Tick, jump.Speed, jump.Direction, jump.Start, jump.Waiting = tick(), 0, Vector3.zero, nil, nil;
				aimSession = nil;
				return;
			end;
			if not entitylib.isAlive then
				return;
			end;
			local held: string? = store.hand.tool and store.hand.tool.Name;
			local cannonInRange: boolean = false;
			for _: number, block: Instance in store.blocks do
				cannonInRange = cannonInRange or (block.Name == 'cannon' and (entitylib.character.RootPart.Position - block.Position).Magnitude <= SearchRange["Value"]);
			end;
			local aimReady: boolean = CannonMode["Value"] == 'Aim' and (not DaveyOnly["Enabled"] or hasKit('davey')) and (held == 'cannon' or not (held and methodOf[held])) and (cannonInRange or (PlaceCannon["Enabled"] and getItem('cannon') ~= nil));
			if aimReady then
				if store.cannonFlight then
					LongJump:Toggle();
					return;
				end;
				startAim();
				return;
			end;

			LongJump:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
				local multiplier: table? = damage.knockbackMultiplier;
				if damage.entityInstance ~= lplr.Character or damage.fromEntity ~= lplr.Character or (multiplier and multiplier.disabled) or not entitylib.isAlive then
					return;
				end;
				local from: Vector3? = damage.fromPosition and Vector3.new(damage.fromPosition.X, damage.fromPosition.Y, damage.fromPosition.Z) or damage.fromEntity and damage.fromEntity.PrimaryPart and damage.fromEntity.PrimaryPart.Position;
				local knockback: number = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {["vertical"] = 0, ["horizontal"] = multiplier and multiplier.horizontal or 1}).Magnitude * 1.1;
				if from and knockback >= jump.Speed then
					propel(entitylib.character.RootPart.Position - from, knockback, StoreDamage["Enabled"] and 4.3 or 2.5);
					jump.Lift = StoreDamage["Enabled"] and storedLift or lift;
				end;
			end));
			LongJump:Clean(vapeEvents.GrapplingHookFunctions.Event:Connect(function(data: table): ()
				if data.hookFunction == 'PLAYER_IN_TRANSIT' and entitylib.isAlive then
					boost('grapple', entitylib.character.RootPart.CFrame.LookVector);
				end;
			end));

			jump.Start = entitylib.character.RootPart.Position;
			LongJump:Clean(runService.PreSimulation:Connect(function(delta: number): ()
				local root: BasePart? = entitylib.isAlive and entitylib.character.RootPart or nil;
				if store.infinitefly then
					return;
				end;
				if not root or not isnetworkowner(root) then
					jump.Start = nil;
					return;
				end;
				local waiting: table? = jump.Waiting;
				if waiting and waiting.Ready() then
					jump.Waiting = nil;
					waiting.Go();
				end;
				local now: number = tick();
				if jump.Tick > now then
					root.CFrame += jump.Direction * (jump.Tick - now > coast and jump.Speed or 0) * delta;
					root.AssemblyLinearVelocity = jump.Direction * getSpeed() + Vector3.new(0, jump.Lift, 0);
					jump.Start = nil;
				else
					if jump.Start then
						root.CFrame = CFrame.lookAlong(jump.Start, root.CFrame.LookVector);
					end;
					root.AssemblyLinearVelocity = Vector3.zero;
					jump.Speed = 0;
				end;
			end));

			local look: Vector3 = (CameraDirection["Enabled"] and gameCamera or entitylib.character.RootPart).CFrame.LookVector;
			local itemType: string? = if held and methodOf[held] then held else nil;
			for _: number, candidate: string in (itemType and {} or methodOrder) do
				if getItem(candidate, nil, true) or hasKit(candidate) then
					itemType = candidate;
					break;
				end;
			end;
			if itemType then
				launches[methodOf[itemType]](getItem(itemType, nil, true), look);
			end;
		end,
		["ExtraText"] = function(): string
			return 'Heatseeker';
		end,
		["Tooltip"] = 'Lets you jump farther. Uses the item you hold (or the first one you have): cannon, cat pounce, fireball, grappling hook, jade hammer, void axe, TNT, daos, or your own knockback.\nCannon "Aim" launches you onto the block under your cursor.'
	});

	local refreshOptions: () -> () = function(): ()
		for option: table, shown: () -> boolean in visibleIn do
			option.Object.Visible = shown();
		end;
	end;
	local aimShown: () -> boolean = function(): boolean
		return CannonMode["Value"] == 'Aim';
	end;

	Speed = LongJump:CreateSlider({
		["Name"] = 'Speed',
		["Min"] = 1,
		["Max"] = 37,
		["Default"] = 37,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	CameraDirection = LongJump:CreateToggle({
		["Name"] = 'Camera Direction'
	});
	StoreDamage = LongJump:CreateToggle({
		["Name"] = 'Store Damage',
		["Tooltip"] = 'Knockback jumps (TNT, your own fireballs) last 4.3s with a lower lift instead of 2.5s.'
	});
	CannonMode = LongJump:CreateDropdown({
		["Name"] = 'Cannon',
		["List"] = {'Boost', 'Aim'},
		["Function"] = refreshOptions,
		["Tooltip"] = 'Boost: places a cannon under you and boosts you forward.\nAim: aims a nearby cannon at your cursor and lands you on that block.'
	});
	AimMode = LongJump:CreateDropdown({
		["Name"] = 'Aim Mode',
		["List"] = {'Blatant', 'Legit'},
		["Darker"] = true
	});
	PositionMode = LongJump:CreateDropdown({
		["Name"] = 'Position Mode',
		["List"] = {'Mouse', 'Camera'},
		["Darker"] = true
	});
	SearchRange = LongJump:CreateSlider({
		["Name"] = 'Search Range',
		["Min"] = 1,
		["Max"] = 18,
		["Default"] = 10,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end
	});
	PlaceCannon = LongJump:CreateToggle({
		["Name"] = 'Place Cannon',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = refreshOptions,
		["Tooltip"] = 'Puts a cannon down on the nearest free block when there is none in range.'
	});
	AutoSwitch = LongJump:CreateToggle({
		["Name"] = 'Auto Switch',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Holds the cannon before placing it.'
	});
	LaunchCannon = LongJump:CreateToggle({
		["Name"] = 'Launch Cannon',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Launches you automatically; turn off to aim only and launch yourself.'
	});
	ShowTarget = LongJump:CreateToggle({
		["Name"] = 'Show Target',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Highlights the block you are landing on until you land.'
	});
	OldCorrection = LongJump:CreateToggle({
		["Name"] = 'Old Correction',
		["Darker"] = true,
		["Tooltip"] = 'Steers the whole flight toward the landing point and stops horizontal movement on arrival.'
	});
	DaveyOnly = LongJump:CreateToggle({
		["Name"] = 'Davey Only',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Only aims cannons while you are playing Davey.'
	});
	CannonSpeed = LongJump:CreateToggle({
		["Name"] = 'Cannon Speed',
		["Function"] = function(callback: boolean): ()
			refreshOptions();
			applyCannonSpeed();
		end,
		["Tooltip"] = 'Changes how hard cannons launch you. Applies to every cannon launch while on, even with LongJump off.'
	});
	CannonLaunchSpeed = LongJump:CreateSlider({
		["Name"] = 'Cannon Launch Speed',
		["Min"] = 1,
		["Max"] = 400,
		["Default"] = legitCannonSpeed,
		["Darker"] = true,
		["Function"] = function(value: number): ()
			if CannonSpeed["Enabled"] then
				applyCannonSpeed();
			end;
		end,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end
	});
	LongJump:CreateButton({
		["Name"] = 'Sync to legit speed',
		["Function"] = function(): ()
			CannonLaunchSpeed:SetValue(legitCannonSpeed);
		end
	});
	for _: number, option: table in {AimMode, PositionMode, SearchRange, PlaceCannon, LaunchCannon, ShowTarget, OldCorrection, DaveyOnly} do
		visibleIn[option] = aimShown;
	end;
	visibleIn[AutoSwitch] = function(): boolean
		return aimShown() and PlaceCannon["Enabled"];
	end;
	visibleIn[CannonLaunchSpeed] = function(): boolean
		return CannonSpeed["Enabled"];
	end;
	refreshOptions();
end);

velo.run(function(): ()
	local ProjectileAimbot: table = {["Enabled"] = false};
	local ProjectileAura: table = {["Enabled"] = false};
	local AimMode: table;
	local AimTargets: table;
	local AimSort: table;
	local AimPart: table;
	local AimFov: table;
	local AimDistance: table;
	local CircleColor: table;
	local CircleTransparency: table;
	local CircleThickness: table;
	local CircleFilled: table;
	local Horizontal: table;
	local Vertical: table;
	local HitChance: table;
	local HeadshotChance: table;
	local AutoCharge: table;
	local ChargePercent: table;
	local ChargeItems: table;
	local AimChange: table;
	local OtherProjectiles: table;
	local AimUmeko: table;
	local Potions: table;
	local Blacklist: table;
	local MiloCheck: table;
	local Terra: table;
	local DeathAdder: table;
	local DeathAdderMode: table;
	local BedRange: table;
	local AuraMode: table;
	local AuraTargets: table;
	local AuraSort: table;
	local AuraPart: table;
	local AuraList: table;
	local UseSophia: table;
	local UseWhim: table;
	local UseNazar: table;
	local UseUmeko: table;
	local FireRate: table;
	local AfkCheck: table;
	local AuraRange: table;
	local SwitchMode: table;
	local ChargeDelay: table;
	local SwitchDelay: table;
	local Owl: table;
	local CrossbowChain: table;

	local kickSpeed: number, kickGravity: number = 100, 20;
	local sorcererSpeed: number = 70;
	local attemptLimit: number, attemptBudget: number = 10, 0.0015;
	local auraInterval: number, owlInterval: number = 0.03, 0.1;
	local swordLockout: number, swingWindow: number, swingRange: number = 0.5, 0.2, 22;
	local random: Random = Random.new();
	local circle: any;
	local namecallHooked: boolean = false;
	local aimPartList: {string} = table.clone(targetParts);
	table.insert(aimPartList, 'Dynamic');
	table.insert(aimPartList, 'Closest');
	local auraPartList: {string} = table.clone(targetParts);
	table.insert(auraPartList, 'Dynamic');

	local screenOrigin: () -> Vector2 = function(): Vector2
		return inputService.TouchEnabled and gameCamera.ViewportSize / 2 or inputService:GetMouseLocation();
	end;

	local aimPartOf: (ent: table, mode: string, itemType: string?) -> BasePart = function(ent: table, mode: string, itemType: string?): BasePart
		if mode == 'Dynamic' then
			local headshot: boolean = hasKit('archer') or (itemType ~= nil and (itemType:find('headhunter', 1, true) ~= nil or itemType:find('tactical', 1, true) ~= nil));
			return getTargetPart(ent, headshot and 'Head' or 'RootPart');
		end;
		if mode == 'Closest' then
			local center: Vector2 = gameCamera.ViewportSize / 2;
			local best: BasePart, gap: number = ent.RootPart, math.huge;
			for _: number, part: Instance in ent.Character:GetChildren() do
				if part:IsA('BasePart') then
					local point: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(part.Position);
					local distance: number = (center - Vector2.new(point.X, point.Y)).Magnitude;
					if visible and distance < gap then
						best, gap = part, distance;
					end;
				end;
			end;
			return best;
		end;
		return getTargetPart(ent, mode);
	end;

	local worldOnly: () -> {Instance} = function(): {Instance}
		local ignore: {Instance} = {gameCamera, lplr.Character, store.antiFallPart};
		for _: number, ent: table in entitylib.List do
			table.insert(ignore, ent.Character);
		end;
		return ignore;
	end;

	local projectileAllowed: (projectile: string) -> boolean = function(projectile: string): boolean
		if projectile:find('splash_potion') then
			return Potions["Enabled"];
		end;
		if not OtherProjectiles["Enabled"] and not projectile:find('arrow') and not (AimUmeko["Enabled"] and projectile:find('^ninja_chakram')) then
			return false;
		end;
		return not table.find(Blacklist.ListEnabled, (projectile == 'glue_trap' or projectile == 'glue_projectile') and 'gloop' or projectile);
	end;

	local pickTarget: (accept: (ent: table) -> boolean) -> table? = function(accept: (ent: table) -> boolean): table?
		if not entitylib.isAlive then
			return nil;
		end;
		local center: Vector2 = screenOrigin();
		local selfPosition: Vector3 = entitylib.character.RootPart.Position;
		local candidates: {table} = {};
		for _: number, ent: table in entitylib.List do
			local wanted: boolean = ent.Targetable and (ent.NPC and AimTargets.NPCs["Enabled"] or ent.Player ~= nil and AimTargets.Players["Enabled"]);
			if wanted and entitylib.isVulnerable(ent) and (ent.RootPart.Position - selfPosition).Magnitude <= AimDistance["Value"] and not (MiloCheck["Enabled"] and ent.Player and bedwars.BlockDisguiseController:getPlayerBlockModel(ent.Player)) then
				local point: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(ent.RootPart.Position);
				local gap: number = (center - Vector2.new(point.X, point.Y)).Magnitude;
				if visible and gap <= AimFov["Value"] then
					table.insert(candidates, {["Entity"] = ent, ["Magnitude"] = ent.Target and -1 or gap});
				end;
			end;
		end;
		table.sort(candidates, sortMethods[AimSort["Value"]] or sortMethods.Distance);
		local started: number = os.clock();
		for index: number, candidate: table in candidates do
			if index > attemptLimit or (index > 1 and os.clock() - started > attemptBudget) then
				break;
			end;
			if accept(candidate.Entity) then
				targetinfo.Targets[candidate.Entity] = tick() + 1;
				return candidate.Entity;
			end;
		end;
		return nil;
	end;

	ProjectileAimbot = vape.Categories.Blatant:CreateModule({
		["Name"] = 'ProjectileAimbot',
		["Function"] = function(callback: boolean): ()
			if circle then
				circle.Visible = callback;
			end;
			if not callback then
				return;
			end;
			ProjectileAimbot:Clean(runService.RenderStepped:Connect(function(): ()
				if circle then
					circle.Position = screenOrigin();
				end;
			end));

			local projectileController: table = bedwars.ProjectileController;
			local oldLaunch: (...any) -> ...any = projectileController.calculateImportantLaunchValues;
			local launchHook: (...any) -> ...any = function(self: table, launchData: table, worldMeta: any, origin: any, shootPosition: Vector3?, ...: any): ...any
				if AutoCharge["Enabled"] and launchData.drawDurationSeconds then
					local meta: table? = bedwars.ProjectileMeta[launchData.projectile];
					local tool: Instance? = store.hand.tool;
					local items: {string} = ChargeItems.ListEnabled;
					if meta and meta.predictionLifetimeSec and (#items == 0 or table.find(items, launchData.projectile) or tool and table.find(items, tool.Name)) then
						local share: number = ChargePercent["Value"] / 100;
						launchData.drawDurationSeconds = math.max(launchData.drawDurationSeconds, meta.predictionLifetimeSec * share);
						launchData.velocityMultiplier = math.max(launchData.velocityMultiplier or 0, share);
					end;
				end;
				local launchPosition: Vector3? = AimMode["Value"] == 'Trajectory' and (shootPosition or self:getLaunchPosition(origin)) or nil;
				if not launchPosition or not projectileAllowed(launchData.projectile) then
					return oldLaunch(self, launchData, worldMeta, origin, shootPosition, ...);
				end;
				local meta: table = launchData:getProjectileMeta();
				local lifetime: number = worldMeta and meta.predictionLifetimeSec or meta.lifetimeSec or 3;
				local gravity: number = (meta.gravitationalAcceleration or config.Gravity) * launchData.gravityMultiplier;
				local speed: number = (meta.launchVelocity or 100) * (AimChange["Enabled"] and launchData.velocityMultiplier or 1);
				local fromPosition: Vector3 = launchPosition + (launchData.projectile == 'owl_projectile' and Vector3.zero or launchData.fromPositionOffset);
				local handName: string? = store.hand.tool and store.hand.tool.Name;
				local values: table?;
				pickTarget(function(ent: table): boolean
					local part: BasePart = aimPartOf(ent, AimPart["Value"], handName);
					local velocity: Vector3 = launchData.projectile == 'telepearl' and Vector3.zero or part.AssemblyLinearVelocity;
					local aim: Vector3?, flight: number? = ballistics.solve(fromPosition, speed, gravity, ent, part.Position, velocity, Horizontal["Value"], Vertical["Value"]);
					if not aim or not flight or flight > lifetime then
						return false;
					end;
					local launchVelocity: Vector3 = (aim - fromPosition).Unit * speed;
					if AimTargets.Walls["Enabled"] and not ballistics.arcClear(fromPosition, launchVelocity, gravity, flight, worldOnly()) then
						return false;
					end;
					store.hitchance.ProjectileAimbot = {["Value"] = ballistics.hitChance(ent, flight), ["Clock"] = tick()};
					values = {
						["initialVelocity"] = launchVelocity,
						["positionFrom"] = fromPosition,
						["deltaT"] = lifetime,
						["gravitationalAcceleration"] = gravity,
						["drawDurationSeconds"] = launchData.drawDurationSeconds
					};
					return true;
				end);
				return values or oldLaunch(self, launchData, worldMeta, origin, shootPosition, ...);
			end;
			projectileController.calculateImportantLaunchValues = launchHook;
			ProjectileAimbot:Clean(function(): ()
				if projectileController.calculateImportantLaunchValues == launchHook then
					projectileController.calculateImportantLaunchValues = oldLaunch;
				end;
			end);

			local sorcerer: table? = bedwars.SorcererController;
			if sorcerer then
				local oldDirection: (...any) -> ...any = sorcerer.getProjectileDirection;
				local directionHook: (...any) -> ...any = function(self: table, ...: any): ...any
					if DeathAdder["Enabled"] and entitylib.isAlive then
						local position: Vector3 = entitylib.character.RootPart.Position;
						local aim: Vector3?;
						if DeathAdderMode["Value"] == 'Bed' then
							local closest: number = BedRange["Value"];
							for _: number, bed: BasePart in collectionService:GetTagged('bed') do
								local distance: number = (position - bed.Position).Magnitude;
								if not bed:GetAttribute('Team'..(lplr:GetAttribute('Team') or -1)..'NoBreak') and distance <= closest then
									aim, closest = bed.Position, distance;
								end;
							end;
						else
							pickTarget(function(ent: table): boolean
								if AimTargets.Walls["Enabled"] and entitylib.Wallcheck(position, ent.RootPart.Position, nil, ent) then
									return false;
								end;
								local tier: table? = bedwars.SorcererBalance.getSorcererTierData(bedwars.SorcererBalance.getSorcererTier(lplr));
								local point: Vector3 = aimPartOf(ent, AimPart["Value"], nil).Position;
								aim = point + ent.RootPart.AssemblyLinearVelocity * ((point - position).Magnitude / (tier and tier.projectileVelocity or sorcererSpeed));
								return true;
							end);
						end;
						if aim and aim ~= position then
							return (aim - position).Unit;
						end;
					end;
					return oldDirection(self, ...);
				end;
				sorcerer.getProjectileDirection = directionHook;
				ProjectileAimbot:Clean(function(): ()
					if sorcerer.getProjectileDirection == directionHook then
						sorcerer.getProjectileDirection = oldDirection;
					end;
				end);
			end;

			local kicker: table? = bedwars.BlockKickerKitController;
			if kicker then
				local oldKick: (...any) -> ...any = kicker.onAbilityUsed;
				local kickHook: (...any) -> ...any = function(self: table, character: any, data: table?, ...: any): ...any
					if not Terra["Enabled"] or not data or data.ability ~= 'BLOCK_KICK' or not entitylib.isAlive then
						return oldKick(self, character, data, ...);
					end;
					local origin: Vector3 = self:getKickBlockProjectileOriginPosition(entitylib.character.RootPart.Position, gameCamera.CFrame.LookVector);
					local direction: Vector3?;
					pickTarget(function(ent: table): boolean
						local part: BasePart = aimPartOf(ent, AimPart["Value"], nil);
						local aim: Vector3?, flight: number? = ballistics.solve(origin, kickSpeed, kickGravity, ent, part.Position, part.AssemblyLinearVelocity, Horizontal["Value"], Vertical["Value"]);
						if not aim or (aim - origin).Magnitude <= 0 then
							return false;
						end;
						if AimTargets.Walls["Enabled"] and flight and not ballistics.arcClear(origin, (aim - origin).Unit * kickSpeed, kickGravity, flight, worldOnly()) then
							return false;
						end;
						store.hitchance.ProjectileAimbot = {["Value"] = ballistics.hitChance(ent, flight), ["Clock"] = tick()};
						direction = (aim - origin).Unit;
						return true;
					end);
					if not direction then
						return oldKick(self, character, data, ...);
					end;
					if bedwars.CameraPerspectiveController:getCameraPerspective() == 1 then
						local scale: number = (0.7 * direction.Y + math.sqrt(0.49 * direction.Y * direction.Y + 3.51)) / 2;
						direction = direction * scale - Vector3.new(0, 0.35, 0);
					end;
					local saved: CFrame = gameCamera.CFrame;
					gameCamera.CFrame = CFrame.lookAt(saved.Position, saved.Position + direction);
					local result: any = oldKick(self, character, data, ...);
					gameCamera.CFrame = saved;
					return result;
				end;
				kicker.onAbilityUsed = kickHook;
				ProjectileAimbot:Clean(function(): ()
					if kicker.onAbilityUsed == kickHook then
						kicker.onAbilityUsed = oldKick;
					end;
				end);
			end;

			if namecallHooked then
				return;
			end;
			namecallHooked = true;
			local oldNamecall: (...any) -> ...any;
			oldNamecall = hookmetamethod(game, '__namecall', newcclosure(function(self: any, ...: any): ...any
				if not ProjectileAimbot["Enabled"] or AimMode["Value"] ~= 'Silent' or checkcaller() or getnamecallmethod() ~= 'InvokeServer' or tostring(self) ~= 'ProjectileFire' then
					return oldNamecall(self, ...);
				end;
				local arguments: table = table.pack(...);
				local projectile: any, origin: any, velocity: any = arguments[3], arguments[4], arguments[6];
				local meta: table? = type(projectile) == 'string' and bedwars.ProjectileMeta[projectile] or nil;
				if meta and typeof(origin) == 'Vector3' and typeof(velocity) == 'Vector3' and velocity.Magnitude > 0 and projectileAllowed(projectile) and random:NextNumber(0, 100) <= HitChance:GetRandomValue() then
					local speed: number, gravity: number = velocity.Magnitude, meta.gravitationalAcceleration or config.Gravity;
					local partMode: string = random:NextNumber(0, 100) < HeadshotChance:GetRandomValue() and 'Head' or AimPart["Value"];
					local handName: string? = store.hand.tool and store.hand.tool.Name;
					pickTarget(function(ent: table): boolean
						local part: BasePart = aimPartOf(ent, partMode, handName);
						if AimTargets.Walls["Enabled"] and entitylib.Wallcheck(origin, part.Position, nil, ent) then
							return false;
						end;
						local aim: Vector3?, flight: number? = ballistics.solve(origin, speed, gravity, ent, part.Position, projectile == 'telepearl' and Vector3.zero or ent.RootPart.AssemblyLinearVelocity, Horizontal["Value"], Vertical["Value"]);
						if not aim or not flight or flight > (meta.lifetimeSec or 3) then
							return false;
						end;
						store.hitchance.ProjectileAimbot = {["Value"] = ballistics.hitChance(ent, flight), ["Clock"] = tick()};
						arguments[6] = CFrame.lookAt(origin, aim).LookVector * speed;
						return true;
					end);
				end;
				return oldNamecall(self, table.unpack(arguments, 1, arguments.n));
			end));
		end,
		["Tooltip"] = 'Aims your projectiles (and Terra / Death Adder abilities) at enemies.\nTrajectory bends the shot you see, Silent only redirects what the server receives.'
	});
	AimMode = ProjectileAimbot:CreateDropdown({
