	});
	AuraSort = ProjectileAura:CreateDropdown({
		["Name"] = 'Target mode',
		["List"] = sortNames,
		["Default"] = 'Distance'
	});
	AuraPart = ProjectileAura:CreateDropdown({
		["Name"] = 'Part',
		["List"] = auraPartList,
		["Tooltip"] = 'Dynamic aims at the head with headshot bows (tactical, headhunter, Archer) and the body otherwise'
	});
	AuraList = ProjectileAura:CreateTextList({
		["Name"] = 'Projectiles',
		["Default"] = {'arrow', 'snowball'}
	});
	UseSophia = ProjectileAura:CreateToggle({
		["Name"] = 'Use sophia',
		["Tooltip"] = 'Also shoots sophia\'s frost staff, swapping it out of mist mode on its own'
	});
	UseWhim = ProjectileAura:CreateToggle({
		["Name"] = 'Use whim',
		["Tooltip"] = 'Also casts whim\'s magic book with whatever element you have cycled'
	});
	UseNazar = ProjectileAura:CreateToggle({
		["Name"] = 'Use nazar',
		["Tooltip"] = 'Also shoots nazar\'s life bow, crossbow and headhunter'
	});
	UseUmeko = ProjectileAura:CreateToggle({
		["Name"] = 'Use umeko',
		["Tooltip"] = 'Also throws umeko\'s chakram, waiting for it to come back between throws'
	});
	FireRate = ProjectileAura:CreateTwoSlider({
		["Name"] = 'Fire Rate',
		["Min"] = 0,
		["Max"] = 1,
		["DefaultMin"] = 0.05,
		["DefaultMax"] = 0.12,
		["Decimal"] = 100
	});
	AfkCheck = ProjectileAura:CreateToggle({
		["Name"] = 'AFK check',
