					task.delay(0.2, track, bed);
				end));
				BedESP:Clean(collectionService:GetInstanceRemovedSignal('bed'):Connect(release));
				BedESP:Clean(runService.RenderStepped:Connect(render));
				for _: number, bed: Instance in collectionService:GetTagged('bed') do
					track(bed);
				end;
			else
				for bed: Instance in tracked do
					release(bed);
				end;
			end;
		end,
		["Tooltip"] = 'Render beds through walls'
	});
	Mode = BedESP:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'2D', '3D', 'Adornment'},
		["Function"] = function(value: string): ()
			rebuild();
			syncOptions();
		end,
		["Tooltip"] = '2D - screen box with optional health and name\n3D - outlined bounding box\nAdornment - highlights every bed part'
	});
	BedColor = BedESP:CreateColorSlider({
		["Name"] = 'Bed Color',
		["Function"] = recolor
	});
	TeamColor = BedESP:CreateToggle({
		["Name"] = 'Use Team Color',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = recolor
	});
	BoundingBox = BedESP:CreateToggle({
		["Name"] = 'Bounding Box',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = rebuild
	});
	Filled = BedESP:CreateToggle({
		["Name"] = 'Filled',
		["Darker"] = true,
		["Function"] = rebuild
	});
	HealthBar = BedESP:CreateToggle({
		["Name"] = 'Health Bar',
		["Darker"] = true,
		["Function"] = rebuild
	});
	ShowName = BedESP:CreateToggle({
		["Name"] = 'Name',
		["Darker"] = true,
		["Function"] = function(callback: boolean): ()
			rebuild();
			syncOptions();
		end
	});
	Background = BedESP:CreateToggle({
		["Name"] = 'Show Background',
		["Darker"] = true,
		["Function"] = rebuild
	});
	HideOwn = BedESP:CreateToggle({
		["Name"] = 'Hide Own Bed',
		["Default"] = true,
		["Tooltip"] = "Hides your own team's bed"
	});
	DistanceCheck = BedESP:CreateToggle({
		["Name"] = 'Distance Check',
		["Function"] = syncOptions
	});
	DistanceRange = BedESP:CreateTwoSlider({
		["Name"] = 'Bed Distance',
		["Min"] = 0,
		["Max"] = 512,
		["DefaultMin"] = 0,
		["DefaultMax"] = 256,
		["Darker"] = true,
		["Visible"] = false
	});
	syncOptions();
