	local boltLayers: {table} = {
		{["Size"] = Vector3.new(1.5, 1.5, 77), ["Material"] = Enum.Material.Neon},
		{["Size"] = Vector3.new(3, 3, 78), ["Material"] = Enum.Material.SmoothPlastic, ["Color"] = Color3.new(0.7, 0.7, 0.7), ["Transparency"] = 0.7}
	};
	local effectIds: {[string]: {[string]: string}} = {["Kill"] = {}, ["BedBreak"] = {}, ["Win"] = {}};

	local customEffects: {[string]: (...any) -> ()} = {
		["Gravity"] = function(_: any, _: any, character: Model): ()
			character:BreakJoints();
			for _: number, attachment: Instance? in {character:FindFirstChildWhichIsA('Highlight'), character:FindFirstChild('Nametag', true)} do
				if attachment then
					attachment:Destroy();
				end;
			end;
			local velocities: {[string]: Vector3} = {};
			for _: number, part: Instance in character:GetDescendants() do
				if part:IsA('BasePart') then
					velocities[part.Name] = part.AssemblyLinearVelocity;
				end;
			end;
			character.Archivable = true;
