			local ground: Vector3 = character.PrimaryPart.Position - Vector3.new(0, 8, 0);
			local from: Vector3 = Vector3.new((math.random(1, 10) - 5) * 2, boltHeight, (math.random(1, 10) - 5) * 2);
			for height: number = boltHeight - boltStep, 0, -boltStep do
				local to: Vector3 = height == 0 and Vector3.zero or Vector3.new((math.random(1, 10) - 5) * 2, height, (math.random(1, 10) - 5) * 2);
				for _: number, layer: table in boltLayers do
					local segment: Part = Instance.new('Part');
					segment.Size = layer.Size;
					segment.Material = layer.Material;
					segment.Color = layer.Color or segment.Color;
					segment.Transparency = layer.Transparency or 0;
					segment.Anchored = true;
					segment.CanCollide = false;
					segment.CFrame = CFrame.new(ground + from + (to - from) * 0.5, ground + to);
					segment.Parent = workspace;
					bedwars.QueryUtil:setQueryIgnored(segment, true);
					debrisService:AddItem(segment, 0.5);
				end;
				from = to;
			end;
			local emitter: Part = Instance.new('Part');
			emitter.Transparency = 1;
			emitter.Anchored = true;
			emitter.Size = Vector3.zero;
			emitter.Position = ground;
			emitter.Parent = workspace;
			bedwars.QueryUtil:setQueryIgnored(emitter, true);
			local thunder: Sound = Instance.new('Sound');
			thunder.SoundId = 'rbxassetid://6993372814';
			thunder.Volume = 2;
			thunder.Pitch = 0.5 + math.random(1, 3) / 10;
			thunder.Parent = emitter;
			thunder.Ended:Once(function(): ()
				emitter:Destroy();
			end);
			thunder:Play();
