							["isPlayDefaultKillEffect"] = function(): boolean
								return false;
							end
						};
					end
				};
			end;
			KillEffect:Clean(lplr:GetAttributeChangedSignal('KillEffectType'):Connect(applyKillEffect));
			applyKillEffect();

			KillEffect:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(data: table): ()
				if not BedBreak["Enabled"] then
					return;
				end;
