	WinList = KillEffect:CreateDropdown({
		["Name"] = 'Win',
		["List"] = namesOf(bedwars.WinEffectMeta, effectIds.Win),
		["Darker"] = true
	});
	WinList.Object.Visible = Win["Enabled"];
end);

velo.run(function(): ()
	local CleanKit: table = {["Enabled"] = false};
	local oldSpawnOrb: ((...any) -> ...any)?;
	local hidden: {GuiObject} = {};

	local hideEffect: (object: Instance) -> () = function(object: Instance): ()
		if object.Name == 'WindWalkerEffect' and object:IsA('GuiObject') then
			object.Visible = false;
			table.insert(hidden, object);
		end;
	end;

	CleanKit = vape.Legit:CreateModule({
		["Name"] = 'Clean Kit',
		["Function"] = function(callback: boolean): ()
			if callback then
				oldSpawnOrb = bedwars.WindWalkerController.spawnOrb;
				bedwars.WindWalkerController.spawnOrb = function(): () end;
				for _: number, object: Instance in lplr.PlayerGui:GetDescendants() do
					hideEffect(object);
				end;
				CleanKit:Clean(lplr.PlayerGui.DescendantAdded:Connect(hideEffect));
				return;
			end;
			bedwars.WindWalkerController.spawnOrb = oldSpawnOrb;
			for _: number, object: GuiObject in hidden do
				object.Visible = true;
			end;
			table.clear(hidden);
		end,
		["Tooltip"] = 'Removes zephyr status indicator'
	});
end);

velo.run(function(): ()
	local Crosshair: table = {["Enabled"] = false};
	local Preset: table;
	local Image: table;
	local BlockOverlay: table;
	local FillColor: table;
	local OutlineColor: table;
	local Thickness: table;
	local Animate: table;
	local AnimationTime: table;
	local overlayOptions: {table} = {};
	local images: table = bedwars.Images and bedwars.Images.ui;
	local originalImages: {string}?;
	local presets: {[string]: string} = images and {
		["PC"] = images.hud.viewmodel_crosshair,
		["Mobile"] = images.mobile_controls.mobile_crosshairs,
		["Turret"] = images.common.turret_crosshair,
		["Mouse lock"] = 'rbxasset://textures/MouseLockedCursor.png'
	} or {};
	local overlay: Part?;
	local overlayBox: SelectionBox?;
	local overlayTween: Tween?;
	local selected: BasePart?;

	local refreshCrosshair: () -> () = function(): ()
		if not images then
			return;
		end;
		local custom: boolean = Crosshair["Enabled"] and Preset["Value"] ~= 'Default';
		if custom and not originalImages then
			originalImages = {images.hud.viewmodel_crosshair, images.mobile_controls.mobile_crosshairs};
		end;
		if custom then
			local image: string = presets[Preset["Value"]] or (tonumber(Image["Value"]) and 'rbxassetid://'..Image["Value"] or Image["Value"]);
			images.hud.viewmodel_crosshair = image;
			images.mobile_controls.mobile_crosshairs = image;
		elseif originalImages then
			images.hud.viewmodel_crosshair = originalImages[1];
			images.mobile_controls.mobile_crosshairs = originalImages[2];
			originalImages = nil;
		end;
		if bedwars.ViewmodelController.crosshair then
			bedwars.ViewmodelController:hideCrosshair();
			bedwars.ViewmodelController:showCrosshair();
		end;
	end;

	local followSelection: (part: Instance) -> () = function(part: Instance): ()
		local box: SelectionBox? = overlay and part:IsA('BasePart') and part.Anchored and part.Transparency == 1 and part:FindFirstChildOfClass('SelectionBox');
		if not box then
			return;
		end;
		box.Visible = false;
		selected = part;
		if overlayTween then
			overlayTween:Cancel();
			overlayTween = nil;
		end;
		if Animate["Enabled"] and overlay.Parent == gameCamera then
			overlayTween = tweenService:Create(overlay, TweenInfo.new(AnimationTime["Value"], Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {["CFrame"] = part.CFrame, ["Size"] = part.Size});
			overlayTween:Play();
			return;
		end;
		overlay.CFrame = part.CFrame;
		overlay.Size = part.Size;
		overlay.Parent = gameCamera;
	end;

	local paintOverlay: () -> () = function(): ()
		if overlayBox then
			overlayBox.LineThickness = Thickness["Value"];
			overlayBox.Color3 = Color3.fromHSV(OutlineColor["Hue"], OutlineColor["Sat"], OutlineColor["Value"]);
			overlayBox.Transparency = 1 - OutlineColor["Opacity"];
			overlayBox.SurfaceColor3 = Color3.fromHSV(FillColor["Hue"], FillColor["Sat"], FillColor["Value"]);
			overlayBox.SurfaceTransparency = 1 - FillColor["Opacity"];
		end;
	end;

	Crosshair = vape.Legit:CreateModule({
		["Name"] = 'Crosshair',
		["Function"] = function(callback: boolean): ()
			refreshCrosshair();
			if callback and BlockOverlay["Enabled"] then
				overlay = Instance.new('Part');
				overlay.Size = Vector3.one * 3;
				overlay.Anchored = true;
				overlay.CanCollide = false;
				overlay.CanQuery = false;
				overlay.CanTouch = false;
				overlay.CastShadow = false;
				overlay.Transparency = 1;
				overlayBox = Instance.new('SelectionBox');
				overlayBox.Adornee = overlay;
				overlayBox.Parent = overlay;
				paintOverlay();
				bedwars.QueryUtil:setQueryIgnored(overlay, true);
				for _: number, child: Instance in workspace:GetChildren() do
					followSelection(child);
				end;
				Crosshair:Clean(workspace.ChildAdded:Connect(function(child: Instance): ()
					task.defer(followSelection, child);
				end));
				Crosshair:Clean(workspace.ChildRemoved:Connect(function(child: Instance): ()
					if child ~= selected then
						return;
					end;
					selected = nil;
					task.delay(0.06, function(): ()
						if selected or not overlay then
							return;
						end;
						if overlayTween then
							overlayTween:Cancel();
							overlayTween = nil;
						end;
						overlay.Parent = nil;
					end);
				end));
			elseif not callback then
				local box: SelectionBox? = selected and selected:FindFirstChildOfClass('SelectionBox');
				if box then
					box.Visible = true;
				end;
				selected = nil;
				if overlayTween then
					overlayTween:Cancel();
					overlayTween = nil;
				end;
				if overlay then
					overlay:Destroy();
					overlay, overlayBox = nil, nil;
				end;
			end;
		end,
		["Tooltip"] = 'Custom first person crosshair and block selection overlay.'
	});
	Preset = Crosshair:CreateDropdown({
		["Name"] = 'Preset',
		["List"] = {'Custom', 'PC', 'Mobile', 'Turret', 'Mouse lock', 'Default'},
		["Function"] = function(value: string): ()
			if Image then
				Image.Object.Visible = value == 'Custom';
			end;
			if Crosshair["Enabled"] then
				refreshCrosshair();
			end;
		end,
		["Tooltip"] = 'Pick one of the games own crosshairs, Custom uses the image id below, Default keeps the game crosshair'
	});
	Image = Crosshair:CreateTextBox({
		["Name"] = 'Image',
		["Placeholder"] = 'image id (roblox)',
		["Function"] = function(enter: boolean): ()
			if enter and Crosshair["Enabled"] then
				refreshCrosshair();
			end;
		end
	});
	BlockOverlay = Crosshair:CreateToggle({
		["Name"] = 'Block Overlay',
		["Function"] = function(callback: boolean): ()
			for _: number, option: table in overlayOptions do
				option.Object.Visible = callback;
			end;
			if Crosshair["Enabled"] then
				Crosshair:Toggle();
				Crosshair:Toggle();
			end;
		end,
		["Tooltip"] = 'Restyles the outline on the block you are aiming at'
	});
	FillColor = Crosshair:CreateColorSlider({
		["Name"] = 'Fill Color',
		["DefaultSat"] = 0,
		["DefaultOpacity"] = 0.25,
		["Darker"] = true,
		["Function"] = paintOverlay
	});
	OutlineColor = Crosshair:CreateColorSlider({
		["Name"] = 'Outline Color',
		["DefaultSat"] = 0,
		["Darker"] = true,
		["Function"] = paintOverlay
	});
	Thickness = Crosshair:CreateSlider({
		["Name"] = 'Thickness',
		["Min"] = 0.01,
		["Max"] = 0.2,
		["Default"] = 0.04,
		["Decimal"] = 100,
		["Darker"] = true,
		["Function"] = paintOverlay
	});
	Animate = Crosshair:CreateToggle({
		["Name"] = 'Animate',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Glides the overlay onto the next block instead of snapping to it'
	});
	AnimationTime = Crosshair:CreateSlider({
		["Name"] = 'Animation time',
		["Min"] = 0.01,
		["Max"] = 0.5,
		["Default"] = 0.08,
		["Decimal"] = 100,
		["Suffix"] = 's',
		["Darker"] = true
	});
	overlayOptions = {FillColor, OutlineColor, Thickness, Animate, AnimationTime};
	for _: number, option: table in overlayOptions do
		option.Object.Visible = false;
	end;
end);

velo.run(function(): ()
	local DamageIndicator: table = {["Enabled"] = false};
