velo.run(function(): ()
	local SongBeats: table = {["Enabled"] = false};
	local Songs: table = {["ListEnabled"] = {}};
	local BeatFov: table = {["Enabled"] = true};
	local Adjustment: table = {["Value"] = 5};
	local Volume: table = {["Value"] = 100};
	local played: {string} = {};
	local sound: Sound?;
	local beatInterval: number = 1.2;
	local nextBeat: number = 0;
	local baseFov: number?;
	local pulse: Tween?;

	local playNext: () -> () = function(): ()
		local current: Sound? = sound;
		if not current then
			return;
		end;
		local pool: {string} = {};
		for _: number, entry: string in Songs.ListEnabled do
			if not table.find(played, entry) then
				table.insert(pool, entry);
			end;
		end;
		if #pool == 0 then
			table.clear(played);
			pool = table.clone(Songs.ListEnabled);
		end;
		local entry: string? = pool[math.random(1, math.max(#pool, 1))];
		local parts: {string} = entry and entry:split('/') or {};
		if not entry or not isfile(parts[1]) then
			notif('Song Beats', entry and 'Missing song ('..parts[1]..')' or 'No songs in the list', 10);
			task.defer(function(): ()
				if SongBeats["Enabled"] then
					SongBeats:Toggle();
				end;
			end);
			return;
		end;
		table.insert(played, entry);
		current.SoundId = getcustomasset(parts[1]);
		local start: () -> () = function(): ()
			if sound == current then
				nextBeat = tick() + (tonumber(parts[3]) or 0);
				beatInterval = 60 / (tonumber(parts[2]) or 50);
				current:Play();
			end;
		end;
		if current.IsLoaded then
			start();
		else
			current.Loaded:Once(start);
		end;
	end;

	SongBeats = vape.Legit:CreateModule({
		["Name"] = 'Song Beats',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local current: Sound = Instance.new('Sound');
			current.Volume = Volume["Value"] / 100;
			current.Parent = workspace;
			sound = current;
			SongBeats:Clean(current);
			SongBeats:Clean(current.Ended:Connect(playNext));
			SongBeats:Clean(runService.RenderStepped:Connect(function(): ()
				if not BeatFov["Enabled"] or not current.IsPlaying or nextBeat > tick() then
					return;
				end;
				nextBeat = tick() + beatInterval;
				baseFov = math.min(bedwars.FovController:getFOV() * (bedwars.SprintController.sprinting and 1.1 or 1), 120);
				gameCamera.FieldOfView = baseFov - Adjustment["Value"];
				pulse = tweenService:Create(gameCamera, TweenInfo.new(math.min(beatInterval, 0.2), Enum.EasingStyle.Linear), {["FieldOfView"] = baseFov});
				pulse:Play();
			end));
			SongBeats:Clean(function(): ()
				if pulse then
					pulse:Cancel();
				end;
				if baseFov then
					gameCamera.FieldOfView = baseFov;
				end;
				sound = nil;
				table.clear(played);
			end);
			playNext();
		end,
		["Tooltip"] = 'Built in mp3 player'
	});
	Songs = SongBeats:CreateTextList({
		["Name"] = 'Songs',
		["Placeholder"] = 'filepath/bpm/start'
	});
	BeatFov = SongBeats:CreateToggle({
		["Name"] = 'Beat FOV',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if Adjustment.Object then
				Adjustment.Object.Visible = callback;
			end;
		end
	});
	Adjustment = SongBeats:CreateSlider({
		["Name"] = 'Adjustment',
		["Min"] = 1,
		["Max"] = 30,
		["Default"] = 5,
		["Darker"] = true
	});
	Volume = SongBeats:CreateSlider({
		["Name"] = 'Volume',
		["Min"] = 1,
		["Max"] = 100,
		["Default"] = 100,
		["Suffix"] = '%',
		["Function"] = function(value: number): ()
			if sound then
				sound.Volume = value / 100;
			end;
		end
	});
end);

velo.run(function(): ()
	local SoundChanger: table = {["Enabled"] = false};
	local Sounds: table = {["ListEnabled"] = {}};
	local replacements: {[string]: string} = {};

	SoundChanger = vape.Legit:CreateModule({
		["Name"] = 'SoundChanger',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			for _: number, target: table in {{bedwars.AudioManager, 'playAudio'}, {bedwars.SoundManager, 'playSound'}} do
				local owner: table?, method: string = target[1], target[2];
				local original: any = owner and owner[method];
				if owner and type(original) == 'function' then
					owner[method] = function(self: table, soundId: string, ...: any): ...any
						return original(self, replacements[soundId] or soundId, ...);
					end;
					SoundChanger:Clean(function(): ()
						owner[method] = original;
					end);
				end;
			end;
		end,
		["Tooltip"] = 'Change ingame sounds to custom ones.'
	});
	Sounds = SoundChanger:CreateTextList({
		["Name"] = 'Sounds',
		["Placeholder"] = '(DAMAGE_1/ben.mp3)',
		["Function"] = function(): ()
			table.clear(replacements);
			for _: number, entry: string in Sounds.ListEnabled do
				local parts: {string} = entry:split('/');
				local soundId: string? = bedwars.SoundList[parts[1]];
				if soundId and #parts > 1 then
					replacements[soundId] = parts[2]:find('rbxasset') and parts[2] or isfile(parts[2]) and getcustomasset(parts[2]) or '';
				end;
			end;
		end
	});
end);

velo.run(function(): ()
	local Viewmodel: table = {["Enabled"] = false};
	local Depth: table = {["Value"] = 0.8};
	local Horizontal: table = {["Value"] = 0.8};
	local Vertical: table = {["Value"] = -0.2};
	local Size: table = {["Value"] = 1};
	local NoBob: table = {["Enabled"] = true};
	local ColorMode: table = {["Value"] = 'None'};
	local FillColor: table;
	local OutlineColor: table;
	local Material: table = {["Value"] = 'Neon'};
	local Rotations: {table} = {};
	local controller: Instance = lplr.PlayerScripts.TS.controllers.global.viewmodel['viewmodel-controller'];
	local paint: table = propertyLock();
	local highlights: {[Highlight]: boolean} = {};
	local pendingScale: {Instance} = {};
	local rig: table = {};

	local applyOffsets: (active: boolean) -> () = function(active: boolean): ()
		controller:SetAttribute('ConstantManager_DEPTH_OFFSET', active and -Depth["Value"] or 0);
		controller:SetAttribute('ConstantManager_HORIZONTAL_OFFSET', active and Horizontal["Value"] or 0);
		controller:SetAttribute('ConstantManager_VERTICAL_OFFSET', active and Vertical["Value"] or 0);
	end;

	local resize: () -> () = function(): ()
		local model: Model? = rig.Model;
		if not Viewmodel["Enabled"] or not model or not model.Parent or #Rotations < 3 then
			return;
		end;
		local size: number = Size["Value"];
		model:ScaleTo(size);
		if rig.Joint then
			rig.Joint.C0 = (rig.JointC0 - rig.JointC0.Position) + rig.JointC0.Position * size + rig.Offset * (1 - size);
		end;
		model.RightHand.RightWrist.C1 = (rig.Wrist + rig.Wrist.Position * (size - 1)) * CFrame.Angles(math.rad(Rotations[1]["Value"]), math.rad(Rotations[2]["Value"]), math.rad(Rotations[3]["Value"]));
	end;

	local paintPart: (part: Instance) -> () = function(part: Instance): ()
		local mode: string = ColorMode["Value"];
		if mode == 'None' or not part:IsA('BasePart') then
			return;
		end;
		local handle: boolean = part.Name == 'Handle' and part.Parent ~= nil and part.Parent:IsA('Accessory');
		if mode == 'Highlight' and not handle then
			return;
		end;
		local fill: Color3 = Color3.fromHSV(FillColor["Hue"], FillColor["Sat"], FillColor["Value"]);
		if mode ~= 'Classic' then
			local highlight: Highlight = Instance.new('Highlight');
			highlight.FillColor = fill;
			highlight.FillTransparency = FillColor["Opacity"];
			highlight.OutlineColor = Color3.fromHSV(OutlineColor["Hue"], OutlineColor["Sat"], OutlineColor["Value"]);
			highlight.OutlineTransparency = OutlineColor["Opacity"];
			highlight.Parent = part;
			highlights[highlight] = true;
			highlight.Destroying:Once(function(): ()
				highlights[highlight] = nil;
			end);
		end;
		if mode == 'Classic' or (mode == 'Normal' and FillColor["Value"] > 0) then
			local mesh: SpecialMesh? = part:FindFirstChildOfClass('SpecialMesh');
			if mesh then
				paint.Apply(mesh, {["TextureId"] = ''});
			end;
			if part:IsA('MeshPart') then
				paint.Apply(part, {["TextureID"] = ''});
			end;
			paint.Apply(part, mode == 'Classic' and {["Material"] = Enum.Material[Material["Value"]], ["Color"] = fill} or {["Material"] = Enum.Material[Material["Value"]]});
		end;
	end;

	local repaint: () -> () = function(): ()
		for highlight: Highlight in table.clone(highlights) do
			highlight:Destroy();
		end;
		table.clear(highlights);
		paint.Restore();
		if Viewmodel["Enabled"] and rig.Model then
			for _: number, part: Instance in rig.Model:GetDescendants() do
				paintPart(part);
			end;
		end;
	end;

	local attach: (model: Model) -> () = function(model: Model): ()
		if rig.Model == model then
			return;
		end;
		model:ScaleTo(1);
		local torso: Instance? = model:FindFirstChild('LowerTorso');
		local accessory: Accessory? = model:FindFirstChildWhichIsA('Accessory');
		local reference: BasePart? = accessory and accessory:FindFirstChild('Handle') or model:FindFirstChild('RightHand');
		rig.Model = model;
		rig.Wrist = model.RightHand.RightWrist.C1;
		rig.Offset = reference and model.HumanoidRootPart.CFrame:PointToObjectSpace(reference.Position);
		rig.Joint = rig.Offset and torso and torso:FindFirstChildWhichIsA('Motor6D') or nil;
		rig.JointC0 = rig.Joint and rig.Joint.C0;
		resize();
		repaint();
		Viewmodel:Clean(model.ChildAdded:Connect(function(child: Instance): ()
			if child:IsA('Accessory') and Size["Value"] ~= 1 then
				if store.matchState == 0 then
					table.insert(pendingScale, child);
				else
					bedwars.scaleTool(child, Size["Value"]);
				end;
			end;
		end));
		Viewmodel:Clean(model.DescendantAdded:Connect(paintPart));
		bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState());
	end;

	Viewmodel = vape.Legit:CreateModule({
		["Name"] = 'Viewmodel',
		["Function"] = function(callback: boolean): ()
			if callback then
				if NoBob["Enabled"] then
					local playAnimation: (...any) -> ...any = bedwars.ViewmodelController.playAnimation;
					bedwars.ViewmodelController.playAnimation = function(self: table, animation: any, ...: any): ...any
						if animation == bedwars.AnimationType.FP_WALK then
							return nil;
						end;
						return playAnimation(self, animation, ...);
					end;
					Viewmodel:Clean(function(): ()
						bedwars.ViewmodelController.playAnimation = playAnimation;
					end);
				end;
				local matchWatch: table = bedwars.Store.changed:connect(function(new: table, old: table): ()
					if new.Game ~= old.Game and new.Game.matchState ~= 0 and #pendingScale > 0 then
						task.delay(0.5, function(): ()
							for _: number, accessory: Instance in pendingScale do
								if accessory.Parent then
									bedwars.scaleTool(accessory, Size["Value"]);
								end;
							end;
							table.clear(pendingScale);
						end);
					end;
				end);
				Viewmodel:Clean(function(): ()
					matchWatch:disconnect();
				end);
				Viewmodel:Clean(gameCamera.ChildAdded:Connect(function(child: Instance): ()
					if child.Name == 'Viewmodel' and child:IsA('Model') then
						attach(child);
					end;
				end));
				applyOffsets(true);
				local current: Instance? = gameCamera:FindFirstChild('Viewmodel');
				if current and current:IsA('Model') then
					attach(current);
				end;
				return;
			end;
			local model: Model? = rig.Model;
			if model and model.Parent then
				model:ScaleTo(1);
				model.RightHand.RightWrist.C1 = rig.Wrist;
				if rig.Joint then
					rig.Joint.C0 = rig.JointC0;
				end;
			end;
			table.clear(rig);
			table.clear(pendingScale);
			repaint();
			applyOffsets(false);
			bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState());
		end,
		["Tooltip"] = 'Changes the viewmodel position, size, animations and visuals'
	});
	for _: number, slider: table in {
		{["Name"] = 'Depth', ["Min"] = 0, ["Max"] = 2, ["Default"] = 0.8},
		{["Name"] = 'Horizontal', ["Min"] = 0, ["Max"] = 2, ["Default"] = 0.8},
		{["Name"] = 'Vertical', ["Min"] = -0.2, ["Max"] = 2, ["Default"] = -0.2}
	} do
		slider.Decimal = 10;
		slider.Function = function(): ()
			if Viewmodel["Enabled"] then
				applyOffsets(true);
			end;
		end;
		local created: table = Viewmodel:CreateSlider(slider);
		if slider.Name == 'Depth' then
			Depth = created;
		elseif slider.Name == 'Horizontal' then
			Horizontal = created;
		else
			Vertical = created;
		end;
	end;
	Size = Viewmodel:CreateSlider({
		["Name"] = 'Size',
		["Min"] = 0.1,
		["Max"] = 2,
		["Default"] = 1,
		["Decimal"] = 10,
		["Function"] = resize
	});
	for _: number, axis: string in {'X', 'Y', 'Z'} do
		table.insert(Rotations, Viewmodel:CreateSlider({
			["Name"] = 'Rotation '..axis,
			["Min"] = 0,
			["Max"] = 360,
			["Function"] = resize
		}));
	end;
	NoBob = Viewmodel:CreateToggle({
		["Name"] = 'No Bobbing',
		["Default"] = true,
		["Function"] = function(): ()
			if Viewmodel["Enabled"] then
				Viewmodel:Toggle();
				Viewmodel:Toggle();
			end;
		end
	});
	ColorMode = Viewmodel:CreateDropdown({
		["Name"] = 'Color Mode',
		["List"] = {'None', 'Highlight', 'Normal', 'Classic'},
		["Function"] = function(mode: string): ()
			if FillColor and OutlineColor and Material then
				FillColor.Object.Visible = mode ~= 'None';
				OutlineColor.Object.Visible = mode == 'Highlight' or mode == 'Normal';
				Material.Object.Visible = mode == 'Normal' or mode == 'Classic';
				repaint();
			end;
		end,
		["Tooltip"] = 'Highlight: outlines the held item\nNormal: highlights the whole viewmodel\nClassic: recolors the viewmodel parts'
	});
	FillColor = Viewmodel:CreateColorSlider({
		["Name"] = 'Color',
		["DefaultSat"] = 0,
		["DefaultOpacity"] = 0.5,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = repaint
	});
	OutlineColor = Viewmodel:CreateColorSlider({
		["Name"] = 'Outline Color',
		["DefaultValue"] = 0,
		["DefaultOpacity"] = 0,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = repaint
	});
	local materials: {string} = {};
	for _: number, material: EnumItem in Enum.Material:GetEnumItems() do
		table.insert(materials, material.Name);
	end;
	Material = Viewmodel:CreateDropdown({
		["Name"] = 'Material',
		["List"] = materials,
		["Default"] = 'Neon',
		["Visible"] = false,
		["Function"] = repaint,
		["Tooltip"] = 'Material used by the Normal and Classic color modes'
	});
end);

velo.run(function(): ()
	local PotionStatus: table = {["Enabled"] = false};
