		'greased', 'grounded', 'grounded_enchant', 'hungry', 'infected_poison', 'isabel_shield_broken', 'lunar_venom', 'mage_burn',
		'oil_spilled', 'oiled', 'on_ice', 'owl_target', 'poison', 'powdered', 'shield_down', 'shrink', 'silas_halloween_hex', 'silence',
		'skeleton_poison', 'snae_poison_arrow', 'snake_poison_sword', 'soaked', 'SPIDER_WEB_SLOW', 'stacking_decay', 'Vengeful_venom',
