		}}
	};
	local scriptPacks: {[string]: string} = {
		["FirstPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/Pack%231',
		["SecondPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/Pack%232',
		["ThirdPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/Modules/main/TexturePack',
		["FourthPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/Pack%234',
		["FifthPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/Pack%235',
		["SixthPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/Pack%236',
		["SeventhPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/Pack%237',
		["EighthPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/1024xPack',
		["EgirlPack"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/E-Girl',
		["CottonCandy"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/CottonCandy256x',
		["Pack512x"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/512xPack',
		["Pack1056x"] = 'https://raw.githubusercontent.com/SnoopyOwner/TexturePacks/main/1024xPack'
	};
	for _: number, name: string in {'FatCat', 'Simply', 'VioletsDreams', 'Enlightened', 'Onyx', 'Fury', 'Wichtiger', 'Makima', 'Marin-Kitsawaba', 'Prime', 'Vile', 'Devourer', 'Acidic', 'Moon4Real', 'Nebula'} do
		scriptPacks[name] = 'https://raw.githubusercontent.com/qwertyui-is-back/TexturePacks/refs/heads/main/'..name..'.lua';
	end;
	local imports: {[number]: Instance} = {};
	local activePack: table = packs.Velocity;
	local activeLookup: {[string]: table} = {};
	local changed: {table} = {};
	local created: {Instance} = {};

	local conceal: (root: Instance, keep: Instance?) -> () = function(root: Instance, keep: Instance?): ()
		for _: number, part: Instance in root:GetDescendants() do
			if part:IsA('BasePart') and part ~= keep then
				table.insert(changed, {["Object"] = part, ["Property"] = 'Transparency', ["Original"] = part.Transparency});
				part.Transparency = 1;
			end;
		end;
	end;

	local attach: (source: BasePart, handle: BasePart, placement: CFrame) -> () = function(source: BasePart, handle: BasePart, placement: CFrame): ()
		local model: BasePart = source:Clone();
		model.Anchored = false;
		model.CanCollide = false;
		model.CFrame = handle.CFrame * placement;
		model.Parent = handle.Parent;
		local weld: WeldConstraint = Instance.new('WeldConstraint');
		weld.Part0 = model;
		weld.Part1 = handle;
		weld.Parent = model;
		table.insert(created, model);
	end;

	local dressModel: (tool: Instance) -> () = function(tool: Instance): ()
		local pack: table = activePack;
		local item: table? = activeLookup[tool.Name];
		local handle: Instance? = item and tool:IsA('Accessory') and tool:WaitForChild('Handle', 5);
		if not handle or not TexturePack["Enabled"] then
			return;
		end;
		local cut: CFrame = CFrame.Angles(math.rad(item.Cut[1]), math.rad(item.Cut[2]), math.rad(item.Cut[3]));
		conceal(tool, nil);
		attach(item.Model, handle, cut * CFrame.Angles(0, math.rad(pack.Turn), 0));
		local held: Instance? = lplr.Character and lplr.Character:WaitForChild(tool.Name, 5);
		local heldHandle: Instance? = held and held:FindFirstChild('Handle');
		if not heldHandle or not TexturePack["Enabled"] then
			return;
		end;
		if pack.KeepHandle then
			conceal(held, heldHandle);
			return;
		end;
		conceal(held, nil);
		attach(item.Model, heldHandle, cut * CFrame.Angles(0, math.rad(pack.CharacterTurn), 0) * CFrame.new(item.Shift or pack.Shift or Vector3.zero));
	end;

	local dressAnimated: (tool: Instance) -> () = function(tool: Instance): ()
		local handle: Instance? = tool:IsA('Accessory') and tool.Name:lower():find('sword') and tool:FindFirstChild('Handle');
		if not handle then
			return;
		end;
		for property: string, value: any in {["Material"] = Enum.Material.ForceField, ["MeshId"] = 'rbxassetid://13471207377', ["BrickColor"] = BrickColor.new('Hot pink')} do
			table.insert(changed, {["Object"] = handle, ["Property"] = property, ["Original"] = handle[property]});
			handle[property] = value;
		end;
		for _: number, fill: Color3 in {Color3.fromRGB(221, 193, 255), Color3.fromHSV(AnimatedColor["Hue"], AnimatedColor["Sat"], AnimatedColor["Value"])} do
			local glow: Highlight = Instance.new('Highlight');
			glow.Adornee = handle;
			glow.FillTransparency = 0.5;
			glow.FillColor = fill;
			glow.OutlineTransparency = 0.2;
			glow.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
			glow.Parent = handle;
			table.insert(created, glow);
		end;
	end;

	local reapply: () -> () = function(): ()
		if TexturePack["Enabled"] then
			TexturePack:Toggle();
			TexturePack:Toggle();
		end;
	end;

	TexturePack = vape.Categories.Velocity:CreateModule({
		["Name"] = 'TexturePack',
		["Function"] = function(callback: boolean): ()
			if not callback then
				for index: number = #changed, 1, -1 do
					local entry: table = changed[index];
					if entry.Object.Parent then
						entry.Object[entry.Property] = entry.Original;
					end;
				end;
				for _: number, object: Instance in created do
					object:Destroy();
				end;
				table.clear(changed);
				table.clear(created);
				return;
			end;
			local url: string? = scriptPacks[Mode["Value"]];
			TexturePack:Clean(task.spawn(function(): ()
				if url then
					local source: string = game:HttpGet(url, true);
					for asset: string in source:gmatch('GetObjects%(%s*["\']rbxassetid://(%d+)') do
						if #game:GetObjects('rbxassetid://'..asset) == 0 then
							notif('TexturePack', Mode["Value"]..' uses asset '..asset..' which is no longer available.', 10, 'alert');
							return;
						end;
					end;
					local chunk: (() -> ())?, problem: string? = loadstring(source);
					if not chunk then
						notif('TexturePack', 'Failed to load '..Mode["Value"]..': '..tostring(problem), 10, 'alert');
						return;
					end;
					chunk();
					return;
				end;
				local viewmodel: Instance? = gameCamera:WaitForChild('Viewmodel', 10);
				if not viewmodel then
					return;
				end;
				local pack: table? = packs[Mode["Value"]];
				if pack then
					local import: Instance? = imports[pack.Asset] or game:GetObjects('rbxassetid://'..pack.Asset)[1];
					if not import then
						notif('TexturePack', 'Could not download the '..Mode["Value"]..' pack.', 10, 'alert');
						return;
					end;
					imports[pack.Asset] = import;
					activePack = pack;
					table.clear(activeLookup);
					for _: number, child: Instance in (pack.FromChildren and import:GetChildren() or {}) do
						activeLookup[child.Name] = {["Model"] = child, ["Cut"] = pack.FromChildren};
					end;
					for _: number, entry: table in pack.Items do
						local model: Instance? = import:FindFirstChild(entry[2]);
						if model then
							activeLookup[entry[1]] = {["Model"] = model, ["Cut"] = entry[3], ["Shift"] = entry[4]};
						end;
					end;
				end;
				local dress: (tool: Instance) -> () = pack and dressModel or dressAnimated;
				TexturePack:Clean(viewmodel.ChildAdded:Connect(dress));
				for _: number, tool: Instance in viewmodel:GetChildren() do
					task.spawn(dress, tool);
				end;
			end));
		end,
		["ExtraText"] = function(): string
			return Mode["Value"];
		end,
		["Tooltip"] = 'Customizes the texture pack. Script packs (Snoopy/qwertyui) stay applied until you rejoin.'
	});
	Mode = TexturePack:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Velocity', 'FirstPack', 'SecondPack', 'ThirdPack', 'FourthPack', 'FifthPack', 'SixthPack', 'SeventhPack', 'EighthPack', 'EgirlPack', 'CottonCandy', 'Pack512x', 'Pack1056x', 'PrivatePack', 'Aquarium', 'Ocean', 'Animated', 'DemonSlayer', 'Glizzy', 'FatCat', 'Simply', 'VioletsDreams', 'Enlightened', 'Onyx', 'Fury', 'Wichtiger', 'Makima', 'Marin-Kitsawaba', 'Prime', 'Vile', 'Devourer', 'Acidic', 'Moon4Real', 'Nebula', 'Lunar'},
		["Default"] = 'Velocity',
		["Function"] = reapply,
		["Tooltip"] = 'Mode to render the texture pack, credits to Snoopy and CatVape.'
	});
	AnimatedColor = TexturePack:CreateColorSlider({
		["Name"] = 'Animated Color',
		["Function"] = function(): ()
			if Mode["Value"] == 'Animated' then
				reapply();
			end;
		end,
		["Tooltip"] = 'Color of the Animated texture pack.'
	});
end);

velo.run(function(): ()
	local BedDefense: table;
	local BedMode: table = {["Value"] = 'Nearest'};
	local View: table = {["Value"] = 'All'};
	local MaxLayers: table = {["Value"] = 6};
	local ShowBed: table = {["Enabled"] = true};
	local AutoRotate: table = {["Enabled"] = true};
	local RotateSpeed: table = {["Value"] = 20, ["Object"] = {}};
	local Transparency: table;
	local checkRate: number = 0.2;
	local zoomRange: Vector2 = Vector2.new(0.35, 3);
	local layerFolders: {Folder} = {};
	local layerButtons: {[string]: TextButton} = {};
	local tracked: {[Instance]: number} = {};
	local orbit: table = {["Yaw"] = 0, ["Pitch"] = math.rad(28), ["Radius"] = 12, ["Center"] = Vector3.zero, ["Zoom"] = 1};
	local drag: table = {["Input"] = nil, ["Last"] = Vector3.zero, ["Touches"] = {}, ["Pinch"] = nil};
	local current: BasePart?, picked: BasePart?, bedClone: Instance?;
	local dirty: boolean, nextCheck: number, layerCount: number = false, 0, 0;

	local holder: Frame = Instance.new('Frame');
	holder.BackgroundColor3 = color.Dark(uipallet.Main, 0.1);
	holder.ClipsDescendants = true;
	holder.Size = UDim2.fromOffset(240, 246);
	Instance.new('UICorner').Parent = holder;
	local bedLabel: TextLabel = Instance.new('TextLabel');
	bedLabel.BackgroundTransparency = 1;
	bedLabel.FontFace = uipallet.Font;
	bedLabel.Position = UDim2.fromOffset(32, 0);
	bedLabel.Size = UDim2.new(1, -64, 0, 32);
	bedLabel.TextSize = 13;
	bedLabel.TextStrokeTransparency = 0.7;
	bedLabel.TextTruncate = Enum.TextTruncate.AtEnd;
	bedLabel.Parent = holder;
	local viewport: ViewportFrame = Instance.new('ViewportFrame');
	viewport.Ambient = Color3.fromRGB(170, 170, 170);
	viewport.BackgroundTransparency = 1;
	viewport.LightColor = Color3.new(1, 1, 1);
	viewport.LightDirection = Vector3.new(-0.4, -1, -0.3);
	viewport.Position = UDim2.fromOffset(0, 33);
	viewport.Size = UDim2.new(1, 0, 0, 176);
	viewport.Parent = holder;
	local viewCamera: Camera = Instance.new('Camera');
	viewCamera.FieldOfView = 40;
	viewCamera.Parent = viewport;
	viewport.CurrentCamera = viewCamera;
	local emptyLabel: TextLabel = bedLabel:Clone();
	emptyLabel.Position = UDim2.fromOffset(0, 186);
	emptyLabel.Size = UDim2.new(1, 0, 0, 20);
	emptyLabel.TextSize = 12;
	emptyLabel.ZIndex = 2;
	emptyLabel.Parent = holder;
	local buttonRow: Frame = Instance.new('Frame');
	buttonRow.BackgroundTransparency = 1;
	buttonRow.Position = UDim2.fromOffset(4, 214);
	buttonRow.Size = UDim2.new(1, -8, 0, 26);
	buttonRow.Parent = holder;
	local rowLayout: UIListLayout = Instance.new('UIListLayout');
	rowLayout.FillDirection = Enum.FillDirection.Horizontal;
	rowLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center;
	rowLayout.Padding = UDim.new(0, 4);
	rowLayout.SortOrder = Enum.SortOrder.LayoutOrder;
	rowLayout.Parent = buttonRow;
	for _: number, offset: number in {32, 209} do
		local divider: Frame = Instance.new('Frame');
		divider.BackgroundColor3 = color.Light(uipallet.Main, 0.04);
		divider.BorderSizePixel = 0;
		divider.Position = UDim2.fromOffset(0, offset);
		divider.Size = UDim2.new(1, 0, 0, 1);
		divider.Parent = holder;
	end;

	local enemyBeds: () -> {BasePart} = function(): {BasePart}
		local beds: {BasePart} = {};
		local team: string = tostring(lplr:GetAttribute('Team'));
		for _: number, bed: Instance in collectionService:GetTagged('bed') do
			if bed:IsA('BasePart') and bed:IsDescendantOf(workspace) and tostring(bed:GetAttribute('TeamId')) ~= team then
				table.insert(beds, bed);
			end;
		end;
		table.sort(beds, function(a: BasePart, b: BasePart): boolean
			return (tonumber(a:GetAttribute('TeamId')) or 0) < (tonumber(b:GetAttribute('TeamId')) or 0);
		end);
		return beds;
	end;

	local targetBed: () -> BasePart? = function(): BasePart?
		local beds: {BasePart} = enemyBeds();
		if BedMode["Value"] == 'Manual' then
			return picked and picked.Parent and picked or beds[1];
		end;
		local eye: CFrame = gameCamera.CFrame;
		local origin: Vector3 = entitylib.isAlive and entitylib.character.RootPart.Position or eye.Position;
		local best: BasePart?, bestScore: number = nil, math.huge;
		for _: number, bed: BasePart in beds do
			local score: number = BedMode["Value"] == 'Crosshair' and -eye.LookVector:Dot((bed.Position - eye.Position).Unit) or (bed.Position - origin).Magnitude;
			if score < bestScore then
				best, bestScore = bed, score;
			end;
		end;
		return best;
	end;

	local scanLayers: (bed: BasePart) -> {{Instance}} = function(bed: BasePart): {{Instance}}
		local depth: {[Vector3]: number} = {};
		local queue: {Vector3} = {};
		local layers: {{Instance}} = {};
		for _: number, cell: Vector3 in {roundPos(bed.Position), roundPos(bed.CFrame * Vector3.new(0, 0, 3))} do
			depth[cell] = 0;
			table.insert(queue, cell);
		end;
		local index: number = 1;
		while queue[index] do
			local cell: Vector3 = queue[index];
			local level: number = depth[cell];
			index += 1;
			if level >= MaxLayers["Value"] then
				continue;
			end;
			for _: number, side: Vector3 in sides do
				local neighbour: Vector3 = cell + side;
				if depth[neighbour] == nil then
					local block: Instance? = getPlacedBlock(neighbour);
					depth[neighbour] = -1;
					if block and block ~= bed and block.Name ~= 'bed' and not block:GetAttribute('NoBreak') then
						depth[neighbour] = level + 1;
						layers[level + 1] = layers[level + 1] or {};
						table.insert(layers[level + 1], block);
						table.insert(queue, neighbour);
					end;
				end;
			end;
		end;
		return layers;
	end;

	local placeCamera: () -> () = function(): ()
		local distance: number = orbit.Radius / math.tan(math.rad(viewCamera.FieldOfView / 2)) * 1.15 * orbit.Zoom;
		viewCamera.CFrame = CFrame.new(orbit.Center) * CFrame.Angles(0, orbit.Yaw, 0) * CFrame.Angles(-orbit.Pitch, 0, 0) * CFrame.new(0, 0, distance);
	end;

	local updateView: () -> () = function(): ()
		local selected: number? = tonumber(View["Value"]:match('%d+'));
		selected = selected and selected <= layerCount and selected or nil;
		local low: Vector3, high: Vector3, shown: number = Vector3.one * math.huge, Vector3.one * -math.huge, 0;
		for level: number, folder: Folder in layerFolders do
			local visible: boolean = not selected or level == selected;
			folder.Parent = visible and viewport or nil;
			for _: number, part: Instance in (visible and folder:GetDescendants() or {}) do
				if part:IsA('BasePart') then
					low, high = low:Min(part.Position - part.Size / 2), high:Max(part.Position + part.Size / 2);
					shown += 1;
				end;
			end;
		end;
		if bedClone and current then
			bedClone.Parent = ShowBed["Enabled"] and viewport or nil;
			low, high = low:Min(current.Position - Vector3.one * 3), high:Max(current.Position + Vector3.one * 3);
		end;
		if low.X ~= math.huge then
			orbit.Center = (low + high) / 2;
			orbit.Radius = math.max((high - low).Magnitude / 2, 6);
		end;
		local teamId: number? = current and tonumber(current:GetAttribute('TeamId'));
		local queue: table? = bedwars.QueueMeta[store.queueType];
		local team: table? = queue and teamId and queue.teams[teamId];
		local bedPart: Instance? = current and current:FindFirstChild('Bed');
		bedLabel.Text = current and (team and team.displayName or 'Team '..tostring(teamId))..' Bed' or 'No bed';
		bedLabel.TextColor3 = bedPart and bedPart:IsA('BasePart') and bedPart.Color or color.Dark(uipallet.Text, 0.16);
		emptyLabel.Visible = not current or shown == 0;
		emptyLabel.Text = not current and 'No bed found' or selected and 'Layer '..selected..' is empty' or 'No defense';
		local accent: Color3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value);
		for name: string, button: TextButton in layerButtons do
			local active: boolean = name == (selected and 'Layer '..selected or 'All');
			button.BackgroundColor3 = active and accent or color.Light(uipallet.Main, 0.034);
			button.Label.TextColor3 = active and uipallet.Text or color.Dark(uipallet.Text, 0.16);
		end;
		placeCamera();
	end;

	local detachedClone: (object: Instance) -> Instance? = function(object: Instance): Instance?
		local copy: Instance? = object:Clone();
		for _: number, child: Instance in (copy and {copy, unpack(copy:GetDescendants())} or {}) do
			for _: number, tag: string in child:GetTags() do
				child:RemoveTag(tag);
			end;
		end;
		return copy;
	end;

	local rebuild: (bed: BasePart?, layers: {{Instance}}?) -> () = function(bed: BasePart?, layers: {{Instance}}?): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		for _: number, folder: Folder in layerFolders do
			folder:Destroy();
		end;
		table.clear(layerFolders);
		table.clear(tracked);
		if bedClone then
			bedClone:Destroy();
			bedClone = nil;
		end;
		current = bed;
		local found: {{Instance}} = layers or bed and scanLayers(bed) or {};
		if #found ~= layerCount then
			layerCount = #found;
			for _: string, button: TextButton in layerButtons do
				button:Destroy();
			end;
			table.clear(layerButtons);
			for order: number = 1, layerCount + 1 do
				local name: string = order <= layerCount and 'Layer '..order or 'All';
				local button: TextButton = Instance.new('TextButton');
				button.Name = name;
				button.AutoButtonColor = false;
				button.BorderSizePixel = 0;
				button.LayoutOrder = order;
				button.Size = UDim2.new(1 / (layerCount + 1), -4, 1, 0);
				button.Text = '';
				button.Parent = buttonRow;
				Instance.new('UICorner').Parent = button;
				local label: TextLabel = Instance.new('TextLabel');
				label.Name = 'Label';
				label.BackgroundTransparency = 1;
				label.FontFace = uipallet.Font;
				label.Size = UDim2.fromScale(1, 1);
				label.Text = layerCount > 3 and order <= layerCount and tostring(order) or name;
				label.TextSize = 12;
				label.TextStrokeTransparency = 0.7;
				label.ZIndex = 2;
				label.Parent = button;
				button.MouseButton1Click:Connect(function(): ()
					View:SetValue(name);
				end);
				layerButtons[name] = button;
			end;
		end;
		for level: number, blockList: {Instance} in found do
			local folder: Folder = Instance.new('Folder');
			for _: number, block: Instance in blockList do
				tracked[block] = level;
				local copy: Instance? = detachedClone(block);
				if copy then
					copy.Parent = folder;
				end;
			end;
			layerFolders[level] = folder;
		end;
		bedClone = bed and detachedClone(bed);
		updateView();
	end;

	BedDefense = vape:CreateOverlay({
		["Name"] = 'Bed Defense',
		["Icon"] = getcustomasset('velo/assets/new/world.png'),
		["Size"] = UDim2.fromOffset(14, 14),
		["Position"] = UDim2.fromOffset(12, 14),
		["CategorySize"] = 240,
		["Function"] = function(callback: boolean): ()
			if not callback then
				drag.Input, drag.Pinch, dirty = nil, nil, false;
				table.clear(drag.Touches);
				rebuild(nil, {});
				return;
			end;
			BedDefense:Clean(vapeEvents.BlocksChanged.Event:Connect(function(): ()
				dirty = true;
			end));
			BedDefense:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(): ()
				dirty = true;
			end));
			BedDefense:Clean(inputService.InputChanged:Connect(function(input: InputObject): ()
				if drag.Pinch and table.find(drag.Touches, input) then
					local spread: number = (drag.Touches[1].Position - drag.Touches[2].Position).Magnitude;
					if spread > 0 then
						orbit.Zoom = math.clamp(orbit.Zoom * drag.Pinch / spread, zoomRange.X, zoomRange.Y);
						drag.Pinch = spread;
						placeCamera();
					end;
				elseif drag.Input and (input == drag.Input or input.UserInputType == Enum.UserInputType.MouseMovement and drag.Input.UserInputType == Enum.UserInputType.MouseButton1) then
					local delta: Vector3 = input.Position - drag.Last;
					drag.Last = input.Position;
					orbit.Yaw -= delta.X * 0.01;
					orbit.Pitch = math.clamp(orbit.Pitch + delta.Y * 0.01, math.rad(-80), math.rad(80));
					placeCamera();
				end;
			end));
			BedDefense:Clean(inputService.InputEnded:Connect(function(input: InputObject): ()
				local touch: number? = table.find(drag.Touches, input);
				if touch then
					table.remove(drag.Touches, touch);
					drag.Pinch = nil;
				end;
				if drag.Input and (input == drag.Input or input.UserInputType == Enum.UserInputType.MouseButton1) then
					drag.Input = nil;
				end;
			end));
			BedDefense:Clean(runService.RenderStepped:Connect(function(deltaTime: number): ()
				if AutoRotate["Enabled"] and not drag.Input and not drag.Pinch and BedDefense.Object.Visible then
					orbit.Yaw += deltaTime * math.rad(RotateSpeed["Value"]);
					placeCamera();
				end;
				local now: number = tick();
				if now < nextCheck then
					return;
				end;
				nextCheck = now + checkRate;
				local bed: BasePart? = targetBed();
				if bed ~= current then
					rebuild(bed, nil);
				elseif dirty and bed then
					dirty = false;
					local layers: {{Instance}} = scanLayers(bed);
					local count: number = 0;
					local same: boolean = true;
					for level: number, blockList: {Instance} in layers do
						for _: number, block: Instance in blockList do
							same = same and tracked[block] == level;
							count += 1;
						end;
					end;
					local trackedCount: number = 0;
					for _: Instance in tracked do
						trackedCount += 1;
					end;
					if not same or count ~= trackedCount then
						rebuild(bed, layers);
					end;
				end;
			end));
			rebuild(targetBed(), nil);
		end
	});

	local baseColor: (self: table, hue: number, sat: number, value: number, rainbow: boolean?) -> () = BedDefense.Color;
	BedDefense.Color = function(self: table, hue: number, sat: number, value: number, rainbow: boolean?): ()
		baseColor(self, hue, sat, value, rainbow);
		updateView();
	end;

	BedMode = BedDefense:CreateDropdown({
		["Name"] = 'Bed',
		["List"] = {'Nearest', 'Crosshair', 'Manual'},
		["Function"] = function(): ()
			if BedDefense.Button["Enabled"] then
				rebuild(targetBed(), nil);
			end;
		end,
		["Tooltip"] = 'Nearest - closest enemy bed\nCrosshair - enemy bed nearest your aim\nManual - pick the bed with the arrows on the viewer'
	});
	View = BedDefense:CreateDropdown({
		["Name"] = 'View',
		["List"] = {'All', 'Layer 1', 'Layer 2', 'Layer 3', 'Layer 4', 'Layer 5', 'Layer 6', 'Layer 7', 'Layer 8', 'Layer 9', 'Layer 10'},
		["Function"] = function(): ()
			updateView();
		end,
		["Tooltip"] = 'Which defense layer to show (the buttons under the viewer change this too)'
	});
	MaxLayers = BedDefense:CreateSlider({
		["Name"] = 'Max layers',
		["Min"] = 1,
		["Max"] = 10,
		["Default"] = 6,
		["Function"] = function(): ()
			if BedDefense.Button["Enabled"] then
				rebuild(current, nil);
			end;
		end,
		["Tooltip"] = 'How many layers to scan outward from the bed'
	});
	ShowBed = BedDefense:CreateToggle({
		["Name"] = 'Show bed',
		["Default"] = true,
		["Function"] = function(): ()
			updateView();
		end
	});
	AutoRotate = BedDefense:CreateToggle({
		["Name"] = 'Auto rotate',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			RotateSpeed.Object.Visible = callback;
		end
	});
	RotateSpeed = BedDefense:CreateSlider({
		["Name"] = 'Rotate speed',
		["Min"] = 5,
		["Max"] = 90,
		["Default"] = 20,
		["Darker"] = true,
		["Suffix"] = '°/s'
	});
	RotateSpeed.Object.Visible = AutoRotate["Enabled"];
	Transparency = BedDefense:CreateSlider({
		["Name"] = 'Transparency',
		["Min"] = 0,
		["Max"] = 1,
		["Default"] = 0.5,
		["Decimal"] = 10,
		["Function"] = function(value: number): ()
			holder.BackgroundTransparency = value;
		end
	});
	holder.BackgroundTransparency = Transparency["Value"];
	holder.Parent = BedDefense.Children;

	for _: number, step: number in {-1, 1} do
		local arrow: TextButton = Instance.new('TextButton');
		arrow.AnchorPoint = Vector2.new(0.5, 0.5);
		arrow.AutoButtonColor = false;
		arrow.BackgroundColor3 = color.Light(uipallet.Main, 0.034);
		arrow.BorderSizePixel = 0;
		arrow.Position = step < 0 and UDim2.fromOffset(16, 16) or UDim2.new(1, -16, 0, 16);
		arrow.Size = UDim2.fromOffset(22, 22);
		arrow.Text = step < 0 and '<' or '>';
		arrow.FontFace = uipallet.Font;
		arrow.TextSize = 14;
		arrow.TextColor3 = color.Dark(uipallet.Text, 0.16);
		arrow.Parent = holder;
		Instance.new('UICorner').Parent = arrow;
		arrow.MouseEnter:Connect(function(): ()
			arrow.BackgroundColor3 = color.Light(uipallet.Main, 0.1);
			arrow.TextColor3 = uipallet.Text;
		end);
		arrow.MouseLeave:Connect(function(): ()
			arrow.BackgroundColor3 = color.Light(uipallet.Main, 0.034);
			arrow.TextColor3 = color.Dark(uipallet.Text, 0.16);
		end);
		arrow.MouseButton1Click:Connect(function(): ()
			local beds: {BasePart} = enemyBeds();
			if #beds == 0 then
				return;
			end;
			picked = beds[((table.find(beds, current) or 0) - 1 + step) % #beds + 1];
			if BedMode["Value"] ~= 'Manual' then
				BedMode:SetValue('Manual');
			elseif BedDefense.Button["Enabled"] then
				rebuild(picked, nil);
			end;
		end);
	end;

	local capture: TextButton = Instance.new('TextButton');
	capture.BackgroundTransparency = 1;
	capture.Position = viewport.Position;
	capture.Size = viewport.Size;
	capture.Text = '';
	capture.Parent = holder;
	capture.InputBegan:Connect(function(input: InputObject): ()
		if input.UserInputType == Enum.UserInputType.Touch then
			table.insert(drag.Touches, input);
			if #drag.Touches == 2 then
				drag.Input, drag.Pinch = nil, (drag.Touches[1].Position - drag.Touches[2].Position).Magnitude;
				return;
			end;
		end;
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			drag.Input, drag.Last = input, input.Position;
		end;
	end);
	capture.InputChanged:Connect(function(input: InputObject): ()
		if input.UserInputType == Enum.UserInputType.MouseWheel then
			orbit.Zoom = math.clamp(orbit.Zoom * (1 - input.Position.Z * 0.12), zoomRange.X, zoomRange.Y);
			placeCamera();
		end;
	end);
	rebuild(nil, {});
	vape:Clean(holder);
end);

velo.run(function(): ()
	local HitAccuracy: table;
	local HideUnused: table = {["Enabled"] = true};
	local ShowColor: table = {["Enabled"] = true};
	local ComboCounter: table = {["Enabled"] = true};
	local ComboComparator: table = {["Enabled"] = false};
	local DamageComparator: table = {["Enabled"] = true};
	local refreshRate: number = 0.05;
	local chanceLifetime: number = 2;
	local rowHeight: number = 20;
	local rowOrder: {string} = {'ProjectileAimbot', 'ProjectileAura', 'Combo', 'Hits', 'Damage'};
	local rows: {[string]: table} = {};
	local fight: table = {["Opponent"] = nil, ["Combo"] = 0, ["Hits"] = 0, ["Dealt"] = 0, ["DealtHits"] = 0, ["Taken"] = 0, ["TakenHits"] = 0};
	local nextRefresh: number = 0;

	local holder: Frame = Instance.new('Frame');
	holder.BackgroundColor3 = Color3.new();
	holder.BackgroundTransparency = 0.5;
	holder.Size = UDim2.fromOffset(190, 32);
	Instance.new('UICorner').Parent = holder;
	for _: number, name: string in {'Waiting', unpack(rowOrder)} do
		local row: Frame = Instance.new('Frame');
		row.BackgroundTransparency = 1;
		row.Name = name;
		row.Position = UDim2.fromOffset(0, 6);
		row.Size = UDim2.new(1, 0, 0, rowHeight);
		row.Parent = holder;
		local title: TextLabel = Instance.new('TextLabel');
		title.BackgroundTransparency = 1;
		title.FontFace = uipallet.Font;
		title.Position = UDim2.fromOffset(10, 0);
		title.Size = UDim2.new(1, -20, 1, 0);
		title.Text = name == 'Waiting' and 'Hit chance' or name;
		title.TextColor3 = Color3.new(1, 1, 1);
		title.TextSize = 14;
		title.TextStrokeTransparency = 0.8;
		title.TextXAlignment = Enum.TextXAlignment.Left;
		title.Parent = row;
		local value: TextLabel = title:Clone();
		value.Text = '--';
		value.TextXAlignment = Enum.TextXAlignment.Right;
		value.Parent = row;
		rows[name] = {["Object"] = row, ["Title"] = title, ["Value"] = value};
	end;

	local refresh: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local shown: number = 0;
		local fighting: boolean = fight.Opponent ~= nil;
		local averageGap: number = (fight.DealtHits > 0 and fight.Dealt / fight.DealtHits or 0) - (fight.TakenHits > 0 and fight.Taken / fight.TakenHits or 0);
		local values: {[string]: table} = {
			["Combo"] = {["Enabled"] = ComboCounter["Enabled"], ["Number"] = fight.Combo},
			["Hits"] = {["Enabled"] = ComboComparator["Enabled"], ["Number"] = fight.Hits},
			["Damage"] = {["Enabled"] = DamageComparator["Enabled"], ["Number"] = math.round(averageGap)}
		};
		for _: number, name: string in rowOrder do
			local row: table = rows[name];
			local stat: table? = values[name];
			local chance: table? = not stat and store.hitchance[name] or nil;
			local live: boolean = if stat then fighting else chance ~= nil and tick() - chance.Clock < chanceLifetime;
			row.Object.Visible = (stat == nil or stat.Enabled) and (live or not HideUnused["Enabled"]);
			if row.Object.Visible then
				row.Object.Position = UDim2.fromOffset(0, 6 + shown * rowHeight);
				shown += 1;
				if stat then
					row.Value.Text = live and (stat.Number > 0 and '+' or '')..stat.Number or '--';
					row.Value.TextColor3 = live and ShowColor["Enabled"] and stat.Number ~= 0 and (stat.Number > 0 and Color3.fromRGB(110, 230, 110) or Color3.fromRGB(240, 90, 90)) or Color3.new(1, 1, 1);
				else
					row.Value.Text = live and math.round(chance.Value * 100)..'%' or '--';
					row.Value.TextColor3 = live and ShowColor["Enabled"] and Color3.fromHSV(chance.Value * 0.33, 0.75, 1) or Color3.new(1, 1, 1);
				end;
			end;
		end;
		rows.Waiting.Object.Visible = shown == 0;
		holder.Size = UDim2.fromOffset(190, 12 + math.max(shown, 1) * rowHeight);
	end;

	HitAccuracy = vape:CreateOverlay({
		["Name"] = 'Hit Accuracy',
		["Icon"] = getcustomasset('velo/assets/new/aim.png'),
		["Size"] = UDim2.fromOffset(18, 12),
		["Position"] = UDim2.fromOffset(11, 14),
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			HitAccuracy:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable: table): ()
				local mine: Model? = lplr.Character;
				local landed: boolean = mine ~= nil and damageTable.fromEntity == mine and damageTable.entityInstance ~= mine;
				local received: boolean = mine ~= nil and damageTable.entityInstance == mine and damageTable.fromEntity ~= nil and damageTable.fromEntity ~= mine;
				if not landed and not received then
					return;
				end;
				local opponent: Instance = landed and damageTable.entityInstance or damageTable.fromEntity;
				if opponent ~= fight.Opponent then
					fight.Opponent, fight.Combo, fight.Hits, fight.Dealt, fight.DealtHits, fight.Taken, fight.TakenHits = opponent, 0, 0, 0, 0, 0, 0;
				end;
				if landed then
					fight.Combo = fight.Combo >= 0 and fight.Combo + 1 or 0;
					fight.Hits += 1;
					fight.Dealt += damageTable.damage or 0;
					fight.DealtHits += 1;
				else
					fight.Combo = fight.Combo <= 0 and fight.Combo - 1 or 0;
					fight.Hits -= 1;
					fight.Taken += damageTable.damage or 0;
					fight.TakenHits += 1;
				end;
			end));
			HitAccuracy:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() >= nextRefresh then
					nextRefresh = tick() + refreshRate;
					refresh();
				end;
			end));
		end
	});
	HitAccuracy:CreateFont({
		["Name"] = 'Font',
		["Default"] = 'Arial',
		["Function"] = function(value: Font): ()
			for _: string, row: table in rows do
				row.Title.FontFace = value;
				row.Value.FontFace = value;
			end;
		end
	});
	HideUnused = HitAccuracy:CreateToggle({
		["Name"] = 'Hide unused',
		["Default"] = true,
		["Function"] = function(): ()
			refresh();
		end,
		["Tooltip"] = 'Leave out a row until its module is aiming or you are in a fight'
	});
	ShowColor = HitAccuracy:CreateToggle({
		["Name"] = 'Color the number',
		["Default"] = true,
		["Tooltip"] = 'Hit chance goes red to green; fight stats are green when you are ahead'
	});
	ComboCounter = HitAccuracy:CreateToggle({
		["Name"] = 'Combo Counter',
		["Default"] = true,
		["Tooltip"] = 'Hits landed (+) or taken (-) in a row against your current opponent'
	});
	ComboComparator = HitAccuracy:CreateToggle({
		["Name"] = 'Combo Comparator',
		["Tooltip"] = 'Hits you landed minus hits you took in the current fight'
	});
	DamageComparator = HitAccuracy:CreateToggle({
		["Name"] = 'Damage Comparator',
		["Default"] = true,
		["Tooltip"] = 'Your average damage per hit minus your opponent\'s'
	});
	HitAccuracy:CreateColorSlider({
		["Name"] = 'Background Color',
		["DefaultValue"] = 0,
		["DefaultOpacity"] = 0.5,
		["Function"] = function(hue: number, sat: number, value: number, opacity: number): ()
			holder.BackgroundColor3 = Color3.fromHSV(hue, sat, value);
			holder.BackgroundTransparency = 1 - opacity;
		end
	});
	holder.Parent = HitAccuracy.Children;
	vape:Clean(HitAccuracy.Children:GetPropertyChangedSignal('AbsolutePosition'):Connect(function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local rightSide: boolean = HitAccuracy.Children.AbsolutePosition.X > vape.gui.AbsoluteSize.X / 2;
		holder.AnchorPoint = Vector2.new(rightSide and 1 or 0, 0);
		holder.Position = UDim2.fromScale(rightSide and 1 or 0, 0);
	end));
	refresh();
	vape:Clean(holder);
end);

velo.run(function(): ()
	local InventoryOverlay: table;
	local Background: table;
	local ShowHotbar: table;
	local Selected: table;
	local ShowInventory: table;
	local columns: number = 9;
	local tileSize: number = 32;
	local gap: number = 4;
	local padding: number = 4;
	local rowLimits: Vector2 = Vector2.new(3, 8);
	local refreshRate: number = 0.1;
	local cardColumns: number = 7;
	local cardTile: number = 30;
	local cardGap: number = 5;
	local cardLift: number = 4;
	local width: number = columns * tileSize + (columns - 1) * gap + padding * 2;
	local tiles: {table} = {};
	local icons: {[string]: string} = {};
	local layout: table = {["Rows"] = 0, ["Hotbar"] = false};
	local nextRefresh: number, nextCard: number = 0, 0;
	local card: table = {["Row"] = nil, ["Cells"] = {}, ["Lifted"] = {}};

	local orderedItems: (inventory: table) -> {table} = function(inventory: table): {table}
		local worn: {[Instance]: boolean} = {};
		local items: {table} = {};
		for _: any, armor: any in inventory.armor do
			if type(armor) == 'table' and armor.tool then
				worn[armor.tool] = true;
			end;
		end;
		if inventory.backpack and inventory.backpack.tool then
			worn[inventory.backpack.tool] = true;
		end;
		for _: number, item: table in inventory.items do
			if item.tool and not worn[item.tool] then
				table.insert(items, item);
			end;
		end;
		table.sort(items, function(a: table, b: table): boolean
			if (a.addedToBackpackTime or 0) ~= (b.addedToBackpackTime or 0) then
				return (a.addedToBackpackTime or 0) < (b.addedToBackpackTime or 0);
			end;
			return a.itemType < b.itemType;
		end);
		return items;
	end;

	local playerNames: () -> {string} = function(): {string}
		local names: {string} = {};
		for _: number, plr: Player in playersService:GetPlayers() do
			if plr ~= lplr then
				table.insert(names, plr.Name);
			end;
		end;
		table.sort(names);
		table.insert(names, 1, 'Self');
		return names;
	end;

	local holder: Frame = Instance.new('Frame');
	holder.BackgroundTransparency = 1;
	holder.Size = UDim2.fromOffset(width, padding * 2 + rowLimits.X * tileSize + (rowLimits.X - 1) * gap);
	local panel: Frame = Instance.new('Frame');
	panel.BackgroundColor3 = uipallet.Main;
	panel.BorderSizePixel = 0;
	panel.Size = UDim2.fromScale(1, 1);
	panel.Parent = holder;
	local panelCorner: UICorner = Instance.new('UICorner');
	panelCorner.CornerRadius = UDim.new(0, 8);
	panelCorner.Parent = panel;

	local refresh: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		if not InventoryOverlay.Object.Visible then
			return;
		end;
		local grid: {[number]: table} = {};
		local hotbar: {[number]: table} = {};
		local last: number = 0;
		local target: Instance? = Selected["Value"] == 'Self' and lplr or playersService:FindFirstChild(Selected["Value"]);
		local slots: table = target == lplr and inventorySlots() or {};
		if #slots > 0 then
			for _: number, slot: table in slots do
				if slot.container == 'hotbar' and slot.index < columns then
					hotbar[slot.index + 1] = slot;
				elseif slot.container == 'inventory' then
					grid[slot.index + 1] = slot;
					last = math.max(last, slot.index + 1);
				end;
			end;
		elseif target and target:IsA('Player') then
			for index: number, item: table in orderedItems(bedwars.getInventory(target)) do
				if index <= columns then
					hotbar[index] = item;
				else
					grid[index - columns] = item;
					last = index - columns;
				end;
			end;
		end;
		local rows: number = math.clamp(math.ceil(last / columns), rowLimits.X, rowLimits.Y);
		if rows ~= layout.Rows or ShowHotbar["Enabled"] ~= layout.Hotbar then
			layout.Rows, layout.Hotbar = rows, ShowHotbar["Enabled"];
			local total: number = rows + (layout.Hotbar and 1 or 0);
			for index: number = 1, math.max(total * columns, #tiles) do
				local tile: table? = tiles[index];
				if index <= total * columns and not tile then
					local frame: Frame = Instance.new('Frame');
					frame.BackgroundColor3 = color.Dark(uipallet.Main, 0.04);
					frame.BorderSizePixel = 0;
					frame.Size = UDim2.fromOffset(tileSize, tileSize);
					frame.Parent = panel;
					Instance.new('UICorner').Parent = frame;
					local icon: ImageLabel = Instance.new('ImageLabel');
					icon.AnchorPoint = Vector2.new(0.5, 0.5);
					icon.BackgroundTransparency = 1;
					icon.Position = UDim2.fromScale(0.5, 0.5);
					icon.ScaleType = Enum.ScaleType.Fit;
					icon.Size = UDim2.fromScale(0.8, 0.8);
					icon.Parent = frame;
					local amount: TextLabel = Instance.new('TextLabel');
					amount.AnchorPoint = Vector2.new(1, 1);
					amount.BackgroundTransparency = 1;
					amount.FontFace = uipallet.FontSemiBold;
					amount.Position = UDim2.new(1, -3, 1, -1);
					amount.Size = UDim2.new(1, -3, 0, 12);
					amount.TextColor3 = uipallet.Text;
					amount.TextSize = 11;
					amount.TextStrokeTransparency = 0.5;
					amount.TextXAlignment = Enum.TextXAlignment.Right;
					amount.ZIndex = 2;
					amount.Parent = frame;
					tile = {["Object"] = frame, ["Icon"] = icon, ["Amount"] = amount, ["Type"] = nil, ["Count"] = nil};
					tiles[index] = tile;
				end;
				if tile then
					tile.Object.Visible = index <= total * columns;
					tile.Object.BackgroundTransparency = Background["Enabled"] and 0.7 or 1;
					tile.Object.Position = UDim2.fromOffset(padding + (index - 1) % columns * (tileSize + gap), padding + math.floor((index - 1) / columns) * (tileSize + gap));
				end;
			end;
			holder.Size = UDim2.fromOffset(width, padding * 2 + total * tileSize + (total - 1) * gap);
		end;
		for index: number = 1, (layout.Rows + (layout.Hotbar and 1 or 0)) * columns do
			local tile: table = tiles[index];
			local entry: table? = index <= layout.Rows * columns and grid[index] or hotbar[index - layout.Rows * columns];
			local itemType: string = entry and entry.itemType or '';
			local count: number = entry and (entry.amount or 1) > 1 and entry.amount or 0;
			if tile.Type ~= itemType then
				tile.Type = itemType;
				if itemType ~= '' and not icons[itemType] then
					icons[itemType] = bedwars.getIcon({["itemType"] = itemType}, true);
				end;
				tile.Icon.Image = icons[itemType] or '';
				tile.Icon.Visible = itemType ~= '';
			end;
			if tile.Count ~= count then
				tile.Count = count;
				tile.Amount.Text = count > 0 and tostring(count) or '';
				tile.Amount.Visible = count > 0;
			end;
		end;
	end;

	InventoryOverlay = vape:CreateOverlay({
		["Name"] = 'Inventory Overlay',
		["Icon"] = getcustomasset('velo/assets/new/inventory.png'),
		["Size"] = UDim2.fromOffset(15, 14),
		["Position"] = UDim2.fromOffset(12, 13),
		["CategorySize"] = width,
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			Selected:Change(playerNames());
			InventoryOverlay:Clean(playersService.PlayerAdded:Connect(function(): ()
				Selected:Change(playerNames());
			end));
			InventoryOverlay:Clean(playersService.PlayerRemoving:Connect(function(): ()
				task.defer(function(): ()
					Selected:Change(playerNames());
				end);
			end));
			InventoryOverlay:Clean(InventoryOverlay.Object:GetPropertyChangedSignal('Visible'):Connect(refresh));
			InventoryOverlay:Clean(vapeEvents.InventoryChanged.Event:Connect(function(): ()
				if Selected["Value"] == 'Self' then
					refresh();
				end;
			end));
			InventoryOverlay:Clean(runService.Heartbeat:Connect(function(): ()
				if Selected["Value"] ~= 'Self' and tick() >= nextRefresh then
					nextRefresh = tick() + refreshRate;
					refresh();
				end;
			end));
			refresh();
		end
	});
	Background = InventoryOverlay:CreateToggle({
		["Name"] = 'Render Background',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			panel.BackgroundTransparency = callback and 0.3 or 1;
			for _: number, tile: table in tiles do
				tile.Object.BackgroundTransparency = callback and 0.7 or 1;
			end;
		end,
		["Tooltip"] = 'Draw the panel and slot tiles behind the items'
	});
	ShowHotbar = InventoryOverlay:CreateToggle({
		["Name"] = 'Show Hotbar',
		["Function"] = function(): ()
			if InventoryOverlay.Button["Enabled"] then
				refresh();
			end;
		end,
		["Tooltip"] = 'Adds the hotbar as an extra row under the inventory'
	});
	Selected = InventoryOverlay:CreateDropdown({
		["Name"] = 'Inventory',
		["List"] = playerNames(),
		["Function"] = function(): ()
			if InventoryOverlay.Button["Enabled"] then
				refresh();
			end;
		end,
		["Tooltip"] = 'Whose inventory to show. Only your own slot positions reach the client, so other players fill the hotbar then the grid in pickup order'
	});
	holder.Parent = InventoryOverlay.Children;
	vape:Clean(holder);

	local targetOverlay: table? = vape.Categories['Target Info'];
	if not targetOverlay then
		return;
	end;
	local clearCard: () -> () = function(): ()
		if card.Row then
			card.Row:Destroy();
			card.Row = nil;
		end;
		table.clear(card.Cells);
		table.clear(card.Lifted);
	end;
	ShowInventory = targetOverlay:CreateToggle({
		["Name"] = 'Show Inventory',
		["Function"] = function(callback: boolean): ()
			if not callback then
				clearCard();
			end;
		end,
		["Tooltip"] = 'Shows the target\'s inventory under the card. The held item is lifted and worn armor is left out.'
	});
	vape:Clean(clearCard);
	vape:Clean(runService.Heartbeat:Connect(function(): ()
		if not ShowInventory["Enabled"] or tick() < nextCard then
			return;
		end;
		nextCard = tick() + refreshRate;
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local target: table?, longest: number = nil, 0;
		for ent: table, expire: any in targetinfo.Targets do
			local remaining: number = type(expire) == 'number' and (expire > 1e8 and expire - tick() or expire - os.clock()) or 0;
			if remaining > longest then
				target, longest = ent, remaining;
			end;
		end;
		local cardFrame: GuiObject? = nil;
		for _: number, child: Instance in targetOverlay.Children:GetChildren() do
			if child ~= card.Row and child:IsA('GuiObject') and child.Visible then
				cardFrame = child;
			end;
		end;
		if not card.Row then
			local row: Frame = Instance.new('Frame');
			row.Name = 'Inventory';
			row.BackgroundTransparency = 1;
			row.Visible = false;
			row.Parent = targetOverlay.Children;
			local grid: UIGridLayout = Instance.new('UIGridLayout');
			grid.CellPadding = UDim2.fromOffset(cardGap, cardGap);
			grid.CellSize = UDim2.fromOffset(cardTile, cardTile);
			grid.SortOrder = Enum.SortOrder.LayoutOrder;
			grid.Parent = row;
			card.Row = row;
		end;
		local inventory: table? = target and target.Player and cardFrame and targetOverlay.Object.Visible and bedwars.getInventory(target.Player) or nil;
		local items: {table} = inventory and orderedItems(inventory) or {};
		local hand: table? = inventory and inventory.hand;
		for index: number, item: table in items do
			local cell: Frame? = card.Cells[index];
			if not cell then
				cell = Instance.new('Frame');
				cell.Name = 'Slot'..index;
				cell.BackgroundTransparency = 1;
				cell.LayoutOrder = index;
				cell.Parent = card.Row;
				local tile: Frame = Instance.new('Frame');
				tile.Name = 'Tile';
				tile.BackgroundColor3 = Color3.fromRGB(29, 36, 46);
				tile.BorderMode = Enum.BorderMode.Inset;
				tile.Size = UDim2.fromScale(1, 1);
				tile.Parent = cell;
				local icon: ImageLabel = Instance.new('ImageLabel');
				icon.Name = 'Icon';
				icon.AnchorPoint = Vector2.new(0.5, 0);
				icon.BackgroundTransparency = 1;
				icon.Position = UDim2.fromScale(0.5, 0.15);
				icon.Size = UDim2.fromScale(0.8, 0.8);
				icon.Parent = tile;
				local amount: TextLabel = Instance.new('TextLabel');
				amount.Name = 'Amount';
				amount.AnchorPoint = Vector2.new(1, 1);
				amount.BackgroundTransparency = 1;
				amount.FontFace = Font.fromName('RobotoMono', Enum.FontWeight.Bold);
				amount.Position = UDim2.new(1, -2, 1, 0);
				amount.Size = UDim2.new(1, -2, 0, 12);
				amount.TextColor3 = Color3.new(1, 1, 1);
				amount.TextSize = 11;
				amount.TextStrokeTransparency = 0.5;
				amount.TextXAlignment = Enum.TextXAlignment.Right;
				amount.ZIndex = 2;
				amount.Parent = tile;
				card.Cells[index] = cell;
			end;
			local held: boolean = hand ~= nil and item.tool == hand.tool;
			local tile: Frame = cell.Tile;
			cell.Visible = true;
			tile.Icon.Image = bedwars.getIcon(item, true);
			tile.Amount.Text = (item.amount or 1) > 1 and tostring(item.amount) or '';
			tile.BackgroundTransparency = held and 0.2 or 0.4;
			tile.BorderColor3 = held and Color3.new(1, 1, 1) or Color3.fromRGB(114, 126, 172);
			if card.Lifted[cell] ~= held then
				card.Lifted[cell] = held;
				tween:Tween(tile, TweenInfo.new(0.12), {["Position"] = UDim2.fromOffset(0, held and -cardLift or 0)});
			end;
		end;
		for index: number = #items + 1, #card.Cells do
			card.Cells[index].Visible = false;
		end;
		local rows: number = math.ceil(#items / cardColumns);
		card.Row.Size = UDim2.fromOffset(cardColumns * (cardTile + cardGap) - cardGap, math.max(rows * (cardTile + cardGap) - cardGap, 0));
		card.Row.Position = cardFrame and UDim2.fromOffset(cardFrame.Position.X.Offset, cardFrame.Position.Y.Offset + cardFrame.Size.Y.Offset + cardGap + cardLift) or UDim2.new();
		card.Row.Visible = #items > 0;
	end));
end);

velo.run(function(): ()
	local AntiEffect: table = {["Enabled"] = false};
	local Dizzy: table;
	local Fear: table;
	local Vignettes: table;
	local Lasso: table;
	local LassoChance: table;
	local LassoTargeting: table;
	local Suffocate: table;
	local SuffocateMode: table;
	local SuffocateHeight: table;
	local suffocateInterval: number = 0.1;
	local lassoGrace: number = 1;
	local escapeOffsets: {Vector3} = {Vector3.new(0, 3, 0), Vector3.new(3, 0, 0), Vector3.new(-3, 0, 0), Vector3.new(0, 0, 3), Vector3.new(0, 0, -3), Vector3.new(0, -3, 0)};
	local savedVignettes: boolean? = nil;
	local nextSuffocateCheck: number = 0;

	local setVignettes: (hidden: boolean) -> () = function(hidden: boolean): ()
		local controller: table = bedwars.VignetteController;
		if hidden and savedVignettes == nil then
			savedVignettes = controller.enableOnScreenEffects;
			controller.enableOnScreenEffects = false;
			controller:destroyAllVignettes();
		elseif not hidden and savedVignettes ~= nil then
			controller.enableOnScreenEffects = savedVignettes;
			savedVignettes = nil;
		end;
	end;

	local watchLasso: (character: Model) -> () = function(character: Model): ()
		AntiEffect:Clean(character.ChildAdded:Connect(function(child: Instance): ()
			if not Lasso["Enabled"] or not child:IsA('Accessory') or not child:FindFirstChild('Rope') or math.random(1, 100) > LassoChance["Value"] then
				return;
			end;
			if LassoTargeting["Enabled"] and not entitylib.EntityPosition({["Range"] = 50, ["Part"] = 'RootPart', ["Players"] = true}) then
				return;
			end;
			local root: BasePart? = character.PrimaryPart;
			if root then
				root.Anchored = true;
				child.Destroying:Once(function(): ()
					task.delay(0.5, function(): ()
						root.Anchored = false;
					end);
				end);
			end;
		end));
	end;

	AntiEffect = vape.Categories.Utility:CreateModule({
		["Name"] = 'AntiEffect',
		["Function"] = function(callback: boolean): ()
			if not callback then
				setVignettes(false);
				return;
			end;
			if Dizzy["Enabled"] then
				runService:UnbindFromRenderStep('dizzy-status');
			end;
			if Fear["Enabled"] then
				runService:UnbindFromRenderStep('werewolf-fear-status');
			end;
			setVignettes(Vignettes["Enabled"]);
			local statusAdded: table = bedwars.SyncEvents.StatusEffectAdded:setPriority(1000):connect(function(event: table): ()
				if event.entityInstance ~= lplr.Character then
					return;
				end;
				if Dizzy["Enabled"] and event.statusEffect == bedwars.StatusEffectMeta.DIZZY then
					runService:UnbindFromRenderStep('dizzy-status');
				elseif Fear["Enabled"] and event.statusEffect == bedwars.StatusEffectMeta.WEREWOLF_FEAR then
					runService:UnbindFromRenderStep('werewolf-fear-status');
				end;
			end);
			AntiEffect:Clean(function(): ()
				statusAdded:Destroy();
			end);
			if entitylib.isAlive then
				watchLasso(entitylib.character.Character);
			end;
			AntiEffect:Clean(entitylib.Events.LocalAdded:Connect(function(ent: table): ()
				task.delay(lassoGrace, function(): ()
					if AntiEffect["Enabled"] and ent.Character.Parent then
						watchLasso(ent.Character);
					end;
				end);
			end));
			AntiEffect:Clean(runService.Heartbeat:Connect(function(): ()
				if not Suffocate["Enabled"] or tick() < nextSuffocateCheck or not entitylib.isAlive or store.matchState ~= 1 then
					return;
				end;
				nextSuffocateCheck = tick() + suffocateInterval;
				local root: BasePart = entitylib.character.RootPart;
				local head: Vector3 = root.Position + Vector3.new(0, SuffocateHeight["Value"], 0);
				local block: Instance? = getPlacedBlock(head);
				if not block then
					return;
				end;
				if SuffocateMode["Value"] == 'Break' then
					breakBlock(block, {["Effects"] = true, ["Animation"] = 'Normal'});
					return;
				end;
				local cell: Vector3 = roundPos(head);
				for _: number, offset: Vector3 in escapeOffsets do
					local escape: Vector3 = cell + offset;
					if not getPlacedBlock(escape) and not getPlacedBlock(escape + Vector3.new(0, 3, 0)) then
						root.CFrame = CFrame.new(escape - Vector3.new(0, SuffocateHeight["Value"], 0)) * root.CFrame.Rotation;
						root.AssemblyLinearVelocity = Vector3.zero;
						break;
					end;
				end;
			end));
		end,
		["Tooltip"] = 'Strips the client side of debuffs: dizziness, werewolf fear, vignettes, lasso pulls and getting trapped inside blocks.'
	});
	Dizzy = AntiEffect:CreateToggle({
		["Name"] = 'Dizzy',
		["Default"] = true,
		["Tooltip"] = 'Stops the dizzy toad swinging your walk direction around (the slow itself is server side).'
	});
	Fear = AntiEffect:CreateToggle({
		["Name"] = 'Werewolf fear',
		["Default"] = true,
		["Tooltip"] = 'Stops the werewolf tail walking you away from it.'
	});
	Vignettes = AntiEffect:CreateToggle({
		["Name"] = 'Vignettes',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if AntiEffect["Enabled"] then
				setVignettes(callback);
			end;
		end,
		["Tooltip"] = 'Clears the coloured screen borders (frozen, decay, soaked ...).'
	});
	Lasso = AntiEffect:CreateToggle({
		["Name"] = 'Lasso',
		["Function"] = function(callback: boolean): ()
			if LassoTargeting then
				LassoChance.Object.Visible = callback;
				LassoTargeting.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Anchors you while a lasso rope is attached so it cannot pull you.'
	});
	LassoChance = AntiEffect:CreateSlider({
		["Name"] = 'Lasso chance',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 100,
		["Suffix"] = '%',
		["Darker"] = true,
		["Visible"] = false
	});
	LassoTargeting = AntiEffect:CreateToggle({
		["Name"] = 'Lasso only when targeting',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Only resist when an enemy is within 50 studs.'
	});
	Suffocate = AntiEffect:CreateToggle({
		["Name"] = 'Suffocate',
		["Function"] = function(callback: boolean): ()
			if SuffocateHeight then
				SuffocateMode.Object.Visible = callback;
				SuffocateHeight.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Gets you out of a block someone placed inside you before it suffocates you.'
	});
	SuffocateMode = AntiEffect:CreateDropdown({
		["Name"] = 'Suffocate mode',
		["List"] = {'Move', 'Break'},
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Move - shifts you into the nearest open cell\nBreak - breaks the block you are stuck in'
	});
	SuffocateHeight = AntiEffect:CreateSlider({
		["Name"] = 'Suffocate height',
		["Min"] = 0,
		["Max"] = 4,
		["Default"] = 1.5,
		["Decimal"] = 10,
		["Darker"] = true,
		["Visible"] = false,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end,
		["Tooltip"] = 'How far above your root the check looks, 1.5 is head level.'
	});
end);

velo.run(function(): ()
	local AutoCollect: table = {["Enabled"] = false};
	local Range: table;
	local Delay: table;
	local Animation: table;
	local Collectables: table;
	local SpeedMushrooms: table;
	local HealMushrooms: table;
	local ShieldMushrooms: table;
	local DizzyMushrooms: table;
	local mushroomTag: string = 'forest_environment_plant';
	local recollectDelay: number = 1;
	local cooldowns: {[Instance]: number} = {};
	local nextCollect: number = 0;

	AutoCollect = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoCollect',
		["Function"] = function(callback: boolean): ()
			if not callback then
				table.clear(cooldowns);
				return;
			end;
			AutoCollect:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextCollect or not entitylib.isAlive then
					return;
				end;
				nextCollect = tick() + Delay["Value"];
				for object: Instance, expires: number in cooldowns do
					if expires < tick() then
						cooldowns[object] = nil;
					end;
				end;
				local origin: Vector3 = entitylib.character.RootPart.Position;
				local character: Model = entitylib.character.Character;
				local mushroomKinds: {[number]: boolean} = {
					[0] = HealMushrooms["Enabled"] and (character:GetAttribute('Health') or 0) < (character:GetAttribute('MaxHealth') or 0),
					[1] = ShieldMushrooms["Enabled"],
					[2] = SpeedMushrooms["Enabled"],
					[3] = DizzyMushrooms["Enabled"]
				};
				local tags: {string} = table.clone(Collectables.ListEnabled);
				if not table.find(tags, mushroomTag) then
					table.insert(tags, mushroomTag);
				end;
				for _: number, tag: string in tags do
					for _: number, object: Instance in collectionService:GetTagged(tag) do
						local part: BasePart? = object:IsA('Model') and object.PrimaryPart or (object:IsA('BasePart') and object or nil);
						local id: any = object:GetAttribute('Id');
						local kind: any = object:GetAttribute('MushroomType');
						if not part or not id or tick() < (cooldowns[object] or 0) or (origin - part.Position).Magnitude > Range["Value"] or (kind ~= nil and not mushroomKinds[kind]) then
							continue;
						end;
						if Animation["Enabled"] then
							bedwars.GameAnimationUtil:playAnimation(character, bedwars.AnimationType.PUNCH);
							bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM);
						end;
						fire('CollectCollectableEntity', 'SendToServer', {["id"] = id, ["collectableName"] = object.Name});
						cooldowns[object] = tick() + recollectDelay;
					end;
				end;
			end));
		end,
		["Tooltip"] = 'Picks up kit collectables and eats forest mushrooms near you without walking into them.'
	});
	Range = AutoCollect:CreateSlider({
		["Name"] = 'Range',
		["Min"] = 1,
		["Max"] = 20,
		["Default"] = 11,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end,
		["Tooltip"] = 'The server drops collects past 12 studs.'
	});
	Delay = AutoCollect:CreateSlider({
		["Name"] = 'Delay',
		["Min"] = 0.05,
		["Max"] = 1,
		["Default"] = 0.1,
		["Decimal"] = 100,
		["Suffix"] = 'seconds'
	});
	Animation = AutoCollect:CreateToggle({
		["Name"] = 'Animation',
		["Default"] = true,
		["Tooltip"] = 'Plays the pickup animation.'
	});
	Collectables = AutoCollect:CreateTextList({
		["Name"] = 'Collectables',
		["Default"] = {'alchemist_ingedients', 'alchemy_crystal', 'crystalheart_seed', 'forest_environment_plant', 'jailor_soul', 'murder_coin', 'shadow_coin', 'soulvine_seed', 'spirit_gardener_energy', 'spirit_gardener_seeds', 'tearbloom_seed'},
		["Darker"] = true,
		["Tooltip"] = 'Collectable tags to pick up (stars and hidden metal are handled by AutoKit).'
	});
	SpeedMushrooms = AutoCollect:CreateToggle({
		["Name"] = 'Speed mushrooms',
		["Default"] = true
	});
	HealMushrooms = AutoCollect:CreateToggle({
		["Name"] = 'Heal mushrooms',
		["Default"] = true,
		["Tooltip"] = 'Only while you are hurt, like the game prompt.'
	});
	ShieldMushrooms = AutoCollect:CreateToggle({
		["Name"] = 'Shield mushrooms',
		["Default"] = true
	});
	DizzyMushrooms = AutoCollect:CreateToggle({
		["Name"] = 'Dizzy mushrooms',
		["Tooltip"] = 'Off by default because being dizzy hurts you.'
	});
end);

velo.run(function(): ()
	local AutoPlay: table = {["Enabled"] = false};
	local Queue: table;
	local RandomQueue: table;
	local Delay: table;
	local Honor: table;
	local HonorDelay: table;
	local Vote: table;
	local VoteOption: table;
	local VoteDelay: table;
	local VoteNotify: table;
	local queueCooldown: number = 5;
	local queuePending: boolean = false;
	local nextQueue: number = 0;
	local honoredTeams: {[any]: boolean} = {};
	local voted: boolean = false;

	local honorPlayers: () -> () = function(): ()
		local team: any = lplr:GetAttribute('Team');
		local players: {Player} = playersService:GetPlayers();
		table.sort(players, function(a: Player, b: Player): boolean
			return a:GetAttribute('Team') == team and b:GetAttribute('Team') ~= team;
		end);
		for _: number, plr: Player in players do
			local teamId: any = plr:GetAttribute('Team');
			local pointsLeft: number = lplr:GetAttribute(teamId == team and 'HonorPointsLeftToGiveToAllies' or 'HonorPointsLeftToGiveToOpponents') or 0;
			if plr ~= lplr and teamId and not honoredTeams[teamId] and pointsLeft > 0 then
				honoredTeams[teamId] = true;
				bedwars.HonorController:honorPlayer(plr.UserId):await();
				task.wait(HonorDelay["Value"]);
			end;
		end;
	end;

	local matchOver: () -> () = function(): ()
		if Honor["Enabled"] then
			AutoPlay:Clean(task.spawn(honorPlayers));
		end;
		if not Queue["Enabled"] or queuePending then
			return;
		end;
		queuePending = true;
		task.delay(Delay["Value"], function(): ()
			queuePending = false;
			local state: table = bedwars.Store:getState();
			if not AutoPlay["Enabled"] or os.clock() < nextQueue or state.Game.customMatch or state.Party.leader.userId ~= lplr.UserId or state.Party.queueState ~= 0 then
				return;
			end;
			nextQueue = os.clock() + queueCooldown;
			local queueType: string = store.queueType;
			if RandomQueue["Enabled"] then
				local modes: {string} = {};
				for mode: string, meta: table in bedwars.QueueMeta do
					if not meta.disabled and not meta.voiceChatOnly and not meta.rankCategory then
						table.insert(modes, mode);
					end;
				end;
				queueType = modes[math.random(1, #modes)];
			end;
			bedwars.QueueController:joinQueue(queueType);
		end);
	end;

	local castVote: () -> () = function(): ()
		if voted or not Vote["Enabled"] or bedwars.Store:getState().Game.matchState ~= 0 then
			return;
		end;
		voted = true;
		task.delay(VoteDelay["Value"], function(): ()
			if AutoPlay["Enabled"] and Vote["Enabled"] and bedwars.Store:getState().Game.matchState == 0 then
				fire('CastPregameVote', 'SendToServer', {["votingOptionIndex"] = VoteOption["Value"] - 1});
				if VoteNotify["Enabled"] then
					notif('AutoPlay', 'Voted for option '..VoteOption["Value"], 4);
				end;
			end;
		end);
	end;

	AutoPlay = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoPlay',
		["Function"] = function(callback: boolean): ()
			if not callback then
				voted = false;
				table.clear(honoredTeams);
				return;
			end;
			AutoPlay:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable: table): ()
				if deathTable.finalKill and deathTable.entityInstance == lplr.Character and #bedwars.Store:getState().Party.members <= 0 and store.matchState ~= 2 then
					matchOver();
				end;
			end));
			AutoPlay:Clean(vapeEvents.MatchEndEvent.Event:Connect(matchOver));
			local storeChanged: table = bedwars.Store.changed:connect(function(new: table, old: table): ()
				if new.Game ~= old.Game then
					if new.Game.matchState ~= 0 then
						voted = false;
					end;
					castVote();
				end;
			end);
			AutoPlay:Clean(function(): ()
				storeChanged:disconnect();
			end);
			castVote();
		end,
		["Tooltip"] = 'Queues the next match, honors players and votes for maps automatically.'
	});
	Queue = AutoPlay:CreateToggle({
		["Name"] = 'Queue',
		["Default"] = true,
		["Tooltip"] = 'Queue again after the match ends, or after your final death when you are solo.'
	});
	RandomQueue = AutoPlay:CreateToggle({
		["Name"] = 'Random',
		["Tooltip"] = 'Chooses a random mode'
	});
	Delay = AutoPlay:CreateSlider({
		["Name"] = 'Delay',
		["Min"] = 0,
		["Max"] = 10,
		["Decimal"] = 10,
		["Default"] = 0,
		["Suffix"] = function(value: number): string
			return value == 1 and 'second' or 'seconds';
		end,
		["Tooltip"] = 'How long to wait before queueing.'
	});
	Honor = AutoPlay:CreateToggle({
		["Name"] = 'Honor',
		["Function"] = function(callback: boolean): ()
			if HonorDelay then
				HonorDelay.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Honors one player per team (allies first) when your match is over.'
	});
	HonorDelay = AutoPlay:CreateSlider({
		["Name"] = 'Honor delay',
		["Min"] = 0,
		["Max"] = 2,
		["Decimal"] = 100,
		["Default"] = 0.1,
		["Suffix"] = 'seconds',
		["Darker"] = true,
		["Visible"] = false
	});
	Vote = AutoPlay:CreateToggle({
		["Name"] = 'Vote',
		["Function"] = function(callback: boolean): ()
			if VoteNotify then
				VoteOption.Object.Visible = callback;
				VoteDelay.Object.Visible = callback;
				VoteNotify.Object.Visible = callback;
			end;
			if callback and AutoPlay["Enabled"] then
				castVote();
			end;
		end,
		["Tooltip"] = 'Casts your map vote when the pregame vote opens.'
	});
	VoteOption = AutoPlay:CreateSlider({
		["Name"] = 'Vote option',
		["Min"] = 1,
		["Max"] = 4,
		["Default"] = 1,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Which of the voting options to pick, counting from the left.'
	});
	VoteDelay = AutoPlay:CreateSlider({
		["Name"] = 'Vote delay',
		["Min"] = 0.5,
		["Max"] = 10,
		["Default"] = 1,
		["Decimal"] = 10,
		["Suffix"] = 'seconds',
		["Darker"] = true,
		["Visible"] = false
	});
	VoteNotify = AutoPlay:CreateToggle({
		["Name"] = 'Vote notify',
		["Default"] = true,
		["Darker"] = true,
		["Visible"] = false
	});
	AutoPlay:CreateButton({
		["Name"] = 'Leave party',
		["Function"] = function(): ()
			bedwars.PartyController:leaveParty();
		end
	});
	AutoPlay:CreateButton({
		["Name"] = 'Match history',
		["Function"] = function(): ()
			bedwars.Flamework.resolveDependency('@easy-games/game-core:client/controllers/app-controller@AppController'):openApp({["appId"] = 'MatchHistoryApp', ["app"] = bedwars.ModerationApp}, {["player"] = lplr, ["matchHistory"] = {}});
		end
	});
end);

velo.run(function(): ()
	local AutoToxic: table = {["Enabled"] = false};
	local AutoGG: table;
	local GGMessage: table;
	local Respond: table;
	local Responses: table;
	local Triggers: table;
	local events: {table} = {
		{["Key"] = 'Kill', ["Label"] = 'Kill', ["Variable"] = '[killed.player]', ["Default"] = 'vxp on top | [killed.player]'},
		{["Key"] = 'Death', ["Label"] = 'Death', ["Variable"] = '[killer.player]', ["Default"] = 'my gaming chair subscription expired :( | [killer.player]'},
		{["Key"] = 'Bed', ["Label"] = 'Bed', ["Variable"] = '[bed.team]', ["Default"] = 'nice bed lul | [bed.team]'},
		{["Key"] = 'BedDestroyed', ["Label"] = 'Bed destroyed', ["Variable"] = '[breaker.player]', ["Default"] = 'how dare you >:( | [breaker.player]'},
		{["Key"] = 'Win', ["Label"] = 'Win', ["Default"] = 'yall garbage'}
	};
	local insultWords: {string} = {'gay', 'gae', 'gey', 'hack', 'exploit', 'cheat', 'hecker', 'haxker', 'hacer', 'report', 'fat', 'black', 'getalife', 'fatherless', 'disco', 'yt', 'dizcourde', 'retard', 'bad', 'trash', 'nolife', 'loser', 'killyour', 'kys', 'hacktowin', 'bozo', 'kid', 'adopted', 'linlife', 'commitnotalive', 'vape', 'futureclient', 'download', 'youtube', 'die', 'lobby', 'ban', 'wizard', 'wisard', 'witch', 'magic'};
	local defaultResponse: string = 'What are you yapping about <obj>? | Velocity';
	local controls: {[string]: table} = {};
	local lastSaid: {[string]: string} = {};
	local responded: {[Player]: boolean} = {};
	local deathSaid: boolean = false;
	local closePreset: any = nil;

	local say: (text: string) -> () = function(text: string): ()
		if not text:match('%S') then
			return;
		end;
		if textChatService.ChatVersion ~= Enum.ChatVersion.TextChatService then
			replicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(text, 'All');
			return;
		end;
		local channel: TextChannel = textChatService.ChatInputBarConfiguration.TargetTextChannel;
		if textChatService:CanUserChatAsync(lplr.UserId) then
			channel:SendAsync(text);
			return;
		end;
		if not closePreset then
			for _: number, group: table in textChatService:GetPresetsAsync().categoryGroups do
				for _: number, category: table in group.categories do
					for _: number, message: table in category.messages do
						closePreset = message.value == 'So close' and message.presetId or closePreset;
					end;
				end;
			end;
		end;
		if closePreset then
			channel:SendPresetAsync(closePreset);
		end;
	end;

	local announce: (event: table, value: string?) -> () = function(event: table, value: string?): ()
		local control: table = controls[event.Key];
		if not control.Toggle["Enabled"] then
			return;
		end;
		local message: string = event.Default;
		local list: {string} = control.List.ListEnabled;
		if control.Mode["Value"] == 'Fixed' then
			message = control.Message["Value"]:match('%S') and control.Message["Value"] or event.Default;
		elseif #list > 0 then
			local index: number = math.random(1, #list);
			if #list > 1 and list[index] == lastSaid[event.Key] then
				index = index % #list + 1;
			end;
			message = list[index];
			lastSaid[event.Key] = message;
		end;
		local filled: string = message:gsub('<obj>', function(): string
			return value or '';
		end);
		if event.Variable then
			filled = filled:gsub((event.Variable:gsub('%p', '%%%0')), function(): string
				return value or '';
			end);
		end;
		say(filled);
	end;

	local onChat: (plr: Player?, text: string) -> () = function(plr: Player?, text: string): ()
		if not Respond["Enabled"] or not plr or plr == lplr or responded[plr] then
			return;
		end;
		local squashed: string = text:gsub('%W+', ''):lower():gsub('(.)%1+', '%1');
		local triggered: boolean = squashed == 'l';
		for _: number, word: string in insultWords do
			triggered = triggered or squashed:find(word, 1, true) ~= nil;
		end;
		for _: number, word: string in Triggers.ListEnabled do
			triggered = triggered or squashed:find(word:lower(), 1, true) ~= nil;
		end;
		if not triggered then
			return;
		end;
		responded[plr] = true;
		local list: {string} = Responses.ListEnabled;
		local name: string = plr.DisplayName ~= '' and plr.DisplayName or plr.Name;
		local reply: string = (#list > 0 and list[math.random(1, #list)] or defaultResponse):gsub('<obj>', function(): string
			return name;
		end):gsub('<name>', function(): string
			return name;
		end);
		say(reply);
	end;

	AutoToxic = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoToxic',
		["Function"] = function(callback: boolean): ()
			if not callback then
				deathSaid = false;
				table.clear(responded);
				return;
			end;
			AutoToxic:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
				responded[plr] = nil;
			end));
			AutoToxic:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(bedTable: table): ()
				if bedTable.brokenBedTeam.id == lplr:GetAttribute('Team') then
					announce(events[4], bedTable.player.DisplayName or bedTable.player.Name);
				elseif bedTable.player.UserId == lplr.UserId then
					local team: table? = bedwars.QueueMeta[store.queueType].teams[tonumber(bedTable.brokenBedTeam.id)];
					announce(events[3], team and team.displayName:lower() or 'white');
				end;
			end));
			AutoToxic:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable: table): ()
				local killer: Player? = playersService:GetPlayerFromCharacter(deathTable.fromEntity);
				local killed: Player? = playersService:GetPlayerFromCharacter(deathTable.entityInstance);
				if not deathTable.finalKill or not killer or not killed then
					return;
				end;
				if killed == lplr and killer ~= lplr and not deathSaid then
					deathSaid = true;
					announce(events[2], killer.DisplayName or killer.Name);
				elseif killer == lplr and killed ~= lplr then
					announce(events[1], killed.DisplayName or killed.Name);
				end;
			end));
			AutoToxic:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(winTable: table): ()
				if AutoGG["Enabled"] then
					say(GGMessage["Value"]:match('%S') and GGMessage["Value"] or 'gg');
				end;
				local myTeam: table? = bedwars.Store:getState().Game.myTeam;
				if myTeam and myTeam.id == winTable.winningTeamId or lplr.Neutral then
					announce(events[5], nil);
				end;
			end));
			if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
				AutoToxic:Clean(textChatService.MessageReceived:Connect(function(message: TextChatMessage): ()
					if message.TextSource then
						onChat(playersService:GetPlayerByUserId(message.TextSource.UserId), message.Text);
					end;
				end));
			elseif replicatedStorage:FindFirstChild('DefaultChatSystemChatEvents') then
				AutoToxic:Clean(replicatedStorage.DefaultChatSystemChatEvents.OnMessageDoneFiltering.OnClientEvent:Connect(function(message: table): ()
					onChat(playersService:FindFirstChild(message.FromSpeaker), message.Message);
				end));
			end;
		end,
		["Tooltip"] = 'Says a message after a certain action.\nEach action uses a Fixed message or a Rotating random entry from its list.\nVariables are replaced with the real name:\n[killed.player] - Kill\n[killer.player] - Death\n[bed.team] - Bed\n[breaker.player] - Bed destroyed'
	});
	AutoGG = AutoToxic:CreateToggle({
		["Name"] = 'AutoGG',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if GGMessage then
				GGMessage.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Says a message when the match ends.'
	});
	GGMessage = AutoToxic:CreateTextBox({
		["Name"] = 'GG message',
		["Default"] = 'gg',
		["Placeholder"] = 'gg',
		["Darker"] = true
	});
	for _: number, event: table in events do
		local control: table = {};
		local refreshVisibility: () -> () = function(): ()
			if control.List then
				control.Mode.Object.Visible = control.Toggle["Enabled"];
				control.Message.Object.Visible = control.Toggle["Enabled"] and control.Mode["Value"] == 'Fixed';
				control.List.Object.Visible = control.Toggle["Enabled"] and control.Mode["Value"] == 'Rotating';
			end;
		end;
		control.Toggle = AutoToxic:CreateToggle({
			["Name"] = event.Key..' ',
			["Function"] = refreshVisibility,
			["Tooltip"] = 'Say something on '..event.Label:lower()..(event.Variable and '\n'..event.Variable..' is replaced with the name' or '')
		});
		control.Mode = AutoToxic:CreateDropdown({
			["Name"] = event.Label..' mode',
			["List"] = {'Rotating', 'Fixed'},
			["Function"] = refreshVisibility,
			["Darker"] = true,
			["Visible"] = false,
			["Tooltip"] = 'Rotating - a random entry from the list (the default message when it is empty)\nFixed - the message below'
		});
		control.Message = AutoToxic:CreateTextBox({
			["Name"] = event.Label..' message',
			["Default"] = event.Default,
			["Placeholder"] = 'Type a message',
			["Darker"] = true,
			["Visible"] = false
		});
		control.List = AutoToxic:CreateTextList({
			["Name"] = event.Key,
			["Darker"] = true,
			["Visible"] = false
		});
		controls[event.Key] = control;
	end;
	Respond = AutoToxic:CreateToggle({
		["Name"] = 'Respond',
		["Default"] = true,
		["Tooltip"] = 'Answer once to players who insult you in chat.'
	});
	Responses = AutoToxic:CreateTextList({
		["Name"] = 'Responses',
		["Placeholder"] = 'response (<name> is the player)'
	});
	Triggers = AutoToxic:CreateTextList({
		["Name"] = 'Triggers',
		["Placeholder"] = 'phrase (text to respond to)'
	});
end);

velo.run(function(): ()
	local NickHider: table = {["Enabled"] = false};
	local Replacement: table;
	local HideOthers: table;
	local ChatTags: table;
	local Level: table;
	local Kit: table;
	local Device: table;
	local refreshDelay: number = 0.35;
	local scanBudget: number = 0.002;
	local textClasses: {[string]: boolean} = {["TextLabel"] = true, ["TextButton"] = true, ["TextBox"] = true};
	local patterns: {string} = {};
	local plainNames: {string} = {};
	local shortest: number = math.huge;
	local fakeName: string = 'hidden';
	local fakeReplacement: string = 'hidden';
	local writing: Instance? = nil;
	local swapped: {[Instance]: string} = {};
	local watched: {[Instance]: RBXScriptConnection} = {};
	local hiddenKits: {[Instance]: boolean} = {};
	local playerHooks: table? = nil;
	local deviceHook: table? = nil;
	local refreshQueued: boolean = false;

	local refresh: () -> () = function(): ()
		if refreshQueued or not NickHider["Enabled"] then
			return;
		end;
		refreshQueued = true;
		task.delay(refreshDelay, function(): ()
			refreshQueued = false;
			if NickHider["Enabled"] then
				NickHider:Toggle();
				NickHider:Toggle();
			end;
		end);
	end;

	local replaceText: (object: Instance) -> ();
	replaceText = function(object: Instance): ()
		local text: any = object.Text;
		if writing == object or type(text) ~= 'string' or #text < shortest then
			return;
		end;
		local lowered: string = text:lower();
		local found: boolean = false;
		for _: number, name: string in plainNames do
			found = found or lowered:find(name, 1, true) ~= nil;
		end;
		if not found then
			return;
		end;
		local replaced: string = text;
		for _: number, pattern: string in patterns do
			replaced = replaced:gsub(pattern, fakeReplacement);
		end;
		if replaced == text then
			return;
		end;
		swapped[object] = text;
		object:SetAttribute('NickHiderOriginalText', text);
		writing = object;
		object.Text = replaced;
		writing = nil;
		if not watched[object] then
			watched[object] = object:GetPropertyChangedSignal('Text'):Connect(function(): ()
				replaceText(object);
			end);
			object.Destroying:Once(function(): ()
				swapped[object] = nil;
				watched[object] = nil;
			end);
		end;
	end;

	local inspect: (object: Instance) -> () = function(object: Instance): ()
		if textClasses[object.ClassName] then
			replaceText(object);
		elseif Kit["Enabled"] and object.Name == 'PlayerKitFrame' and hiddenKits[object] == nil then
			task.defer(function(): ()
				local label: Instance? = object.Parent and object.Parent:FindFirstChild('PlayerName', true);
				if NickHider["Enabled"] and label and label.Text:find(fakeName, 1, true) then
					hiddenKits[object] = object.Visible;
					object.Visible = false;
					object.Destroying:Once(function(): ()
						hiddenKits[object] = nil;
					end);
				end;
			end);
		end;
	end;

	local scan: (root: Instance) -> () = function(root: Instance): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		NickHider:Clean(root.DescendantAdded:Connect(inspect));
		local started: number = os.clock();
		for _: number, object: Instance in root:GetDescendants() do
			inspect(object);
			if os.clock() - started > scanBudget then
				task.wait();
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				started = os.clock();
			end;
		end;
	end;

	NickHider = vape.Categories.Utility:CreateModule({
		["Name"] = 'NickHider',
		["Function"] = function(callback: boolean): ()
			if not callback then
				if playerHooks then
					for name: string, original: any in playerHooks.Originals do
						playerHooks.Class[name] = original;
					end;
					playerHooks = nil;
				end;
				if deviceHook then
					bedwars.UserInputController.getUserInputType = deviceHook.Original;
					fire('SendUserInputType', 'SendToServer', {["userInputType"] = deviceHook.Previous});
					deviceHook = nil;
				end;
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				for _: Instance, connection: RBXScriptConnection in watched do
					connection:Disconnect();
				end;
				table.clear(watched);
				for object: Instance, visible: boolean in hiddenKits do
					if object.Parent then
						object.Visible = visible;
					end;
				end;
				table.clear(hiddenKits);
				for object: Instance, original: string in swapped do
					if object.Parent then
						writing = object;
						object.Text = original;
						object:SetAttribute('NickHiderOriginalText', nil);
					end;
				end;
				writing = nil;
				table.clear(swapped);
				return;
			end;

			table.clear(patterns);
			table.clear(plainNames);
			shortest = math.huge;
			for _: number, plr: Player in playersService:GetPlayers() do
				if plr == lplr or HideOthers["Enabled"] then
					for _: number, name: string in {plr.Name, plr.DisplayName} do
						local lowered: string = name:lower();
						if name ~= '' and not table.find(plainNames, lowered) then
							table.insert(plainNames, lowered);
							shortest = math.min(shortest, #lowered);
							table.insert(patterns, (name:gsub('%W', '%%%0'):gsub('%a', function(letter: string): string
								return '['..letter:lower()..letter:upper()..']';
							end)));
						end;
					end;
				end;
			end;
			fakeName = Replacement["Value"] ~= '' and Replacement["Value"] or 'hidden';
			for _: number, pattern: string in patterns do
				fakeName = fakeName:find(pattern) and 'hidden' or fakeName;
			end;
			fakeReplacement = fakeName:gsub('%%', '%%%%');

			local gamePlayer: any = bedwars.GamePlayerUtil.getGamePlayer(lplr);
			local meta: any = gamePlayer and getmetatable(gamePlayer);
			local class: any = type(meta) == 'table' and rawget(meta, '__index');
			if type(class) == 'table' then
				local originals: table = {["getUsername"] = class.getUsername, ["getDisplayName"] = class.getDisplayName, ["getClanTag"] = class.getClanTag, ["getLevel"] = class.getLevel};
				playerHooks = {["Class"] = class, ["Originals"] = originals};
				local concealed: (self: table) -> boolean = function(self: table): boolean
					local plr: Player? = self:getPlayer();
					return plr ~= nil and (plr == lplr or HideOthers["Enabled"]);
				end;
				class.getUsername = function(self: table, ...: any): any
					return concealed(self) and fakeName or originals.getUsername(self, ...);
				end;
				class.getDisplayName = function(self: table, ...: any): any
					return concealed(self) and fakeName or originals.getDisplayName(self, ...);
				end;
				class.getClanTag = function(self: table, ...: any): any
					return self:getPlayer() == lplr and ChatTags["Enabled"] and '' or originals.getClanTag(self, ...);
				end;
				class.getLevel = function(self: table, ...: any): any
					local plr: Player? = self:getPlayer();
					if plr and (HideOthers["Enabled"] or plr == lplr and Level["Enabled"]) then
						return -1;
					end;
					return originals.getLevel(self, ...);
				end;
			end;

			if Device["Value"] ~= 'Off' then
				local controller: table = bedwars.UserInputController;
				deviceHook = {["Original"] = rawget(controller, 'getUserInputType'), ["Previous"] = controller:getUserInputType()};
				controller.getUserInputType = function(): string
					return Device["Value"]:upper();
				end;
				fire('SendUserInputType', 'SendToServer', {["userInputType"] = Device["Value"]:upper()});
			end;

			local roots: {Instance} = {coreGui};
			table.insert(roots, lplr:FindFirstChildOfClass('PlayerGui'));
			if gethui then
				table.insert(roots, gethui());
			end;
			if lplr.Character then
				table.insert(roots, lplr.Character);
			end;
			NickHider:Clean(task.spawn(function(): ()
				for _: number, root: Instance in roots do
					scan(root);
				end;
			end));
			NickHider:Clean(lplr.CharacterAdded:Connect(function(character: Model): ()
				NickHider:Clean(task.spawn(scan, character));
			end));
			NickHider:Clean(playersService.PlayerAdded:Connect(function(): ()
				if HideOthers["Enabled"] then
					refresh();
				end;
			end));
			NickHider:Clean(playersService.PlayerRemoving:Connect(function(): ()
				if HideOthers["Enabled"] then
					refresh();
				end;
			end));
		end,
		["Tooltip"] = 'Replaces your username and display name everywhere it shows up on your screen, and can spoof your device.',
		["ExtraText"] = function(): string
			return Replacement["Value"] ~= '' and Replacement["Value"] or 'hidden';
		end
	});
	Replacement = NickHider:CreateTextBox({
		["Name"] = 'Name',
		["Default"] = 'hidden',
		["Function"] = refresh
	});
	HideOthers = NickHider:CreateToggle({
		["Name"] = 'Hide others',
		["Function"] = refresh,
		["Tooltip"] = 'Hides every player\'s username and level.'
	});
	ChatTags = NickHider:CreateToggle({
		["Name"] = 'Hide chat tags',
		["Tooltip"] = 'Hides your clan tag wherever it renders.'
	});
	Level = NickHider:CreateToggle({
		["Name"] = 'Hide level',
		["Function"] = refresh,
		["Tooltip"] = 'Hides your level wherever it renders.'
	});
	Kit = NickHider:CreateToggle({
		["Name"] = 'Hide kit',
		["Function"] = refresh,
		["Tooltip"] = 'Hides your kit icon in the tab list.'
	});
	Device = NickHider:CreateDropdown({
		["Name"] = 'Device',
		["List"] = {'Off', 'Mobile', 'PC', 'Gamepad'},
		["Function"] = refresh,
		["Tooltip"] = 'Spoofs the device you show up as to the server.'
	});
end);

velo.run(function(): ()
	local StaffDetector: table = {["Enabled"] = false};
	local Mode: table;
	local Clans: table;
	local Profile: table;
	local Users: table;
	local staffGroup: number = 5774246;
	local staffRank: number = 100;
	local spectatorGrace: number = 5;
	local joinWindow: number = 20;
	local friendPages: number = 6;
	local viewerRows: number = 8;
	local blacklistedClans: {string} = {'gg', 'gg2', 'DV', 'DV2'};
	local blacklistedIds: {number} = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275};
	local safeModules: {string} = {'AutoClicker', 'Reach', 'Sprint', 'HitFix', 'StaffDetector'};
	local categories: {string} = {'Spectate', 'Mod', 'Impossible'};
	local categoryColors: {[string]: string} = {["Spectate"] = 'rgb(236,129,43)', ["Mod"] = 'rgb(250,50,56)', ["Impossible"] = 'rgb(180,90,250)'};
	local leaveTips: {[string]: string} = {
		["Spectate"] = 'Notifies when a flagged spectator leaves',
		["Mod"] = 'Notifies when a detected staff role, blacklisted user or blacklisted clan member leaves',
		["Impossible"] = 'Notifies when a player flagged for an impossible join leaves'
	};
	local leaveNotify: {[string]: table} = {};
	local joinedNames: {[number]: string} = {};
	local rejoined: {[number]: boolean} = {};
	local joinTimes: {[number]: number} = {};
	local spectatorWatch: {[Player]: RBXScriptConnection} = {};
	local entries: {table} = {};
	local window: TextButton? = nil;
	local infoLabel: TextLabel? = nil;
	local expanded: boolean = false;

	local refreshViewer: () -> () = function(): ()
		if not window or not infoLabel then
			return;
		end;
		local counts: {[string]: number} = {["Spectate"] = 0, ["Mod"] = 0, ["Impossible"] = 0};
		for _: number, entry: table in entries do
			counts[entry.Category] += 1;
		end;
		local listed: boolean = expanded and #entries > 0;
		local lines: {string} = {'<b>StaffDetector</b>', '<font size="4"> </font>'};
		for _: number, category: string in categories do
			table.insert(lines, '<font color="'..categoryColors[category]..'">'..category..': '..counts[category]..'</font>');
		end;
		if listed then
			table.insert(lines, '<font size="4"> </font>');
			for index: number = 1, math.min(#entries, viewerRows) do
				table.insert(lines, entries[index].Name..' <font color="'..categoryColors[entries[index].Category]..'">'..entries[index].Reason..'</font>');
			end;
		end;
		infoLabel.Text = table.concat(lines, '\n');
		local bounds: Vector2 = getfontsize(removeTags(infoLabel.Text), infoLabel.TextSize, infoLabel.FontFace);
		local title: Vector2 = getfontsize('StaffDetector', infoLabel.TextSize, Font.new(infoLabel.FontFace.Family, Enum.FontWeight.Bold));
		window.Size = UDim2.fromOffset(math.max(bounds.X, title.X) + 16, bounds.Y + (listed and -8 or 4));
	end;

	local addEntry: (plr: Player, reason: string, category: string) -> () = function(plr: Player, reason: string, category: string): ()
		if plr.Parent == playersService then
			table.insert(entries, 1, {["Name"] = plr.Name, ["UserId"] = plr.UserId, ["Reason"] = reason, ["Category"] = category});
		end;
		refreshViewer();
	end;

	local flagStaff: (plr: Player, reason: string) -> () = function(plr: Player, reason: string): ()
		notif('StaffDetector', 'Staff Detected ('..reason..'): '..plr.Name..' ('..plr.UserId..')', 60, 'alert');
		whitelist.customtags[plr.Name] = {{["text"] = 'GAME STAFF', ["color"] = Color3.new(1, 0, 0)}};
		addEntry(plr, reason, reason == 'impossible_join' and 'Impossible' or 'Mod');
		if Mode["Value"] == 'Uninject' then
			task.defer(function(): ()
				vape:Uninject();
			end);
			starterGui:SetCore('SendNotification', {["Title"] = 'StaffDetector', ["Text"] = 'Staff Detected ('..reason..')\n'..plr.Name..' ('..plr.UserId..')', ["Duration"] = 60});
		elseif Mode["Value"] == 'Requeue' then
			bedwars.QueueController:joinQueue(store.queueType);
		elseif Mode["Value"] == 'Profile' then
			vape.Save = function(): () end;
			if vape.Profile ~= Profile["Value"] then
				vape:Load(true, Profile["Value"]);
			end;
		elseif Mode["Value"] == 'AutoConfig' then
			vape.Save = function(): () end;
			for name: string, module: table in vape.Modules do
				if not table.find(safeModules, name) and module.Category ~= 'Render' then
					if module["Enabled"] then
						module:Toggle();
					end;
					module.Bind:SetBind({});
				end;
			end;
		end;
	end;

	local noteSpectator: (plr: Player, how: string) -> () = function(plr: Player, how: string): ()
		notif('StaffDetector', 'Spectator '..plr.Name..' joined '..how, 20, 'warning');
		addEntry(plr, 'spectator', 'Spectate');
	end;

	local dropWatch: (plr: Player) -> () = function(plr: Player): ()
		local watch: RBXScriptConnection? = spectatorWatch[plr];
		if watch then
			watch:Disconnect();
			spectatorWatch[plr] = nil;
		end;
	end;

	local checkSpectator: (plr: Player) -> boolean = function(plr: Player): boolean
		if plr:GetAttribute('Team') or not plr:GetAttribute('Spectator') or store.matchState ~= 1 or bedwars.Store:getState().Game.customMatch or tick() - (joinTimes[plr.UserId] or 0) > joinWindow then
			return false;
		end;
		dropWatch(plr);
		task.wait(spectatorGrace);
		if not StaffDetector["Enabled"] or plr.Parent ~= playersService or plr:GetAttribute('Team') or not plr:GetAttribute('Spectator') then
			return false;
		end;
		if rejoined[plr.UserId] then
			noteSpectator(plr, 'back after leaving');
			return false;
		end;
		if plr.FollowUserId ~= 0 and joinedNames[plr.FollowUserId] then
			noteSpectator(plr, 'following '..joinedNames[plr.FollowUserId]);
			return false;
		end;
		local pages: FriendPages = playersService:GetFriendsAsync(plr.UserId);
		for _: number = 1, friendPages do
			for _: number, friend: table in pages:GetCurrentPage() do
				if joinedNames[friend.Id] then
					noteSpectator(plr, 'from '..joinedNames[friend.Id]);
					return false;
				end;
			end;
			if pages.IsFinished then
				flagStaff(plr, 'impossible_join');
				return true;
			end;
			pages:AdvanceToNextPageAsync();
		end;
		return false;
	end;

	local checkPlayer: (plr: Player) -> () = function(plr: Player): ()
		rejoined[plr.UserId] = joinedNames[plr.UserId] ~= nil or nil;
		joinedNames[plr.UserId] = plr.Name;
		local teleported: number? = plr:GetAttribute('LastTeleported');
		joinTimes[plr.UserId] = teleported and tick() - math.min(workspace:GetServerTimeNow() - teleported, 60) or tick();
		if plr == lplr then
			return;
		end;
		if table.find(blacklistedIds, plr.UserId) or table.find(Users.ListEnabled, tostring(plr.UserId)) then
			flagStaff(plr, 'blacklisted_user');
			return;
		end;
		if plr:GetRankInGroup(staffGroup) >= staffRank then
			flagStaff(plr, 'staff_role');
			return;
		end;
		spectatorWatch[plr] = plr:GetAttributeChangedSignal('Spectator'):Connect(function(): ()
			StaffDetector:Clean(task.spawn(checkSpectator, plr));
		end);
		StaffDetector:Clean(spectatorWatch[plr]);
		if checkSpectator(plr) then
			return;
		end;
		if not plr:GetAttribute('ClanTag') then
			plr:GetAttributeChangedSignal('ClanTag'):Wait();
		end;
		local clan: string = plr:GetAttribute('ClanTag');
		if Clans["Enabled"] and table.find(blacklistedClans, clan) then
			dropWatch(plr);
			flagStaff(plr, 'blacklisted_clan_'..clan:lower());
		end;
	end;

	local startScan: () -> () = function(): ()
		StaffDetector:Clean(playersService.PlayerAdded:Connect(function(plr: Player): ()
			StaffDetector:Clean(task.spawn(checkPlayer, plr));
		end));
		StaffDetector:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
			dropWatch(plr);
			for index: number = #entries, 1, -1 do
				local entry: table = entries[index];
				if entry.UserId == plr.UserId then
					table.remove(entries, index);
					if leaveNotify[entry.Category]["Enabled"] then
						notif('StaffDetector', entry.Name..' left ('..entry.Reason..')', 10, 'info');
					end;
				end;
			end;
			refreshViewer();
		end));
		for _: number, plr: Player in playersService:GetPlayers() do
			StaffDetector:Clean(task.spawn(checkPlayer, plr));
		end;
	end;

	StaffDetector = vape.Categories.Utility:CreateModule({
		["Name"] = 'StaffDetector',
		["Function"] = function(callback: boolean): ()
			if not callback then
				table.clear(joinedNames);
				table.clear(rejoined);
				table.clear(joinTimes);
				table.clear(spectatorWatch);
				table.clear(entries);
				refreshViewer();
				return;
			end;
			if vape.Loaded then
				startScan();
				return;
			end;
			local loadWatch: RBXScriptConnection;
			loadWatch = runService.Heartbeat:Connect(function(): ()
				if vape.Loaded then
					loadWatch:Disconnect();
					startScan();
				end;
			end);
			StaffDetector:Clean(loadWatch);
		end,
		["Tooltip"] = 'Detects people with a staff rank ingame'
	});
	Mode = StaffDetector:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Uninject', 'Profile', 'Requeue', 'AutoConfig', 'Notify'},
		["Function"] = function(value: string): ()
			if Profile then
				Profile.Object.Visible = value == 'Profile';
			end;
		end
	});
	Clans = StaffDetector:CreateToggle({
		["Name"] = 'Blacklist clans',
		["Default"] = true
	});
	Profile = StaffDetector:CreateTextBox({
		["Name"] = 'Profile',
		["Default"] = 'default',
		["Darker"] = true,
		["Visible"] = false
	});
	Users = StaffDetector:CreateTextList({
		["Name"] = 'Users',
		["Placeholder"] = 'player (userid)'
	});
	for _: number, category: string in categories do
		leaveNotify[category] = StaffDetector:CreateToggle({
			["Name"] = 'Notify '..category..' leave',
			["Tooltip"] = leaveTips[category]
		});
	end;
	StaffDetector:CreateToggle({
		["Name"] = 'Viewer',
		["Function"] = function(callback: boolean): ()
			if callback and not window then
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				window = Instance.new('TextButton');
				window.Name = 'StaffDetectorViewer';
				window.Position = UDim2.fromOffset(12, 120);
				window.BackgroundColor3 = Color3.new();
				window.BackgroundTransparency = 0.5;
				window.Text = '';
				window.AutoButtonColor = false;
				window.Parent = vape.gui.ScaledGui;
				addBlur(window);
				local corner: UICorner = Instance.new('UICorner');
				corner.CornerRadius = UDim.new(0, 5);
				corner.Parent = window;
				infoLabel = Instance.new('TextLabel');
				infoLabel.Size = UDim2.new(1, -16, 1, -16);
				infoLabel.Position = UDim2.fromOffset(8, 8);
				infoLabel.BackgroundTransparency = 1;
				infoLabel.TextXAlignment = Enum.TextXAlignment.Left;
				infoLabel.TextYAlignment = Enum.TextYAlignment.Top;
				infoLabel.TextSize = 16;
				infoLabel.TextColor3 = Color3.new(1, 1, 1);
				infoLabel.TextStrokeColor3 = Color3.new();
				infoLabel.TextStrokeTransparency = 0.8;
				infoLabel.Font = Enum.Font.Arial;
				infoLabel.RichText = true;
				infoLabel.Parent = window;
				vape:Clean(window);
				vape:Clean(window.MouseButton1Click:Connect(function(): ()
					expanded = not expanded;
					refreshViewer();
				end));
			end;
			if window then
				window.Visible = callback;
				refreshViewer();
			end;
		end,
		["Tooltip"] = 'Shows a panel with detection counts, click it to list who tripped them.'
	});

	local autoEnable: RBXScriptConnection;
	autoEnable = runService.Heartbeat:Connect(function(): ()
		if vape.Loaded == false then
			return;
		end;
		autoEnable:Disconnect();
		if vape.Loaded and not StaffDetector["Enabled"] then
			StaffDetector:Toggle();
		end;
	end);
	vape:Clean(autoEnable);
end);

velo.run(function(): ()
	local TrapDisabler: table = {["Enabled"] = false};
	local traps: {table} = {
		{["Remote"] = 'StepOnSnapTrap', ["Name"] = 'Snap traps', ["Default"] = true, ["Tooltip"] = 'Stops trapper snap traps from marking you.'},
		{["Remote"] = 'TriggerInvisibleLandmine', ["Name"] = 'Landmines', ["Default"] = true, ["Tooltip"] = 'Stops invisible landmines from detonating on you.'},
		{["Remote"] = 'StepOnTeleportBlock', ["Name"] = 'Teleport blocks', ["Default"] = false, ["Tooltip"] = 'Stops teleport blocks from moving you.'},
		{["Remote"] = 'StepOnVoidPortal', ["Name"] = 'Void portals', ["Default"] = false, ["Tooltip"] = 'Stops void portals from moving you, this also blocks your own.'}
	};

	TrapDisabler = vape.Categories.Utility:CreateModule({
		["Name"] = 'TrapDisabler',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			for _: number, trap: table in traps do
				remoteHooks[trap.Remote] = function(remote: any, ...: any): ...any
					if trap.Toggle["Enabled"] then
						return nil;
					end;
					return remote:SendToServer(...);
				end;
				TrapDisabler:Clean(function(): ()
					remoteHooks[trap.Remote] = nil;
				end);
			end;
		end,
		["Tooltip"] = 'Drops the reports the game makes you send when you walk into a trap.'
	});
	for _: number, trap: table in traps do
		trap.Toggle = TrapDisabler:CreateToggle({
			["Name"] = trap.Name,
			["Default"] = trap.Default,
			["Tooltip"] = trap.Tooltip
		});
	end;
end);

velo.run(function(): ()
	vape.Categories.World:CreateModule({
		["Name"] = 'Anti-AFK',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			for _: number, connection: table in getconnections(lplr.Idled) do
				connection:Disconnect();
			end;
			for _: number, connection: table in getconnections(runService.Heartbeat) do
				if type(connection.Function) == 'function' and islclosure(connection.Function) and table.find(debug.getconstants(connection.Function), 'AfkInfo') then
					connection:Disconnect();
				end;
			end;
			fire('AfkInfo', 'SendToServer', {["afk"] = false});
		end,
		["Tooltip"] = 'Lets you stay ingame without getting kicked'
	});
end);

velo.run(function(): ()
	local SetEmote: table = {["Enabled"] = false};
	local Emote: table;
	local Nightmare: table;
	local movingEmoteTime: number = 6;
	local nightmareAnimation: string = 'rbxassetid://9191822700';
	local emoteTypes: {[string]: any} = {};
	local emoteNames: {string} = {};
	local playing: table = {};
	for emoteType: any, meta: table in bedwars.EmoteMeta do
		if emoteType ~= bedwars.EmoteType.NONE and meta.name and not emoteTypes[meta.name] then
			emoteTypes[meta.name] = emoteType;
			table.insert(emoteNames, meta.name);
		end;
	end;
	table.sort(emoteNames);

	local stopEmote: () -> () = function(): ()
		if playing.Track then
			playing.Track:Stop();
			playing.Track:Destroy();
		end;
		for _: number, key: string in {'Billboard', 'Effect'} do
			if playing[key] then
				playing[key]:Destroy();
			end;
		end;
		if playing.Follow then
			playing.Follow:Disconnect();
		end;
		table.clear(playing);
		if lplr.Character and lplr.Character:GetAttribute('PlayingEmote') then
			lplr.Character:SetAttribute('PlayingEmote', nil);
		end;
	end;
	vape:Clean(stopEmote);

	SetEmote = vape.Categories.Utility:CreateModule({
		["Name"] = 'SetEmote',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			SetEmote:Toggle();
			local emoteType: any = emoteTypes[Emote["Value"]];
			local meta: table? = bedwars.EmoteMeta[emoteType];
			if not entitylib.isAlive or not meta then
				return;
			end;
			stopEmote();
			local character: Model = entitylib.character.Character;
			local humanoid: Humanoid = entitylib.character.Humanoid;
			character:SetAttribute('PlayingEmote', emoteType);
			local playBegin: any = bedwars.EmoteController.createEmoteBeginAudioPlayers or bedwars.EmoteController.playEmoteBeginSounds;
			if playBegin then
				playBegin(bedwars.EmoteController, emoteType, lplr);
			end;
			local animation: table? = meta.animation or meta.emoteDisplayType and bedwars.EmoteDisplayMeta[meta.emoteDisplayType] and bedwars.EmoteDisplayMeta[meta.emoteDisplayType].animation;
			local effectTemplate: Instance? = Nightmare["Enabled"] and replicatedStorage:FindFirstChild('Assets') and replicatedStorage.Assets:FindFirstChild('Effects') and replicatedStorage.Assets.Effects:FindFirstChild('NightmareEmote');
			if effectTemplate then
				local effect: Model = effectTemplate:Clone();
				for _: number, part: Instance in effect:GetDescendants() do
					if part:IsA('BasePart') then
						bedwars.QueryUtil:setQueryIgnored(part, true);
						part.CanCollide = false;
						part.Anchored = true;
					end;
				end;
				for _: number, ring: Instance? in {effect:FindFirstChild('Outer'), effect:FindFirstChild('Middle')} do
					if ring and ring:IsA('BasePart') then
						tweenService:Create(ring, TweenInfo.new(ring.Name == 'Outer' and 1.5 or 12.5, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, -1), {["Orientation"] = ring.Orientation + Vector3.new(0, ring.Name == 'Outer' and 360 or -360, 0)}):Play();
					end;
				end;
				effect.Parent = workspace;
				playing.Effect = effect;
				playing.Follow = runService.RenderStepped:Connect(function(): ()
					local torso: BasePart? = character:FindFirstChild('LowerTorso');
					if torso and effect.PrimaryPart then
						effect:SetPrimaryPartCFrame(torso.CFrame + Vector3.new(0, -2, 0));
					end;
				end);
				local custom: Animation = Instance.new('Animation');
				custom.AnimationId = nightmareAnimation;
				playing.Track = humanoid:LoadAnimation(custom);
				playing.Track:Play();
			elseif animation then
				playing.Track = humanoid:LoadAnimation(bedwars.GameAnimationUtil:getAnimation(animation.type));
				playing.Track.Looped = animation.looped or false;
				playing.Track:Play(nil, nil, animation.speed or 1);
			end;
			if not meta.animation and character:FindFirstChild('Head') then
				local billboard: BillboardGui = Instance.new('BillboardGui');
				billboard.Size = UDim2.fromScale(6, 2.5);
				billboard.StudsOffset = Vector3.new(0, 2, 0);
				billboard.AlwaysOnTop = true;
				billboard.Adornee = character.Head;
				local image: ImageLabel = Instance.new('ImageLabel');
				image.AnchorPoint = Vector2.new(0.5, 1);
				image.Position = UDim2.fromScale(0.5, 1);
				image.Size = UDim2.fromScale(0, 0);
				image.Image = meta.image;
				image.BackgroundTransparency = 1;
				image.ImageTransparency = 1;
				image.ScaleType = Enum.ScaleType.Fit;
				image.Parent = billboard;
				billboard.Parent = character.Head;
				playing.Billboard = billboard;
				tweenService:Create(image, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {["Position"] = UDim2.fromScale(0.5, 0.5), ["Size"] = UDim2.fromScale(1, 1), ["ImageTransparency"] = 0}):Play();
			end;
			if meta.allowMovement then
				task.delay(movingEmoteTime, stopEmote);
			else
				humanoid:GetPropertyChangedSignal('MoveDirection'):Once(stopEmote);
			end;
		end,
		["Tooltip"] = 'Plays the selected emote on your character, other players can see it too.'
	});
	Emote = SetEmote:CreateDropdown({
		["Name"] = 'Emote',
		["List"] = emoteNames,
		["Default"] = 'nightmare'
	});
	Nightmare = SetEmote:CreateToggle({
		["Name"] = 'Nightmare effect',
		["Tooltip"] = 'Also spawns the nightmare ring effect and animation around you (client side).'
	});
end);

velo.run(function(): ()
	local MissileTP: table = {["Enabled"] = false};
	local Projectile: table;
	local missileSteerRate: number = 0.1;
	local ravenSteerRate: number = 0.05;
	local ravenFlight: number = 1;
	local ravenDetonate: number = 0.3;

	local steer: (model: Model, ent: table, interval: number, duration: number?) -> () = function(model: Model, ent: table, interval: number, duration: number?): ()
		local root: BasePart = model.PrimaryPart;
		local lift: BodyForce = Instance.new('BodyForce');
		lift.Name = 'AntiGravity';
		lift.Force = Vector3.new(0, root.AssemblyMass * workspace.Gravity, 0);
		lift.Parent = root;
		local started: number, nextStep: number = tick(), 0;
		local follow: RBXScriptConnection;
		follow = runService.Heartbeat:Connect(function(): ()
			if not model.Parent or not ent.RootPart or (duration and tick() - started > duration) then
				follow:Disconnect();
				return;
			end;
			if tick() >= nextStep then
				nextStep = tick() + interval;
				model:SetPrimaryPartCFrame(CFrame.lookAlong(ent.RootPart.Position, gameCamera.CFrame.LookVector));
			end;
		end);
		vape:Clean(follow);
	end;

	MissileTP = vape.Categories.Utility:CreateModule({
		["Name"] = 'MissileTP',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			MissileTP:Toggle();
			local ent: table? = entitylib.EntityMouse({["Range"] = 1000, ["Players"] = true, ["Part"] = 'RootPart'});
			if not ent then
				return;
			end;
			local hasMissile: boolean = getItem('guided_missile') ~= nil;
			if Projectile["Value"] == 'Missile' or (Projectile["Value"] == 'Auto' and hasMissile) then
				if not hasMissile then
					return;
				end;
				local launched: table? = bedwars.RuntimeLib.await(bedwars.GuidedProjectileController.fireGuidedProjectile:CallServerAsync('guided_missile'));
				if not launched then
					notif('MissileTP', 'Missile on cooldown.', 3);
					return;
				end;
				local model: Model = launched.model;
				if not model.PrimaryPart then
					model:GetPropertyChangedSignal('PrimaryPart'):Wait();
				end;
				steer(model, ent, missileSteerRate, nil);
			elseif getItem('raven') then
				fire('SpawnRaven', 'CallServerAsync'):andThen(function(raven: Model?): ()
					if raven and raven.PrimaryPart then
						steer(raven, ent, ravenSteerRate, ravenFlight);
						task.delay(ravenDetonate, function(): ()
							bedwars.RavenController:detonateRaven();
						end);
					end;
				end);
			end;
		end,
		["Tooltip"] = 'Spawns a guided missile or raven and teleports it to the player\nnearest your mouse.'
	});
	Projectile = MissileTP:CreateDropdown({
		["Name"] = 'Projectile',
		["List"] = {'Auto', 'Missile', 'Raven'},
		["Tooltip"] = 'Auto - missile when you have one, otherwise your raven.'
	});
end);

velo.run(function(): ()
	local PickupRange: table = {["Enabled"] = false};
	local Range: table;
	local Network: table;
	local Lower: table;
	local pickupInterval: number = 0.1;
	local dropGrace: number = 2;
	local picking: {[Instance]: boolean} = {};
	local nextPickup: number = 0;

	PickupRange = vape.Categories.Utility:CreateModule({
		["Name"] = 'PickupRange',
		["Function"] = function(callback: boolean): ()
			if not callback then
				table.clear(picking);
				return;
			end;
			local drops: table = collection('ItemDrop', PickupRange);
			PickupRange:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextPickup or not entitylib.isAlive then
					return;
				end;
				nextPickup = tick() + pickupInterval;
				for drop: Instance in picking do
					if not drop.Parent then
						picking[drop] = nil;
					end;
				end;
				local origin: Vector3 = entitylib.character.RootPart.Position;
				for _: number, drop: BasePart in drops do
					if picking[drop] or tick() - (drop:GetAttribute('ClientDropTime') or 0) < dropGrace then
						continue;
					end;
					if Network["Enabled"] and entitylib.character.Humanoid.Health > 0 and isnetworkowner(drop) then
						drop.CFrame = CFrame.new(origin - Vector3.new(0, 3, 0));
					end;
					if (origin - drop.Position).Magnitude > Range["Value"] or (Lower["Enabled"] and origin.Y - drop.Position.Y < entitylib.character.HipHeight - 1) then
						continue;
					end;
					picking[drop] = true;
					fire('PickupItemDrop', 'CallServerAsync', {["itemDrop"] = drop}):andThen(function(success: any): ()
						picking[drop] = nil;
						if not success then
							return;
						end;
						bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP);
						local meta: table? = bedwars.ItemMeta[drop.Name];
						if meta and meta.pickUpOverlaySound then
							bedwars.AudioManager:playAudio(meta.pickUpOverlaySound, {["position"] = drop.Position, ["volumeMultiplier"] = 0.9});
						end;
					end);
				end;
			end));
		end,
		["Tooltip"] = 'Picks up items from a farther distance'
	});
	Range = PickupRange:CreateSlider({
		["Name"] = 'Range',
		["Min"] = 1,
		["Max"] = 10,
		["Default"] = 10,
		["Suffix"] = function(value: number): string
			return value == 1 and 'stud' or 'studs';
		end
	});
	Network = PickupRange:CreateToggle({
		["Name"] = 'Network TP',
		["Default"] = true
	});
	Lower = PickupRange:CreateToggle({
		["Name"] = 'Feet Check'
	});
end);

velo.run(function(): ()
	local AutoMatchDodge: table = {["Enabled"] = false};
	local Mode: table;
	local Timeout: table;
	local SkillCheck: table;
	local RankCheck: table;
	local PlayerCheck: table;
	local Teammates: table;
	local RegionLock: table;
	local Regions: table;

	local flagPath: string = 'velo/profiles/matchdodge.txt';
	local unclaimedRelease: number = 45;
	local checkInterval: number = 0.1;
	local regionTimeout: number = 30;
	local priorMatches: number = 10;
	local fetchTimeout: number = 10;
	local fetchTries: number = 3;
	local hoverOption: number = 0;
	local defenderClass: number = 2;
	local statWeights: {[string]: number} = {["Win"] = 1, ["Combat"] = 0.5, ["Rank"] = 2, ["Kit"] = 1, ["KitPlays"] = 0.2, ["Experience"] = 0.15, ["Streak"] = 0.25, ["FinalKills"] = 0.5, ["BedBreaks"] = 0.5, ["Level"] = 0.2, ["Device"] = 0.4, ["Recent"] = 0.5};
	local roleThreat: {[string]: number} = {["Juggernaut"] = 1, ["Breaker"] = 0.8, ["Defender"] = 0.6, ["Cycler"] = 0.5, ["Support"] = 0.4};
	local kitRoles: {[string]: {string}} = {
		["Defender"] = {'black_market_trader', 'slime_tamer', 'hannah', 'fisherman', 'farmer_cletus', 'spirit_gardener'},
		["Cycler"] = {'fisherman', 'metal_detector', 'beekeeper', 'cowgirl', 'farmer_cletus', 'steam_engineer', 'spirit_gardener', 'davey', 'miner'},
		["Breaker"] = {'davey', 'oil_man', 'santa', 'dino_tamer', 'smoke', 'yeti', 'glacial_skater', 'elk_master', 'mimic', 'shielder', 'airbender'},
		["Support"] = {'baker', 'soul_broker', 'oasis', 'melody', 'hatter'},
		["Juggernaut"] = {'frost_hammer_kit', 'axolotl', 'summoner', 'bigman', 'pinata', 'tinker', 'blood_assassin', 'miner', 'aery', 'nazar', 'barbarian', 'ice_queen', 'block_kicker', 'seahorse', 'void_knight'}
	};
	local deviceThreat: {[string]: number} = {["PC"] = 1, ["GAMEPAD"] = 0.5, ["MOBILE"] = 0};
	local ignoredKits: {[string]: boolean} = {["none"] = true, ["random"] = true, [""] = true};
	local regionCountries: {[string]: string} = {
		["NA"] = 'AG AI AR AW BB BL BM BO BQ BR BS BV BZ CA CL CO CR CU CW DM DO EC EU FK GD GF GL GP GS GT GY HN HT JM KN KY LC MF MQ MS MX NI PA PE PM PR PY SR SV SX TC TT US UY VC VE VG VI',
		["EU"] = 'AD AL AO AQ AT AX BA BE BF BG BI BJ BW BY CD CF CG CH CI CM CV CZ DE DJ DK DZ EE EG EH ER ES ET FI FO FR GA GB GG GH GI GM GN GQ GR GW HR HU IE IM IO IS IT JE KE KM LI LR LS LT LU LV LY MA MC MD ME MG MK ML MR MT MU MW MZ NA NE NG NL NO PL PT RE RO RS RU RW SC SD SE SH SI SJ SK SL SM SN SO SS ST SZ TD TF TG TN TZ UA UG VA XK YT ZA ZM ZW',
		["AS"] = 'AE AM AZ BD BH BN BT CN CY GE HK ID IL IN IQ IR JO JP KG KH KP KR KW KZ LA LB LK MM MN MO MV MY NP OM PH PK PS QA SG SY TH TJ TL TM TR TW UZ VN YE',
		["OCEANIA"] = 'AU CC CK CX FJ FM GU HM KI MH MP NC NF NR NU NZ PF PG PN PW SB TK TO TV UM VU WF WS'
	};
	local regionOf: {[string]: string} = {["NA"] = 'NA', ["EU"] = 'EU', ["AS"] = 'AS', ["ASIA"] = 'AS', ["OCEANIA"] = 'OCEANIA', ["USA"] = 'NA', ["AMERICA"] = 'NA', ["UK"] = 'EU', ["EUROPE"] = 'EU', ["OCE"] = 'OCEANIA', ["AUS"] = 'OCEANIA', ["AUSTRALIA"] = 'OCEANIA'};
	for region: string, codes: string in regionCountries do
		for code: string in codes:gmatch('%a+') do
			regionOf[code] = regionOf[code] or region;
		end;
	end;
	local kitThreat: {[string]: number} = {};
	for role: string, kits: {string} in kitRoles do
		for _: number, kit: string in kits do
			kitThreat[kit] = math.max(kitThreat[kit] or 0, roleThreat[role]);
		end;
	end;
	for kit: string, meta: table in bedwars.BedwarsKitMeta do
		if meta.kitClass == defenderClass then
			kitThreat[kit] = math.max(kitThreat[kit] or 0, roleThreat.Defender);
		end;
	end;
	local topDivision: number = 1;
	for division: any in bedwars.RankMeta do
		if type(division) == 'number' and division > topDivision then
			topDivision = division;
		end;
	end;

	local hold: table = getgenv().veloMatchHold or {["Held"] = false};
	getgenv().veloMatchHold = hold;
	hold.Release = function(): ()
		if not hold.Held then
			return;
		end;
		hold.Held = false;
		hold.Block = nil;
		hold.Dodging = false;
		if hold.Connect then
			hold.Connect.Remote:FireServer(table.unpack(hold.Connect.Args, 1, hold.Connect.Args.n));
			hold.Connect = nil;
		end;
		if hold.Ready then
			hold.Ready:FireServer();
			hold.Ready = nil;
		end;
	end;
	local executor: string = identifyexecutor and ({identifyexecutor()})[1] or '';
	if not hold.Hooked and hookmetamethod and isfile(flagPath) and readfile(flagPath) == 'true' and not lplr:GetAttribute('PlayerConnected') and not table.find({'Madium', 'Solara', 'Xeno'}, executor) then
		hold.Hooked, hold.Held, hold.Started = true, true, os.clock();
		local oldNamecall: (...any) -> ...any;
		oldNamecall = hookmetamethod(game, '__namecall', newcclosure(function(self: any, ...: any): ...any
			if hold.Held and not checkcaller() and getnamecallmethod() == 'FireServer' then
				local remoteName: string = tostring(self);
				if remoteName == 'PlayerConnect' then
					hold.Connect = {["Remote"] = self, ["Args"] = table.pack(...)};
					hold.Dodging = true;
					return nil;
				elseif remoteName == 'PlayerReady' then
					hold.Ready = self;
					hold.Dodging = true;
					return nil;
				end;
			end;
			return oldNamecall(self, ...);
		end));
		task.delay(unclaimedRelease, function(): ()
			if not hold.Claimed then
				hold.Release();
			end;
		end);
	end;
	vape:Clean(hold.Release);

	local profiles: {[Player]: table} = {};
	vape:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
		profiles[plr] = nil;
	end));
	local fetchProfile: (plr: Player) -> table = function(plr: Player): table
		local entry: table = profiles[plr] or {["Tries"] = 0, ["Retry"] = 0, ["Started"] = 0};
		profiles[plr] = entry;
		local now: number = os.clock();
		if entry.Done or (entry.Pending and now - entry.Started < fetchTimeout) or (not entry.Pending and now < entry.Retry) then
			return entry;
		end;
		if entry.Tries >= fetchTries then
			entry.Done = true;
			return entry;
		end;
		entry.Pending, entry.Started, entry.Tries = true, now, entry.Tries + 1;
		local attempt: number = entry.Tries;
		AutoMatchDodge:Clean(task.spawn(function(): ()
			local data: any = fire('RequestProfileData', 'CallServer', plr);
			local ranks: any = fire('FetchRanks', 'CallServer', {plr.UserId});
			if entry.Tries ~= attempt then
				return;
			end;
			entry.Pending, entry.Retry = false, os.clock() + 5;
			if type(data) ~= 'table' or type(data.queues) ~= 'table' then
				return;
			end;
			local rows: {table} = {};
			for _: number, match: table in data.matchHistory or {} do
				for _: number, row: table in (not match.matchCancelled and match.players or {}) do
					if row.playerInfo and row.playerInfo.userId == data.userId then
						table.insert(rows, {["Queue"] = match.queueType, ["Outcome"] = row.generic and row.generic.matchOutcome, ["Kit"] = row.bedwars and row.bedwars.kit});
						break;
					end;
				end;
			end;
			entry.Data, entry.Rows, entry.Done = data, rows, true;
			entry.Rank = type(ranks) == 'table' and type(ranks[1]) == 'table' and ranks[1].rankDivision or nil;
		end));
		return entry;
	end;

	local matchContext: () -> table = function(): table
		local teleportData: any = teleportService:GetLocalPlayerTeleportData();
		local match: table? = type(teleportData) == 'table' and (teleportData.match or teleportData.customMatch) or nil;
		local queue: string = match and match.queueType or store.queueType;
		local meta: table? = bedwars.QueueMeta[queue];
		return {
			["Queue"] = queue,
			["Baseline"] = 1 / math.max(meta and meta.teams and #meta.teams or 2, 2),
			["Ranked"] = meta ~= nil and meta.rankCategory ~= nil,
			["Draft"] = bedwars.Store:getState().Draft
		};
	end;

	local skillScore: (plr: Player, entry: table, context: table) -> number = function(plr: Player, entry: table, context: table): number
		local data: table? = entry.Data;
		if not data then
			return 0;
		end;
		local baseline: number = context.Baseline;
		local stats: table = data.queues[context.Queue] or {};
		local logit: (wins: number, losses: number) -> number = function(wins: number, losses: number): number
			local rate: number = (wins + baseline * priorMatches) / (wins + losses + priorMatches);
			return math.log(rate * (1 - baseline) / ((1 - rate) * baseline));
		end;
		local recentWins: number, recentLosses: number = 0, 0;
		for _: number, row: table in entry.Rows do
			if row.Queue == context.Queue then
				recentWins += row.Outcome == 'win' and 1 or 0;
				recentLosses += row.Outcome == 'loss' and 1 or 0;
			end;
		end;

		local kit: string? = plr:GetAttribute('PlayingAsKits');
		local confidence: number = 1;
		if not kit or ignoredKits[kit] then
			kit, confidence = nil, 0;
			local userId: string = tostring(plr.UserId);
			local pick: table? = context.Draft.teamData.kitSelection[userId];
			for _: number, team: table in (pick == nil and context.Draft.enemyTeamData or {}) do
				pick = pick or team.kitSelection and team.kitSelection[userId];
			end;
			if pick and pick.kit and pick.selectorOption ~= hoverOption and not ignoredKits[pick.kit] then
				kit, confidence = pick.kit, 1;
			elseif context.Ranked then
				local banned: {[string]: boolean} = {};
				for _: any, bans: {string} in context.Draft.sharedData.kitBans or {} do
					for _: number, bannedKit: string in bans do
						banned[bannedKit] = true;
					end;
				end;
				local plays: {[string]: number} = table.clone(data.favoriteKitData or {});
				for _: number, row: table in entry.Rows do
					if row.Kit then
						plays[row.Kit] = (plays[row.Kit] or 0) + 1;
					end;
				end;
				local best: number, total: number = 0, 0;
				for candidate: string, count: number in plays do
					if not ignoredKits[candidate] then
						total += count;
						if not banned[candidate] and count > best then
							kit, best = candidate, count;
						end;
					end;
				end;
				confidence = best / (total + priorMatches);
			end;
		end;

		local matches: number = (stats.matches or 0) + priorMatches;
		local parts: {[string]: number} = {
			["Win"] = logit(stats.wins or 0, stats.losses or 0),
			["Combat"] = math.log(((stats.kills or 0) + priorMatches) / ((stats.deaths or 0) + priorMatches)),
			["Rank"] = (entry.Rank or 0) / topDivision,
			["Kit"] = (kit and kitThreat[kit] or 0) * confidence,
			["KitPlays"] = math.log(1 + (kit and data.favoriteKitData and data.favoriteKitData[kit] or 0)) * confidence,
			["Experience"] = math.log(1 + (data.globalStats and data.globalStats.matches or 0)),
			["Streak"] = math.log(1 + (stats.currentWinStreak or 0)),
			["FinalKills"] = math.log(1 + (stats.finalKills or 0) / matches),
			["BedBreaks"] = math.log(1 + (stats.bedBreaks or 0) / matches),
			["Level"] = math.log(1 + (data.level or 0)),
			["Device"] = deviceThreat[plr:GetAttribute('UserInputType') or data.platform] or 0,
			["Recent"] = logit(recentWins, recentLosses)
		};
		local score: number = 0;
		for name: string, value: number in parts do
			score += value * statWeights[name];
		end;
		return score;
	end;

	local dodgeReason: () -> string? = function(): string?
		local context: table = matchContext();
		if RankCheck["Enabled"] and not context.Ranked then
			return nil;
		end;
		if SkillCheck["Enabled"] then
			local mine: table = fetchProfile(lplr);
			local stronger: number = 0;
			for _: number, ent: table in entitylib.List do
				local plr: Player? = ent.Player;
				if plr and plr:GetAttribute('Team') ~= lplr:GetAttribute('Team') and plr:IsDescendantOf(playersService) then
					local theirs: table = fetchProfile(plr);
					if mine.Done and theirs.Done and skillScore(lplr, mine, context) <= skillScore(plr, theirs, context) then
						stronger += 1;
					end;
				end;
			end;
			if stronger > 1 then
				return 'Dodging because multiple opponents are "better" than you';
			end;
		end;
		if PlayerCheck["Enabled"] then
			local whitelisted: {[string]: boolean} = {};
			for _: number, name: string in Teammates.ListEnabled do
				whitelisted[name:lower()] = true;
			end;
			local myTeam: any = lplr:GetAttribute('Team');
			local allies: number, enemies: {[any]: number}, pending: boolean = 1, {}, false;
			for _: number, plr: Player in playersService:GetPlayers() do
				local team: any = plr:GetAttribute('Team');
				if plr == lplr or plr:GetAttribute('Spectator') then
					continue;
				elseif whitelisted[plr.Name:lower()] or (myTeam and team == myTeam) then
					allies += 1;
				elseif not team then
					pending = true;
				elseif myTeam then
					enemies[team] = (enemies[team] or 0) + 1;
				end;
			end;
			local state: table = bedwars.Store:getState();
			local meta: table? = bedwars.QueueMeta[store.queueType];
			local present: number, expected: number, largest: number = allies, 0, 0;
			for _: any, count: number in enemies do
				present += count;
				largest = math.max(largest, count);
			end;
			for _: any, team: table in state.Game.teams or {} do
				for _: any in team.members or {} do
					expected += 1;
				end;
			end;
			local drafting: boolean = meta ~= nil and meta.drafting ~= nil and meta.drafting.enabled == true;
			local ready: boolean = present >= expected and (not drafting or state.Draft.sharedData.matchDraftPhase >= 3);
			if myTeam and not pending and ready and allies < largest then
				return 'Dodging because you have fewer players ('..allies..') than the enemy team ('..largest..')';
			end;
		end;
		return nil;
	end;

	local regionVerdict: (code: string) -> boolean = function(code: string): boolean
		local normalize: (text: string) -> string? = function(text: string): string?
			local word: string? = text:upper():gsub('<[^>]*>', ''):gsub('REGION:', ''):match('%a+');
			return word and regionOf[word];
		end;
		local region: string? = normalize(code);
		local selected: {[string]: boolean} = {};
		local anySelected: boolean = false;
		for _: number, entry: string in Regions.ListEnabled do
			local name: string? = normalize(entry);
			if name then
				selected[name], anySelected = true, true;
			end;
		end;
		if not anySelected then
			notif('AutoMatchDodge', 'No valid region is turned on, loading every region', 8, 'warning');
		elseif not region then
			notif('AutoMatchDodge', 'Unknown region '..code..', loading anyway', 8, 'warning');
		elseif not selected[region] then
			notif('AutoMatchDodge', 'Dodging '..code..' ('..region..'), it is not in your regions', 12, 'info');
			return false;
		end;
		return true;
	end;

	AutoMatchDodge = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoMatchDodge',
		["Function"] = function(callback: boolean): ()
			writefile(flagPath, tostring(callback));
			if not callback then
				table.clear(profiles);
				hold.Release();
				return;
			end;
			if not hold.Held then
				return;
			end;
			hold.Claimed = true;
			local regionDone: boolean = not RegionLock["Enabled"];
			local nextCheck: number = 0;
			local watcher: RBXScriptConnection;
			watcher = runService.Heartbeat:Connect(function(): ()
				local now: number = os.clock();
				if not hold.Held then
					watcher:Disconnect();
					return;
				end;
				if now < nextCheck then
					return;
				end;
				nextCheck = now + checkInterval;
				if not regionDone then
					local display: Instance? = lplr.PlayerGui:FindFirstChild('ServerRegionDisplay');
					local label: Instance? = display and display:FindFirstChild('ServerRegionText');
					local code: string? = label and label.Text:gsub('<[^>]*>', ''):gsub('REGION:%s*', ''):match('%S+');
					if code then
						regionDone = true;
						hold.Block = not regionVerdict(code) and 'RegionLock' or nil;
					elseif now - hold.Started > regionTimeout then
						regionDone = true;
						notif('AutoMatchDodge', 'Could not read the server region, loading anyway', 8, 'warning');
					end;
				end;
				if Mode["Value"] ~= 'Auto' then
					return;
				end;
				local reason: string? = dodgeReason();
				if reason then
					notif('AutoMatchDodge', reason, 12, 'info');
					watcher:Disconnect();
				elseif regionDone and not hold.Block and now > hold.Started + Timeout["Value"] then
					watcher:Disconnect();
					hold.Release();
				end;
			end);
			AutoMatchDodge:Clean(watcher);
		end,
		["ExtraText"] = function(): string
			return hold.Dodging and 'Dodging' or 'Game loaded';
		end,
		["Tooltip"] = 'Holds you in the loading screen so you can dodge the match. Carries over into the next match.'
	});
	Mode = AutoMatchDodge:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Auto', 'Manual'},
		["Function"] = function(value: string): ()
			for _: number, option: table? in {Timeout, SkillCheck, RankCheck, PlayerCheck} do
				if option then
					option.Object.Visible = value == 'Auto';
				end;
			end;
		end
	});
	AutoMatchDodge:CreateButton({
		["Name"] = 'Load',
		["Function"] = hold.Release,
		["Tooltip"] = 'Loads this match now'
	});
	Timeout = AutoMatchDodge:CreateSlider({
		["Name"] = 'Load timeout',
		["Min"] = 1,
		["Max"] = 90,
		["Default"] = 45,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'sec' or 'secs';
		end,
		["Tooltip"] = 'Loads into the game after this long'
	});
	SkillCheck = AutoMatchDodge:CreateToggle({
		["Name"] = 'Skill check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Dodges when more than one opponent looks "better" than you (not 100% accurate)'
	});
	RankCheck = AutoMatchDodge:CreateToggle({
		["Name"] = 'Rank check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Only dodges in ranked queues, any other match just loads'
	});
	PlayerCheck = AutoMatchDodge:CreateToggle({
		["Name"] = 'Player check',
		["Darker"] = true,
		["Function"] = function(callback: boolean): ()
			if Teammates then
				Teammates.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Dodges when your team has fewer players than the biggest enemy team'
	});
	Teammates = AutoMatchDodge:CreateTextList({
		["Name"] = 'Players Whitelist',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Players that will always be on your team if they are in the server'
	});
	RegionLock = AutoMatchDodge:CreateToggle({
		["Name"] = 'Region lock',
		["Function"] = function(callback: boolean): ()
			if Regions then
				Regions.Object.Visible = callback;
			end;
			if not callback and hold.Block == 'RegionLock' then
				hold.Block = nil;
			end;
		end,
		["Tooltip"] = 'Dodges servers outside your selected regions'
	});
	Regions = AutoMatchDodge:CreateTextList({
		["Name"] = 'Regions',
		["Placeholder"] = 'NA / EU / AS / OCEANIA',
		["Default"] = {'NA', 'EU', 'AS', 'OCEANIA'},
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = function(): ()
			for _: number, list: {string} in (Regions and {Regions.List, Regions.ListEnabled} or {}) do
				for index: number, entry: string in list do
					list[index] = entry:gsub('%s+', ''):upper();
				end;
			end;
		end,
		["Tooltip"] = 'Turn off the regions you do not want. SG-03 counts as AS, AU/NZ as OCEANIA, US-CA as NA. Leaving every region on accepts anything'
	});
end);

velo.run(function(): ()
	local AutoPearl: table = {["Enabled"] = false};
	local VoidSave: table;
	local Aggro: table;
	local LegitSwitch: table;
	local SwitchBack: table;
	local LandCheck: table;
	local PearlCheck: table;
	local BackDelay: table;
	local LimitItem: table;
	local DistanceLimit: table;
	local MinHealth: table;
	local Cooldown: table;

	local fallVelocity: number = -98;
	local voidDepth: number = 60;
	local groundDepth: number = 300;
	local searchRadii: {number} = {0, 6, 12, 18, 24, 30, 36};
	local voidTolerance: number = 5;
	local aggroTolerance: number = 4;
	local followMinimum: number = 12;
	local flightStep: number = 0.05;
	local maxFlight: number = 4;
	local landTimeout: number = 10;
	local pearlBox: Vector3 = Vector3.new(3, 1, 3);
	local anchor: Vector3?;
	local fallHandled: boolean = false;
	local throwing: boolean = false;
	local inFlight: Instance?;
	local nextThrow: number = 0;

	local landingOf: (origin: Vector3, velocity: Vector3, gravity: number) -> Vector3? = function(origin: Vector3, velocity: Vector3, gravity: number): Vector3?
		local last: Vector3 = origin;
		for step: number = 1, math.round(maxFlight / flightStep) do
			local t: number = step * flightStep;
			local point: Vector3 = origin + velocity * t + Vector3.new(0, -0.5 * gravity * t * t, 0);
			local hit: RaycastResult? = workspace:Blockcast(CFrame.new(last), pearlBox, point - last, store.airRay);
			if hit then
				return last + (point - last).Unit * hit.Distance;
			end;
			last = point;
		end;
		return nil;
	end;

	local launchTo: (from: Vector3, spot: Vector3, tolerance: number) -> Vector3? = function(from: Vector3, spot: Vector3, tolerance: number): Vector3?
		local meta: table = bedwars.ProjectileMeta.telepearl;
		local speed: number, gravity: number = meta.launchVelocity, meta.gravitationalAcceleration or config.Gravity;
		local offset: Vector3 = spot - from;
		local flat: Vector3 = offset * Vector3.new(1, 0, 1);
		local candidates: {Vector3} = {};
		if flat.Magnitude < 1 then
			table.insert(candidates, Vector3.new(0, offset.Y < 0 and -speed or speed, 0));
		else
			local discriminant: number = speed ^ 4 - gravity * (gravity * flat.Magnitude ^ 2 + 2 * offset.Y * speed ^ 2);
			for _: number, sign: number in (discriminant >= 0 and {-1, 1} or {}) do
				local angle: number = math.atan((speed ^ 2 + sign * math.sqrt(discriminant)) / (gravity * flat.Magnitude));
				table.insert(candidates, flat.Unit * (math.cos(angle) * speed) + Vector3.new(0, math.sin(angle) * speed, 0));
			end;
		end;
		for _: number, velocity: Vector3 in candidates do
			local landing: Vector3? = landingOf(from, velocity, gravity);
			if landing and (landing - spot).Magnitude <= tolerance then
				return velocity;
			end;
		end;
		return nil;
	end;

	local voidThrow: (from: Vector3) -> Vector3? = function(from: Vector3): Vector3?
		for _: number, radius: number in searchRadii do
			for slice: number = 0, radius > 0 and 7 or 0 do
				local direction: Vector3 = Vector3.new(math.cos(slice * math.pi / 4), 0, math.sin(slice * math.pi / 4));
				local ground: RaycastResult? = workspace:Raycast(Vector3.new(from.X, anchor.Y + 3, from.Z) + direction * radius, Vector3.new(0, -groundDepth, 0), store.airRay);
				local velocity: Vector3? = ground and launchTo(from, ground.Position, voidTolerance);
				if velocity then
					return velocity;
				end;
			end;
		end;
		return nil;
	end;

	local pearlActive: () -> boolean = function(): boolean
		if inFlight and inFlight.Parent then
			return true;
		end;
		for _: number, projectile: Instance in store.selfProjectiles do
			if projectile.Name == 'telepearl' then
				return true;
			end;
		end;
		return false;
	end;

	local holdingPearl: () -> boolean = function(): boolean
		return store.hand.tool ~= nil and store.hand.tool.Name == 'telepearl';
	end;

	local throwPearl: (item: table, solve: (from: Vector3) -> Vector3?, rejected: (() -> ())?) -> () = function(item: table, solve: (from: Vector3) -> Vector3?, rejected: (() -> ())?): ()
		throwing = true;
		local previous: Instance? = store.hand.tool;
		local slot: number? = hotbarSlotOf(item.tool);
		switchItem(item.tool, 0);
		if LegitSwitch["Enabled"] and slot then
			hotbarSwitch(slot);
		end;
		task.wait(math.max(0.04, store.ping.total));
		local position: Vector3? = entitylib.isAlive and entitylib.character.RootPart.Position or nil;
		local velocity: Vector3? = position and solve(position);
		local projectile: Instance?;
		if position and velocity then
			local meta: table = bedwars.ProjectileMeta.telepearl;
			local shotId: string = bedwars.IdUtil.generateId(8);
			local shot: table = ballistics.shotData('telepearl');
			projectile = bedwars.ProjectileController:createLocalProjectile(meta, 'telepearl', 'telepearl', position, shotId, velocity, shot);
			inFlight = projectile;
			fire('ProjectileFire', 'CallServerAsync', item.tool, 'telepearl', 'telepearl', position, position, velocity, shotId, shot, workspace:GetServerTimeNow() - config.ShotLatency):andThen(function(result: any): ()
				if type(result) == 'table' and result.accepted then
					if not projectile and typeof(result.model) == 'Instance' then
						inFlight = result.model;
					elseif result.model then
						result.model.Parent = replicatedStorage;
					end;
				elseif rejected then
					rejected();
				end;
			end);
		elseif rejected then
			rejected();
		end;
		throwing = false;
		if not SwitchBack["Enabled"] or not previous then
			return;
		end;
		local switched: boolean = false;
		local restore: () -> () = function(): ()
			if switched then
				return;
			end;
			switched = true;
			task.delay(BackDelay:GetRandomValue(), function(): ()
				switchItem(previous);
				local previousSlot: number? = hotbarSlotOf(previous);
				if LegitSwitch["Enabled"] and previousSlot then
					hotbarSwitch(previousSlot);
				end;
			end);
		end;
		if LandCheck["Enabled"] and projectile and projectile.Parent then
			local landing: RBXScriptConnection;
			landing = projectile.AncestryChanged:Connect(function(): ()
				if not projectile.Parent then
					landing:Disconnect();
					restore();
				end;
			end);
			task.delay(landTimeout, restore);
		else
			restore();
		end;
	end;

	local onLaunch: (event: table) -> () = function(event: table): ()
		if event.projectileType ~= 'telepearl' or not entitylib.isAlive then
			return;
		end;
		if event.shooter == entitylib.character.Character then
			if typeof(event.projectile) == 'Instance' and event.projectile:IsA('PVInstance') then
				inFlight = event.projectile;
			end;
			return;
		end;
		if not Aggro["Enabled"] or not store.airRay or typeof(event.origin) ~= 'Vector3' or typeof(event.launchVelocity) ~= 'Vector3' then
			return;
		end;
		local shooter: table?;
		for _: number, ent: table in entitylib.List do
			if ent.Character == event.shooter then
				shooter = ent;
				break;
			end;
		end;
		if not shooter or not shooter.Targetable then
			return;
		end;
		local meta: table = bedwars.ProjectileMeta.telepearl;
		local spot: Vector3? = landingOf(event.origin, event.launchVelocity, meta.gravitationalAcceleration or config.Gravity);
		local position: Vector3 = entitylib.character.RootPart.Position;
		local gap: number = spot and (spot - position).Magnitude or math.huge;
		if not spot or gap > DistanceLimit["Value"] or gap < followMinimum or gap < (event.origin - position).Magnitude then
			return;
		end;
		if tick() < nextThrow or throwing or (PearlCheck["Enabled"] and pearlActive()) or (LimitItem["Enabled"] and not holdingPearl()) then
			return;
		end;
		if MinHealth["Value"] > 0 and entitylib.character.Health < MinHealth["Value"] then
			return;
		end;
		local item: table? = getItem('telepearl');
		if not item or not launchTo(position, spot, aggroTolerance) then
			return;
		end;
		local previousThrow: number = nextThrow;
		local reserved: number = tick() + Cooldown["Value"];
		nextThrow = reserved;
		task.spawn(throwPearl, item, function(from: Vector3): Vector3?
			return launchTo(from, spot, aggroTolerance);
		end, function(): ()
			if nextThrow == reserved then
				nextThrow = previousThrow;
			end;
		end);
	end;

	AutoPearl = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoPearl',
		["Function"] = function(callback: boolean): ()
			if not callback then
				anchor, inFlight, fallHandled = nil, nil, false;
				return;
			end;
			local launches: table = bedwars.SyncEvents.ProjectileLaunched:connect(onLaunch);
			AutoPearl:Clean(function(): ()
				launches:Destroy();
			end);
			AutoPearl:Clean(runService.Heartbeat:Connect(function(): ()
				if not VoidSave["Enabled"] or throwing or not entitylib.isAlive or not store.airRay or (LimitItem["Enabled"] and not holdingPearl()) then
					return;
				end;
				local root: BasePart = entitylib.character.RootPart;
				if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
					anchor = root.Position;
				end;
				if not anchor or root.AssemblyLinearVelocity.Y > fallVelocity or workspace:Raycast(root.Position, Vector3.new(0, -voidDepth, 0), store.airRay) then
					fallHandled = false;
					return;
				end;
				if fallHandled then
					return;
				end;
				fallHandled = true;
				local item: table? = getItem('telepearl');
				if item and not (PearlCheck["Enabled"] and pearlActive()) and voidThrow(root.Position) then
					throwPearl(item, voidThrow, nil);
				end;
			end));
		end,
		["Tooltip"] = 'Pearls you back to ground when falling into the void, and can follow enemy pearls to where they land.'
	});
	VoidSave = AutoPearl:CreateToggle({
		["Name"] = 'Void save',
		["Default"] = true,
		["Tooltip"] = 'Throws a pearl onto nearby ground after falling toward the void'
	});
	Aggro = AutoPearl:CreateToggle({
		["Name"] = 'Aggro',
		["Function"] = function(callback: boolean): ()
			for _: number, option: table? in {DistanceLimit, MinHealth, Cooldown} do
				if option then
					option.Object.Visible = callback;
				end;
			end;
		end,
		["Tooltip"] = 'Predicts where an enemy pearl lands the moment it is thrown and pearls you to the same spot.\nPearls into the void, closer to you than the thrower, or out of reach are ignored'
	});
	DistanceLimit = AutoPearl:CreateSlider({
		["Name"] = 'Distance limit',
		["Min"] = 10,
		["Max"] = 200,
		["Default"] = 150,
		["Suffix"] = 'studs',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'How far away an enemy pearl can land before it is ignored'
	});
	MinHealth = AutoPearl:CreateSlider({
		["Name"] = 'Min health',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 0,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Never follows a pearl below this health, 0 disables the check'
	});
	Cooldown = AutoPearl:CreateSlider({
		["Name"] = 'Cooldown',
		["Min"] = 0,
		["Max"] = 5,
		["Default"] = 1,
		["Decimal"] = 10,
		["Suffix"] = 'seconds',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Minimum gap between two followed pearls'
	});
	LegitSwitch = AutoPearl:CreateToggle({
		["Name"] = 'Legit Switch',
		["Default"] = true,
		["Tooltip"] = 'Shows the hotbar switch clientside'
	});
	SwitchBack = AutoPearl:CreateToggle({
		["Name"] = 'Switch back',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			for _: number, option: table? in {BackDelay, LandCheck} do
				if option then
					option.Object.Visible = callback;
				end;
			end;
		end,
		["Tooltip"] = 'Switches back to what you held before the pearl'
	});
	LandCheck = AutoPearl:CreateToggle({
		["Name"] = 'Only after landed',
		["Darker"] = true,
		["Tooltip"] = 'Only switches back once your pearl landed'
	});
	BackDelay = AutoPearl:CreateTwoSlider({
		["Name"] = 'Switch Back Delay',
		["Min"] = 0,
		["Max"] = 2,
		["DefaultMin"] = 0.1,
		["DefaultMax"] = 0.2,
		["Darker"] = true
	});
	PearlCheck = AutoPearl:CreateToggle({
		["Name"] = 'Pearl check',
		["Default"] = true,
		["Tooltip"] = 'Does not throw while one of your pearls is still in the air'
	});
	LimitItem = AutoPearl:CreateToggle({
		["Name"] = 'Limit to item',
		["Tooltip"] = 'Only throws while holding a pearl'
	});
end);

velo.run(function(): ()
	local Scaffold: table = {["Enabled"] = false};
	local Expand: table;
	local Tower: table;
	local Downwards: table;
	local Diagonal: table;
	local LimitItem: table;
	local MouseDown: table;
	local FillColor: table;
	local OutlineColor: table;
	local HudPosition: table;
	local BlockUp: table;
	local ReturnSlot: table;
	local Center: table;
	local Blacklist: table;

	local bridgeInterval: number = 0.03;
	local towerVelocity: number = 38;
	local towerMinHealth: number = 8;
	local towerGate: number = 0.15;
	local towerRepeat: number = 0.5;
	local towerCooldown: number = 0.2;
	local towerGrace: number = 0.25;
	local proximityReach: Vector3 = Vector3.new(21, 21, 21);
	local raise: Vector3 = Vector3.new(0, 3, 0);
	local anchorFaces: {Vector3} = {Vector3.new(0, -3, 0), Vector3.new(3, 0, 0), Vector3.new(-3, 0, 0), Vector3.new(0, 0, 3), Vector3.new(0, 0, -3)};
	local neighbours: {Vector3} = {};
	for x: number = -3, 3, 3 do
		for y: number = -3, 3, 3 do
			for z: number = -3, 3, 3 do
				if x ~= 0 or y ~= 0 or z ~= 0 then
					table.insert(neighbours, Vector3.new(x, y, z));
				end;
			end;
		end;
	end;
	local clickGui: Frame = vape.gui.ScaledGui.ClickGui;
	local lastCell: Vector3 = Vector3.zero;
	local nextBridge: number = 0;
	local preview: Part?;
	local previewTween: Tween?;
	local previewCell: Vector3?;
	local hud: table?;
	local tower: table = {["Started"] = false, ["Held"] = false, ["LastPlace"] = 0, ["Cooldown"] = 0};

	local pickBlock: (towering: boolean) -> (string?, number, number?) = function(towering: boolean): (string?, number, number?)
		local blacklisted: (itemType: string) -> boolean = function(itemType: string): boolean
			return table.find(Blacklist.ListEnabled, itemType) ~= nil or (itemType:find('wool') ~= nil and table.find(Blacklist.ListEnabled, 'wool') ~= nil);
		end;
		local hand: table = store.hand;
		if hand.toolType == 'block' and hand.tool and (hand.amount or 0) > 0 and not blacklisted(hand.tool.Name) then
			return hand.tool.Name, hand.amount, nil;
		end;
		if LimitItem["Enabled"] then
			return nil, 0, nil;
		end;
		local best: table?, bestSlot: number?, bestRank: number, bestHealth: number = nil, nil, math.huge, math.huge;
		for _: number, item: table in store.inventory.inventory.items do
			local block: table? = bedwars.ItemMeta[item.itemType] and bedwars.ItemMeta[item.itemType].block;
			if block and (item.amount or 0) > 0 and not blacklisted(item.itemType) and (not towering or (block.health or 0) >= towerMinHealth) then
				local slot: number? = hotbarSlotOf(item.tool);
				local rank: number = (towering and not slot and 2 or 0) + (item.itemType:find('wool') and 0 or 1);
				if rank < bestRank or (rank == bestRank and (block.health or 0) < bestHealth) then
					best, bestSlot, bestRank, bestHealth = item, slot, rank, block.health or 0;
				end;
			end;
		end;
		return best and best.itemType, best and best.amount or 0, bestSlot;
	end;

	local supportFor: (position: Vector3, cell: Vector3) -> Vector3? = function(position: Vector3, cell: Vector3): Vector3?
		for _: number, offset: Vector3 in neighbours do
			if getPlacedBlock(cell + offset) then
				return cell;
			end;
		end;
		local best: Vector3?, bestDistance: number = nil, 60;
		local from: Vector3 = bedwars.BlockController:getBlockPosition(position - proximityReach);
		local to: Vector3 = bedwars.BlockController:getBlockPosition(position + proximityReach);
		for _: number, block: Vector3 in getBlocksInPoints(from, to) do
			local reach: Vector3 = block + (position - block).Unit * 100;
			local corner: Vector3 = Vector3.new(math.clamp(reach.X, block.X - 3, block.X + 3), math.clamp(reach.Y, block.Y - 3, block.Y + 3), math.clamp(reach.Z, block.Z - 3, block.Z + 3));
			if (position - corner).Magnitude < bestDistance then
				best, bestDistance = corner, (position - corner).Magnitude;
			end;
		end;
		return best;
	end;

	local hudOffset: () -> UDim2 = function(): UDim2
		local x: string?, y: string? = HudPosition["Value"]:match('^(%-?%d+),(%-?%d+)$');
		return UDim2.new(0.5, tonumber(x) or 0, 0.5, tonumber(y) or 60);
	end;

	local updateHud: (block: string?, count: number) -> () = function(block: string?, count: number): ()
		local now: number = os.clock();
		local delta: number = math.max(now - hud.Clock, 0.001);
		if block ~= hud.Block then
			hud.Block, hud.Peak, hud.Last = block, 0, count;
			hud.Icon.Image = block and bedwars.getIcon({["itemType"] = block}, true) or '';
		end;
		hud.Speed += (math.max(hud.Last - count, 0) / delta - hud.Speed) * math.min(delta * 0.5, 1);
		hud.Peak, hud.Last, hud.Clock = math.max(hud.Peak, count), count, now;
		local accent: Color3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value);
		hud.Badge.BackgroundColor3, hud.Trail.BackgroundColor3, hud.Fill.BackgroundColor3 = accent, accent, accent;
		local ratio: number = hud.Peak > 0 and count / hud.Peak or 0;
		if ratio ~= hud.Ratio then
			local draining: boolean = ratio < hud.Ratio;
			hud.Ratio = ratio;
			for _: number, running: Tween in hud.Tweens do
				running:Cancel();
			end;
			hud.Tweens = {
				tweenService:Create(hud.Fill, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {["Size"] = UDim2.fromScale(ratio, 1)}),
				tweenService:Create(hud.Trail, TweenInfo.new(draining and 0.45 or 0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, 0, false, draining and 0.2 or 0), {["Size"] = UDim2.fromScale(ratio, 1)})
			};
			for _: number, running: Tween in hud.Tweens do
				running:Play();
			end;
		end;
		hud.Count.Text = '<font color="#'..accent:ToHex()..'">'..count..'</font> '..(count == 1 and 'block' or 'blocks');
		hud.Rate.Text = string.format('%.1f b/s', hud.Speed);
		local width: number = 228 + math.ceil(math.max(hud.Count.TextBounds.X, hud.Rate.TextBounds.X));
		if hud.Frame.Size.X.Offset ~= width then
			hud.Frame.Size = UDim2.fromOffset(width, 44);
		end;
	end;

	local refreshHud: () -> () = function(): ()
		if not hud then
			return;
		end;
		hud.Frame.Visible = Scaffold["Enabled"] or clickGui.Visible;
		if hud.Frame.Visible and not Scaffold["Enabled"] then
			local block: string?, count: number = pickBlock(false);
			updateHud(block, count);
		end;
	end;

	local destroyHud: () -> () = function(): ()
		if hud then
			hud.Connection:Disconnect();
			hud.Frame:Destroy();
			hud = nil;
		end;
	end;

	local buildHud: () -> () = function(): ()
		local make: (className: string, parent: Instance, props: {[string]: any}, rounded: boolean?) -> any = function(className: string, parent: Instance, props: {[string]: any}, rounded: boolean?): any
			local object: any = Instance.new(className);
			for property: string, value: any in props do
				object[property] = value;
			end;
			if rounded then
				Instance.new('UICorner', object).CornerRadius = UDim.new(1, 0);
			end;
			object.Parent = parent;
			return object;
		end;
		local frame: Frame = make('Frame', vape.gui, {["Size"] = UDim2.fromOffset(300, 44), ["Position"] = hudOffset(), ["AnchorPoint"] = Vector2.new(0.5, 0), ["BackgroundColor3"] = Color3.fromRGB(22, 22, 26), ["BackgroundTransparency"] = 0.45, ["BorderSizePixel"] = 0}, true);
		local badge: Frame = make('Frame', frame, {["Size"] = UDim2.fromOffset(32, 32), ["Position"] = UDim2.new(0, 6, 0.5, 0), ["AnchorPoint"] = Vector2.new(0, 0.5), ["BackgroundTransparency"] = 0.7, ["BorderSizePixel"] = 0}, true);
		local track: Frame = make('Frame', frame, {["Size"] = UDim2.fromOffset(150, 4), ["Position"] = UDim2.new(0, 48, 0.5, 0), ["AnchorPoint"] = Vector2.new(0, 0.5), ["BackgroundColor3"] = Color3.new(1, 1, 1), ["BackgroundTransparency"] = 0.85, ["BorderSizePixel"] = 0}, true);
		hud = {
			["Frame"] = frame,
			["Badge"] = badge,
			["Icon"] = make('ImageLabel', badge, {["Size"] = UDim2.fromOffset(22, 22), ["Position"] = UDim2.fromScale(0.5, 0.5), ["AnchorPoint"] = Vector2.new(0.5, 0.5), ["BackgroundTransparency"] = 1}),
			["Trail"] = make('Frame', track, {["Size"] = UDim2.fromScale(0, 1), ["BackgroundTransparency"] = 0.6, ["BorderSizePixel"] = 0}, true),
			["Fill"] = make('Frame', track, {["Size"] = UDim2.fromScale(0, 1), ["ZIndex"] = 2, ["BorderSizePixel"] = 0}, true),
			["Count"] = make('TextLabel', frame, {["Size"] = UDim2.fromOffset(100, 22), ["Position"] = UDim2.fromOffset(214, 9), ["BackgroundTransparency"] = 1, ["Text"] = '0 blocks', ["TextColor3"] = Color3.new(1, 1, 1), ["TextSize"] = 16, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["RichText"] = true, ["FontFace"] = uipallet.Font}),
			["Rate"] = make('TextLabel', frame, {["Size"] = UDim2.fromOffset(100, 15), ["Position"] = UDim2.fromOffset(214, 25), ["BackgroundTransparency"] = 1, ["Text"] = '0.0 b/s', ["TextColor3"] = Color3.fromRGB(150, 150, 158), ["TextSize"] = 12, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["FontFace"] = uipallet.Font}),
			["Tweens"] = {},
			["Ratio"] = 0,
			["Peak"] = 0,
			["Last"] = 0,
			["Speed"] = 0,
			["Clock"] = os.clock(),
			["Connection"] = clickGui:GetPropertyChangedSignal('Visible'):Connect(refreshHud)
		};
		frame.InputBegan:Connect(function(input: InputObject): ()
			if not clickGui.Visible or (input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch) then
				return;
			end;
			local start: Vector3 = input.Position;
			local origin: UDim2 = frame.Position;
			local moveType: Enum.UserInputType = input.UserInputType == Enum.UserInputType.Touch and Enum.UserInputType.Touch or Enum.UserInputType.MouseMovement;
			local moving: RBXScriptConnection = inputService.InputChanged:Connect(function(change: InputObject): ()
				if change.UserInputType == moveType then
					local viewport: Vector2 = gameCamera.ViewportSize;
					local limitX: number = (viewport.X - frame.AbsoluteSize.X) / 2;
					frame.Position = UDim2.new(0.5, math.clamp(origin.X.Offset + change.Position.X - start.X, -limitX, limitX), 0.5, math.clamp(origin.Y.Offset + change.Position.Y - start.Y, -viewport.Y / 2, viewport.Y / 2 - frame.AbsoluteSize.Y));
				end;
			end);
			local released: RBXScriptConnection;
			released = input.Changed:Connect(function(): ()
				if input.UserInputState == Enum.UserInputState.End then
					moving:Disconnect();
					released:Disconnect();
					HudPosition:SetValue(math.round(frame.Position.X.Offset)..','..math.round(frame.Position.Y.Offset));
				end;
			end);
		end);
		refreshHud();
	end;
	vape:Clean(destroyHud);

	local warnOnce: (text: string) -> () = function(text: string): ()
		if tower.Warned ~= text then
			tower.Warned = text;
			notif('Scaffold', text, 3, 'warning');
		end;
	end;

	local suppressJump: (enable: boolean) -> () = function(enable: boolean): ()
		if enable then
			if tower.Humanoid or not entitylib.isAlive then
				return;
			end;
			tower.Humanoid = entitylib.character.Humanoid;
			tower.JumpHeight = tower.Humanoid.JumpHeight;
			tower.Humanoid.JumpHeight = 0;
			return;
		end;
		if tower.Humanoid and tower.JumpHeight and tower.Humanoid.JumpHeight == 0 then
			tower.Humanoid.JumpHeight = tower.JumpHeight;
		end;
		tower.Humanoid, tower.JumpHeight = nil, nil;
	end;

	local stopTower: () -> () = function(): ()
		if ReturnSlot["Enabled"] and tower.Previous and tower.Equipped == store.inventory.hotbarSlot and entitylib.isAlive then
			task.defer(hotbarSwitch, tower.Previous);
		end;
		suppressJump(false);
		tower.Started, tower.Warned, tower.Previous, tower.Equipped, tower.LostAt = false, nil, nil, nil, nil;
		tower.Cooldown = os.clock() + towerCooldown;
	end;

	local towerTarget: () -> (Vector3?, string?, string?) = function(): (Vector3?, string?, string?)
		local position: Vector3 = entitylib.character.RootPart.Position;
		local feet: number = position.Y - entitylib.character.HipHeight;
		local target: Vector3 = roundPos(Vector3.new(position.X, feet - 1.5, position.Z));
		for _: number = 1, 3 do
			if target.Y - 1.5 > feet + 3 or not getPlacedBlock(target) then
				break;
			end;
			target += raise;
		end;
		if target.Y - 1.5 > feet + 3 or getPlacedBlock(target + raise) or getPlacedBlock(target + raise * 2) then
			return nil, nil, nil;
		end;
		local anchored: boolean = false;
		for _: number, face: Vector3 in anchorFaces do
			anchored = anchored or getPlacedBlock(target + face) ~= nil;
		end;
		if not anchored then
			return nil, nil, nil;
		end;
		local itemType: string? = pickBlock(true);
		if not itemType then
			return nil, nil, 'No blocks to place';
		end;
		local map: table? = bedwars.MapController;
		local cell: Vector3 = bedwars.BlockController:getBlockPosition(target);
		if lplr:GetAttribute('DenyBlockPlace') or (map and ((type(map.isInDenyRegion) == 'function' and map:isInDenyRegion(cell)) or (type(map.isOutOfBounds) == 'function' and map:isOutOfBounds(cell)))) then
			return nil, nil, "Can't place blocks here";
		end;
		return target, itemType, nil;
	end;

	local towerStep: () -> () = function(): ()
		if not entitylib.isAlive then
			suppressJump(false);
			tower.Started, tower.Warned, tower.Previous, tower.Equipped, tower.LostAt = false, nil, nil, nil, nil;
			return;
		end;
		local jumpMode: boolean = BlockUp["Value"] == 'Holding jump';
		if jumpMode and not tower.Held then
			if tower.Started or tower.Humanoid then
				stopTower();
			end;
			return;
		end;
		if not tower.Started then
			if os.clock() < tower.Cooldown or (jumpMode and not towerTarget()) then
				return;
			end;
			tower.Started = true;
			local itemType: string?, _: number, slot: number? = pickBlock(true);
			if not itemType then
				warnOnce('No blocks to place');
			elseif slot and slot ~= store.inventory.hotbarSlot then
				tower.Previous, tower.Equipped = store.inventory.hotbarSlot, slot;
				task.defer(hotbarSwitch, slot);
			end;
			if jumpMode then
				suppressJump(true);
			end;
		end;
		local root: BasePart = entitylib.character.RootPart;
		local humanoid: Humanoid = entitylib.character.Humanoid;
		if Center["Enabled"] and humanoid.MoveDirection.Magnitude < 0.1 and humanoid.FloorMaterial ~= Enum.Material.Air and isnetworkowner(root) then
			local middle: Vector3 = roundPos(root.Position);
			if math.abs(middle.X - root.Position.X) > 0.05 or math.abs(middle.Z - root.Position.Z) > 0.05 then
				root.CFrame = CFrame.new(middle.X, root.Position.Y, middle.Z) * root.CFrame.Rotation;
			end;
		end;
		local now: number = workspace:GetServerTimeNow();
		local placeDelay: number = 1 / math.max(bedwars.SharedConstants.BLOCK_PLACE_CPS, 1);
		if now - math.max(tower.LastPlace, bedwars.BlockCpsController.lastPlaceTimestamp) < placeDelay or not canPlace() then
			return;
		end;
		local target: Vector3?, itemType: string?, reason: string? = towerTarget();
		if jumpMode then
			if target then
				tower.LostAt = nil;
				suppressJump(true);
			else
				tower.LostAt = tower.LostAt or os.clock();
				if os.clock() - tower.LostAt >= towerGrace then
					suppressJump(false);
				end;
			end;
		elseif reason then
			warnOnce(reason);
		end;
		if not target or target.Y - 1.5 > root.Position.Y - entitylib.character.HipHeight + towerGate or (target == tower.LastTarget and now - tower.LastPlace < towerRepeat) then
			return;
		end;
		tower.Warned = nil;
		tower.LastPlace, tower.LastTarget = now, target;
		task.defer(placeBlock, target, itemType);
	end;

	local bridgeStep: () -> () = function(): ()
		local held: string?, amount: number = pickBlock(false);
		if hud then
			updateHud(held, amount);
		end;
		local itemType: string? = held;
		if (MouseDown["Enabled"] and not inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)) or BlockUp["Value"] == 'When enabled' then
			itemType = nil;
		end;
		if not itemType then
			return;
		end;
		local root: BasePart = entitylib.character.RootPart;
		local humanoid: Humanoid = entitylib.character.Humanoid;
		if Tower["Enabled"] and BlockUp["Value"] == 'Off' and inputService:IsKeyDown(Enum.KeyCode.Space) and not inputService:GetFocusedTextBox() then
			root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, towerVelocity, root.AssemblyLinearVelocity.Z);
		end;
		local drop: number = entitylib.character.HipHeight + (Downwards["Enabled"] and inputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5);
		for step: number = Expand["Value"], 1, -1 do
			local cell: Vector3 = roundPos(root.Position - Vector3.new(0, drop, 0) + humanoid.MoveDirection * (step * 3));
			if Diagonal["Enabled"] and math.abs(math.round(math.deg(math.atan2(-humanoid.MoveDirection.X, -humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
				local delta: Vector3 = lastCell - cell;
				if ((delta.X == 0 and delta.Z ~= 0) or (delta.X ~= 0 and delta.Z == 0)) and ((lastCell - root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
					cell = lastCell;
				end;
			end;
			if preview then
				local shown: Vector3 = bedwars.BlockController:getBlockPosition(cell) * 3;
				if previewCell ~= shown then
					if previewTween then
						previewTween:Cancel();
					end;
					if preview.Parent == gameCamera then
						previewTween = tweenService:Create(preview, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {["CFrame"] = CFrame.new(shown)});
						previewTween:Play();
					else
						preview.CFrame = CFrame.new(shown);
						preview.Parent = gameCamera;
					end;
					previewCell = shown;
				end;
			end;
			local block: Instance?, blockCell: Vector3? = getPlacedBlock(cell);
			local spot: Vector3? = not block and supportFor(cell, blockCell * 3) or nil;
			if spot then
				task.defer(placeBlock, spot, itemType);
			end;
			lastCell = cell;
		end;
	end;

	local setHeld: (down: boolean) -> () = function(down: boolean): ()
		tower.Held = down;
		if down and BlockUp["Value"] == 'Holding jump' and entitylib.isAlive and towerTarget() then
			suppressJump(true);
		end;
	end;

	Scaffold = vape.Categories.Utility:CreateModule({
		["Name"] = 'Scaffold',
		["Function"] = function(callback: boolean): ()
			refreshHud();
			if not callback then
				stopTower();
				if previewTween then
					previewTween:Cancel();
					previewTween = nil;
				end;
				if preview then
					preview.Parent = nil;
				end;
				previewCell = nil;
				return;
			end;
			if not vape.Loaded and BlockUp["Value"] == 'When enabled' then
				task.defer(function(): ()
					if Scaffold["Enabled"] then
						Scaffold:Toggle();
					end;
				end);
				return;
			end;
			if hud then
				hud.Block, hud.Speed = nil, 0;
			end;
			tower.Started, tower.Warned, tower.Previous, tower.Equipped, tower.LostAt, tower.LastPlace, tower.Cooldown = false, nil, nil, nil, nil, 0, 0;
			setHeld(not inputService:GetFocusedTextBox() and inputService:IsKeyDown(Enum.KeyCode.Space));
			Scaffold:Clean(inputService.InputBegan:Connect(function(input: InputObject): ()
				if not inputService:GetFocusedTextBox() and (input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA) then
					setHeld(true);
				end;
			end));
			Scaffold:Clean(inputService.InputEnded:Connect(function(input: InputObject): ()
				if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
					setHeld(false);
				end;
			end));
			local touchGui: Instance? = inputService.TouchEnabled and lplr.PlayerGui:FindFirstChild('TouchGui') or nil;
			local jumpButton: Instance? = touchGui and touchGui:FindFirstChild('JumpButton', true);
			if jumpButton then
				Scaffold:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function(): ()
					setHeld(jumpButton.ImageRectOffset.X == 146);
				end));
			end;
			Scaffold:Clean(runService.Heartbeat:Connect(function(): ()
				if BlockUp["Value"] ~= 'Off' then
					towerStep();
				end;
				local now: number = os.clock();
				if now < nextBridge or not entitylib.isAlive then
					return;
				end;
				nextBridge = now + bridgeInterval;
				bridgeStep();
			end));
		end,
		["Tooltip"] = 'Helps you bridge and scaffold walk, and can tower straight up under you.'
	});
	Expand = Scaffold:CreateSlider({
		["Name"] = 'Expand',
		["Min"] = 1,
		["Max"] = 6
	});
	Tower = Scaffold:CreateToggle({
		["Name"] = 'Tower',
		["Default"] = true,
		["Tooltip"] = 'Boosts you upward while holding jump (when Block up is off)'
	});
	Downwards = Scaffold:CreateToggle({
		["Name"] = 'Downwards',
		["Default"] = true
	});
	Diagonal = Scaffold:CreateToggle({
		["Name"] = 'Diagonal',
		["Default"] = true
	});
	LimitItem = Scaffold:CreateToggle({
		["Name"] = 'Limit to items',
		["Tooltip"] = 'Only places the block in your hand, never switches or digs through your inventory'
	});
	MouseDown = Scaffold:CreateToggle({
		["Name"] = 'Require mouse down'
	});
	BlockUp = Scaffold:CreateDropdown({
		["Name"] = 'Block up',
		["List"] = {'Off', 'Holding jump', 'When enabled'},
		["Function"] = function(value: string): ()
			if tower.Started then
				stopTower();
			end;
			for _: number, option: table? in {ReturnSlot, Center} do
				if option then
					option.Object.Visible = value ~= 'Off';
				end;
			end;
		end,
		["Tooltip"] = 'Equips blocks and towers under you as fast as the game allows.\nHolding jump: builds while you hold jump and there is room, cancelling that jump.\nWhen enabled: towers whenever Scaffold is on instead of bridging (best with a hold bind)'
	});
	ReturnSlot = Scaffold:CreateToggle({
		["Name"] = 'Return to last slot',
		["Default"] = true,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Switches back to what you were holding when towering stops'
	});
	Center = Scaffold:CreateToggle({
		["Name"] = 'Center',
		["Default"] = true,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Keeps you in the middle of your block while standing still so the tower stays one block wide'
	});
	Blacklist = Scaffold:CreateTextList({
		["Name"] = 'Blacklist',
		["Default"] = {'ballista', 'cannon', 'siege_tnt', 'tnt'},
		["Tooltip"] = 'Block types it will never place'
	});
	Scaffold:CreateToggle({
		["Name"] = 'Visual',
		["Function"] = function(callback: boolean): ()
			for _: number, option: table? in {FillColor, OutlineColor} do
				if option then
					option.Object.Visible = callback;
				end;
			end;
			if previewTween then
				previewTween:Cancel();
				previewTween = nil;
			end;
			if preview then
				preview:Destroy();
				preview, previewCell = nil, nil;
			end;
			if not callback then
				return;
			end;
			local part: Part = Instance.new('Part');
			part.Size = Vector3.new(3, 3, 3);
			part.Anchored = true;
			part.CanCollide = false;
			part.CanQuery = false;
			part.CanTouch = false;
			part.CastShadow = false;
			part.Transparency = 1;
			local selection: SelectionBox = Instance.new('SelectionBox');
			selection.Adornee = part;
			selection.LineThickness = 0.04;
			selection.Color3 = Color3.fromHSV(OutlineColor["Hue"], OutlineColor["Sat"], OutlineColor["Value"]);
			selection.Transparency = 1 - OutlineColor["Opacity"];
			selection.SurfaceColor3 = Color3.fromHSV(FillColor["Hue"], FillColor["Sat"], FillColor["Value"]);
			selection.SurfaceTransparency = 1 - FillColor["Opacity"];
			selection.Parent = part;
			bedwars.QueryUtil:setQueryIgnored(part, true);
			preview = part;
		end,
		["Tooltip"] = 'Outlines the block about to be placed'
	});
	FillColor = Scaffold:CreateColorSlider({
		["Name"] = 'Fill Color',
		["DefaultSat"] = 0,
		["DefaultOpacity"] = 0.4,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = function(hue: number, sat: number, val: number, opacity: number): ()
			if preview then
				preview.SelectionBox.SurfaceColor3 = Color3.fromHSV(hue, sat, val);
				preview.SelectionBox.SurfaceTransparency = 1 - opacity;
			end;
		end
	});
	OutlineColor = Scaffold:CreateColorSlider({
		["Name"] = 'Outline Color',
		["DefaultValue"] = 0,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = function(hue: number, sat: number, val: number, opacity: number): ()
			if preview then
				preview.SelectionBox.Color3 = Color3.fromHSV(hue, sat, val);
				preview.SelectionBox.Transparency = 1 - opacity;
			end;
		end
	});
	Scaffold:CreateToggle({
		["Name"] = 'Block Count',
		["Function"] = function(callback: boolean): ()
			destroyHud();
			if callback then
				buildHud();
			end;
		end,
		["Tooltip"] = 'Shows your block count and placement rate. Open the menu and drag it to move it'
	});
	HudPosition = Scaffold:CreateTextBox({
		["Name"] = 'HUD Position',
		["Default"] = '0,60',
		["Visible"] = false,
		["Function"] = function(): ()
			if hud then
				hud.Frame.Position = hudOffset();
			end;
		end
	});
end);

velo.run(function(): ()
	local Nuker: table = {["Enabled"] = false};
	local AutoBreak: table = {["Enabled"] = true};
	local Mode: table = {["Value"] = 'Health'};
	local ClosestBreak: table = {["Enabled"] = false};
	local Range: table = {["Value"] = 30};
	local BreakSpeed: table = {["Value"] = 0.25};
	local UpdateRate: table = {["Value"] = 60};
	local Custom: table = {["ListEnabled"] = {}};
	local Bed: table = {["Enabled"] = true};
	local Tesla: table = {["Enabled"] = true};
	local Hive: table = {["Enabled"] = true};
	local LuckyBlock: table = {["Enabled"] = true};
	local IronOre: table = {["Enabled"] = true};
	local Effect: table = {["Enabled"] = true};
	local CustomHealth: table = {["Enabled"] = true};
	local Animation: table = {["Value"] = 'No Animation'};
	local SelfBreak: table = {["Enabled"] = false};
	local Wallcheck: table = {["Enabled"] = true};
	local ViewAngle: table = {["Value"] = 60};
	local AutoTool: table = {["Enabled"] = false};
	local SwitchDelay: table = {};
	local LimitItem: table = {["Enabled"] = false};
	local PlayerCheck: table = {["Enabled"] = false};
	local FastBreak: table = {["Enabled"] = false};
	local BedCheck: table = {["Enabled"] = false};
	local HiveCheck: table = {["Enabled"] = false};
	local UseBlacklist: table = {["Enabled"] = false};
	local Blacklist: table = {["ListEnabled"] = {}};
	local BedAssist: table = {["Enabled"] = false};
	local AssistCurve: table = {["Value"] = 'Simple'};
	local AssistAim: table = {["Value"] = 'Camera'};
	local AssistSpeed: table = {["Value"] = 7};
	local AssistRange: table = {["Value"] = 18};
	local AssistShake: table = {["Value"] = 3};
	local AutoMine: table = {["Enabled"] = true};
	local MineBed: table = {["Enabled"] = true};
	local PhaseMine: table = {["Enabled"] = false};

	local legitCooldown: number = 0.3;
	local pathLength: number = 30;
	local healthbarLifetime: number = 5;
	local assistSearchInterval: number = 0.15;
	local assistDepthRadius: number = 18;
	local aimOffsets: {Vector3} = {Vector3.zero, Vector3.xAxis * 1.35, -Vector3.xAxis * 1.35, Vector3.yAxis * 1.35, -Vector3.yAxis * 1.35, Vector3.zAxis * 1.35, -Vector3.zAxis * 1.35};
	local pathColors: {[string]: Color3} = {["Target"] = Color3.new(1, 0.2, 0.2), ["Hit"] = Color3.new(0.2, 0.2, 1), ["Path"] = Color3.new(0.2, 1, 0.2)};

	local customBlocks: {Instance} = {};
	local blacklistNames: {string} = {};
	local pathParts: {BasePart} = {};
	local activeBlock: Instance? = nil;
	local pathShown: boolean = false;
	local nextBreak: number = 0;
	local fastActive: boolean = false;
	local healthbar: table = {};
	local phased: {[Model]: table} = {};
	local shield: (block: Instance) -> boolean = function(block: Instance): boolean
		return (block:GetAttribute('BedShieldEndTime') or 0) > workspace:GetServerTimeNow();
	end;
	local ownTeamNoBreak: (block: Instance) -> boolean = function(block: Instance): boolean
		return block:GetAttribute('Team'..(lplr:GetAttribute('Team') or -1)..'NoBreak') ~= nil;
	end;
	local holdingBreaker: () -> boolean = function(): boolean
		local meta: table? = store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name];
		return meta ~= nil and meta.breakBlock ~= nil;
	end;

	local showPath: (position: Vector3?, path: {[Vector3]: Vector3}?, target: Vector3?) -> () = function(position: Vector3?, path: {[Vector3]: Vector3}?, target: Vector3?): ()
		if not position and not pathShown then
			return;
		end;
		pathShown = position ~= nil;
		local node: Vector3? = position;
		for _: number, part: BasePart in pathParts do
			part.Position = node or Vector3.zero;
			if node then
				part.BoxHandleAdornment.Color3 = node == target and pathColors.Target or node == position and pathColors.Hit or pathColors.Path;
			end;
			node = node and path and path[node];
		end;
	end;

	local drawHealthbar: (_: table, blockRef: table, health: number, maxHealth: number?, change: number, block: Instance) -> () = function(_: table, blockRef: table, health: number, maxHealth: number?, change: number, block: Instance): ()
		if block:GetAttribute('NoHealthbar') then
			return;
		end;
		local maximum: number = maxHealth or math.max(health, 1);
		if healthbar.Cell ~= blockRef.blockPosition then
			if healthbar.Anchor then
				healthbar.Anchor:Destroy();
			end;
			local anchor: Attachment = Instance.new('Attachment');
			anchor.WorldPosition = bedwars.BlockController:getWorldPosition(blockRef.blockPosition);
			anchor.Parent = workspace.Terrain;
			local gui: BillboardGui = Instance.new('BillboardGui');
			gui.Size = UDim2.fromOffset(160, 50);
			gui.StudsOffset = Vector3.new(0, 2.5, 0);
			gui.MaxDistance = 40;
			gui.AlwaysOnTop = true;
			gui.Adornee = anchor;
			gui.Parent = anchor;
			local frame: Frame = Instance.new('Frame');
			frame.Size = UDim2.fromScale(1, 1);
			frame.BackgroundColor3 = Color3.new();
			frame.BackgroundTransparency = 0.5;
			frame.Parent = gui;
			Instance.new('UICorner', frame).CornerRadius = UDim.new(0, 5);
			local title: TextLabel = Instance.new('TextLabel');
			title.Size = UDim2.fromOffset(145, 14);
			title.Position = UDim2.fromOffset(12, 11);
			title.BackgroundTransparency = 1;
			title.Text = bedwars.ItemMeta[block.Name] and bedwars.ItemMeta[block.Name].displayName or block.Name;
			title.TextXAlignment = Enum.TextXAlignment.Left;
			title.TextColor3 = color.Dark(uipallet.Text, 0.16);
			title.TextStrokeTransparency = 0.6;
			title.TextScaled = true;
			title.Font = Enum.Font.Arial;
			title.Parent = frame;
			local bar: Frame = Instance.new('Frame');
			bar.Size = UDim2.fromOffset(138, 4);
			bar.Position = UDim2.fromOffset(12, 32);
			bar.BackgroundColor3 = uipallet.Main;
			bar.Parent = frame;
			Instance.new('UICorner', bar).CornerRadius = UDim.new(1, 0);
			local fill: Frame = Instance.new('Frame');
			fill.Size = UDim2.fromScale(math.clamp(health / maximum, 0, 1), 1);
			fill.BackgroundColor3 = Color3.fromHSV(math.clamp(health / maximum / 2.5, 0, 1), 0.89, 0.75);
			fill.Parent = bar;
			Instance.new('UICorner', fill).CornerRadius = UDim.new(1, 0);
			healthbar.Anchor, healthbar.Fill, healthbar.Cell = anchor, fill, blockRef.blockPosition;
		end;
		local token: table = {};
		healthbar.Token = token;
		local percent: number = math.clamp((health - change) / maximum, 0, 1);
		tweenService:Create(healthbar.Fill, TweenInfo.new(0.3), {["Size"] = UDim2.fromScale(percent, 1), ["BackgroundColor3"] = Color3.fromHSV(math.clamp(percent / 2.5, 0, 1), 0.89, 0.75)}):Play();
		task.delay(healthbarLifetime, function(): ()
			if healthbar.Token == token and healthbar.Anchor then
				healthbar.Anchor:Destroy();
				table.clear(healthbar);
			end;
		end);
	end;

	local fastAllowed: (block: Instance?) -> boolean = function(block: Instance?): boolean
		if not block or (BedCheck["Enabled"] and block.Name == 'bed') or (HiveCheck["Enabled"] and block.Name == 'beehive') then
			return false;
		end;
		for _: number, name: string in (UseBlacklist["Enabled"] and blacklistNames or {}) do
			if block.Name:find(name, 1, true) then
				return false;
			end;
		end;
		return true;
	end;

	local phaseCharacter: (character: Model) -> () = function(character: Model): ()
		if phased[character] then
			return;
		end;
		local entry: table = {["Parts"] = {}, ["Connections"] = {}};
		phased[character] = entry;
		local ignore: (part: Instance) -> () = function(part: Instance): ()
			if part:IsA('BasePart') then
				table.insert(entry.Parts, part);
				bedwars.QueryUtil:setQueryIgnored(part, true);
			end;
		end;
		for _: number, part: Instance in character:GetDescendants() do
			ignore(part);
		end;
		table.insert(entry.Connections, character.DescendantAdded:Connect(ignore));
		table.insert(entry.Connections, character.Destroying:Connect(function(): ()
			for _: number, connection: RBXScriptConnection in entry.Connections do
				connection:Disconnect();
			end;
			phased[character] = nil;
		end));
	end;
	local unphase: () -> () = function(): ()
		for _: Model, entry: table in phased do
			for _: number, connection: RBXScriptConnection in entry.Connections do
				connection:Disconnect();
			end;
			for _: number, part: BasePart in entry.Parts do
				if part.Parent then
					bedwars.QueryUtil:setQueryIgnored(part, false);
				end;
			end;
		end;
		table.clear(phased);
	end;
	local phaseEveryone: () -> () = function(): ()
		for _: number, ent: table in entitylib.List do
			if ent.Player and ent.Character then
				phaseCharacter(ent.Character);
			end;
		end;
	end;

	local containedCells: (block: Instance) -> {Vector3} = function(block: Instance): {Vector3}
		local handler: table? = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name);
		return handler and handler:getContainedPositions(block) or {bedwars.BlockController:getBlockPosition(block.Position)};
	end;

	local pickBlock: (entry: table, origin: Vector3, mouseRay: Ray, mouseHit: Instance?, playerParams: RaycastParams) -> Instance? = function(entry: table, origin: Vector3, mouseRay: Ray, mouseHit: Instance?, playerParams: RaycastParams): Instance?
		local chosen: Instance?, best: number = nil, math.huge;
		for _: number, block: Instance in entry.List do
			local distance: number = math.huge;
			for _: number, cell: Vector3 in containedCells(block) do
				if bedwars.BlockController:isBlockBreakable({["blockPosition"] = cell}, lplr) then
					distance = math.min(distance, (cell * 3 - origin).Magnitude);
				end;
			end;
			if distance >= Range["Value"] or shield(block) or (not SelfBreak["Enabled"] and block:GetAttribute('PlacedByUserId') == lplr.UserId) then
				continue;
			end;
			if entry.TeamCheck then
				local placer: Player? = playersService:GetPlayerByUserId(block:GetAttribute('PlacedByUserId') or 0);
				if placer and placer:GetAttribute('Team') == lplr:GetAttribute('Team') then
					continue;
				end;
			end;
			if block ~= activeBlock and Wallcheck["Enabled"] and not ClosestBreak["Enabled"] and ViewAngle["Value"] < 180 then
				local offset: Vector3 = block.Position - gameCamera.CFrame.Position;
				if offset.Magnitude > 0 and math.deg(math.acos(math.clamp(offset.Unit:Dot(gameCamera.CFrame.LookVector), -1, 1))) > ViewAngle["Value"] then
					continue;
				end;
			end;
			if (LimitItem["Enabled"] and not holdingBreaker()) or (PlayerCheck["Enabled"] and workspace:Raycast(entitylib.character.Head.Position, block.Position - entitylib.character.Head.Position, playerParams)) then
				continue;
			end;
			if block == activeBlock then
				return block;
			end;
			local score: number = distance;
			if ClosestBreak["Enabled"] then
				local offset: Vector3 = block.Position - mouseRay.Origin;
				local along: number = offset:Dot(mouseRay.Direction);
				score = block == mouseHit and 0 or along > 0 and (offset - mouseRay.Direction * along).Magnitude or offset.Magnitude;
			end;
			if score < best then
				chosen, best = block, score;
			end;
		end;
		return chosen;
	end;

	local aimAt: (block: Instance, position: Vector3, direction: Vector3, params: RaycastParams) -> Vector3? = function(block: Instance, position: Vector3, direction: Vector3, params: RaycastParams): Vector3?
		local eye: Vector3 = gameCamera.CFrame.Position;
		for _: number, offset: Vector3 in aimOffsets do
			if block.Name == 'bed' and (offset == Vector3.zero or getPlacedBlock(position + offset.Unit * 3)) then
				continue;
			end;
			local delta: Vector3 = position + offset - eye;
			if delta.Magnitude <= 0.001 or delta.Unit:Dot(direction) < math.cos(math.rad(ViewAngle["Value"])) then
				continue;
			end;
			local hit: RaycastResult? = bedwars.QueryUtil:raycast(eye, delta.Unit * (delta.Magnitude + 3), params);
			if not hit or (hit.Instance ~= block and not hit.Instance:IsDescendantOf(block)) then
				continue;
			end;
			if block.Name == 'bed' then
				local nearest: Vector3?, gap: number = nil, math.huge;
				for _: number, cell: Vector3 in containedCells(block) do
					local separation: number = (cell * 3 - (hit.Position - hit.Normal * 0.1)).Magnitude;
					if separation < gap then
						nearest, gap = cell * 3, separation;
					end;
				end;
				if nearest ~= position then
					continue;
				end;
			end;
			return hit.Position;
		end;
		return nil;
	end;

	Nuker = vape.Categories.World:CreateModule({
		["Name"] = 'Nuker',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			activeBlock, nextBreak, fastActive = nil, 0, false;
			for _: number = 1, pathLength do
				local part: Part = Instance.new('Part');
				part.Anchored = true;
				part.CanQuery = false;
				part.CanCollide = false;
				part.Transparency = 1;
				part.Parent = gameCamera;
				local highlight: BoxHandleAdornment = Instance.new('BoxHandleAdornment');
				highlight.Size = Vector3.one;
				highlight.AlwaysOnTop = true;
				highlight.ZIndex = 1;
				highlight.Transparency = 0.5;
				highlight.Adornee = part;
				highlight.Parent = part;
				table.insert(pathParts, part);
				Nuker:Clean(part);
			end;
			customBlocks = collection('block', Nuker, function(list: table, block: Instance, tag: string): ()
				if table.find(Custom.ListEnabled, block.Name) then
					table.insert(list, block);
				end;
			end);
			local beds: {Instance} = collection('bed', Nuker);
			local targets: {table} = {
				{["List"] = beds, ["Option"] = Bed, ["Route"] = true},
				{["List"] = collection('beehive', Nuker), ["Option"] = Hive, ["TeamCheck"] = true},
				{["List"] = collection('tesla-trap', Nuker), ["Option"] = Tesla, ["TeamCheck"] = true},
				{["List"] = collection('iron_ore_mesh_block', Nuker), ["Option"] = IronOre},
				{["List"] = collection('LuckyBlock', Nuker), ["Option"] = LuckyBlock},
				{["List"] = customBlocks}
			};
			local mouseParams: RaycastParams = RaycastParams.new();
			mouseParams.FilterType = Enum.RaycastFilterType.Exclude;
			local playerParams: RaycastParams = RaycastParams.new();
			playerParams.FilterType = Enum.RaycastFilterType.Include;
			local assistParams: RaycastParams = RaycastParams.new();
			assistParams.FilterType = Enum.RaycastFilterType.Exclude;
			local assistMaid: table = rawget(getmetatable(bedwars.BlockBreaker.maid), 'new')();
			local random: Random = Random.new();
			local busy: boolean, nextUpdate: number = false, 0;
			local assist: table = {["Search"] = 0, ["Started"] = 0};

			Nuker:Clean(function(): ()
				assistMaid:DoCleaning();
				table.clear(pathParts);
				activeBlock = nil;
				store.breakTool = nil;
				if healthbar.Anchor then
					healthbar.Anchor:Destroy();
				end;
				table.clear(healthbar);
				if fastActive then
					bedwars.BlockBreaker:setCooldown(legitCooldown);
				end;
				unphase();
			end);

			blockHitHooks.Nuker = function(breaker: table, _: table, mouseRay: any): ()
				if not FastBreak["Enabled"] then
					return;
				end;
				local info: table? = breaker.clientManager:getBlockSelector():getMouseInfo(1, {["ray"] = mouseRay});
				if fastAllowed(info and info.target and info.target.blockInstance) then
					fastActive = true;
					breaker:setCooldown(BreakSpeed["Value"]);
				end;
			end;
			Nuker:Clean(function(): ()
				blockHitHooks.Nuker = nil;
			end);

			local previousHit: (...any) -> ...any = bedwars.BlockBreaker.hitBlock;
			local pending: table? = nil;
			local assistHit: (...any) -> ...any;
			assistHit = function(breaker: table, maid: table, mouseRay: any, ...: any): ...any
				if not BedAssist["Enabled"] or not MineBed["Enabled"] then
					return previousHit(breaker, maid, mouseRay, ...);
				end;
				local info: table? = breaker.clientManager:getBlockSelector():getMouseInfo(1, {["ray"] = mouseRay, ["range"] = math.min(AssistRange["Value"], breaker:getRange())});
				local selected: table? = info and info.target;
				if not selected or selected.blockInstance.Name ~= 'bed' then
					return previousHit(breaker, maid, mouseRay, ...);
				end;
				local block: Instance = selected.blockInstance;
				local timeout: number = math.max(1, lplr:GetNetworkPing() * 4 + 0.5);
				if (pending and tick() - pending.Sent < timeout) or not entitylib.isAlive or store.matchState ~= 1 or lplr:GetAttribute('DenyBlockBreak') or tick() - breaker.lastHitTime < breaker:getCooldown() or not bedwars.BlockController:isBlockBreakable(selected.blockRef, lplr) or ownTeamNoBreak(block) or shield(block) then
					return nil;
				end;
				local data: Instance? = bedwars.BlockController:getStore():getBlockData(selected.blockRef.blockPosition);
				local healthKey: string = breaker.blockHealthbar:getHealthKey(block);
				local before: number = data and data:GetAttribute(healthKey) or block:GetAttribute('Health');
				local request: table = {["Sent"] = tick()};
				pending = request;
				breaker.lastHitTime = tick();
				store.lastHit = breaker.lastHitTime;
				for _: string, hook: (...any) -> () in blockHitHooks do
					hook(breaker, maid, mouseRay, ...);
				end;
				local track: AnimationTrack? = bedwars.AnimationUtil:playAnimation(lplr, bedwars.BlockController:getAnimationController():getAssetId(1));
				if track then
					maid:GiveTask(function(): ()
						track:Stop();
						track:Destroy();
					end);
				end;
				breaker.onBreak:Fire();
				bedwars.ClientDamageBlock:Get('DamageBlock'):CallServerAsync({
					["blockRef"] = selected.blockRef,
					["hitPosition"] = selected.hitPosition,
					["hitNormal"] = selected.hitNormal
				}):andThen(function(result: any): ()
					if pending == request then
						pending = nil;
					end;
					if not Nuker["Enabled"] then
						return;
					end;
					if result == 'destroyed' then
						breaker.blockHealthbar:destroy();
						breaker.breakTextureHandler:removeTexture(selected.blockRef);
						if bedwars.BlockController:getStore():getBlockAt(selected.blockRef.blockPosition) == block then
							bedwars.BlockController:destroyBlock(selected.blockRef);
						end;
						breaker.breakEffect:playBreak(block.Name, selected.blockRef.blockPosition, lplr);
					elseif result == 'damaged' then
						local after: number = data and data:GetAttribute(healthKey) or block:GetAttribute('Health');
						breaker:updateHealthbar(selected.blockRef, before, block:GetAttribute('MaxHealth'), math.max(before - after, 0), block);
						breaker.breakEffect:playHit(block.Name, selected.blockRef.blockPosition, lplr);
					end;
					assist.Search = 0;
				end):catch(function(): ()
					if pending == request then
						pending = nil;
					end;
					assist.Search = 0;
				end);
				return nil;
			end;
			bedwars.BlockBreaker.hitBlock = assistHit;
			Nuker:Clean(function(): ()
				if bedwars.BlockBreaker.hitBlock == assistHit then
					bedwars.BlockBreaker.hitBlock = previousHit;
				end;
			end);

			if PhaseMine["Enabled"] then
				phaseEveryone();
			end;
			Nuker:Clean(entitylib.Events.EntityAdded:Connect(function(ent: table): ()
				if ent.Player and PhaseMine["Enabled"] then
					task.delay(1, function(): ()
						if Nuker["Enabled"] and PhaseMine["Enabled"] and ent.Character then
							phaseCharacter(ent.Character);
						end;
					end);
				end;
			end));

			Nuker:Clean(runService.Heartbeat:Connect(function(): ()
				local now: number = tick();
				if fastActive and (not FastBreak["Enabled"] or now - (store.lastHit or 0) > legitCooldown) then
					fastActive = false;
					bedwars.BlockBreaker:setCooldown(legitCooldown);
				end;
				if not AutoBreak["Enabled"] or busy or now < nextUpdate or not entitylib.isAlive or store.damageBlockFail > now then
					return;
				end;
				nextUpdate = now + 1 / UpdateRate["Value"];
				local ignore: {Instance} = {lplr.Character, gameCamera};
				local players: {Instance} = {};
				for _: number, ent: table in entitylib.List do
					if ent.Character then
						table.insert(ignore, ent.Character);
						if ent.Player then
							table.insert(players, ent.Character);
						end;
					end;
				end;
				mouseParams.FilterDescendantsInstances = ignore;
				playerParams.FilterDescendantsInstances = players;
				local mouse: Vector2 = inputService:GetMouseLocation();
				local mouseRay: Ray = gameCamera:ViewportPointToRay(mouse.X, mouse.Y);
				local mouseResult: RaycastResult? = ClosestBreak["Enabled"] and workspace:Raycast(mouseRay.Origin, mouseRay.Direction * 999, mouseParams) or nil;
				local origin: Vector3 = entitylib.character.RootPart.Position;
				for _: number, entry: table in targets do
					if entry.Option and not entry.Option["Enabled"] then
						continue;
					end;
					local block: Instance? = pickBlock(entry, origin, mouseRay, mouseResult and mouseResult.Instance, playerParams);
					if not block then
						continue;
					end;
					activeBlock = block;
					if now < nextBreak then
						return;
					end;
					busy = true;
					local position: Vector3?, path: {[Vector3]: Vector3}?, target: Vector3?, sent: boolean = breakBlock(block, {
						["Effects"] = Effect["Enabled"],
						["Animation"] = Animation["Value"] ~= 'No Animation' and Animation["Value"] or nil,
						["Healthbar"] = Effect["Enabled"] and CustomHealth["Enabled"] and drawHealthbar or nil,
						["AutoTool"] = AutoTool["Enabled"],
						["Wallcheck"] = Wallcheck["Enabled"],
						["Nearest"] = ClosestBreak["Enabled"] or Mode["Value"] == 'Distance',
						["DirectOnly"] = not entry.Route,
						["Sequential"] = true,
						["SwitchDelay"] = SwitchDelay:GetRandomValue(),
						["OnTarget"] = showPath
					});
					busy = false;
					if sent then
						nextBreak = tick() + BreakSpeed["Value"];
					end;
					showPath(position, path, target);
					if position then
						return;
					end;
				end;
				activeBlock = nil;
				showPath(nil, nil, nil);
			end));

			Nuker:Clean(runService.PostSimulation:Connect(function(delta: number): ()
				if not BedAssist["Enabled"] then
					return;
				end;
				if not entitylib.isAlive or store.matchState ~= 1 or lplr:GetAttribute('Spectator') or lplr:GetAttribute('DenyBlockBreak') or inputService:GetFocusedTextBox() or guiService.MenuIsOpen or bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) or (LimitItem["Enabled"] and not holdingBreaker()) then
					assist.Target, assist.Bed, assist.Position, assist.Search = nil, nil, nil, 0;
					return;
				end;
				local reach: number = math.min(AssistRange["Value"], bedwars.BlockBreaker:getRange());
				local mouse: Vector2 = inputService.MouseEnabled and inputService:GetMouseLocation() or gameCamera.ViewportSize / 2;
				local mouseRay: Ray = gameCamera:ViewportPointToRay(mouse.X, mouse.Y);
				local origin: Vector3 = entitylib.character.RootPart.Position;
				assistParams.FilterDescendantsInstances = {lplr.Character, gameCamera};
				if tick() >= assist.Search or (assist.Target and not assist.Target.Parent) then
					local chosen: Instance?, chosenBed: Instance?, chosenPosition: Vector3?, cost: number, gap: number = nil, nil, nil, math.huge, math.huge;
					for _: number, bed: Instance in beds do
						if not bed.Parent or ownTeamNoBreak(bed) or shield(bed) or (bed.Position - origin).Magnitude > reach + 3 then
							continue;
						end;
						for _: number, cell: Vector3 in containedCells(bed) do
							local position: Vector3?, routeCost: number? = mining.route(bed, cell * 3, true, false);
							local hit: Instance? = position and getPlacedBlock(position);
							if hit and (position - bed.Position).Magnitude <= assistDepthRadius and (position - origin).Magnitude <= reach and (routeCost < cost or (routeCost == cost and (position - origin).Magnitude < gap)) then
								chosen, chosenBed, chosenPosition, cost, gap = hit, bed, position, routeCost, (position - origin).Magnitude;
							end;
						end;
					end;
					if chosen ~= assist.Target then
						assist.Started = tick();
					end;
					assist.Target, assist.Bed, assist.Position, assist.Search = chosen, chosenBed, chosenPosition, tick() + assistSearchInterval;
				end;
				local target: Instance? = assist.Target;
				if not target or not target.Parent or not assist.Bed.Parent or ownTeamNoBreak(assist.Bed) or shield(assist.Bed) or (target == assist.Bed and not MineBed["Enabled"]) or (origin - assist.Position).Magnitude > reach then
					return;
				end;
				local aimPoint: Vector3? = aimAt(target, assist.Position, mouseRay.Direction, assistParams);
				if not aimPoint then
					return;
				end;
				local speed: number = AssistSpeed["Value"];
				if AssistCurve["Value"] == 'Adaptive' then
					local progress: number = math.clamp((tick() - assist.Started) * speed * 0.5, 0, 1);
					speed *= progress < 0.5 and 4 * progress ^ 3 or 1 - (-2 * progress + 2) ^ 3 / 2;
				end;
				local alpha: number = 1 - math.exp(-speed * delta);
				local aim: Vector3 = aimPoint + Vector3.new(random:NextNumber(-1, 1), random:NextNumber(-1, 1), random:NextNumber(-1, 1)) * AssistShake["Value"] * 0.005;
				if AssistAim["Value"] == 'Mouse' then
					local screen: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(aim);
					if visible then
						local move: Vector2 = (Vector2.new(screen.X, screen.Y) - mouse) * alpha;
						mousemoverel(move.X, move.Y);
					end;
				else
					local direction: Vector3 = (aim - mouseRay.Origin).Unit;
					local axis: Vector3 = mouseRay.Direction:Cross(direction);
					if axis.Magnitude > 0.0001 then
						local turn: CFrame = CFrame.fromAxisAngle(axis.Unit, math.acos(math.clamp(mouseRay.Direction:Dot(direction), -1, 1)) * alpha);
						gameCamera.CFrame = CFrame.new(gameCamera.CFrame.Position) * turn * gameCamera.CFrame.Rotation;
					end;
				end;
				if AutoMine["Enabled"] and not inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and tick() - bedwars.BlockBreaker.lastHitTime >= bedwars.BlockBreaker:getCooldown() then
					local ray: Ray = gameCamera:ViewportPointToRay(mouse.X, mouse.Y);
					local info: table? = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(1, {["ray"] = ray, ["range"] = reach});
					if info and info.target and info.target.blockInstance == target then
						assistMaid:DoCleaning();
						bedwars.BlockBreaker:hitBlock(assistMaid, ray);
					end;
				end;
			end));
		end,
		["Tooltip"] = 'Breaks beds and blocks around you, speeds up manual mining and assists aiming into beds.'
	});
	AutoBreak = Nuker:CreateToggle({
		["Name"] = 'Auto break',
		["Default"] = true,
		["Tooltip"] = 'Breaks the selected targets automatically'
	});
	Mode = Nuker:CreateDropdown({
		["Name"] = 'Break mode',
		["List"] = {'Health', 'Distance'},
		["Default"] = 'Health'
	});
	ClosestBreak = Nuker:CreateToggle({
		["Name"] = 'Closest break',
		["Function"] = function(callback: boolean): ()
			Mode.Object.Visible = not callback;
