	AssistCurve = Nuker:CreateDropdown({["Name"] = 'Assist curve', ["List"] = {'Simple', 'Adaptive'}, ["Default"] = 'Simple', ["Darker"] = true, ["Visible"] = false});
	AssistAim = Nuker:CreateDropdown({
