	AssistSpeed = Nuker:CreateSlider({["Name"] = 'Assist speed', ["Min"] = 1, ["Max"] = 20, ["Default"] = 7, ["Darker"] = true, ["Visible"] = false});
	AssistRange = Nuker:CreateSlider({
