					if value and value > bestScore then
						best, bestScore = contract, value;
					end;
					if value and contract.id == pending.Priority then
						current, currentScore = contract, value;
					end;
				end;
				if current and best ~= current and bestScore < currentScore + stickiness then
					best = current;
				end;
				pending.Priority = best and best.id or nil;
				return best, true;
			end;
			local pickByHits: (contracts: {table}) -> table? = function(contracts: {table}): table?
				local offered: {[string]: table} = {};
				for _: number, contract: table in contracts do
					if contract.target then
						offered[contract.target.Name] = contract;
					end;
				end;
				for _: number, ent: table in entitylib.AllPosition({["Part"] = 'RootPart', ["Players"] = true, ["Range"] = Range["Value"], ["Sort"] = sortMethods[TargetMode["Value"]]}) do
					local contract: table? = offered[ent.Player.Name];
					if contract and (hits[ent.Character] or 0) > tick() and not spectating(ent) and (ContractMode["Value"] ~= 'On Low' or ent.Health < MinHealth["Value"]) then
						return contract;
					end;
				end;
				return nil;
			end;
