					reset(false);
					return;
				end;
				local kitState: table? = bedwars.Store:getState().Kit;
				local active: table? = kitState and kitState.activeContract;
				if not kitState or active then
					pending.Id = nil;
					pending.Priority = active and active.id or nil;
					if active and DropContract["Enabled"] and pending.DropUntil <= tick() and abandonable(active) then
						fire('BloodAssassinSelectContract', 'SendToServer', {["contractId"] = nil});
						pending.DropUntil = tick() + 5;
					end;
					return;
				end;
				if pending.Id and pending.Until > tick() then
					return;
				end;
				pending.Id = nil;
				local contracts: {table}? = kitState.availableContracts;
				if not contracts or #contracts == 0 then
					return;
				end;
