				else
					pending.Priority = nil;
				end;
				if not rewarding then
					contract = pickByHits(contracts);
				end;
				if contract then
					fire('BloodAssassinSelectContract', 'SendToServer', {["contractId"] = contract.id});
					pending.Id = contract.id;
					pending.Until = tick() + 1;
				end;
			end));
		end
	};
end);

