velo.run(function(): ()
	local checkRate: number = 0.1;
	local banners: {[string]: string} = {["Fire"] = 'damage_banner', ["Defense"] = 'defense_banner', ["Heal"] = 'heal_banner'};
	local spots: {Vector3} = {Vector3.new(3, 3, 0), Vector3.new(-3, 3, 0), Vector3.new(0, 3, 3), Vector3.new(0, 3, -3), Vector3.new(0, 3, 0)};
	local Banner: table;
	local Trigger: table;
	local Range: table;
	local Cooldown: table;
	local LegitSwitch: table;
	local SwitchDelay: table;
	kitSpecs.Conqueror = {
		["Kits"] = {'vesta'},
		["Options"] = function(autoKit: table): {table}
			Banner = autoKit:CreateDropdown({["Name"] = 'Conqueror Banner', ["List"] = {'Fire', 'Defense', 'Heal'}, ["Tooltip"] = 'Fire gives the damage buff'});
			Trigger = autoKit:CreateDropdown({["Name"] = 'Conqueror Place on', ["List"] = {'On attack', 'On near'}, ["Tooltip"] = 'On attack waits until you trade hits, On near places as soon as someone walks up'});
			Range = autoKit:CreateSlider({["Name"] = 'Conqueror Range', ["Min"] = 5, ["Max"] = 100, ["Default"] = 30, ["Suffix"] = 'studs', ["Tooltip"] = 'How close an enemy has to be for On near'});
			Cooldown = autoKit:CreateSlider({["Name"] = 'Conqueror Cooldown', ["Min"] = 1, ["Max"] = 60, ["Default"] = 30, ["Suffix"] = 's', ["Tooltip"] = 'A banner lasts 30 seconds'});
			LegitSwitch = autoKit:CreateToggle({["Name"] = 'Conqueror Legit switch', ["Tooltip"] = 'Holds the banner through the hotbar and switches back after'});
			SwitchDelay = autoKit:CreateSlider({["Name"] = 'Conqueror Switch delay', ["Min"] = 0, ["Max"] = 1, ["Default"] = 0.08, ["Decimal"] = 100, ["Suffix"] = 's'});
			return {Banner, Trigger, Range, Cooldown, LegitSwitch, SwitchDelay};
		end,
		["Start"] = function(autoKit: table): ()
			local nextPlace: number, placing: boolean = 0, false;
			local plant: () -> () = function(): ()
				if placing or tick() < nextPlace or not entitylib.isAlive then
					return;
				end;
				local itemType: string = banners[Banner["Value"]];
				local item: table? = getItem(itemType);
				if not item or (item.amount or 1) <= 0 then
					return;
				end;
				local origin: Vector3 = entitylib.character.RootPart.Position;
				for _: number, flag: Instance in collectionService:GetTagged('flag-kit') do
					if flag:IsA('BasePart') and flag.Name == itemType and (flag.Position - origin).Magnitude <= bedwars.ConquerorBalance.CONQUEROR_FLAG_RADIUS / 2 then
						return;
					end;
				end;
				local floor: Vector3 = roundPos(origin - Vector3.new(0, entitylib.character.HipHeight + 1.5, 0));
				local spot: Vector3?;
				for _: number, offset: Vector3 in spots do
					if not getPlacedBlock(floor + offset) and getPlacedBlock(floor + offset - Vector3.new(0, 3, 0)) then
						spot = floor + offset;
						break;
					end;
				end;
				if not spot then
					return;
				end;
				placing, nextPlace = true, tick() + Cooldown["Value"];
				local previous: number? = LegitSwitch["Enabled"] and store.hand.tool and hotbarSlotOf(store.hand.tool) or nil;
				local holding: boolean = not LegitSwitch["Enabled"] or store.hand.tool == item.tool or hotbarSwitch(hotbarSlotOf(item.tool));
				if holding then
					if LegitSwitch["Enabled"] then
						task.wait(SwitchDelay["Value"]);
					end;
					placeBlock(spot, itemType);
					if previous and previous ~= hotbarSlotOf(item.tool) then
						task.wait(SwitchDelay["Value"]);
						hotbarSwitch(previous);
					end;
				end;
				placing = false;
			end;
			autoKit:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
				local involved: boolean = (damage.fromEntity ~= nil and damage.fromEntity.Name == lplr.Name) or (lplr.Character ~= nil and damage.entityInstance == lplr.Character);
				if Trigger["Value"] == 'On attack' and damage.damageType == 0 and involved then
					plant();
				end;
			end));
			local nextCheck: number = 0;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if Trigger["Value"] ~= 'On near' or tick() < nextCheck or not entitylib.isAlive then
					return;
				end;
				nextCheck = tick() + checkRate;
				if entitylib.EntityPosition({
					["Range"] = Range["Value"],
					["Part"] = 'RootPart',
					["Players"] = autoKit.Options.Targets.Players["Enabled"],
					["NPCs"] = autoKit.Options.Targets.NPCs["Enabled"],
					["Wallcheck"] = autoKit.Options.Targets.Walls["Enabled"] or nil
				}) then
					plant();
				end;
			end));
		end
	};
end);

