						collectAt[drill] = tick() + CollectDelay["Value"];
						fire('ExtractFromDrill', 'SendToServer', {["drill"] = drill});
						if Notify["Enabled"] then
							notif('AutoKit', 'Collected drill resources', 4, 'info');
