			local modifier: table = bedwars.SprintController:getMovementStatusModifier();
			local addModifier: (self: table, data: table?) -> any = modifier.addModifier;
			local keepSpeedUntil: number = 0;
			modifier.addModifier = function(self: table, data: table?): any
				if data and data.moveSpeedMultiplier == 0 and NoSlow["Enabled"] and tick() < keepSpeedUntil then
