			Priority = autoKit:CreateDropdown({["Name"] = 'Eldric Priority', ["List"] = {'Enemies', 'Teammates'}, ["Tooltip"] = 'Which side the staff links first when both are in range'});
			Heal = autoKit:CreateToggle({["Name"] = 'Eldric Heal teammates', ["Default"] = true, ["Tooltip"] = 'Links a hurt teammate when no enemy is in range'});
			AllyHealth = autoKit:CreateSlider({["Name"] = 'Eldric Ally health', ["Min"] = 1, ["Max"] = 100, ["Default"] = 70, ["Suffix"] = '%'});
			return {Range, Priority, Heal, AllyHealth};
		end,
		["Start"] = function(autoKit: table): ()
			local linked: Model? = nil;
			local busy: boolean, nextCheck: number = false, 0;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if busy or tick() < nextCheck or not entitylib.isAlive then
					return;
				end;
