			LegitSwitch = autoKit:CreateToggle({["Name"] = 'Gingerbread Legit switch', ["Tooltip"] = 'Swaps to the breaking tool through the hotbar'});
			OwnPads = autoKit:CreateToggle({["Name"] = 'Gingerbread Own pads only', ["Default"] = true});
			SuccessOnly = autoKit:CreateToggle({["Name"] = 'Gingerbread Successful launch only', ["Default"] = true});
			Jump = autoKit:CreateToggle({["Name"] = 'Gingerbread Jump after launch'});
