		end,
		["Start"] = function(autoKit: table): ()
			local launcher: table = bedwars.LaunchPadController;
			local attemptLaunch: (...any) -> ...any = launcher.attemptLaunch;
			launcher.attemptLaunch = function(self: table, pad: Instance?, ...: any): ...any
				local before: number = self and self.lastLaunch or 0;
				local results: table = table.pack(attemptLaunch(self, pad, ...));
				local launched: boolean = not SuccessOnly["Enabled"] or (self and self.lastLaunch ~= nil and self.lastLaunch ~= before);
				if launched and entitylib.isAlive then
					local own: boolean = pad ~= nil and pad:IsA('BasePart') and (not OwnPads["Enabled"] or pad:GetAttribute('PlacedByUserId') == lplr.UserId);
