			ShowLoot = autoKit:CreateToggle({["Name"] = 'Fisherman Show loot drops', ["Tooltip"] = 'Notifies what your next catch drops'});
			Minigame = autoKit:CreateToggle({["Name"] = 'Fisherman Auto minigame', ["Default"] = true});
			MinigameMode = autoKit:CreateDropdown({["Name"] = 'Fisherman Minigame mode', ["List"] = {'Instant', 'Legit'}, ["Tooltip"] = 'Instant wins as soon as it opens, Legit plays the bar itself'});
			CompleteDelay = autoKit:CreateTwoSlider({["Name"] = 'Fisherman Complete delay', ["Min"] = 0, ["Max"] = 25, ["Decimal"] = 5, ["DefaultMin"] = 0.1, ["DefaultMax"] = 0.9});
			Reaction = autoKit:CreateTwoSlider({["Name"] = 'Fisherman Reaction', ["Min"] = 0, ["Max"] = 1, ["Decimal"] = 100, ["DefaultMin"] = 0.06, ["DefaultMax"] = 0.19, ["Tooltip"] = 'How long it takes to notice the fish moved away'});
			Clicks = autoKit:CreateTwoSlider({["Name"] = 'Fisherman Clicks', ["Min"] = 3, ["Max"] = 20, ["DefaultMin"] = 8, ["DefaultMax"] = 13, ["Tooltip"] = 'Taps per second used to hover the bar on the fish'});
			AutoCast = autoKit:CreateToggle({["Name"] = 'Fisherman Auto cast', ["Tooltip"] = 'Finds water near you and casts there, ignoring the camera'});
			CastDelay = autoKit:CreateTwoSlider({["Name"] = 'Fisherman Cast delay', ["Min"] = 0, ["Max"] = 5, ["Decimal"] = 5, ["DefaultMin"] = 0.3, ["DefaultMax"] = 1.2});
			MenuCheck = autoKit:CreateToggle({["Name"] = 'Fisherman GUI check', ["Tooltip"] = 'Waits while a game menu is open before casting or playing'});
			return {Blacklist, ShowLoot, Minigame, MinigameMode, CompleteDelay, Reaction, Clicks, AutoCast, CastDelay, MenuCheck};
		end,
		["Start"] = function(autoKit: table): ()
			local util: table = bedwars.FishermanUtil;
			local minigames: table = bedwars.FishingMinigameController;
			local rod: table = bedwars.FishingRodController;
			local rejected: {Vector3} = {};
			local menuOpen: () -> boolean = function(): boolean
				return MenuCheck["Enabled"] and bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN);
			end;
			local bobber: () -> Instance? = function(): Instance?
				for _: number, projectile: Instance in store.selfProjectiles do
					if projectile.Name == 'fisherman_bobber' and projectile.Parent then
						return projectile;
					end;
				end;
				return nil;
