			Delay = autoKit:CreateSlider({["Name"] = 'Lumen Delay', ["Min"] = 0, ["Max"] = 2, ["Default"] = 0.1, ["Decimal"] = 100, ["Suffix"] = 's'});
			return {Range, FullCharge, Delay};
		end,
		["Start"] = function(autoKit: table): ()
			local charger: table = bedwars.SwordChargeController;
			local balance: table = bedwars.LumenBalance or {["MIN_CHARGE_TIME"] = 0.65, ["MAX_CHARGE_TIME"] = 1.25};
			local started: number?, holdFor: number = nil, 0;
			local nextCheck: number, cooldown: number = 0, 0;
			autoKit:Clean(function(): ()
				if started then
					charger:stopCharging(swordType);
				end;
			end);
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				local charged: table = bedwars.ItemMeta[swordType].sword.chargedAttack or {};
				if started then
					local held: number = tick() - started;
					if entitylib.isAlive and held < holdFor then
						return;
					end;
					started = nil;
					charger:stopCharging(swordType);
					cooldown = tick() + Delay["Value"];
					local tool: Instance? = store.hand.tool;
					if not entitylib.isAlive or not tool or tool.Name ~= swordType then
						return;
					end;
					if not (charged.skipSwingDamage and held > (charged.minChargeTimeSec or balance.MIN_CHARGE_TIME)) then
						bedwars.SwordController:swingSwordAtMouse(held);
					end;
					bedwars.SyncEvents.SwordChargedSwing:fire(lplr, tool, {["chargeTime"] = held});
					return;
				end;
				if tick() < math.max(nextCheck, cooldown) or not entitylib.isAlive or not store.hand.tool or store.hand.tool.Name ~= swordType then
					return;
				end;
				nextCheck = tick() + checkRate;
				local targets: table = autoKit.Options.Targets;
				local ent: table? = entitylib.EntityMouse({
					["Origin"] = entitylib.character.RootPart.Position,
					["Range"] = Range["Value"],
					["Part"] = 'RootPart',
					["Players"] = targets.Players["Enabled"],
					["NPCs"] = targets.NPCs["Enabled"],
					["Wallcheck"] = targets.Walls["Enabled"] or nil
				});
				if not ent or charger:getChargeState() ~= bedwars.ChargeState.Idle then
					return;
				end;
				charger:startCharging(swordType);
				local chargeStart: number = charger:getChargeStartTime();
				if chargeStart ~= 0 then
					started = chargeStart;
					holdFor = (FullCharge["Enabled"] and (charged.maxChargeTimeSec or balance.MAX_CHARGE_TIME) or (charged.minChargeTimeSec or balance.MIN_CHARGE_TIME)) + releasePad;
				end;
			end));
		end
	};
end);

