			Range = autoKit:CreateSlider({["Name"] = 'Skoll Range', ["Min"] = 1, ["Max"] = 100, ["Default"] = 50, ["Suffix"] = 'studs', ["Tooltip"] = 'Fenrir travels 39 studs a second and lives 3 seconds'});
