			DetonateAt = autoKit:CreateDropdown({["Name"] = 'Skoll Detonate at', ["List"] = {'Low health', 'Instantly', 'Before it expires'}, ["Tooltip"] = 'Low health finishes them off; Before it expires keeps the buff until the mark runs out'});
			Health = autoKit:CreateSlider({["Name"] = 'Skoll Health', ["Min"] = 1, ["Max"] = 100, ["Default"] = 30, ["Suffix"] = '%', ["Tooltip"] = 'Low health threshold for detonating'});
			return {TargetMode, Range, AimWolf, Detonate, DetonateAt, Health};
		end,
		["Start"] = function(autoKit: table): ()
			local marked: {[Instance]: number} = {};
			local pickTarget: () -> table? = function(): table?
				local targets: table = autoKit.Options.Targets;
				return entitylib.EntityPosition({
					["Range"] = Range["Value"],
					["Part"] = 'RootPart',
					["Players"] = targets.Players["Enabled"],
					["NPCs"] = targets.NPCs["Enabled"],
					["Wallcheck"] = targets.Walls["Enabled"] or nil,
					["Sort"] = sortMethods[TargetMode["Value"]]
				});
			end;
			local controller: table = bedwars.VoidHunterKitController;
			local original: (...any) -> ...any = controller.onAbilityUsed;
			local hooked: (...any) -> ...any = function(self: table, character: Model, data: table?, ...: any): ...any
				local ent: table? = AimWolf["Enabled"] and data and data.ability == 'void_hunter_mark' and character == lplr.Character and character.PrimaryPart and pickTarget() or nil;
				local delta: Vector3 = ent and ent.RootPart.Position - character.PrimaryPart.Position or Vector3.zero;
				if delta.Magnitude > 0 then
					fire('VoidHunter_MarkAbilityRequest', 'SendToServer', {["originPosition"] = character.PrimaryPart.Position, ["direction"] = delta.Unit});
					return;
				end;
				return original(self, character, data, ...);
			end;
			controller.onAbilityUsed = hooked;
