			end));
		end
	};
end);

velo.run(function(): ()
	local checkRate: number = 0.1;
	local sellCooldown: number = 0.5;
	local shopReach: number = 20;
	local Iron: table;
	local Emerald: table;
	local Diamond: table;
	local Amount: table;
	kitSpecs.Taliyah = {
		["Kits"] = {'taliyah'},
		["Options"] = function(autoKit: table): {table}
			Iron = autoKit:CreateToggle({["Name"] = 'Taliyah Iron', ["Default"] = true, ["Tooltip"] = 'Buys the chicken when it costs iron'});
			Emerald = autoKit:CreateToggle({["Name"] = 'Taliyah Emerald', ["Default"] = true, ["Tooltip"] = 'Buys the chicken when it costs emeralds'});
			Diamond = autoKit:CreateToggle({["Name"] = 'Taliyah Diamond', ["Default"] = true, ["Tooltip"] = 'Buys the chicken when it costs diamonds'});
			Amount = autoKit:CreateSlider({["Name"] = 'Taliyah Amount', ["Min"] = 1, ["Max"] = 1000, ["Default"] = 2, ["Tooltip"] = 'Only buys when the price is at least this much'});
			return {Iron, Emerald, Diamond, Amount};
		end,
		["Start"] = function(autoKit: table): ()
			local nextCheck: number = 0;
			local chicken: table?;
			local currencies: {[string]: table} = {["iron"] = Iron, ["emerald"] = Emerald, ["diamond"] = Diamond};
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextCheck or not entitylib.isAlive or not bedwars.Shop then
					return;
				end;
				nextCheck = tick() + checkRate;
				chicken = chicken or bedwars.Shop.getShopItem('chicken_shop_item', lplr);
				local origin: Vector3 = entitylib.character.RootPart.Position;
				local shopId: string?;
				for _: number, shop: table in store.shop do
					if shop.Shop and (shop.RootPart.Position - origin).Magnitude <= shopReach then
						shopId = shop.Id;
						break;
					end;
				end;
				local price: table = shopId and chicken and bedwars.TaliyahUtil:getPrice() or {};
				local wanted: table? = price.currency and currencies[price.currency];
				if not wanted or not wanted["Enabled"] or price.price < Amount["Value"] then
					return;
				end;
				nextCheck = tick() + sellCooldown;
				local item: table = chicken;
				fire('BedwarsPurchaseItem', 'CallServerAsync', {["shopItem"] = item, ["shopId"] = shopId}):andThen(function(bought: boolean): ()
					if not bought then
						return;
					end;
					bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM);
					bedwars.Store:dispatch({["type"] = 'BedwarsAddItemPurchased', ["itemType"] = item.itemType});
					if item.tiered then
						bedwars.BedwarsShopController.alreadyPurchasedMap[item.itemType] = true;
					end;
				end);
			end));
		end
	};
end);

velo.run(function(): ()
	local checkRate: number = 0.1;
	local reuseDelay: number = 2;
	local leadCap: number = 18;
