				ringCount = 0;
			end, ["Tooltip"] = 'Bed ring surrounds a bed; Enemies throws ahead of targets using travel and arming time'});
			TrapType = autoKit:CreateDropdown({["Name"] = 'Trapper Trap type', ["List"] = {'Auto', 'Snap', 'Venom', 'Explosive'}, ["Tooltip"] = 'Auto uses your selected stocked trap on enemies and the Traps list around beds'});
			Target = autoKit:CreateDropdown({["Name"] = 'Trapper Target', ["List"] = {'Your bed', 'Enemy bed'}});
