			Range = autoKit:CreateSlider({["Name"] = 'Trapper Range', ["Min"] = 4, ["Max"] = 60, ["Default"] = 20, ["Suffix"] = 'studs', ["Tooltip"] = 'How close the bed has to be'});
			Amount = autoKit:CreateSlider({["Name"] = 'Trapper Amount', ["Min"] = 1, ["Max"] = 8, ["Default"] = 3, ["Suffix"] = 'traps', ["Tooltip"] = 'Traps per bed ring pass'});
			PlaceRange = autoKit:CreateSlider({["Name"] = 'Trapper Place Range', ["Min"] = 1, ["Max"] = 45, ["Default"] = 30, ["Suffix"] = 'studs', ["Tooltip"] = "Capped at the game's throw range"});
			Delay = autoKit:CreateSlider({["Name"] = 'Trapper Delay', ["Min"] = 0.35, ["Max"] = 10, ["Default"] = 0.5, ["Decimal"] = 100, ["Suffix"] = 's', ["Tooltip"] = "Wait between enemy throws or ring passes, never below the game's cooldown"});
