			Detonate = autoKit:CreateToggle({["Name"] = 'Trapper Auto detonate', ["Default"] = true, ["Tooltip"] = 'Detonates armed explosives when an enemy is inside the blast and predicted to stay'});
			SwitchBack = autoKit:CreateToggle({["Name"] = 'Trapper Switch back', ["Default"] = true, ["Tooltip"] = 'Restores your hotbar slot after placing an inventory trap'});
			Notify = autoKit:CreateToggle({["Name"] = 'Trapper Notify'});
			Traps = autoKit:CreateTextList({["Name"] = 'Trapper Traps', ["Default"] = {'snap_trap', 'venom_trap', 'explosive_trap', 'invisible_landmine', 'spike_trap', 'tesla_trap', 'grave_trap', 'lucky_block_trap'}, ["Placeholder"] = 'item', ["Tooltip"] = 'Bed ring priority; Trapper traps use kit stock, others use your inventory'});
			KitCheck = autoKit:CreateToggle({["Name"] = 'Trapper Kit check', ["Default"] = true, ["Tooltip"] = 'Only throws traps while you play Trapper; turn off to place inventory traps with any kit'});
			return {Mode, TrapType, Target, Radius, Range, Amount, PlaceRange, Delay, IgnoreWalls, Detonate, SwitchBack, Notify, Traps, KitCheck};
