				local points: {Vector3} = {};
				local origin: Vector3 = entitylib.character.RootPart.Position;
				if hunting then
					for _: number, ent: table in enemies do
						local travel: number = trapperUtil.trapThrowDuration(origin + Vector3.new(0, 1, 0), ent.RootPart.Position) + balance.SettleTime + constants.TrapperTrapMeta[item].setupTime + store.ping.total;
						local lead: Vector3 = ent.RootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1) * travel;
						lead = lead.Magnitude > leadCap and lead.Unit * leadCap or lead;
						for _: number, share: number in {1, 0.5, 0} do
							table.insert(points, ent.RootPart.Position + lead * share - Vector3.new(0, ent.HipHeight - 1.5, 0));
						end;
					end;
					return points;
				end;
				local ownBed: string = 'Team'..(lplr:GetAttribute('Team') or -1)..'NoBreak';
				local bed: BasePart?, closest: number = nil, Range["Value"];
				for _: number, candidate: BasePart in collectionService:GetTagged('bed') do
