			AutoOwl = autoKit:CreateToggle({["Name"] = 'Whisper Auto owl', ["Tooltip"] = 'Sends the owl to your chosen teammate as soon as it is ready'});
			Teammate = autoKit:CreateDropdown({["Name"] = 'Whisper Teammate', ["List"] = teammates, ["Tooltip"] = 'Who the owl is summoned onto'});
			FovCheck = autoKit:CreateToggle({["Name"] = 'Whisper FOV check', ["Tooltip"] = 'Only picks a teammate near your mouse, inside owl range and without an owl\nWith Teammate on None it picks whoever is closest to your mouse'});
			Fov = autoKit:CreateSlider({["Name"] = 'Whisper FOV', ["Min"] = 1, ["Max"] = 1000, ["Default"] = 150});
			RangeCircle = autoKit:CreateToggle({["Name"] = 'Whisper Range Circle'});
			CircleColor = autoKit:CreateColorSlider({["Name"] = 'Whisper Circle Color'});
			CircleTransparency = autoKit:CreateSlider({["Name"] = 'Whisper Transparency', ["Min"] = 0, ["Max"] = 1, ["Default"] = 0.5, ["Decimal"] = 10});
			CircleThickness = autoKit:CreateSlider({["Name"] = 'Whisper Thickness', ["Min"] = 1, ["Max"] = 10, ["Default"] = 1, ["Decimal"] = 10, ["Tooltip"] = 'Outline width, ignored while the circle is filled'});
			CircleFilled = autoKit:CreateToggle({["Name"] = 'Whisper Circle Filled'});
			return {Heal, Health, Lift, AutoOwl, Teammate, FovCheck, Fov, RangeCircle, CircleColor, CircleTransparency, CircleThickness, CircleFilled};
		end,
		["Start"] = function(autoKit: table): ()
			local controller: table = bedwars.OwlKitController;
			local ownHandler: any = rawget(controller, 'onAbilityUsed');
			local original: (...any) -> ...any = controller.onAbilityUsed;
			local hook: (...any) -> ...any = function(self: table, character: Model, data: table?, ...: any): ...any
				if AutoOwl["Enabled"] and data and data.ability == 'SUMMON_OWL' and character == lplr.Character then
					local target: Player? = entitylib.isAlive and pickTeammate() or nil;
					if target and target ~= lplr then
						fire('SummonOwl', 'CallServer', target);
						return nil;
					end;
				end;
				return original(self, character, data, ...);
			end;
			controller.onAbilityUsed = hook;
			autoKit:Clean(function(): ()
				if controller.onAbilityUsed == hook then
					controller.onAbilityUsed = ownHandler;
				end;
			end);

			if Drawing then
				local circle: any = Drawing.new('Circle');
				circle.NumSides = 100;
				autoKit:Clean(function(): ()
					circle:Remove();
				end);
				autoKit:Clean(runService.RenderStepped:Connect(function(): ()
					circle.Visible = AutoOwl["Enabled"] and FovCheck["Enabled"] and RangeCircle["Enabled"];
					if circle.Visible then
						circle.Position = mouseOrigin();
						circle.Radius = Fov["Value"];
						circle.Color = Color3.fromHSV(CircleColor["Hue"], CircleColor["Sat"], CircleColor["Value"]);
						circle.Transparency = 1 - CircleTransparency["Value"];
						circle.Thickness = CircleThickness["Value"];
						circle.Filled = CircleFilled["Enabled"];
					end;
				end));
			end;

			local mapBottom: number?;
			local footingOwner: Model?, footingY: number = nil, -math.huge;
			local nextCheck: number = 0;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextCheck or store.matchState == 0 or not entitylib.isAlive then
					return;
				end;
				nextCheck = tick() + checkRate;
				if AutoOwl["Enabled"] and not bedwars.OwlAbilityController.target and bedwars.AbilityController:canUseAbility('SUMMON_OWL', quiet) and pickTeammate() then
					bedwars.AbilityController:useAbility('SUMMON_OWL');
				end;
				local attached: Instance? = bedwars.OwlAbilityController.target;
				local character: Model? = attached and (attached:IsA('Player') and attached.Character or attached:IsA('Model') and attached) or nil;
				if not character then
					return;
				end;
				local root: BasePart? = character.PrimaryPart;
				if root then
					if not mapBottom then
