			Mode = autoKit:CreateDropdown({["Name"] = 'Zola Mode', ["List"] = {'On See', 'On Hit'}, ["Default"] = 'On See', ["Tooltip"] = 'On See - links enemies as soon as you can see them\nOn Hit - links enemies you hit'});
			Range = autoKit:CreateSlider({["Name"] = 'Zola Range', ["Min"] = 1, ["Max"] = 50, ["Default"] = 30, ["Suffix"] = 'studs'});
			return {Mode, Range};
		end,
		["Start"] = function(autoKit: table): ()
			local links: {[Instance]: number} = {};
			local nextLink: number = 0;
			autoKit:Clean(function(): ()
				table.clear(links);
			end);
			local link: (character: Model) -> () = function(character: Model): ()
				if tick() < nextLink or (links[character] or 0) > tick() then
					return;
				end;
				local active: number = 0;
				for linked: Instance, expires: number in links do
					if expires > tick() then
						active += 1;
					else
						links[linked] = nil;
					end;
				end;
				if active < bedwars.SoulBrokerConstants.MAX_SOUL_LINKS then
					links[character], nextLink = tick() + linkGap, tick() + linkGap;
					fire('AttemptSoulLink', 'CallServerAsync', character);
				end;
			end;
			autoKit:Clean(bedwars.Client:Get('SoulLinkFormed'):Connect(function(event: table): ()
				if event.broker == lplr and not event.guard then
					links[event.target] = tick() + bedwars.SoulBrokerConstants.SOUL_LINK_DURATION;
				end;
			end));
			autoKit:Clean(bedwars.Client:Get('SoulLinkRemoved'):Connect(function(event: table): ()
				if event.broker == lplr and not event.guard then
					links[event.target] = nil;
				end;
			end));
			autoKit:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
				if Mode["Value"] ~= 'On Hit' or damage.fromEntity ~= lplr.Character or not entitylib.isAlive then
					return;
				end;
				local victim: table? = entitylib.getEntity(damage.entityInstance);
				if victim and victim.Player and victim.Targetable and (entitylib.character.RootPart.Position - victim.RootPart.Position).Magnitude <= Range["Value"] then
					link(victim.Character);
				end;
			end));
			local nextCheck: number = 0;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if Mode["Value"] ~= 'On See' or tick() < math.max(nextCheck, nextLink) or not entitylib.isAlive then
					return;
				end;
				nextCheck = tick() + checkRate;
				for _: number, ent: table in entitylib.AllPosition({["Range"] = Range["Value"], ["Part"] = 'RootPart', ["Players"] = true, ["Wallcheck"] = true}) do
					if (links[ent.Character] or 0) <= tick() then
						link(ent.Character);
						break;
					end;
				end;
			end));
		end
	};
end);

