			return {NoCooldown};
		end,
		["Start"] = function(autoKit: table): ()
			local abilities: table = bedwars.AbilityController;
			local cooldowns: table = abilities.cooldownController;
			local ownCooldown: any, ownUse: any = rawget(cooldowns, 'setOnCooldown'), rawget(abilities, 'useAbility');
			local setOnCooldown: (...any) -> ...any = cooldowns.setOnCooldown;
			local useAbility: (...any) -> ...any = abilities.useAbility;
			local cooldownHook: (...any) -> ...any = function(self: table, cooldownId: string, ...: any): ...any
				if cooldownId == warp and NoCooldown["Enabled"] then
					return nil;
				end;
				return setOnCooldown(self, cooldownId, ...);
			end;
			local useHook: (...any) -> ...any = function(self: table, ability: string, ...: any): ...any
				if ability == warp and NoCooldown["Enabled"] then
