			cooldowns.setOnCooldown, abilities.useAbility = cooldownHook, useHook;
			if NoCooldown["Enabled"] then
				cooldowns:removeCooldown(warp);
			end;
			autoKit:Clean(function(): ()
				if cooldowns.setOnCooldown == cooldownHook then
					cooldowns.setOnCooldown = ownCooldown;
				end;
				if abilities.useAbility == useHook then
					abilities.useAbility = ownUse;
				end;
			end);
		end
	};
end);

