		return function(...: any): Vector3
			return Vector3.new(0, height, 0);
		end;
	end;
	local along: (direction: Vector3?) -> Vector3? = function(direction: Vector3?): Vector3?
		local horizontal: Vector3 = direction and direction * flat or Vector3.zero;
		return horizontal.Magnitude > 0 and horizontal.Unit * 70 or nil;
	end;
