		["Yamini Wall Kick"] = {["Controller"] = 'CatController', ["Method"] = 'dismountWall', ["Push"] = lift(25)},
		["Yuzi Dash"] = {["Controller"] = 'DaoController', ["Method"] = 'dashForward', ["Push"] = along},
		["Xurot Wing Flap"] = {["Controller"] = 'VoidDragonController', ["Method"] = 'flapWings', ["Push"] = lift(40)}
	};

	local boostOptions: (autoKit: table, label: string, tooltip: string) -> {table} = function(autoKit: table, label: string, tooltip: string): {table}
		local boost: table = boosts[label];
		boost.Toggle = autoKit:CreateToggle({["Name"] = label..' boost', ["Tooltip"] = tooltip});
		boost.Multiplier = autoKit:CreateSlider({["Name"] = label..' multiplier', ["Min"] = 1, ["Max"] = 5, ["Default"] = 2, ["Decimal"] = 10, ["Suffix"] = 'x'});
		return {boost.Toggle, boost.Multiplier};
	end;

	local hookBoost: (autoKit: table, label: string) -> () = function(autoKit: table, label: string): ()
		local boost: table = boosts[label];
