			for _: number, option: table in boostOptions(autoKit, 'Yamini Wall Kick', 'Extends how high dropping off a climbed wall throws you') do
				table.insert(created, option);
			end;
			return created;
		end,
		["Start"] = function(autoKit: table): ()
			hookBoost(autoKit, 'Yamini Pounce');
			hookBoost(autoKit, 'Yamini Wall Kick');
