			InstantCharge = autoKit:CreateToggle({["Name"] = 'Yuzi Instant charge', ["Tooltip"] = 'Your dao is fully charged the moment charging starts, so you can dash right away'});
			table.insert(created, InstantCharge);
			return created;
		end,
		["Start"] = function(autoKit: table): ()
			hookBoost(autoKit, 'Yuzi Dash');
			local dao: table? = bedwars.DaoController;
			local original: any = dao and dao.enterChargingState;
			if type(original) ~= 'function' then
				return;
			end;
			local own: any = rawget(dao, 'enterChargingState');
			local hook: (...any) -> ...any = function(self: table, ...: any): ...any
				local results: table = table.pack(original(self, ...));
				if InstantCharge["Enabled"] and self.chargingMaid then
					self.beginChargeTime = time() - 60;
				end;
				return table.unpack(results, 1, results.n);
			end;
			dao.enterChargingState = hook;
			autoKit:Clean(function(): ()
				if dao.enterChargingState == hook then
