			Range = autoKit:CreateSlider({["Name"] = 'Xurot Range', ["Min"] = 1, ["Max"] = 200, ["Default"] = 120, ["Suffix"] = 'studs', ["Tooltip"] = 'Breathes on enemies in this range while you are a dragon'});
