end);

velo.run(function(): ()
	local AutoKit: table = {["Enabled"] = false};
	local ShowAll: table = {["Enabled"] = false};
	local Notify: table = {["Enabled"] = true};
	local specNames: {string} = {};
	for name: string in kitSpecs do
		table.insert(specNames, name);
	end;
	table.sort(specNames);

	local appliesNow: (spec: table) -> boolean = function(spec: table): boolean
		for _: number, kit: string in spec.Kits or {} do
			if hasKit(kit) then
				return true;
			end;
		end;
		return spec.Kits == nil;
	end;

	local refreshOptions: () -> () = function(): ()
		for _: number, name: string in specNames do
			local spec: table = kitSpecs[name];
			local shown: boolean = ShowAll["Enabled"] or appliesNow(spec);
			for _: number, option: table in spec.Objects or {} do
				option.Object.Visible = shown;
			end;
		end;
	end;

	AutoKit = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoKit',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local started: {string} = {};
			for _: number, name: string in specNames do
				local spec: table = kitSpecs[name];
				if spec.Objects and (appliesNow(spec) or spec.AnyKit) and xpcall(spec.Start, function(message: any): ()
					velo.report('AutoKit '..name, message);
				end, AutoKit) then
					if spec.Kits and appliesNow(spec) then
						table.insert(started, name);
					end;
				end;
			end;
			if Notify["Enabled"] and #started > 0 then
				local kitNames: {string} = {};
				for _: number, kit: string in store.equippedKits do
					local meta: table? = bedwars.BedwarsKitMeta[kit];
					table.insert(kitNames, meta and meta.name or kit);
				end;
				notif('AutoKit', 'Running for '..table.concat(kitNames, ' & ')..': '..table.concat(started, ', '), 8, 'info');
			end;
			AutoKit:Clean(vapeEvents.KitChanged.Event:Connect(function(): ()
				task.defer(function(): ()
					if AutoKit["Enabled"] then
						AutoKit:Toggle();
						AutoKit:Toggle();
					end;
				end);
			end));
		end,
		["Tooltip"] = 'Automates every supported kit. Only the options of the kit you are playing are shown.'
	});
	AutoKit:CreateTargets({
		["Players"] = true,
		["NPCs"] = true
	});
	AutoKit:CreateToggle({
		["Name"] = 'Legit Range',
		["Tooltip"] = 'Kits with a range keep it within what a legit player could reach.'
	});
	ShowAll = AutoKit:CreateToggle({
		["Name"] = 'Show all kits',
		["Function"] = refreshOptions,
		["Tooltip"] = 'Show the options of kits you are not playing.'
	});
	Notify = AutoKit:CreateToggle({
		["Name"] = 'Notify',
		["Default"] = true,
		["Tooltip"] = 'Notify which kit automations started.'
	});
	for _: number, name: string in specNames do
		local built: boolean, objects: any = xpcall(kitSpecs[name].Options, function(message: any): ()
			velo.report('AutoKit '..name, message);
		end, AutoKit);
		kitSpecs[name].Objects = built and objects or nil;
	end;
	refreshOptions();
	vape:Clean(vapeEvents.KitChanged.Event:Connect(refreshOptions));
end);
